class Main {
  import java.io._
  import java.util.StringTokenizer

  import scala.collection.mutable
  import scala.util.Sorting
  import math.{abs, max, min}
  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  /**
    * @param tpe 0: row, 1: col, 2, どっちも
    */
  case class Restriction(tpe: Int, v: Int)

  def solve(): Unit = {
    val N, M = ni()
    val A = na(N)
    val B = na(M)

    val inRow = A.toSet
    val inCol = B.toSet
    val restrictions = ArrayBuffer[Restriction]()

    REP(N) { i =>
      val tpe = if (inCol.contains(A(i))) 2 else 0
      restrictions += Restriction(tpe, A(i))
    }

    REP(M) { i =>
      if (!inRow.contains(B(i))) restrictions += Restriction(1, B(i))
    }

    // vの降順でそーとしてある
    var ans = 1L
    var cur = N * M + 1
    val R = restrictions.sortBy(_.v).reverse

    def calc(): Long = {
      var r, c = 0

      // cur+1からuntil手前までシミュレートする
      def place(until: Int): Boolean = {
        var i = cur - 1
        while (i > until) {
          val alreadyPlaced = N * M - i
          val free = r * c - alreadyPlaced
          if (free <= 0) return false
          ans = ans * free % MOD
          i -= 1
        }

        true
      }

      REP(R.length) { i =>
        R(i).tpe match {
          // row
          case 0 =>
            if (!place(R(i).v)) return 0
            ans = (ans * c) % MOD
            cur = R(i).v
            r += 1

          // col
          case 1 =>
            if (!place(R(i).v)) return 0
            ans = (ans * r) % MOD
            cur = R(i).v
            c += 1

          // どっちも
          case 2 =>
            if (!place(R(i).v)) return 0
            cur = R(i).v
            c += 1
            r += 1
        }
      }

      place(0)

      ans
    }

    def validate(X: Array[Int]) = {
      X.max == N * M && X.groupBy(identity).values.forall(_.length == 1)
    }

    if (validate(A) && validate(B)) {
      out.println(calc())
    } else {
      out.println(0)
    }
  }


