    if (yes) {
	Mint ans = 1;
	int rest = 0;

	for (int cur=N*M; cur>=1; cur--) {
	    int r = row[cur], c = col[cur];
	    if (r >= 0 && c >= 0) {
		assert(use[r][c] == 0);
		use[r][c] = 2;
		REP (i, N) {
		    if (use[i][c] == 1) rest++;
		    use[i][c]++;
		    A_pool[i]++;
		}
		REP (j, M) {
		    if (use[r][j] == 1) rest++;
		    use[r][j]++;
		    B_pool[j]++;
		}
	    } else if (r >= 0) {
		ans *= A_pool[r];
		REP (j, M) {
		    if (use[r][j] == 1) rest++;
		    else B_pool[j]++;
		    use[r][j]++;
		}
		rest--;
	    } else if (c >= 0) {
		ans *= B_pool[c];
		REP (i, N) {
		    if (use[i][c] == 1) rest++;
		    else A_pool[i]++;
		    use[i][c]++;
		}
		rest--;
	    } else {
		ans *= rest;
		rest--;
	    }
	    if (rest < 0) ans = 0;
	}

	printf("%d\n", ans.geti());
    } else {
	puts("0");
    }
}

