const ll mod=1e9+7;
std::vector<P> row,col;
const int N=1005;
bool vc[N],vr[N];
int n,m;
int main() {
    scanf("%d%d",&n,&m);
    for(int i=0,x;i<n;i++) {
        scanf("%d",&x);
        row.push_back(P(x,i+1));
    }
    for(int i=0,x;i<m;i++) {
        scanf("%d",&x);
        col.push_back(P(x,i+1));
    }
    std::sort(row.begin(),row.end(),std::greater<P>());
    std::sort(col.begin(),col.end(),std::greater<P>());
    int pl=0,pr=0;int nr=0,nc=0;
    ll ans=1;
    for(int i=n*m;i;i--) {
        if(pl<row.size()&&row[pl].first>i) {ans=0;break;}
        if(pr<col.size()&&col[pr].first>i) {ans=0;break;}
        int L=0,R=0;
        if(pl<row.size()&&row[pl].first==i) L=row[pl++].second;
        if(pr<col.size()&&col[pr].first==i) R=col[pr++].second;
        if(L&&vr[L]||R&&vc[R]) {
            ans=0;break;
        }
        if(!L&&!R) {
            int tmp=nr*nc-(n*m-i);
            if(tmp<=0) {
                ans=0;break;
            }ans=ans*tmp%mod;
        }
        else if(!L) {
            nc++;ans=ans*nr%mod;
            vc[R]=1;
        }
        else if(!R) {
            nr++;ans=ans*nc%mod;
            vr[L]=1;
        }
        else {
            nr++;nc++;
            vr[L]=vc[R]=1;
        }
    }
    printf("%lld\n",ans);
    return 0;
}

