  UNIQUE(B);

  //元のサイズより小さいなら、重複があったということ
  if (A.size() < N || B.size() < M) {
    cout << 0 << endl;
    return 0;
  }

  int ans = 1;
  for (int i = N * M; i >= 1; i--) {
    bool fa = EXIST(sta, i);
    bool fb = EXIST(stb, i);

    int na = N - (int)(upper_bound(ALL(A), i) - A.begin());
    int nb = M - (int)(upper_bound(ALL(B), i) - B.begin());

    //縦横ともに存在
    if (fa && fb) {
      continue;

      //縦横ともに存在しない
    } else if (!fa && !fb) {
      int tmp = na * nb - (N * M - i);

      if (tmp <= 0) {
        cout << 0 << endl;
        return 0;
      }

      ans *= tmp;
      ans %= MOD;

      //片方に存在
    } else if (fa && !fb) {
      ans *= nb;
      ans %= MOD;
    } else if (!fa && fb) {
      ans *= na;
      ans %= MOD;
    }
  }

  cout << ans << endl;
  return 0;
}

