const ll INF = 1e9;
const ll MOD = 1e9+7;
const ll LINF = 1e18;

// 参考: https://drken1215.hatenablog.com/entry/2019/01/14/033200

ll n,m; 
vll a,b;

ll solve(){
  ll res=1;
  ll biggerX_a=0, biggerX_b=0; // a,b で x より大きいのが何個あるか
  for(ll x=n*m; x>=1; --x){
    if(a[biggerX_a]>x) return 0;
    if(b[biggerX_b]>x) return 0;

    ll tmp=1;
    if(a[biggerX_a]==x && b[biggerX_b]==x){
      // 行、列の両方にxが登場する
      tmp=1;
      ++biggerX_a, ++biggerX_b;
    }else if(a[biggerX_a]==x){
      // 行側にのみxが登場する
      // xより大きい値が入ることが確定している列のみ選択可能
      tmp=biggerX_b;
      ++biggerX_a;
    }else if(b[biggerX_b]==x){
      // 列側にのみxが登場する
      tmp=biggerX_a;
      ++biggerX_b;
    }else{
      // 行、列の両方にxが登場しない
      // xより大きい値が入ることが確定している行列内のいずれかに入る
      // このうち、n*m-x個はxより大きい値で埋められているので除外する必要がある
      tmp=biggerX_a*biggerX_b-(n*m-x);
      if(tmp<=0) return 0;
    }
    res=(res*tmp)%MOD;
  }
  return res;
}

