In ll dPow(ll a, ll b)
{
	Rg ll r=1;
	for(; b; a=a*a%p, b>>=1)
		if(b & 1)
			r=r*a%p;
	return r;
}

int main()
{
	St int n, m, a[mxN], b[mxN], fact[mxA], invF[mxA];
	scanf("%d%d", &n, &m);
	for(Rg int i=1; i<=n; ++i)
		scanf("%d", a+i);
	for(Rg int i=1; i<=m; ++i)
		scanf("%d", b+i);
	sort(a+1, a+n+1);
	sort(b+1, b+m+1);
	a[n+1]=b[m+1]=1e9;
	Rg ll ans=1, used=0;
	for(Rg int i=1; i<n; ++i)
		if(a[i]==a[i+1])
			goto End;
	for(Rg int i=1; i<m; ++i)
		if(b[i]==b[i+1])
			goto End;
	fact[0]=1;
	for(Rg int i=1; i<mxA; ++i)
		fact[i]=(ll)i*fact[i-1]%p;
	invF[mxA-1]=dPow(fact[mxA-1], p-2);
	for(Rg int i=mxA-1; i; --i)
		invF[i-1]=(ll)i*invF[i]%p;
	for(Rg int i=1, j=1; i<=n || j<=m;)
	{
