		{
			if(used+(n-i)+(m-j)>=a[i])
				goto End;
			ans=ans*fact[a[i]-used-1]%p*invF[a[i]-used-1-n+i-m+j]%p;
			used+=n-i+m-j+1;
			++i;
			++j;
		}
		else if(a[i]<b[j])
		{
			if(used+(m-j)>=a[i])
				goto End;
			ans=ans*fact[a[i]-used-1]%p*invF[a[i]-used-1-m+j]%p*(m-j+1)%p;
			used+=(m-j)+1;
			++i;
		}
		else
		{
			if(used+(n-i)>=b[j])
				goto End;
			ans=ans*fact[b[j]-used-1]%p*invF[b[j]-used-1-n+i]%p*(n-i+1)%p;
			used+=(n-i)+1;
			++j;
