template<class T,class S> inline ll RightNumOf(vector<T> &v,S x){
	return (ll)v.size() - (lower_bound(ALL(v),x) - v.begin());
}
/*  x以右(以上)の個数を得る。vが昇順の時のみ。
ll nm = RightNumOf(v, x);
*/


void solve()
{
	ll n,m;  cin >> n >> m;
	vector<ll> a(n);  rep(i,0,n-1){ ll a_; cin>>a_; a[i]=a_; }
	vector<ll> b(m);  rep(i,0,m-1){ ll b_; cin>>b_; b[i]=b_; }

	sort(ALL(a));
	sort(ALL(b));
	{
		bool isany=false;
		rep(i,1,n-1) if (a[i-1]==a[i]) isany=true;
		if (isany){
			cout << 0 << '\n'; return;
		}
	}
	{
		bool isany=false;
		rep(i,1,m-1) if (b[i-1]==b[i]) isany=true;
		if (isany){
			cout << 0 << '\n'; return;
		}
	}

	mll ans=1;
	dep(i,n*m,1){
		ll anm = RightNumOf(a, i);
		ll bnm = RightNumOf(b, i);

		ll v;
		if (a[n-anm]==i or b[m-bnm]==i){
			if (a[n-anm]==i) anm=1;
			if (b[m-bnm]==i) bnm=1;
			v=anm*bnm;
		}
		else{
			v=anm*bnm-(n*m-i);
		}
		if (v<=0){
			cout << 0 << '\n'; return;
		}
		ans*=v;
	}
	cout << ans << '\n';
}


