int n, m, a[N], b[N], presum[N*N], presuma[N*N], presumb[N*N]; 

int main()
{
//	freopen( "d.in", "r", stdin ); 

	n = read(); m = read(); int maxx = n * m; 

	for( int i = 1; i <= n; i ++ )
		a[i] = read(), presuma[ a[i] ] ++;	

	for( int i = 1; i <= m; i ++ )
		b[i] = read(), presumb[ b[i] ] ++; 

	for( int i = 1; i <= n; i ++ )
		for( int j = 1; j <= m; j ++ )
			presum[ min( a[i], b[j] ) ] ++; 

	for( int i = 2; i <= maxx; i ++ )
		presum[i]  += presum[i-1] , 
		presuma[i] += presuma[i-1],
		presumb[i] += presumb[i-1];  

	ll ans = 1;
	for( int i = maxx; i >= 1; i -- )
	{
		int ina = presuma[i] - presuma[i-1], 
			inb = presumb[i] - presumb[i-1];

		if( ina > 1 || inb > 1 ) { ans = 0; break; }

		if( ina && inb ) continue;

		if( ina ) {	ans = ans * ( presumb[maxx] - presumb[i-1] ) % MOD; continue; }
		if( inb ) {	ans = ans * ( presuma[maxx] - presuma[i-1] ) % MOD; continue; }

		if( presum[maxx] - presum[i-1] - ( maxx - i ) <= 0 ) { ans = 0; break; }

		ans = ans * ( presum[maxx] - presum[i-1] - ( maxx - i ) ) % MOD;
	}

	cout << ans << endl;	

	return 0; 
}

