  for (int i = h * w; i > 0; i--) {
    if (a[hh] == i && b[ww] == i) {
      ok++;
      hh++;
      ww++;
      continue;
    }

    if (i == a[hh] && hh < h) {
      int tmp = min(w, ww + 1);
      if (i > b[ww]) tmp--;
      ans *= (ll)tmp;
      ans %= MOD;
      hh++;
    }

    else if (i == b[ww] && ww < w) {
      int tmp = min(h, hh + 1);
      if (i > a[hh]) tmp--;
      ans *= (ll)tmp;
      ans %= MOD;
      ww++;
    }

    else {
      ans *= (ll)ww * (ll)hh - ok;
      ans %= MOD;
    }
    ok++;
  }
  cout << ans % MOD << endl;
  return 0;
}

