            sum = mod(sum * 1ll * t);continue;
        }
        ///其中一个都走到头了
        if (l1 == n && l2 != m) {
            if (s2[l2] > i) return 0;
            if (s2[l2] == i) {
                ll t = l1;
                l2++;
                if (t == 0) return 0;
                sum = mod(sum * 1ll * t);
                continue;
            }
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);continue;
        }
        ///其中一个都走到头了
        if (l1 != n && l2 == m) {
            if (s1[l1] > i) return 0;
            if (s1[l1] == i) {
                ll t = l2;
                l1++;
                if (t == 0) return 0;
                sum = mod(sum * 1ll * t);
                continue;
            }
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);continue;
        }

        ///如果当前的值大于枚举值，直接判无效
        if (s1[l1] > i || s2[l2] > i) return 0;

        /// 确定位置
        if (s1[l1] == i && s2[l2] == i) {
            l1++,l2++;continue;
        }

        ///确定了某一行或列
        if (s1[l1] == i && s2[l2] != i) {
            ll t = l2;
            l1++;
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);
            continue;
        }
        if (s1[l1] != i && s2[l2] == i) {
            ll t = l1;
            l2++;
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);
            continue;
        }

        ///行列都不确定
        if (s1[l1] != i && s2[l2] != i) {
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);
        }
    }
    return sum;
}



