		return 1;
	if(f_[n])
		return f_[n];
	return n * f(n-1) % mod;
}

ll ivf_[1000100];
ll ivf(ll n) {
	if(ivf_[n])
		return ivf_[n];
	ll x = f(n);
	ll p = mod -2;
	ll res = 1;
	while(p) {
		if(p & 1)
			res = (res * x) % mod;
		x = (x * x) % mod;
		p /= 2;
	}
	return res;
}

ll choose(ll n, ll r) {
	return (f(n) * ivf(n-r)) % mod;
}

