void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);//おまじないでcin, cout早くする
    COMinit();

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    vector<int> b(m);
    rep(i, n){
        cin >> a[i];
    }
    rep(i, m){
        cin >> b[i];
    }
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    for(int i = 0; i < n-1; i++){
        if(a[i] == a[i+1]){
            cout << 0 << "\n";
            return 0;
        }
    }
    if(a[n-1] != n * m){
        cout << 0 << "\n";
        return 0;
    }
    for(int i = 0; i < m-1; i++){
        if(b[i] == b[i+1]){
            cout << 0 << "\n";
            return 0;
        }
    }
    if(b[m-1] != n * m){
        cout << 0 << "\n";
        return 0;        
    }

    int r = 0;
    int c = 0;

    ll used = 0;
    ll ans = 1;
    while(r != n - 1 && c != m - 1){
        if(a[r] > b[c]){
            if(b[c] - used - 1 < n - r - 1){
                cout << 0 << "\n";
                return 0;
            }
            ans = (ans * COM(b[c] - used - 1, n - r - 1)) % MOD;
            c++;
            used += n - r;
        }else if(a[r] < b[c]){
            if(a[r] - used - 1 < m - c - 1){
                return 0;
            }
            ans = (ans * COM(a[r] - used - 1, m - c - 1)) % MOD;
            r++;
            used += m - c;
        }else if(a[r] == b[c]){
            ans = (ans * COM(a[r] - used - 1 , m - c - 1)) % MOD;
            used += m - c - 1;
            ans = (ans * COM(b[c] - used - 1, n - r - 1)) % MOD;
            c++;
            r++;
            used += n - r - 1 + 1;
        }
    }

    cout << ans << "\n";

    return 0;
}

