void fail() {
    cout << 0 << endl;
    exit(0);
}

bool v_unlocked[1010];
bool h_unlocked[1010];

set<int> v_free_count[1010];
set<int> h_free_count[1010];
set<pair<int, int> > free_count;

void add(ll r, ll c) {
    free_count.insert({r, c});
    v_free_count[c].insert(r);
    h_free_count[r].insert(c);
}

void dec(ll r, ll c) {
    h_free_count[r].erase(c);
    v_free_count[c].erase(r);
    assert(free_count.erase({r, c}));
}

ll dec_h(ll r) {
    ll res = h_free_count[r].size();
    if( res == 0 ) return 0;
    ll c = *h_free_count[r].begin();
    dec(r, c);
    return res;
}

ll dec_v(ll c) {
    ll res = v_free_count[c].size();
    if( res == 0 ) return 0;
    ll r = *v_free_count[c].begin();
    dec(r, c);
    return res;
}

ll dec_any() {
    ll res = free_count.size();
    if( res == 0 ) return 0;
    int r, c;
    tie(r, c) = *free_count.begin();
    dec(r, c);
    return res;
}

void unlock_v(ll c) {
    if (v_unlocked[c]) return;
    v_unlocked[c] = true;
    for (int r = 0; r < H; r++) {
        if (h_unlocked[r] == 1) {
            add(r, c);
        }
    }
}

void unlock_h(ll r) {
    if (h_unlocked[r]) return;
    h_unlocked[r] = true;
    for (int i = 0; i < W; i++) {
        if (v_unlocked[i] == 1) {
            add(r, i);
        }
    }
}


ll ans = 1;

void mult(ll x) {
    ans *= x;
    ans %= MOD;
}

void solve() {
    R.push_back(-1);
    C.push_back(-1);
    sort(R.begin(), R.end());
    sort(C.begin(), C.end());
    for (int i = H * W; i > 0; i--) {
        if (R.back() > i) fail();
        if (C.back() > i) fail();

        if (R.back() == i && C.back() == i) {
            unlock_h(R.size() - 2);
