    for(int x: a) {
        int i = lower_bound(b.begin(), b.end(), x) - b.begin();
        if (i < m && b[i] == x) {
            continue;
        } else {
            res *= (m-i);
        }
    }
    for (int x: b) {
        int i = lower_bound(a.begin(), a.end(), x) - a.begin();
        if (i < n && a[i] == x) {
            continue;
        } else {
            res *= (n-i);
        }
