    */
    map<int, int> used;
    vector< pair<int, int> > u = {{0, 0}};
    map<int, int> ma;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (a[i] == b[j]) {
               used[a[i]]++;
                continue;
            }
            ma[min(a[i], b[j])]++;
        }
    }
    for (auto it = ma.begin(); it != ma.end(); it++) {
        u.push_back({it->first, it->second});
    }
    sort(u.rbegin(), u.rend()); int mm = n * m;
    int rest = 0; int count = 0;
    for (int i = 0; i < u.size()-1; i++) {
        int p = u[i].first; int q = u[i].second;
