const int M = 1000000007;

bool check(vector<int>& a) {
	set<int> st(all(a));
	if (st.size() != a.size()) { return true; }
	return false;
}

signed main() {
	int n, m;
	cin >> n >> m;
	vector<int> a(n), b(m);
	cin >> a >> b;

	if (check(a) or check(b)) {
		cout << 0 << endl;
		return 0;
	}

	sort(all(a));
	sort(all(b));

	int ans = 1;
	int i = n - 1, j = m - 1;
	for (int c = n * m; c >= 1; c--) {
		while (i > 0 and a[i - 1] >= c) i--;
		while (j > 0 and b[j - 1] >= c) j--;

		if (a[i] == c and b[j] == c) continue;
		if (a[i] == c) {
			ans *= m - j;
		} else if (b[j] == c) {
			ans *= n - i;
		} else {
			ans *= (n - i) * (m - j) - (n * m - c);
		}
		ans = (ans % M + M) % M;
	}
	cout << ans << endl;
}

