    int cnti = 0, cntj = 0;
    rrep(i, 1, N * M + 1){
        if(*lower_bound(ALL(A), i) == i && *lower_bound(ALL(B), i) == i){
            // ans *= 1;
            cnti++, cntj++;
        }else if(*lower_bound(ALL(A), i) == i){
            ans *= cntj;
            cnti++;
        }else if(*lower_bound(ALL(B), i) == i){
            ans *= cnti;
            cntj++;
        }else{
            ans *= cnti * cntj - cnt;
        }
        cnt++;
        // cerr << ans << endl;
    }
    cout << ans << endl;
    return 0;
}

