int N, M;
vector<lint> A, B;
map<int, int> obs;


constexpr lint MOD = 1000000007;
vector<lint> fac, facInv, inv;
void facInit(int nmax)
{
    fac = facInv = inv = vector<lint>(nmax + 1, 1);
    for (int i = 2; i <= nmax; i++)
    {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        facInv[i] = facInv[i-1] * inv[i] % MOD;
    }
}
lint nPr(int n, int r)
{
    if (n<r || r<0) return 0;
    if (n >= (int)fac.size()) facInit(n);
    return fac[n] * facInv[n-r] % MOD;
}

void NO()
{
    puts("0");
    exit(0);
}

int main()
{

    facInit(2000000);
    cin >> N >> M;
    A.resize(N);
    B.resize(M);
    cin >> A >> B;

    for (auto v : A) obs[v] += 1;
    for (auto v : B) obs[v] += 2;

    map<int, int> coun[2];
    for (auto v : A) coun[0][v]++;
    for (auto v : B) coun[1][v]++;
    REP(d, 2) for (auto pa : coun[d]) if (pa.second > 1) NO();

    lint v0 = 0, v1 = 0;

    lint ume = 0;
    lint res = 1;
    FOR(v, 1, N * M + 1)
    {
        if (obs[v] == 0) ume++;
        else if (obs[v] == 3)
        {
            lint marg = N + M - 2 - v0 - v1;
            if (marg > ume) NO();
            res *= nPr(ume, marg);
            ume -= marg;
            v0++;
            v1++;
        }
        else if (obs[v] == 1)
        {
            lint marg = M - v1;

            res *= marg;
            marg--;

            res %= MOD;
            if (marg > ume) NO();
            res *= nPr(ume, marg);
            ume -= marg;
            v0++;
        }
        else if (obs[v] == 2)
        {
            lint marg = N - v0;

            res *= marg;
            marg--;

            res %= MOD;
            if (marg > ume) NO();
            res *= nPr(ume, marg);
            ume -= marg;
            v1++;
        }

        res %= MOD;
    }

    cout << res << endl;
}

