			P(0);
			return 0;
		}
	}
	rep(i, M)rep(j, i) {
		if (B[i] == B[j]) {
			P(0);
			return 0;
		}
		if (B[i] < N) {
			P(0);
			return 0;
		}
	}

	ll ans = 1;
	ll count = 0;
	ll yoko = 0, tate = 0;

	int NM = N*M;

	for (int i = N*M; i >= 1; i--) {
		if (m[i] == 3) {
			count += yoko + tate+1;
