		if(a[i] == a[i+1])
			return 0;
	for(int i=0; i<m-1; ++i)
		if(b[i] == b[i+1])
			return 0;
	if(a[n-1] != b[m-1] || a[n-1] != n*m)
		return 0;
	long long ret = 1, mod = 1e9+7;
	for(int i=n*m-1; i>0; --i){
		auto p = lower_bound(a.begin(), a.end(), i);
		auto q = lower_bound(b.begin(), b.end(), i);
		if(*p == i){
			if(*q == i){
//				ret *= 1;
