    REP(i, M) p.push_back(Pii(B[i], 1));
    SORT(p);

    int mod = 1000000007;
    Combination comb(N + M + 10, mod);

    int ans = 1;
    int u = 0;

    int i = 0;
    while(i < N + M){
        if(i != N * M - 1 && p[i].first == p[i + 1].first){
            int v = p[i].first;
            int tmp = N - n + M - m - 1;
            ans *= (comb.fact[tmp - 1] * comb.nCr(v - 1 - u, tmp - 1)) % mod;
            u += tmp;
