            }else{
                ans *= (comb.fact[N - n] * comb.nCr(v - 1 - u, N - n - 1)) % mod;
                u += N - n;
                m++;
            }
            i++;
            //cout << "b:";
        }
        ans %= mod;
        //cout << ans << endl;
    }
