int main() {
	using mint = modint<1000000007>;
	usize n, m;
	::std::cin >> n >> m;
	::std::vector<u32> a(n), b(m);
	for (auto &e : a) {
		::std::cin >> e;
	}
	::std::sort(a.rbegin(), a.rend());
	a.emplace_back(0);
	if (std::unique(a.begin(), a.end()) != a.end()) {
		::std::cout << 0 << ::std::endl;
		return 0;
	}
	for (auto &e : b) {
		::std::cin >> e;
	}
	::std::sort(b.rbegin(), b.rend());
	b.emplace_back(0);
	if (std::unique(b.begin(), b.end()) != b.end()) {
		::std::cout << 0 << ::std::endl;
		return 0;
	}
	mint ans = 1;
	auto used = md_vec(n, m, false);
	::std::vector<bool> sk(n*m + 1, false);
	{
		usize i = 0, j = 0;
		while (i != n || j != m) {

			if (a[i] == b[j]) {
				used[i][j] = true;
				sk[a[i]] = true;
				++i;
				++j;
				continue;
			}

			if (a[i] > b[j]) {
				ans *= j;
				used[i][j - 1] = true;
				sk[a[i]] = true;
				++i;
			}
			else {
				ans *= i;
				used[i - 1][j] = true;
				sk[b[j]] = true;
				++j;
			}
		}

	}
	::std::vector<mint> kou(n*m + 1, 0);
	for (const auto i : rep<>(0, n)) {
		for (const auto j : rep<>(0, m)) {
			//if (used[i][j])continue;
			++kou[::std::min(a[i], b[j])];
		}
	}
	for (const auto i : revrep<>(0, n*m)) {
		kou[i] += kou[i + 1];
	}
	for (const auto i : rep<>(1, n*m + 1)) {
		if (sk[i])continue;
		if (kou[i] <= n*m - i) {
			::std::cout << 0 << ::std::endl;
			return 0;
		}
		ans *= mint(n*m - i) - kou[i];
	}
	::std::cout << ans.value() << ::std::endl;
	return 0;
}

