using namespace std;

typedef long long ll;

const int MOD = (int)1e9 + 7;
int N, M;
vector<int> A, B;

void input_init(void) {
	cin >> N >> M;
	A.resize(N);
	for (int j = 0; j < N; ++j)
		cin >> A[j];
	B.resize(M);
	for (int i = 0; i < M; ++i)
		cin >> B[i];
	sort(A.begin(), A.end());
	A.erase(unique(A.begin(), A.end()), A.end());
	sort(B.begin(), B.end());
	B.erase(unique(B.begin(), B.end()), B.end());
}

int calcu(int n) {
	vector<int>::iterator it_a = lower_bound(A.begin(), A.end(), n);
	vector<int>::iterator it_b = lower_bound(B.begin(), B.end(), n);
	int idx_a = distance(A.begin(), it_a);
	int idx_b = distance(B.begin(), it_b);

	int ret = 0;
	if (*it_a == n && *it_b == n)				// A, B 共に有る
		ret = 1;
	else if (*it_a == n && *it_b != n)			// A のみに有る
		ret = M - idx_b;
	else if (*it_a != n && *it_b == n)			// B のみに有る
		ret = N - idx_a;
	else										// A, B 共に無い
		ret = (M - idx_b) * (N - idx_a) - (N * M - n);

	return ret;
}

int main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);

	input_init();
	ll ans = (ll)0;
	if (A.size() == N && B.size() == M) {
		A.push_back(N * M + 1);
		B.push_back(N * M + 1);
		ans = (ll)1;
		for (int i = 1; i <= N * M; ++i) {
			ans *= (ll)calcu(i);
			ans %= (ll)MOD;
		}
	}

	cout << ans << '\n';
	return 0;
}

