#include <bits/stdc++.h>
using namespace std;
using lint = long long int;

template<int64_t MOD> struct Mint {
    int64_t v;
    Mint() { v = 0; }
    Mint(int64_t x) { v = x % MOD; if(v < 0)  v += MOD; }

    Mint operator-() { return Mint{-v}; };
    Mint operator+(Mint x) { return Mint(v + x.v); };
    Mint operator-(Mint x) { return Mint(v - x.v); };
    Mint operator*(Mint x) { return Mint(v * x.v); };
    Mint operator/(Mint x) { return Mint(v * pow(x.v, MOD-2).v); };

    Mint& operator+=(Mint x) { return *this = (*this + x); };
    Mint& operator-=(Mint x) { return *this = (*this - x); };
    Mint& operator*=(Mint x) { return *this = (*this * x); };
    Mint& operator/=(Mint x) { return *this = (*this / x); };

    static Mint pow(Mint base, int64_t exp) {
        if(exp == 0)  return Mint(1);
        return pow(base*base, exp/2) * (exp&1 ? base : Mint(1));
    }

    friend ostream& operator<<(ostream& os, Mint x) { return os << x.v; }
};
using mint = Mint<1000000007>;

int main() {
    lint n, m;
    cin >> n >> m;

    vector<lint> a(n);
    for(auto& elem : a)  cin >> elem;
    vector<lint> b(m);
    for(auto& elem : b)  cin >> elem;

    // 重複があるかチェック
    set<lint> as(a.begin(), a.end());
    set<lint> bs(b.begin(), b.end());
    if(as.size() < n || bs.size() < m) {
        cout << 0 << endl;
        return 0;
    }

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    mint ans = 1;    
    for(lint i=n*m; i>=1; i--) {
        // iと書かれた列がある場合
        if(as.count(i)) {
            // iと書かれた行がある場合はans *= 1
            // iと書かれた行がない場合
            if(bs.count(i) == 0) {
                // iより大の行の個数
                lint bc = b.end() - upper_bound(b.begin(), b.end(), i);
                ans *= mint(bc);
            }
        }
        // iと書かれた列がない場合
        else {
            // iと書かれた行がある場合
            if(bs.count(i)) {
                lint ac = a.end() - upper_bound(a.begin(), a.end(), i);
                ans *= mint(ac);
            }
            // iと書かれた行がない場合
            else {
                lint ac = a.end() - upper_bound(a.begin(), a.end(), i);
                lint bc = b.end() - upper_bound(b.begin(), b.end(), i);
                ans *= mint(ac) * mint(bc) - mint(n*m-i);
            }
        }
    }

    cout << ans << endl;
}

