inline int power(int x,int y) {
	int z=1;
	for (;y;y>>=1, x=1ll*x*x%md)
	if (y&1) z=1ll*z*x%md;
	return z;
}
inline int A(int n,int m) {
	//printf("* A(%d,%d)\n",n,m);
	return n<m?0:1ll*fac[n]*inv[n-m]%md;
}
