void abort() {
  cout << 0 << endl;
  exit(0);
}

int main() {
  int N, M;
  cin >> N >> M;
  vector<int> A(N), B(M);
  for (int& a : A) cin >> a;
  for (int& b : B) cin >> b;
  sort(A.begin(), A.end(), greater<>());
  sort(B.begin(), B.end(), greater<>());
  if (duplicated(A) || duplicated(B)) abort();

  long ans = 1;
  int ai = 0, bi = 0;
  for (int x = N * M; 0 < x; x--) {
    int num_filled = N * M - x;
    bool fa = ai < N && A[ai] == x;
    bool fb = bi < M && B[bi] == x;
    ai += fa; bi += fb;
    if (fa && fb) continue;
    else if (!fa && !fb) {
      if (ai * bi < num_filled + 1) abort();
      ans *= ai * bi - num_filled;
    } else {
      if (fa) ans *= bi;
      if (fb) ans *= ai;
    }
    ans %= MOD;
  }
  cout << ans << endl;
}

