	std::vector<std::vector<LL>>max(N, std::vector<LL>(M));
	std::map<LL, bool>kotei, must;
	rep(i, N)
	{
		rep(j, M)
		{
			max[i][j] = std::min(A[i], B[j]);
			if (A[i] == B[j]) kotei[A[i]] = true;
		}
	}

	std::vector<std::vector<LL>>res(N, std::vector<LL>(M));
	std::map<LL, LL>add;
	std::vector<LL>musts(N*M);
	rep(i, N)
	{
		rep(j, M)
		{
			if (A[i] == B[j]) res[i][j] = -1;
			else res[i][j] = max[i][j];
			++add[res[i][j]];
		}
	}
	rep(i, N)
	{
		if (kotei[A[i]]) continue;
		must[A[i]] = true;
		rep(j, M) if (B[j] > A[i]) ++musts[A[i]];
	}
	rep(j, M)
	{
		if (kotei[B[j]]) continue;
		must[B[j]] = true;
		rep(i, N) if (A[i] > B[j]) ++musts[B[j]];
	}

	LL avail = 0, ans = 1;
	for (LL i = N * M; i >= 1; --i)
	{
		avail += add[i];
		if (kotei[i]) continue;
		else if (must[i]) (ans *= musts[i]) %= mod;
		else (ans *= avail) %= mod;
		--avail;
	}

	out << ans << std::endl;
}

