#define MOD 1000000007
long long int ppow(long long int i, long long int j) {
	long long int res = 1LL;
	while (j) {
		if ((j & 1LL)) {
			res *= i;
			if (res >= MOD) {
				res %= MOD;
			}
		}
		j >>= 1;
		i *= i;
		if (i >= MOD) {
			i %= MOD;
		}
	}
	return res;
}
long long int usee = 0;
vector<int> nt;
int FF;
long long int k[1000002];
long long int choose(long long int beg, long long int num) {
	if (beg < num)return 0;
	long long int u = k[beg];
	long long int d = ppow(k[beg-num], MOD - 2);
	u *= d;
	return u % MOD;
}
set<int> valid;
long long int way(long long int can, long long int lim,bool flag=false) {
	if (can == 0LL)return 0;
	while (FF < nt.size() && nt[FF] <= lim)FF++;
	int ava = FF - usee;
	if (ava < can) {
		puts("0");
		exit(0);
	}
	long long int u = choose(ava, can);// ppow(ava, can);
	long long int d = choose(ava - 1, can);// ppow(ava - 1, can);
	if (valid.count(lim)) {
		//cout << lim << endl;
		u += MOD - d;
		u %= MOD;
	}
	usee += can;
	return u;
}
