    sort(ALL(A), greater<int>());
    sort(ALL(B), greater<int>());

    int a_i = 0;
    int b_i = 0;
    modint ans = modint(1);
    for (int x = N * M; x > 0; x--) {
        while (A[a_i] > x) {
            a_i++;
        }
        while (B[b_i] > x) {
            b_i++;
        }
        if (A[a_i] == B[b_i] && A[a_i] == x) {
            if ((a_i + 1 < N && A[a_i + 1] == A[a_i]) || (b_i + 1 < M && B[b_i + 1] == B[b_i])) {
                cout << 0 << endl;
                return 0;
            }
        } else if (A[a_i] == x) {
            ans *= modint(b_i);
        } else if (B[b_i] == x) {
            ans *= modint(a_i);
        } else {
            ans *= modint(a_i) * modint(b_i) - (modint(N * M) - modint(x));
        }
    }

