int main(int argc, char** argv) {
  int N, M;
  cin >> N >> M;
  vi A(N);
  vi B(M);
  for (auto& a : A) {
    cin >> a;
  }
  for (auto& b: B) {
    cin >> b;
  }

  vvi G(N, vi(M, INF));
  REP(i, N) {
    REP(j, M) {
      chmin(G[i][j], A[i]);
      chmin(G[i][j], B[j]);
    }
  }

  vi count(N*M+1);
  REP(i, N) {
    REP(j, M) {
      count[G[i][j]]++;
    }
  }

  vi singles;
  REP(i, N) {
    REP(j, M) {
      if (A[i] == B[j]) {
        singles.emplace_back(A[i]);
      }
    }
  }
  Sort(singles);
  Reverse(singles);

  for (auto x : singles) {
    int tmp = count[x];
    if (x>1) {
      count[x-1] += tmp-1;
    }
    count[x] = 1;
  }

  ll remains = 0;
  mint ret = 1;
  for (int x = N*M; x>0; x--) {
    remains += count[x];
    ret *= remains;
    remains--;
  }

  cout << ret << endl;

  return 0;
}

