ll mod = 1e9 + 7;
ll sumr[100005], sumc[100005];
int ir[100005], ic[100005];

int main() {
	int N, M; cin >> N >> M;
	for (int i = 0; i <= 100000; i++) ir[i] = ic[i] = -1;
	for (int i = 0; i < N; i++) {
		int a; cin >> a;
		if (ir[a] != -1) {
			cout << 0 << endl;
			return 0;
		}
		ir[a] = i;
		sumr[a] += 1;
	}
	for (int j = 0; j < M; j++) {
		int b; cin >> b;
		if (ic[b] != -1) {
			cout << 0 << endl;
			return 0;
		}
		ic[b] = j;
		sumc[b] += 1;
	}
	for (int i = 100000; i > 0; i--) sumr[i - 1] += sumr[i];
	for (int j = 100000; j > 0; j--) sumc[j - 1] += sumc[j];
	ll cnt = 0;
	ll ans = 1;
	for (int i = N*M; i > 0; i--) {
		if (ir[i] != -1 && ic[i] != -1) {
			cnt += ((sumc[i] + sumr[i])%mod - 2 + mod) % mod;
		}
		else if (ir[i] != -1) {
			cnt += sumc[i] - 1;
			ans *= sumc[i];
			ans %= mod;
		}
		else if (ic[i] != -1) {
			cnt += sumr[i] - 1;
			ans *= sumr[i];
			ans %= mod;
		}
		else {
			ans *= cnt;
			ans %= mod;
			cnt--;
		}
	}
	for (ll i = 1; i <= cnt; i++) {
		ans *= i;
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

