int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n, m;
  cin >> n >> m;
  int a[n], b[m];
  for(int i = 0; i < n; i++) cin >> a[i];
  for(int i = 0; i < m; i++) cin >> b[i];

  if(!(unique(a, n) && unique(b, m))){
    cout << 0 << endl;
    return 0;
  }

  ll p[n * m + 1];
  fill(p, p + n * m + 1, -1);

  for(int i = 0; i < n; i++){
    bool c = false;
    int count = 0;
    for(int j = 0; j < m; j++){
      if(a[i] == b[j]){
        c = true;
        p[a[i]] = 1;
        break;
      }
      if(b[j] >= a[i]) ++count;
    }
    if(!c) p[a[i]] = count;
  }

  for(int j = 0; j < m; j++){
    bool c = false;
    int count = 0;
    for(int i = 0; i < n; i++){
      if(a[i] == b[j]){
        c = true;
        p[b[j]] = 1;
        break;
      }
      if(a[i] >= b[j]) ++count;
    }
    if(!c) p[b[j]] = count;
  }

  sort(a, a + n);
  sort(b, b + m);

  ll sum = 1;
  ll count = 0;
  for(int i = n * m; i >= 1; i--){
    if(p[i] >= 0) sum = (sum * p[i]) % MOD;
    else{
      ll tmp = n - distance(a, upper_bound(a, a + n, i));
      tmp = (tmp * (m - distance(b, upper_bound(b, b + m, i))));
      if(tmp - count <= 0){
        sum = 0;
        break;
      }
      sum = (sum * (tmp - count)) % MOD;
    }
    ++count;
  }

  cout << sum << endl;

  return 0;
}

