}
//xCyを求める
ll comb(ll x, ll y, ll m) {
	if (x < y)return 0;
	ll res = p[x];
	(res *= mod_inverse(p[y], m)) %= mod;
	(res *= mod_inverse(p[x - y], m)) %= mod;
	return res;
}
ll comb2(ll x, ll y) {
	if (x < y)return 0;
	ll res = comb(x, y, mod);
	res = res * p[y] % mod;
	return res;
}
