			int num = v[i].first;
			c[0]++; c[1]++;
			ans = ans * comb2(num - 1 - sum, rest) % mod;
			sum += rest + 1;

			i++;
		}
		else {
			int id = v[i].second;
			int num = v[i].first;
			int rest = 0;
			if (id == 0) {
				rest = m - c[1];
			}
			else {
				rest = n - c[0];
			}
			c[id]++;
			ans = ans * rest%mod; rest--;
			ans = ans * comb2(num -1- sum, rest) % mod;
			sum += rest+1;
		}
	}
	cout << ans << endl;
	//stop
		return 0;
}

