	bool valid = true;
	for (i = 1; i < n; i++) {
		if (a[i] == a[i - 1]) valid = false;
	}
	for (i = 1; i < m; i++) {
		if (b[i] == b[i - 1]) valid = false;
	}

	if (!valid) ans = 0;
	else {
		ans = 1;
		for (i = n * m; i >= 1; i--) {
			pa = lower_bound(a.begin(), a.end(), i);
			pb = lower_bound(b.begin(), b.end(), i);

			if ((pa == a.end()) || (pb == b.end())) {
				ans = 0;
				break;
			}

			if ((*pa == i) && (*pb == i)) v = 1;
			else if (*pa == i) {
				v = b.end() - pb;
			}
			else if (*pb == i) {
				v = a.end() - pa;
			}
			else {
				x = a.end() - pa;
				y = b.end() - pb;
				v = (x * y - (n * m - i)) % MOD;
			}

			ans = (ans * v) % MOD;
		}
	}

	cout << ans % MOD << "\n";
	return 0;
}

