void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
    sort(ALL(A));
    A.erase(unique(ALL(A)), A.end());

    sort(ALL(B));
    B.erase(unique(ALL(B)), B.end());

    if (A.size() != N || B.size() != M) {
        cout << 0 << endl;
        return;
    }

    map<int,int> mp1, mp2;
    for(int i = 0; i < A.size(); ++i) {
        mp1[A[i]] = i;
    }
    for(int j = 0; j < B.size(); ++j) {
        mp2[B[j]] = j;
    }
    int res = 1;
    vector<vector<int>> f(N, vector<int>(M));

    for(int k = N * M; k >= 1; --k) {
        if (mp1.find(k) != mp1.end() && mp2.find(k) != mp2.end()) {
        } else if (mp1.find(k) != mp1.end()) {
            int b = B.end() - lower_bound(ALL(B), k);
            res = (res * b) % MOD;
        } else if (mp2.find(k) != mp2.end()) {
            int a = A.end() - lower_bound(ALL(A), k);
            res = (res * a) % MOD;
        } else {
            int a = A.end() - lower_bound(ALL(A), k);
            int b = B.end() - lower_bound(ALL(B), k);
            res = (res * max(0LL, a * b - (N * M - k))) % MOD;
        }
    }

    cout << res << endl;
}

