int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    lint N; cin >> N;
    lint M; cin >> M;

    vector<lint> A(N);
    vector<lint> B(M);

    REP(i, N) {
      lint x; cin >> x; A[i] = x;
    }

    SORT(A);

    REP(i, M) {
      lint x; cin >> x; B[i] = x;
    }
    SORT(B);

    lint n = N-1;
    lint m = M-1;

    lint res = 1;
    lint current = N*M;

    while(current > 0) {
      while(A[n] > current && n >= 0) {
        n--;
      }
      while(B[m] > current && m >= 0) {
        m--;
      }

      if(n >= 0 && A[n] == current && m >=0 && B[m] == current) {
