ll fact[100008];
void factorial() {
  ll a = 1;
  fact[0] = 1;
  REP(i, 100007) {
    a *= (i + 1);
    a %= MOD;
    fact[i + 1] = a;
  }
}

int main() {
  ll n, m;
  cin >> n >> m;
  factorial();
  vector<ll> v, w;
  set<ll> s, e, same;
  REP(i, n) {
    ll p;
    cin >> p;
    v.pb(p);
    s.insert(p);
    same.insert(p);
  }
  REP(i, m) {
    ll p;
    cin >> p;
    w.pb(p);
    e.insert(p);
    same.insert(p);
  }
  if (s.size() != n || e.size() != m) {
    cout << 0 << endl;
    return 0;
  }
  ll ans = 1;
  REP(i, n) {
    ll cnt = 0;
    REP(j, m) {
      if (v[i] == w[j]) {
        cnt = 1;
        break;
      } else if (v[i] < w[j]) {
        cnt++;
      }
    }
    ans *= cnt;
    ans %= MOD;
  }

  REP(j, m) {
    ll cnt = 0;
    REP(i, n) {
      if (v[i] == w[j]) {
        cnt = 1;
        break;
      }
      if (w[j] < v[i]) {
        cnt++;
      }
    }
    ans *= cnt;
    ans %= MOD;
  }

  ll cnt = 0;

  for (ll i = n * m; i > 0; i--) {
    if (same.lower_bound(i) == same.end() || *same.lower_bound(i) == i) {
      continue;
    }

    ll x = distance(e.lower_bound(i), e.end());
    ll y = distance(s.lower_bound(i), s.end());
    ll sa = distance(same.lower_bound(i), same.end());

    cout << i << " " << x << " " << y << " " << sa << endl;
    ll aa = x * y - sa - cnt;
    if (aa <= 0) {
      cout << 0 << endl;
      return 0;
    }
    ans *= fact[aa];
    ans %= MOD;

    cnt++;
  }
  cout << ans << endl;
}

