const int MOD = ten(9) + 7;
int tbl[ten(6) + 10];
int main() {
	int n, m; reader(n, m);

	FOR(i, n) {
		int x; reader(x); tbl[x] |= 1;
	}
	FOR(i, m) {
		int x; reader(x); tbl[x] |= 2;
	}

	int aUsed = 0, bUsed = 0;
	ll ans = 1;
	for (int v = n * m; v > 0; v--) {
		const int curId = n * m - v;
		if (tbl[v] == 3) {
			aUsed++;
			bUsed++;
		} else if (tbl[v] == 2) {
			ans = ans * aUsed % MOD;
			bUsed++;
		} else if (tbl[v] == 1) {
			ans = ans * bUsed % MOD;
			aUsed++;
		} else {
			int rem = max(aUsed * bUsed - curId, 0);
			ans = ans * rem % MOD;
		}
	}
	writerLn(ans);

	return 0;
}

#ifndef __INTMOD_H__0001__
#define __INTMOD_H__0001__

#include <vector>
