int H, W;
int A[1000];
int B[1000];
int C[1000000];

int P[1000000];
int Q[1000000];

int Appear(int a) {
	if (P[a] == -1 && Q[a] == -1) return 0;
	if (P[a] != -1 && Q[a] != -1) return 1;
	if (P[a] != -1) {
		int cnt = 0;
		REP(i, 0, W) {
			cnt += B[i] >= a;
		}
		return cnt;
	}
	if (Q[a] != -1) {
		int cnt = 0;
		REP(i, 0, H) {
			cnt += A[i] >= a;
		}
		return cnt;
	}
}

int main() {
	cin >> H >> W;
	Fill(P, -1);
	Fill(Q, -1);
	REP(i, 0, H) {
		cin >> A[i];
		--A[i];
		if (P[A[i]] != -1) {
			cout << 0 << endl;
			return 0;
		}
		P[A[i]] = i;
	}
	REP(i, 0, W) {
		cin >> B[i];
		--B[i];
		if (Q[B[i]] != -1) {
			cout << 0 << endl;
			return 0;
		}
		Q[B[i]] = i;
	}

	REP(i, 0, H) {
		REP(j, 0, W) {
			int v = min(A[i], B[j]);
			C[v]++;
		}
	}

	MInt prod = 1;
	int cnt = 0;
	REM(i, 0, H * W) {
		cnt += C[i];
		int v = Appear(i);
		if (v != 0) {
			prod *= v;
		} else {
			prod *= cnt;
		}
		cnt -= 1;
	}
	cout << prod << endl;
	return 0;
}

