			return 0;
		}
		fw (j, 0, i) if (b[i] == b[j]) {
			cout << "0";
			return 0;
		}
	}
	fac[0] = ifac[0] = 1;
	fw (i, 1, N * N) {
		fac[i] = 1ll * fac[i - 1] * i % mod;
		ifac[i] = inv(fac[i]);
	}

	fw (i, 0, n) maxVal[i] = Max(a[i], i, 1);
	fw (i, 0, m) maxVal[i + n] = Max(b[i], i, 0);
	sort(maxVal, maxVal + n + m);

	int ans = 1;
	fw (i, 0, n + m) {
		int id = maxVal[i].id;
//		cout << maxVal[i].maxValue << " " << maxVal[i].id + 1 << " " << maxVal[i].isRow << "\n";
		if (maxVal[i].isRow) {
			bool filledMax = 0;
			fw (j, 0, m) if (b[j] == a[id]) {
				if (!covered[id][j]) {
					covered[id][j] = 1;
					usedNumbers++;
					//Fill this space already.
				}
				filledMax = 1;
				break;
			}
			int cntEmpty = 0;
			fw (j, 0, m) if (!covered[id][j]) cntEmpty++;
			//filledMax = 0 means max should also be taken into consideration of cntEmpty.
//			cout << "usedNumbers = " << usedNumbers << " cntEmpty = " << cntEmpty << "\n";
			int availableNumbers = maxVal[i].maxValue - usedNumbers;
			if (filledMax) {
//				cout << "Available = " << availableNumbers << "\n";
				int cnt = C(availableNumbers, cntEmpty);
				cnt = mul(cnt, fac[cntEmpty]); //Permute
				ans = mul(ans, cnt);
			} else {
				//max must appear, so availableNumbers is decreased by 1.
				int cnt = C(availableNumbers - 1, cntEmpty - 1);
				cnt = mul(cnt, fac[cntEmpty]); //Permute all cntEmpty numbers, including max
				ans = mul(ans, cnt);
			}
			fw (j, 0, m) if (!covered[id][j]) {
				covered[id][j] = 1;
				usedNumbers++;
			}
		} else {
			bool filledMax = 0;
			fw (j, 0, n) if (a[j] == b[id]) {
				if (!covered[j][id]) {
					covered[j][id] = 1;
					usedNumbers++;
				}
				filledMax = 1;
				break;
			}
			int cntEmpty = 0;
			fw (j, 0, n) if (!covered[j][id]) cntEmpty++;
//			cout << "usedNumbers = " << usedNumbers << " cntEmpty = " << cntEmpty << "\n";
			int availableNumbers = maxVal[i].maxValue - usedNumbers;
			if (filledMax) {
//				cout << "Available = " << availableNumbers << "\n";
				int cnt = C(availableNumbers, cntEmpty);
				cnt = mul(cnt, fac[cntEmpty]);
				ans = mul(ans, cnt);
			} else {
				int cnt = C(availableNumbers - 1, cntEmpty - 1);
				cnt = mul(cnt, fac[cntEmpty]);
				ans = mul(ans, cnt);
			}
			fw (j, 0, n) if (!covered[j][id]) {
				covered[j][id] = 1;
				usedNumbers++;
			}
		}
	}
	cout << ans;
	return 0;
}

