  REP(i, n - 1)
  {
    if (a[i] == a[i + 1])
    {
      cout << 0 << endl;
      return 0;
    }
  }

  REP(i, m - 1)
  {
    if (b[i] == b[i + 1])
    {
      cout << 0 << endl;
      return 0;
    }
  }

  ll result = 1;

  for (int i = n * m; i > 0; i--)
  {
    int ai = lower_bound(a, a + n, i) - a;
    int bi = lower_bound(b, b + m, i) - b;

    if (a[ai] == i && b[bi] == i)
    {
      continue;
    }
    if (a[ai] == i)
    {
      result = result * (m - bi) % MOD;
      continue;
    }
    if (b[bi] == i)
    {
      result = result * (n - ai) % MOD;
      continue;
    }
    result = result * ((n - ai) * (m - bi) - (m * n - i)) % MOD;
  }

  cout << result << endl;
  return 0;
}

