int N, M;
int A[1003], B[1003];

void imposs() {
	puts("0");
	exit(0);
}

int main() {
	cin >> N >> M;
	for (int i=1; i<=N; i++) cin >> A[i];
	for (int i=1; i<=M; i++) cin >> B[i];

	sort(A+1, A+N+1); reverse(A+1, A+N+1);
	sort(B+1, B+M+1); reverse(B+1, B+M+1);

	for (int i=1; i<=N-1; i++) if (A[i] == A[i+1]) imposs();
	for (int j=1; j<=M-1; j++) if (B[j] == B[j+1]) imposs();

	int i = 1;
	int j = 1;
	int occupied = 0;
	ll ans = 1;
	for (int v=N*M; v>=1; v--) {
		if (i+1<=N && A[i+1]>=v) i++;
		if (j+1<=M && B[j+1]>=v) j++;

		if (i*j <= occupied) imposs();

		if (A[i]==v && B[j]==v) ans *= 1;
		else if (A[i]==v) ans *= j;
		else if (B[j]==v) ans *= i;
		else ans *= ((i*j)-occupied);

