            bg[j]++;
        } else {
            ag[i]++;
            isFree[lower_bound(c.begin(), c.end(), a[i]) - c.begin()] = false;
        }
    }

    vector<int> cg(c.size(), 0);
    rep(i, n)
    {
        int idx = lower_bound(c.begin(), c.end(), a[i]) - c.begin();
        cg[idx] += ag[i];
    }
    rep(i, m)
    {
        int idx = lower_bound(c.begin(), c.end(), b[i]) - c.begin();
        cg[idx] += bg[i];
    }

    vector<int64_t> fact(n * m + 1);
    irep(i, n * m)
    {
        if (i == 0) {
            fact[i] = 1;
        } else {
            fact[i] = fact[i - 1] * i % MOD;
        }
    }

    int64_t result = 1, used = 0;
    rep(i, c.size())
    {
        int64_t r = c[i] - used;
        //cout << "i=" << i << " c[i]=" << c[i] << " used=" << used << " r=" << r << " cg[i]=" << cg[i] << " free=" << boolalpha << isFree[i]
        //     << " result=" << result << endl;
        if (r < cg[i]) {
            cout << 0 << endl;
            return 0;
        }
        if (isFree[i]) {
            result = result * cg[i] % MOD;
        }
        result = result * (fact[r - 1] * inv(fact[r - 1 - (cg[i] - 1)]) % MOD) % MOD;
        used += cg[i];
    }
    cout << result << endl;
    return 0;
}

