void solve(){
    int i,j;
    string str;
    cin >> n >> m;
    vector<int> a(n),b(m);
    for(i = 0;i < n;i++) cin >> a[i];
    for(i = 0;i < m;i++) cin >> b[i];
    sort(a.begin(),a.end());
    sort(b.begin(),b.end());
    for(i = 1;i < n;i++) if(a[i-1] == a[i]){
