ll fmemo[1000010];
ll fact(ll x) {
	if (fmemo[x] > 0) return fmemo[x];
	if (x == 0) return 1;
	fmemo[x] = (x * fact(x - 1));
	fmemo[x] %= INF;
	return fmemo[x];
}
void solv() {
	ll n, m;
	cin >> n >> m;
	ll a[1010];
	ll ai[1000010];
	ll b[1010];
	ll bi[1000010];
	memset(ai, -1, sizeof(ai));
	memset(bi, -1, sizeof(bi));
	ll cnt = n * m;
	ll cnt2 = n * m;
	for (size_t i = 0; i < n; i++) {
		cin >> a[i];
		ai[a[i]] = i;
	}


	ll tb[1010][1010];
	memset(tb, 0, sizeof(tb));
	ll tc[1000010];
	memset(tc, 0, sizeof(tc));

	for (size_t i = 0; i < m; i++)
	{
		cin >> b[i];
		bi[b[i]] = i;
		if (ai[b[i]] >= 0) {
			tb[ai[b[i]]][bi[b[i]]] = b[i];
			tc[b[i]] = -1;
			cnt--;
			cnt2--;
		}
	}


	// 行を処理
	for (size_t i = 0; i < n; i++)
	{
		ll v = a[i];
		if (bi[v] >= 0) continue;

		for (size_t j = 0; j < m; j++)
		{
			if (v <= b[j]) {
				tc[v]++;
				tb[i][j] = v;
				cnt--;
			}
		}
	}

	// 列を処理
	for (size_t i = 0; i < m; i++)
	{
		ll v = b[i];
		if (ai[v] >= 0) continue;

		for (size_t j = 0; j < n; j++)
		{
			if (v <= a[j]) {
				tc[v]++;
				tb[i][j] = v;
				cnt--;
			}
		}
	}

	ll rem = 0;
	ll res = 1;
	ll mc = 0;
	for (ll i = 1; i <= n * m; i++)
	{
		ll cn = tc[i];
		if (cn == 0) {
			mc++;
			continue;
		}
		if (cn == -1) continue;
		res *= cn;
		res %= INF;
		ll rv = mc + rem;
		rem = rv - (cn - 1);
		res *= COM(rv, cn - 1);
		res %= INF;
		res *= fact(cn - 1);
		res %= INF;
		mc = 0;
	}


