//階乗とその逆元
ll fac[MAX + 1], facInv[MAX + 1];

ll power(ll e, ll x)
{ //e^x % MOD
	if (x == 0)
		return 1LL;
	if (x % 2 != 0)
		return ((power(e, x - 1) * e) % MOD);
	ll temp = power(e, x / 2);
	return (temp * temp) % MOD;
}

ll nck(ll n, ll k)
{
	if (!(n >= k && k >= 0))
		return 0;
	ll temp = (fac[n] * facInv[n - k]) % MOD;
	return ((temp * facInv[k]) % MOD);
}

void fact(void)
{
	//階乗とその逆元
	fac[0] = facInv[0] = 1; //0! = 1
	//(x!)^(-1) ≡ (x!)^(p-2) (mod p)
	Rep(1, MAX, i) fac[i] = (fac[i - 1] * i) % MOD;
	facInv[MAX] = power(fac[MAX], MOD - 2);
	Rep(1, MAX - 1, i) facInv[MAX - i] = (facInv[MAX - i + 1] * (MAX - i + 1)) % MOD;
}

void solve()
{
	int N, M;
	cin >> N >> M;
	vector<long> as(N), bs(M);
	for (int i = 0; i < N; i++) cin >> as[i];
	for (int i = 0; i < M; i++) cin >> bs[i];

	sort(as.begin(), as.end());
	sort(bs.begin(), bs.end());

	//reverse(as.begin(), as.end());
	//reverse(bs.begin(), bs.end());
	//cout << as << endl;
	//cout << bs << endl;


	fact();

	long ans = 1;

	for (int i = 0; i < N; i++)
	{
		long pre = M, lat = 0, f = 0;
		for (int j = 0; j < M; j++)
		{
			if (bs[j] < as[i])
			{
				pre = j + 1;
				lat = M - pre;
			}
			else if (bs[j] == as[i])
			{
				pre = j+1;
				lat = M - pre;
				pre--;
				f = 1;
			}
		}
		//cout << pre << ' ' << lat << endl;
		long pc = as[i] - M * i + 1;
		//cout << pc << ' ' << lc << endl;
		ans *= nck(pre, pc+1);
		ans %= MOD;
		ans *= nck(lat, pc+1);
		ans %= MOD;
	}

	cout << ans << endl;

}

int main(void)
{
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

