int main() {
  int n, m;
  cin>>n>>m;
  int a[n], b[m];
  for (int i=0; i<n; i++) cin>>a[i];
  for (int i=0; i<m; i++) cin>>b[i];

  sort(a, a + n);
  sort(b, b + m);

  set<int> sa(a, a + n);
  if (sa.size() != n) {
    cout<<0<<endl;
    return 0;
  }
  set<int> sb(b, b + m);
  if (sb.size() != m) {
    cout<<0<<endl;
    return 0;
  }
  vector<int> unused;
  for (int i=1; i<=n*m; i++) {
    if (sa.find(i) == sa.end() && sb.find(i) == sb.end()) {
      unused.push_back(i);
    }
  }

  int d[n][m];
  for (int i=0; i<n; i++) {
    for (int j=0; j<m; j++) {
      d[i][j] = -1;
    }
  }
  int i = 0, j = 0;
  while (i < n && j < m) {
    if (a[i] == b[j]) {
      d[i][j] = a[i];
      ++i;
      ++j;
    } else if (a[i] < b[j]) {
      d[i][j] = a[i];
      ++i;
    } else {
      d[i][j] = b[j];
      ++j;
    }
  }

  int max_row[n];
  for (int i=0; i<n; i++) {
    int tmp = -1;
    for (int j=0; j<m; j++) {
      tmp = max(d[i][j], tmp);
    }
    max_row[i] = tmp;
  }
  int max_col[m];
  for (int i=0; i<m; i++) {
    int tmp = -1;
    for (int j=0; j<n; j++) {
      tmp = max(d[j][i], tmp);
    }
    max_col[i] = tmp;
  }
  map<int, int> cnt;
  for (int i=0; i<n; i++) {
    for (int j=0; j<m; j++) {
      if (d[i][j] != -1) {
        continue;
      }
      ++cnt[min(max_row[i], max_col[j])];
    }
  }
  // cout<<"cnt"<<endl;
  // int sum = 0;
  // for (auto i: cnt) {
  //   cout<<i.first<<" "<<i.second<<endl;
  //   sum += i.second;
  // }
  // cout<<"sum"<<sum<<endl;
  // cout<<"cnt"<<endl;
  long long mod = 1e9 + 7;
  long long ans = 1;
  int acc = 0;
  for (int i=n*m; i>0; i--) {
    if (sa.find(i) != sa.end() && sb.find(i) != sb.end()) {
      acc += cnt[i];
      continue;
    }
    if (cnt.find(i) != cnt.end()) {
      acc += cnt[i];
      ans *= cnt[i] + 1;
      ans %= mod;
    } else {
      ans *= acc;
      ans %= mod;
      --acc;
    }
  }
  cout<<ans<<endl;
}

