using namespace std;

const int MOD = 1000000007;

int solve(const vector<int>& A, const vector<int>& B){
    const int N = A.size();
    const int M = B.size();
    int cntA = 0;
    int cntB = 0;
    int rest = 0;
    long long res = 1;
    for(int i=N*M;i>=1;i--){
        bool checkA = (cntA < N && A[N-1-cntA] == i);
        bool checkB = (cntB < M && B[M-1-cntB] == i);
        if(checkA && checkB){
            rest += cntA + cntB;
            ++cntA;
            ++cntB;
        } else if(checkA){
            res = (cntB * res) % MOD;
            rest += cntB - 1;
            ++cntA;
        } else if(checkB){
            res = (cntA * res) % MOD;
            rest += cntA - 1;
            ++cntB;
        } else {
            if(rest <= 0) return 0;
            res = (rest * res) % MOD;
            --rest;
        }
    }
    return (int)res;
}

int main(){
    int N, M;
    while(cin >> N >> M){
