int N, M;
vector<int> A, B;

long long solve() {
    long long res = 1;
    int biggerX_a = 0, biggerX_b = 0; // A, B で x より大きいのが何個あるか
    for (int x = N*M; x >= 1; --x) {
        if (A[biggerX_a] > x) return 0;
        if (B[biggerX_b] > x) return 0;

        long long tmp = 1;
        if (A[biggerX_a] == x && B[biggerX_b] == x) {
            tmp = 1;
            ++biggerX_a, ++biggerX_b;
        }
        else if (A[biggerX_a] == x) {
            tmp = biggerX_b;
            ++biggerX_a;
        }
        else if (B[biggerX_b] == x) {
            tmp = biggerX_a;
            ++biggerX_b;
        }
        else {
            tmp = biggerX_a * biggerX_b - (N * M - x);
            if (tmp <= 0) return 0;
        }
        res = (res * tmp) % MOD;
    }
    return res;
}
