long long combination(int n, int r){
  ll tmp = fact[n];
  ll tmp2 = modmul(fact[n-r], fact[r]);
  tmp = modmul(tmp, getinv(tmp2));
  return tmp;
}

long long get_count(int i, vector<int> & col, int &not_decided){
  auto itr = upper_bound(col.begin(), col.end(), i);
  if (itr == col.end())return 0; // imposible
  int pos = col.size() - (itr - col.begin());

  if (not_decided < pos-1)return 0;
  long long tmp2 = combination(not_decided, pos-1);
  tmp2 = modmul(tmp2, fact[pos]);
  long long ret = tmp2;
  not_decided -= (pos-1);
  return ret;
}

