	rep(i, n - 1)if (a[i] == a[i + 1])ans *= 0;
	rep(i, m - 1)if (b[i] == b[i + 1])ans *= 0;
	for (int i = n*m; i >=1; i--) {
		auto nl = lower_bound(a.begin(), a.end(), i);
		auto ml = lower_bound(b.begin(), b.end(), i);
		int N = nl - a.begin();
		int M = ml - b.begin();

		if (*nl == i&&*ml == i) {
			rwa.update(N+1, M+1 , 1);
		}
		else if (*nl == i) {
		//(N,M)~(N,m-1)
			ans *= (m - M) - rwa.qsum(N + 1, M + 1, N + 1, m);
			rwa.update(N + 1, m, 1);
		}
		else if (*ml == i) {
		//(N,M)~(n-1,M)
			ans *= (n - N) - rwa.qsum(N+1,M+1,n,M+1);
			rwa.update(n, M + 1, 1);
		}
		else {
		//(N,M)~(n-,m-)
			ans *= (n - N)*(m - M) - (n*m-i);
			rwa.update(n, m, 1);
		}

		ans %= mod;
	}

	cout << ans << endl;
}

