    for (ll i = 1; i < MAX_SIZE; i++) fac[i] = fac[i - 1] * i % MOD;
    finv[0] = modpow(fac[MAX_SIZE - 1], MOD - 2, MOD);
    repe(i, 1, MAX_SIZE) finv[i] = finv[i - 1] * (MAX_SIZE - i) % MOD;
    reverse(all(finv));

    //inv init
    repe(i, 1, MAX_SIZE) inv[i] = modpow(i, MOD - 2, MOD);
}

ll perm(ll a, ll b) { return fac[a] * finv[a - b] % MOD; }

ll comb(ll a, ll b) { return fac[a] * finv[b] % MOD * finv[a - b] % MOD; }

int main() {
    init();
    fac_init();
    ll N, M;
    cin >> N >> M;
    vl A(N), B(M);
    rep(i, N) cin >> A[i];
    rep(i, M) cin >> B[i];
    sort(all(A),greater<ll>()), sort(all(B),greater<ll>());
    rep(i,N-1){
        if(A[i]==A[i+1]){
            cout << 0 << endl;
            return 0;
        }
    }
    rep(i,M-1){
        if(B[i]==B[i+1]){
            cout << 0 << endl;
            return 0;
        }
    }

    ll ai = 0, bi = 0, now = N * M;
    ll ans = 1, ncnt = 0, mcnt = 0;
    while(now){
        ll isa = false, isb = false;
        if (ai < N && now == A[ai]) isa = true, ai++;
        if (bi < M && now == B[bi]) isb = true, bi++;

        if(isa&&isb){
            ncnt++, mcnt++;
        }else if(isa){
            ans *= mcnt;
            ans %= MOD;
            ncnt++;
        }else if(isb){
            ans *= ncnt;
            ans %= MOD;
            mcnt++;
        }else{
            ans *= ncnt * mcnt - (N * M - now);
            ans %= MOD;
        }

        now--;
    }

    cout << ans << endl;
}

