    vector<ll> a(n),b(m);
    for(int i=0;i<n;i++){cin>>a[i];}
    for(int i=0;i<m;i++){cin>>b[i];}
    sort(a.begin(),a.end(),greater<ll>());
    sort(b.begin(),b.end(),greater<ll>());
    ll ans=1;
    ll A=0,B=0;
    ll used=0;
    ll mx=n*m;
    vector<ll> CA(n,0);
    vector<ll> CB(m,0);
    while(A<n || B<m){
        ll rem=A*B-used;
        //cout<<rem<<" "<<a[A]<<" "<<b[B]<<" "<<A<<" "<<B<<" "<<ans<<" "<<used<<endl;
        if(A<n && B<m){
            if(mx!=max(a[A],b[B])){
                if(mx-max(a[A],b[B])<0){ans=0; break;}
                ans*=C.c(rem,mx-max(a[A],b[B]))*C.F[mx-max(a[A],b[B])]%MOD;
                ans%=MOD;
                used+=mx-max(a[A],b[B]);
                mx=max(a[A],b[B]);
            }
            else if(a[A]==b[B]){
                CA[A]--;
                CB[B]--;
                used++;
                A++; B++;
                mx--;
            }
            else if(a[A]>b[B]){
                used++;
                ll cnt=B+CA[A];
                (ans*=cnt)%=MOD;
                mx--;
                A++;
            }
            else{
                used++;
                ll cnt=A+CB[B];
                (ans*=cnt)%=MOD;
                mx--;
                B++;
            }
        }
        else if(A<n){
            if(a[A]!=mx){
                if(mx-a[A]<0){ans=0; break;}
                ans*=C.c(rem,mx-a[A])*C.F[mx-a[A]]%MOD;
                ans%=MOD;
                used+=mx-a[A];
                mx=a[A];
                continue;
            }
            used++;
            ll cnt=B+CA[A];
            (ans*=cnt)%=MOD;
            mx--;
            A++;
        }
        else{
            if(b[B]!=mx){
                if(mx-b[B]<0){ans=0; break;}
                ans*=C.c(rem,mx-b[B])*C.F[mx-b[B]]%MOD;
                used+=mx-b[B];
                ans%=MOD;
                mx=b[B];
                continue;
            }
            used++;
            ll cnt=A+CB[B];
            (ans*=cnt)%=MOD;
            mx--;
            B++;
        }
    }
    //cout<<mx<<endl;
    ans*=C.F[mx];
    ans%=MOD;
    if(ans<0){ans+=MOD;}
    cout<<ans%MOD<<endl;



    return 0;
}

