vector<int> mustRow;
vector<int> mustCol;
int N,M;

int search(int next,vector<int> canRow,vector<int> canCol,bitset<1000000> table){
    if(next==N/2)return 1;
    int sum=0;
    for(int i=0;i<N;i++){
        if(canRow[i]>=next){
            for(int j=0;j<M;j++){
                if(mustRow[i]==next&&mustCol[j]==next){
                    vector<int> newCanRow(canRow);
                    vector<int> newCanCol(canCol);
                    bitset<1000000> newTable;
                    newTable=table;
                    newCanRow[i]=next-1;
                    newCanCol[j]=next-1;
                    newTable[M*i+j]=true;
                    return search(next-1,newCanRow,newCanCol,newTable);
                }
                if(canCol[j]>=next&&!table[M*i+j]){
                    vector<int> newCanRow(canRow);
                    vector<int> newCanCol(canCol);
                    bitset<1000000> newTable;
                    newTable=table;
                    newCanRow[i]=next-1;
                    newCanCol[j]=next-1;
                    newTable[M*i+j]=true;
                    sum+=search(next-1,newCanRow,newCanCol,newTable);
                }   
            }
        }
    }
    if(sum==0){
        cout<<0<<endl;
        exit(0);
    }
    return sum;
}
