        A[i] = 0;
    }
    rep(i, M+1) {
        B[i] = 0;
    }
    rep(i, N) {
        cin >> A[i];
        if (cnt_A[A[i]] > 0) flag = false;
    }
    rep(i, M) {
        cin >> B[i];
        if (cnt_B[B[i]] > 0) flag = false;
    }

    if (!flag) {
        cout << 0 << endl;
        return 0;
    }

    sort(A, A+N);
    reverse(A, A+N);
    sort(B, B+N);
    reverse(B, B+N);

    ll ans=1;
    ll a_cur=0, b_cur=0;
    for (ll i=N*M; i>=1; i--) {
        if (A[a_cur] == i && B[b_cur] == i) {
            ans = ans * 1;
            a_cur++;
            b_cur++;
        } else if (A[a_cur] == i) {
            ans = (ans % mod) * (b_cur % mod);
            ans %= mod;
            a_cur++;
        } else if (B[b_cur] == i) {
            ans = (ans % mod) * (a_cur % mod);
            ans %= mod;
            b_cur++;
        } else {
            if (a_cur*b_cur > (N*M-i)) {
                ans = (ans % mod) * ((a_cur*b_cur - (N*M-i)) % mod);
                ans %= mod;
            } else {
                cout << 0 << endl;
                return 0;
            }

        }
    }

    cout << (ans % mod) << endl;

    return 0;
}

