	for(int i=0; i<M; i++) cin >> B[i];

	set<int> am, bm;
	for(int i=0; i<N; i++){
		if(am.count(A[i])){
			cout << 0 << endl;
			return 0;
		}
		am.insert(A[i]);
	}
	for(int i=0; i<M; i++){
		if(bm.count(B[i])){
			cout << 0 << endl;
			return 0;
		}
		bm.insert(B[i]);
	}
	int n_done = 0, m_done = 0;
	ll ans = 1;

	for(int i=N*M; i>0; i--){
		if(am.count(i)>0&&bm.count(i)>0){
			if(n_done==N||m_done==M){
				ans = 0;
			} else {
				n_done++;
				m_done++;
			}
		} else if(am.count(i)>0){
			if(n_done==N){
				ans = 0;
			} else {
				ans *= m_done;
				ans %= P;
				n_done++;
			}
		} else if(bm.count(i)>0){
			if(m_done==M){
				ans = 0;
			} else {
