const int M = 1000000007;

signed main() {
	int n, m;
	cin >> n >> m;
	vector<int> a(n), b(m);
	cin >> a >> b;

	{
		set<int> st(all(a));
		if (st.size() != a.size()) {
			cout << 0 << endl;
			return 0;
		}
	}
	{
		set<int> st(all(b));
		if (st.size() != b.size()) {
			cout << 0 << endl;
			return 0;
		}
	}

	sort(all(a));
	sort(all(b));

	int ans = 1;
	for (auto i : a) {
		auto it = lower_bound(all(b), i);
		if (*it == i) continue;
		(ans *= distance(it, b.end())) %= M;
	}
	for (auto i : b) {
		auto it = lower_bound(all(a), i);
		if (*it == i) continue;
		(ans *= distance(it, a.end())) %= M;
	}

	int unique[1005][1005] = {};
	{
		set<int> a_s;
		for (int i = n - 1; i >= 0; i--) {
			a_s.emplace(a[i]);

			set<int> ab_s(a_s);
			for (int j = m - 1; j >= 0; j--) {
				ab_s.emplace(b[j]);
				unique[i][j] = ab_s.size();
			}
		}
	}

	set<int> s;
	int used = 0;
	for (auto i : a) s.emplace(i);
	for (auto i : b) s.emplace(i);
	for (int i = n * m; i >= 1; i--) {
		if (s.count(i)) continue;
		auto dis_a = distance(lower_bound(all(a), i), a.end());
		auto dis_b = distance(lower_bound(all(b), i), b.end());
		(ans *= dis_a * dis_b - unique[n- dis_a][m-dis_b] - used) %= M;
		used++;
	}
	cout << ans << endl;
}

