class DDoubleLandscape {
public:
    int N, M;
    vl A, B;

    void input(std::istream& in, std::ostream& out){
        ios_base::sync_with_stdio(false);
        in>>N>>M;
        A = vl(N*M+1, 0), B = vl(N*M+1, 0);
        REP(i, N){
            int a;
            in>>a;
            a--;
            A[a]++;
        }
        REP(i, M){
            int b;
            in>>b;
            b--;
            B[b]++;
        }
    }

    void solve(std::istream& in, std::ostream& out){
        input(in, out);
        mint ans = 1;
        for(int i=N*M-1;0<=i;i--){
            if(A[i]>1 or B[i]>1){
                out<<"0\n";
                return;
            }else if(A[i]==1 and B[i]==1){
                A[i] += A[i+1], B[i] += B[i+1];
                continue;
            }else if(A[i]==1 and B[i]==0){
                ans *= B[i+1];
                A[i] += A[i+1], B[i] += B[i+1];
            }else if(A[i]==0 and B[i]==1){
                ans *= A[i+1];
                A[i] += A[i+1], B[i] += B[i+1];
            }else{
                A[i] += A[i+1], B[i] += B[i+1];
                ans *= A[i] * B[i] - N * M + i + 1;
            }
        }
        out<<ans<<'\n';
    }
};


int main() {
	DDoubleLandscape solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

