long long mod = 1000000007;

int main(){
  int n,m;
  cin >> n >> m;

  vector<int> a(n),b(m);

  for(int i = 0;i < n;i++){
    cin >> a[i];
  }

  sort(a.begin(),a.end(),greater<int>());

  for(int i = 0;i < m;i++){
    cin >> b[i];
  }

  sort(b.begin(),b.end(),greater<int>());

  int acnt = 0,bcnt = 0;
  int choice = 0;
  long long ret = 1;

  for(int i = m*n;i >= 1;i--){
    if(acnt == n && bcnt == m){
      for(int j = i;j >= 1;j--){
	ret = (ret*j) % mod;
      }
      break;
    }
    if(a[acnt] == i){
      acnt++;
      if(b[bcnt] == i){
	bcnt++;
      }else{
	if(bcnt == 0){
	  ret = 0;
	  break;
	}
	choice += bcnt-1;
	ret = (ret*bcnt) % mod;
      }
    }else if(b[bcnt] == i){
      bcnt++;
      if(acnt == 0){
	ret = 0;
	break;
      }
      choice += acnt-1;
      ret = (ret*acnt) % mod;
    }else{
      if(choice <= 0){
	ret = 0;
	break;
      }
      ret = (ret*choice) % mod;
      choice -= 1;
    }
  }

  cout << ret << endl;
}

