    long long ans = 1;
    int i = N, j = M;
    for (int k = N * M; k > 0; k--) {
        if(A[i] == k + 1 || B[j] == k + 1) {
            ans = 0;
            break;
        }

        if (A[i] == k && B[j] == k) {
            i--;
            j--;
            continue;
        } else if (A[i] == k) {
            ans *= M - j;
            i--;
        } else if (B[j] == k) {
            ans *= N - i;
            j--;
        }  else {
            ans *= (N - i) * (M - j) - (N * M - k);
        }
        ans %= mod;
    }
    cout << ans << endl;
