#define MOD 1000000007

int main(void) {
  int N, M;
  cin >> N >> M;

  VI a(N), b(M);
  int Aappear[N*M];
  int Bappear[N*M];

  // initialize
  for (int i=0; i<N*M; i++) {
    Aappear[i] = 0;
    Bappear[i] = 0;
  }

  long long ans = 1;

  for (int i=0; i<N; i++) {
    cin >> a[i];
    if (Aappear[a[i]-1] != 0) {
      ans = 0;
    }
    Aappear[a[i]-1]++;
  }
  for (int i=0; i<M; i++) {
    cin >> b[i];
    if (Bappear[b[i]-1] != 0) {
      ans = 0;
    }
    Bappear[b[i]-1]++;
  }

  sort(a.begin(), a.end(), greater<int>());
  sort(b.begin(), b.end(), greater<int>());

  int Asmaller = 0;
  int Bsmaller = 0;

  if (ans != 0) {
    for (int i=N*M; i>0; i--) {
      if (Aappear[i-1] && Bappear[i-1]) {
        ans *= 1;
      } else if (Aappear[i-1] || Bappear[i-1]) {
        if (Aappear[i-1] == 1) {
          for (int j=Bsmaller; j<M; j++) {
            if(b[j] > i) {
              Bsmaller++;
            } else {
              break;
            }
          }
          ans *= Bsmaller;
        } else if (Bappear[i-1] == 1) {
          for (int j=Asmaller; j<N; j++) {
            if (a[j] > i) {
              Asmaller++;
            } else {
              break;
            }
          }
          ans *= Asmaller;
        }
      } else {
        for (int j=Asmaller; j<N; j++) {
          if (a[j] > i) {
            Asmaller++;
          } else {
            break;
          }
        }
        for (int k=Bsmaller; k<M; k++) {
          if (b[k] > i) {
            Bsmaller++;
          } else {
            break;
          }
        }
        long long count = Asmaller * Bsmaller;
        count -= M*N-i;

        ans *= count;
      }
      ans %= MOD;
    }
  }

  cout << ans << endl;

  return 0;

}

