LL N, M;
LL A[1005], B[1005];

LL factorials[1000005], inverseFactorials[1000005];

LL binaryPower(LL a, LL n) {
	if (n == 0)
		return 1;
	LL tmp = binaryPower(a, n >> 1);

	tmp = (tmp * tmp) % Mod;
	if (n & 1)	tmp *= a;
	return tmp % Mod;
}

void precalculation() {
	F(i, 0, 1000001) {
		if (i == 0)	factorials[0] = 1;
		else		factorials[i] = ((i * 1LL) * factorials[i - 1]) % Mod;

		inverseFactorials[i] = binaryPower(factorials[i], Mod - 2);
	}
}

LL C(LL n, LL k) {
	if (k == 0)
		return 1;
	if (n < k)
		return 0;
	return (factorials[n] * inverseFactorials[n - k]) % Mod;
}

void input()
{
	cin >> N >> M;
	F(i, 0, N)
		cin >> A[i];

	F(i, 0, M)
		cin >> B[i];
}

void solve()
{
	sort(A, A + N);
	sort(B, B + M);

	LL ans = 1, largest = 0;
	int i = 0, j = 0, filled = 0;
	while (i < N || j < M) {
		filled = (i * M + j * N - i * j);
		if (j == M || A[i] < B[j]) {
			if (A[i] == largest)
				ans = 0;
			ans = ((N - j) * (ans * C(A[i] - filled - 1, N - j - 1)) % Mod) % Mod;
			largest = A[i];
			i++;
		}
		else if (i == N || A[i] > B[j]) {
			if (B[j] == largest)
				ans = 0;
			ans = ((M - i) * (ans * C(B[j] - filled - 1, M - i - 1)) % Mod) % Mod;
			largest = B[j];
			j++;
		}
		else {
			if (largest == A[i])
				ans = 0;
			ans = (ans * C(A[i] - filled - 1, M + N - i - j - 2)) % Mod;
			largest = A[i];
			i++;
			j++;
		}
	}
	cout << ans << endl;
}	

