    }

    GF<mod> ans = 1;
    ll cnt = 0;
    ll i = 0, j = 0;
    while (cnt < n * m) {
        if (a[i] == b[j]) {
            if (a[i] - 1 - cnt < (n - i - 1) + (m - j - 1)) {
                cout << 0 << endl;
                return 0;
            }
            ans *= GF<mod>::nCr(a[i] - 1 - cnt, (n - i - 1) + (m - j - 1));
            ans *= GF<mod>::fact((n - i - 1) + (m - j - 1));
            cnt += (n - i - 1) + (m - j - 1) + 1;
            i++;
