        } else {
            if (b[j] - 1 - cnt < n - i - 1) {
                cout << 0 << endl;
                return 0;
            }
            ans *= GF<mod>::nCr(b[j] - 1 - cnt, n - i - 1);
            ans *= GF<mod>::fact(n - i);
            cnt += n - i;
            j++;
        }
    }

    cout << ans.v << endl;
