		int64_t ai;
		cin >> ai;
		a.push_back(ai);
	}
	for (int i = 0; i < m; ++i) {
		int64_t bi;
		cin >> bi;
		b.push_back(bi);
	}
	sort(a.rbegin(), a.rend());
	sort(b.rbegin(), b.rend());
	vector<vector<int64_t>> field(n, vector<int64_t>(m, 0));
	if (a[0] != n * m || b[0] != n * m) {
		cout << "0" << endl;
		return 0;
	}
	int w, h;
	w = h = 1;
	int64_t filled = 1;
	int64_t pat = 1;
	int64_t plc = n * m - 1;
	for(int64_t plc=n*m-1; plc>0 ; plc--){
		int64_t next_ylim;
		if (h == n) next_ylim = -1;
		else next_ylim = a[h];
		int64_t next_xlim;
		if (w == m) next_xlim = -1;
		else next_xlim = b[w];
		if (plc > max(next_ylim, next_xlim)) {
			int64_t cpat = max(w*h - filled, 0LL);
			pat = (pat * cpat) % MOD;
			filled++;
		}
		else if (plc == next_ylim && plc > next_xlim) {
			h++;
			pat = (pat*w) % MOD;
			filled++;
		}
		else if (plc == next_xlim && plc > next_ylim) {
			w++;
			pat = (pat*h) % MOD;
			filled++;
		}
		else if (plc == next_xlim && plc == next_ylim) {
			filled++;
			w++;
			h++;
		}
		else {
			pat = 0;
		}
		if (pat == 0) break;
	}
	cout << pat << endl;
	return 0;
