ll perm(ll n,ll k){
  ll result=1;
  for(int i=0;i<k;i++){
    result*=n-i;
    result%=MOD;
  }
  return result;
}

ll solve(){
  sort(a+1,a+N+1);
  sort(b+1,b+M+1);
  if(a[N]!=N*M || b[M]!=N*M) return 0;
  for(int n=2;n<=N;n++) if(a[n-1]==a[n]) return 0;
  for(int m=2;m<=M;m++) if(b[m-1]==b[m]) return 0;
  for(int m=1;m<=M;m++) if(b[m]<N*m) return 0;
  for(int n=1;n<=N;n++) if(a[n]<M*n) return 0;

  ll result=1;
  {
    int n=1,m=1;
    int k,used=0;
    while(n<N||m<M){
      if(a[n]==b[m]){
	k=(N-n)+(M-m);
	//cout<<a[n]<<" "<<b[m]<<" "<<k<<" "<<used<<endl;
	if(a[n]-1-used<k)return 0;
	result*=perm(a[n]-1-used,k);
	result%=MOD;
	used+=k+1;
	n++;m++;
      }else if(a[n]<b[m]){
	k=M-m+1;
	//cout<<a[n]<<" "<<b[m]<<" "<<k<<" "<<used<<endl;
	if(a[n]-used<k)return 0;
	result*=perm(a[n]-used,k);
	result%=MOD;
	used+=k;
	n++;
      }else{//a[n]>b[m]
	k=N-n+1;
	//cout<<a[n]<<" "<<b[m]<<" "<<k<<" "<<used<<endl;
	if(b[m]-used<k)return 0;
	result*=perm(b[m]-used,k);
	result%=MOD;
	used+=k;
	m++;
      }
      //cout<<result<<endl;
    }
  }

  return result;
}

int main(){ _;
  cin>>N>>M;
  REP(n,N)cin>>a[n+1];
  REP(m,M)cin>>b[m+1];
  cout<<solve()<<endl;
}

