const lli SIZE = 1000001;
const lli mod = 1e9 + 7;

lli fact[SIZE];
void fact_init() {
  fact[0] = 1;
  for (lli i=1; i<SIZE; ++i) {
    fact[i] = i * fact[i-1] % mod;
  }
}

lli inv(lli x) {
  lli y = 1;
  for (lli n = mod - 2; n > 0; n >>= 1) {
    if (n & 1) y = y * x % mod;
    x = x * x % mod;
  }
  return y;
}

lli perm(lli a, lli b) {
  return fact[a] * inv(fact[a-b]) % mod;
}

lli n, m;
vector<lli> a, b;
int main() {
  fact_init();

  cin >> n >> m;
  read_n(a, n); read_n(b, m);
  sort(begin(a), end(a), greater<lli>());
  sort(begin(b), end(b), greater<lli>());
  a.push_back(0); b.push_back(0);
  if (a[0] != b[0]) { cout << 0 << endl; return 0; }

  lli ans = 1, space = 0, past = a[0];
  for (lli i=0, j=0; ; ) {
    // cout << a[i+1] << ' ' << b[j+1] << endl;
    if (a[i+1] == b[j+1]) {
      ++i; ++j;
      lli t = past - a[i] - 1;
      if (t > space) { cout << 0 << endl; return 0; }
      ans = (ans * perm(space, t)) % mod;
      space = space + i + j - t;
      past = a[i];
    } else if (a[i+1] > b[j+1]) {
      ++i;
      lli t = past - a[i] - 1;
      if (t > space) { cout << 0 << endl; return 0; }
      ans = (ans * perm(space, t)) % mod;
      space = space + j - t;
      past = a[i];
    } else {
      ++j;
      lli t = past - b[j] - 1;
      if (t > space) { cout << 0 << endl; return 0; }
      ans = (ans * perm(space, t)) % mod;
      space = space + i - t;
      past = b[j];
    }
    // cout << i << ' ' << j << ' ' << a[i] << ' '<< b[j] << ' ' << space << endl;
    // cout << ans << endl;
    if (a[i+1] == 0 && b[j+1] == 0) break;
  }
  ans = (ans * fact[space]) % mod;
  cout << ans << endl;
  return 0;
}

