	ll res = 1;

	unordered_map<ll,int> mp;
	rep(i,N) {
		mp[A[i+1].fi]++;
		if(mp[A[i+1].fi] >= 2)
			res = 0;
	}
	mp.clear();
	rep(i,M) {
		mp[B[i+1].fi]++;
		if(mp[B[i+1].fi] >= 2)
			res = 0;
	}
	while(res && A.size()+B.size() > 2) {
		bool a, b;
		a = b = false;
		if(A.back().fi == B.back().fi)
			a = b = true;
		else if(A.back().fi < B.back().fi)
			a = true;
		else
			b = true;

		int c = 0;
		int n = 0;
		if(a) {
			c += B.size()-1;
			n = A.back().fi;
			A.pop_back();
		}
		if(b) {
			c += A.size()-1;
			n = B.back().fi;
			B.pop_back();
		}
		if(n < x+c) {
			res = 0;
		}
		else {
			res = res * choose((n-1)-x, c-1) % mod;
			if(a && !b)
				res = res * (B.size()-1) % mod;
			else if(!a && b)
				res = res * (A.size()-1) % mod;
			x += c;
		}
	}
	cout << res << endl;
	return 0;
}

