    for (ll i = n * m; i >= 1; --i) {
        ll x = (r.count(i) ? r[i] : -1), y = (c.count(i) ? c[i] : -1);
        // Problem definitely lies within the single row/col condition
        if (x >= 0 && y >= 0) {
            ++rd, ++cd;
