// Double Landscape
const int64_t mod = 1e9 + 7;

int64_t factorial[1000001];
int64_t mod_pow(int64_t x, int64_t n) {
  if (n % 2 == 0) {
    if (n == 0) {
      return 1;
    } else {
      int64_t tmp = mod_pow(x, n / 2);
      return (tmp * tmp) % mod;
    }
  } else {
    return (x * mod_pow(x, n - 1)) % mod;
  }
}
int64_t solve(int64_t place, int64_t number) {  // number個をplaceに並べる並べ方
  return number >= place ? (factorial[number] * mod_pow(factorial[number - place], mod - 2)) % mod : 0;
}
int main() {
  int64_t N, M;
  cin >> N >> M;
  vector<int64_t> A(N), B(M);
  for (int64_t i = 0; i < N; i++) {
    cin >> A[i];
  }
  for (int64_t j = 0; j < M; j++) {
    cin >> B[j];
  }
  sort(A.begin(), A.end());
  A.push_back(0);
  A.push_back(0);
  A.erase(unique(A.begin(), A.end()));
  A.pop_back();
  sort(B.begin(), B.end());
  B.push_back(0);
  B.push_back(0);
  B.erase(unique(B.begin(), B.end()));
  B.pop_back();
  factorial[0] = 1;
  for (int i = 1; i <= 1000000; i++) {
    factorial[i] = (factorial[i - 1] * i) % mod;
  }
  int64_t ans = 1;
  if (A.size() != N || B.size() != M) {
    cout << 0 << endl;
    return 0;
  }
  int64_t x = 0;     // Aをどこまで片付けたか
  int64_t y = 0;     // Bをどこまで片付けたか
  int64_t used = 0;  // これまで埋めた数字の数
  while (x < N && y < M) {
    // cout << x << ' ' << y << endl;
    // cout << A[x] << ' ' << B[y] << endl;
    if (A[x] < B[y]) {
      ans = (ans * solve(M - y - 1, A[x] - used - 1) % mod * (M - y)) % mod;
      used += M - y;
      x++;
    } else if (A[x] > B[y]) {
      ans = (ans * solve(N - x - 1, B[y] - used - 1) % mod * (N - x)) % mod;
      used += N - x;
      y++;
    } else {  // A[x]==B[y]
      ans = (ans * solve(M + N - x - y - 2, A[x] - used - 1)) % mod;
      used += M + N - x - y - 1;
      x++;
      y++;
    }
    if (ans == 0) break;
  }
  cout << ans << endl;
  return 0;
}

