  long long int A[MAX_N], B[MAX_N];
  long long int ans = 1;
  long long int MODP = 1000000007;
  cin >> N >> M;
  for(int i = 0; i < N; i++){
    cin >> A[i];
  }
  for(int i = 0; i < M; i++){
    cin >> B[i];
  }
  for(int i = 0; i < M*N; i++){
    grid[i] = 0;
  }
