    cin >> N >> M;
    for(int i=0;i<N;i++){
        cin >> A[i];
    }
    for(int i=0;i<M;i++){
        cin >> B[i];
    }

    descendOrder(N, A);
    descendOrder(M, B);

    for(int i=1;i<N;i++){
        if(A[i-1]==A[i]){
            cout << 0;
            return 0;
        }
    }
    for(int i=1;i<M;i++){
        if(B[i-1]==B[i]){
            cout << 0;
            return 0;
        }
    }
    long count = 1;
    long a = 0,b = 0;
    for(long i=N*M;i>0;i--){
        int p,q;
        if(a==N){ p=0; }
        else{ p=A[a]; }
        if(b==M){ q=0; }
        else{ q=B[b]; }

        if(i==p && i==q){
            a++;
            b++;
        }
        else if(p==i){
            count *= b;
            count %= mod;
            a++;
        }
        else if(q==i){
            count *= a;
            count %= mod;
            b++;
        }
        else{
            long k = a*b - (N*M - i);
            count *= k;
            count %= mod;
        }
    }
    cout << count;

    return 0;
}

