	//ループ有					:O(E+VlogV)
	//ループ有(負の閉路)		:ダイクストラは適用外
	void dijkstra(int posStart) {
		val(posStart).dis = 0;
		std::multimap<int, int>q;		//累計距離->頂点
		const int N = vertex.size();
		for (auto& edge : vertex[posStart].edges) {
			q.insert({ edge.w + val(posStart).dis ,edge.next });
		}
		while (!q.empty()) {
			auto itr = q.begin();
			if (val(itr->second).dis > itr->first) {
				val(itr->second).dis = itr->first;
				for (auto& edge : vertex[itr->second].edges) {
					q.insert({ edge.w + val(itr->second).dis ,edge.next });
				}
			}
			q.erase(itr);
		}
