void solve(void)
{
  int N;cin>>N;
  int M;cin>>M;
  vector<int> A (N,0);
  set<int> CA,CB;
  int flag = 1;
  for (int i = 0; i < N; i++)
  {
     cin>>A[i];
    auto r = CA.insert(A[i]);
    if(r.second == false) flag = 0;

  }
  vector<int> B (M,0);
  for (int i = 0; i < M; i++)
  {
     cin>>B[i];
    auto r = CB.insert(B[i]);
    if(r.second == false) flag = 0;
  }

  mint res = 1;
  res *= flag;
  for (int x = N*M; x >= 1; x--) 
  {
    int iA = -1;
    int iB = -1;
    for (int i = 0; i < N; i++)
    {
      if(x == A[i]) iA = i;
    }

    for (int i = 0; i < M; i++)
    {
      if(x == B[i])iB = i;
    }
    if(iA != -1 && iB != -1)
    {
      res *= 1;
    }
    else if(iA == -1 && iB == -1)
    {
      int cntA = 0,cntB = 0;
      for (int i = 0; i < N; i++)
      {
        if(A[i] >= x)cntA++;
      }
      for (int i = 0; i < M; i++)
      {
        if(B[i] >= x)cntB++;
      }

      res *= (cntA)*(cntB) - (N*M - x);


    }
    else
    {
      int cnt = 0;
      if(iB == -1)
      {
        for (int i = 0; i < M; i++)
        {
          if(B[i] >= x)cnt++;
        }

      }
      else
      {
        for (int i = 0; i < N; i++)
        {
          if(A[i] >= x)cnt++;
        }

      }
      res *= cnt;

    }



  }  
  cout<<res.x<<endl;
  return;
}
