using namespace std;

long fact_mod(int x) {
    if (x == 0)
        return 1;
    return (x * fact_mod(x - 1)) % MOD;
}

int main() {
    int n, m;
    cin >> n >> m;
    int a[n], b[m];
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int j = 0; j < m; j++) {
        cin >> b[j];
    }

    int table[n][m];
    bool number_used[n * m], cell_used[n][m];


    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            table[i][j] = a[i];
            number_used[m * i + j] = cell_used[i][j] = false;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (table[i][j] == b[j]) {
                if (number_used[b[i] - 1]) {
                    cout << 0 << endl;
                    return 0;
                }

                number_used[b[i] - 1] = cell_used[i][j] = true;
            }
            table[i][j] = min(table[i][j], b[j]);
        }
    }

    long ans = 1;
    priority_queue<int> max_list;
    stack<int> unused;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (!number_used[m * i + j])
                unused.push(m * i + j + 1);
            if (!cell_used[i][j])
                max_list.push(table[i][j]);
        }
    }

    long count = 0;
    while (!max_list.empty()) {
        int top = max_list.top();
        if (unused.top() > top) {
            ans *= count;
            ans %= MOD;
            //cout << unused.top() << ' ' << top << endl;
            unused.pop();
            count--;
        } else {
            count++;
            max_list.pop();
        }
    }
    //cout << ans << endl;
    if (!unused.empty()) {
        ans *= fact_mod(unused.size());
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

