bool a[maxn], b[maxn];

int main() {

	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cin >> n >> m;

	int tmp;
	for (int i = 0; i < n; ++i)
	{
		cin >> tmp;
		if (a[tmp]) {
			cout << 0 << endl;
			return 0;
		}
		a[tmp] = true;
	}

	for (int i = 0; i < m; ++i)
	{
		cin >> tmp;
		if (b[tmp]) {
			cout << 0 << endl;
			return 0;
		}
		b[tmp] = true;
	}

	long long ans = 1;
	for (int i = n*m; i >= 1; --i) {
		sum_a[i] = sum_a[i+1] + a[i];
		sum_b[i] = sum_b[i+1] + b[i];

		if (a[i] && b[i])
			continue;

		if (a[i])
			ans = ans * sum_b[i] % mo;
		else
			if (b[i])
