using namespace std;
FILE* in = stdin; FILE* out = stdout;

const int MAX = 1001;
const int MOD = 1000000007;

int n, m;
int a[MAX][MAX];
int limR[MAX], whichR[MAX * MAX], avR[MAX];
int limC[MAX], whichC[MAX * MAX], avC[MAX];
int cnt[MAX * MAX];
vector < pair <int, int> > where[MAX * MAX];

int main(void) {
	// in = fopen("D.in", "rt");

	memset(whichR, -1, sizeof(whichR));
	memset(whichC, -1, sizeof(whichC));

	fscanf(in, "%d %d", &n, &m);
	for (int i = 0; i < n; i++) {
	    fscanf(in, "%d", &limR[i]);
	    if (whichR[limR[i]] != -1) {
	        fprintf(out, "0\n");
	        return 0;
        }
        whichR[limR[i]] = i;
    }
	for (int i = 0; i < m; i++) {
	    fscanf(in, "%d", &limC[i]);
	    if (whichC[limC[i]] != -1) {
	        fprintf(out, "0\n");
	        return 0;
        }
        whichC[limC[i]] = i;
    }

	for (int row = 0; row < n; row++) {
	    for (int col = 0; col < m; col++) {
	        cnt[min(limR[row], limC[col])]++;
	        where[min(limR[row], limC[col])].push_back(make_pair(row, col));
        }
    }

    int ans = 1;
    int available = 0;
    for (int num = n * m; num >= 1; num--) {
        available += cnt[num];
        for (int i = 0; i < (int)where[num].size(); i++) {
            avR[where[num][i].first]++;
            avC[where[num][i].second]++;
        }
        // Has predefined position
        if (whichR[num] != -1 && whichC[num] != -1) {
             avR[whichR[num]]--;
            avC[whichC[num]]--;
            available--;
            continue;
        }
        // Has predefined row or column
        if (whichR[num] != -1 || whichC[num] != -1) {
            int positions = 0;
            if (whichR[num] != -1) {
                positions = avR[whichR[num]]--;
            } else {
                positions = avC[whichC[num]]--;
            }
//            fprintf(stderr, "%d has predefined row or column with %d options.\n", num, positions);
            ans = ((long long)ans * positions) % MOD;
            available--;
            continue;
        }
//        fprintf(stderr, "%d has %d choices.\n", num, available);
        if (available == 0) {
            ans = 0;
            break;
        }
        ans = ((long long)ans * available) % MOD;
        available--;
    }
	fprintf(out, "%d\n", ans);

	return 0;
}

