typedef long long ll;

const ll MOD = 1000000007;

vector<ll> sil(2000001);

ll Pot(ll n, ll k)
{
    if (k == 0)
        return 1;
    if (k % 2 == 0)
    {
        ll p = Pot(n, k / 2);
        return p * p % MOD;
    }
    return Pot(n, k - 1) * n % MOD;
}

ll Inv(ll n)
{
    return Pot(n, MOD - 2);
}

ll C(ll n, ll k)
{
    return (sil[n] * Inv(sil[k] * sil[n - k] % MOD)) % MOD;
}

