    ll x = n,y = m,k = min(a.top(),b.top()),ans = fac[k-1];
    while(true){
        //cout << x << " " << y << " " << k << " " << ans << '\n';
        if (x == 0 || y == 0){
            if (k <= n*m) ans = 0;
            break;
        }
        if (k == a.top() && k == b.top()){
            x--;
            y--;
            a.pop();
            b.pop();
        }
        else if (k == a.top()){
            (ans *= y)%=MOD;
            x--;
            a.pop();
        }
        else if (k == b.top()){
            (ans *= x)%=MOD;
            y--;
            b.pop();
        }
        else{
            if (x*y < n*m-k+1){
                ans = 0;
                break;
            }
            else{
                (ans *= (x*y-(n*m-k)))%=MOD;
            }
        }
        k++;
    }
    PRINT(ans);
}

