			printf("0\n");
			return 0;
		}
		whereB[b[j]] = j;
	}
	int cntA = 0, cntB = 0, ans = 1, used = 0;
	for (int i = n * m - 1; i >= 0; --i, ++used) {
		if ((whereA[i] != -1) && (whereB[i] != -1)) {
			cntA++, cntB++;
			continue;
		}
		if ((whereA[i] == -1) && (whereB[i] == -1)) {
