	for(long long i=0;i<M;i++)cin >> B[i];

	sort(A.begin(),A.end());
	sort(B.begin(),B.end());

	for(long long i=1;i<N;i++){
		if(A[i]==A[i-1]){
			printf("0\n");
			return 0;
		}
	}
	for(long long i=1;i<M;i++){
		if(B[i]==B[i-1]){
			printf("0\n");
			return 0;
		}
	}

	long long ans=1;

	for(long long i=N*M;i>0;i--){
		auto A_upper=upper_bound(A.begin(),A.end(),i);
		auto A_lower=lower_bound(A.begin(),A.end(),i);
		auto B_upper=upper_bound(B.begin(),B.end(),i);
		auto B_lower=lower_bound(B.begin(),B.end(),i);

		bool A_exist=(A_upper-A_lower==1);
		bool B_exist=(B_upper-B_lower==1);

		if(!A_exist && !B_exist)ans*=(A.end()-A_upper)*(B.end()-B_upper)-(N*M-i);
		if(A_exist && !B_exist)ans*=(B.end()-B_upper);
		if(!A_exist && B_exist)ans*=(A.end()-A_upper);
		ans%=1000000007;
	}

	cout << ans << endl;
