/* 二項係数 C(n,k) mod p を計算 */
const int MOD = 1000000007;
const int MAX = 201000;
long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

long long COM(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

void yes() {
  cout << "Yes" << endl;
  exit(0);
}

void no() {
  cout << 0 << endl;
  exit(0);
}

int main() {
  ll N, M;
  cin >> N >> M;
  COMinit();
  vector<ll> A(N), B(M);
  const ll MAX = N * M;
  // cntA[x] = A[i]>=xとなるiの個数
  vector<ll> cntA(MAX + 2, 0), cntB(MAX + 2, 0);
  REP(i, N) {
    cin >> A[i];
    cntA[A[i]]++;
  }
  REP(j, M) {
    cin >> B[j];
    cntB[B[j]]++;
  }
  // A,Bに重複がある場合は0通り
  A.resize(unique(ALL(A)) - A.begin());
  if (SZ(A) < N) no();
  B.resize(unique(ALL(B)) - B.begin());
  if (SZ(B) < M) no();
  IFOR(i, 1, MAX + 1) {
    cntA[i - 1] += cntA[i];
    cntB[i - 1] += cntB[i];
  }
  ll ans = 1;
  IFOR(x, 1, MAX + 1) {
    ll s = cntA[x] - cntA[x + 1];  // A[i] = xなるiがあるか？
    ll t = cntB[x] - cntB[x + 1];  // B[j] = xなるjがあるか？
    if (s == 1 && t == 1) continue;
    if (s == 1) {
      (ans *= cntB[x]) %= MOD;
    } else if (t == 1) {
      (ans *= cntA[x]) %= MOD;
    } else {
      (ans *= cntA[x] * cntB[x] - (MAX - x)) %= MOD;
    }
  }
  cout << ans << endl;
}

