const ll MOD = 1000000000LL + 7LL;
inline ll add(ll a, ll b) { return (a+b)%MOD; }
inline ll sub(ll a, ll b) { return (a+MOD-b)%MOD; }
inline ll mul(ll a, ll b) { return (a*b)%MOD; }
inline void chadd(ll &a, ll b) { a = add(a, b); }
inline void chmul(ll &a, ll b) { a = mul(a, b); }

ll solve(const int N, const int M, const vector<int> &A, const vector<int> &B) {
  //  REP(i,N) cout << " " << A[i];                                                    
  //  cout << endl;                                                                    
  //  REP(i,M) cout << " " << B[i];                                                    
  //  cout << endl;                                                                    
  REP(i,N-1) if(A[i] == A[i+1]) return 0;
  REP(i,M-1) if(B[i] == B[i+1]) return 0;
  ll ans = 1;
  int sum = N*M;
  int m	= 0, n = 0;
  for(int i = N*M; i >=	1; i--) {
    if(n < N && A[n] == i && m < M && B[m] == i) {
      // 両方あるから交点に置く                                              
      chmul(ans, 1LL);
      n++, m++;
    }
    else if(n < N && A[n] == i &&( (m < M && B[m] != i) || m >= M)) {
      // 行にだけある                                                                  
      chmul(ans, m);
      n++;
    }
    else if(m < M && B[m] == i &&( (n < N && A[n] != i) || n >= N)) {
      // 列にだけある                                                              
      chmul(ans, n);
      m++;
    } else {
      // どちらにもない                                                      
      int rem = m * n - (sum - i);
      //      cout << rem << endl;                                                     
      if(rem <= 0) return 0;
      chmul(ans, rem);
    }
  }
  return ans;
}


int main() {
  int N, M;
  cin>>N>>M;
  vector<int> A(N), B(M);
  REP(i,N) cin>>A[i];
  REP(i,M) cin>>B[i];
  sort(A.begin(), A.end());
  reverse(A.begin(), A.end());
  sort(B.begin(), B.end());
  reverse(B.begin(), B.end());
  ll ans = 0;
  if(N >= M) ans = solve(N, M, A, B);
  else ans = solve(M, N, B, A);
  //  cout << "Answer=";                                                               
  cout << ans << endl;
  return 0;
}

