				rem1--;
			} else {
				if(v[i].first - used < rem1) {
					cout << 0 << endl;
					return 0;
				}
				ans *= (modpow[rem1] * mod_comb(v[i].first - used - 1, rem1 - 1)) % MOD;
				ans %= MOD;
				used += rem1;
				rem2--;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

