ll get(ll t)
{
	ll ret=0;	
	ll x=lower_bound(a.begin(),a.end(),t)-a.begin();	
	ll y=lower_bound(b.begin(),b.end(),t)-b.begin();
	if(a[x]==t&&b[y]==t)
		ret=1;
	else if(a[x]==t)
		ret=m-y;
	else if(b[y]==t)
		ret=n-x;
	else
		ret=(m-y)*(n-x)-(n*m-t);
	return ret;
}

