class Solve {
public:
    void input() {

    }

    void solve() {
        input();
        int N, M;
        cin >> N >> M;
        vector<int> A(N), B(M);
        vector<int> col(N * M, -1), row(N * M, -1);

        rep(i, 0, N) {
            cin >> A[i];
            A[i]--;
            col[A[i]] = i;
        }

        rep(i, 0, M) {
            cin >> B[i];
            B[i]--;
            row[B[i]] = i;
        }

        ll ans = 1ll;

        ll c = 0, r = 0; //最大値が置かれている縦と横の数
        for (int i = N * M - 1, t = 0; i >= 0; --i, t++) {
            //tは盤面に埋まったマス
            int cnt = 0;
            if (col[i] != -1) cnt++;
            if (row[i] != -1) cnt++;

            if (cnt == 2) {
                c++;
                r++;
            } else if (cnt == 1) {
                if (col[i] != -1) {
                    c++;
                    ll tmp = r;
                    if (tmp < 0)
                        tmp = 0;
                    ans *= tmp;
                    ans %= MOD;
                } else {
                    r++;
                    ll tmp = c;
                    if (tmp < 0)
                        tmp = 0;
                    ans *= tmp;
                    ans %= MOD;
                }
            } else {
                ll tmp = c * r - t;
                if (tmp < 0)
                    tmp = 0;
                tmp %= MOD;
                ans *= tmp;
                ans %= MOD;

            }
        }
        cout << ans << endl;
    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    Solve().solve();


    return 0;
}

