const ll MAX = 200000;
const ll MOD = 1000000007;
ll fac[MAX];

//テーブルを作る前処理
void FACinit() {
	fac[0] = fac[1] = 1;
	for (ll i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
	}
}

//階乗計算
mll FAC(ll n) {
	return fac[n];
}
//--↑--階乗をmodした数値を高速に求める--↑--


struct LLTriple {
	ll num = 0;
	ll rowFlag = 0;
	ll index = 0;
	ll fixed = 0;
	LLTriple() {}
	LLTriple(ll num, ll rowFlag, ll index, ll fixed) {
		this->num = num;
		this->rowFlag = rowFlag;
		this->index = index;
		this->fixed = fixed;
	}
};

int main() {
	ll R;
	cin >> R;
	ll C;
	cin >> C;

	set<ll> sR;
	vector<ll> r(R);
	rep(i, R) {
		cin >> r[i];
		if (sR.count(r[i]) > 0) {
			//多重に入っているのでダメ
			cout << 0 << endl;
			return 0;
 		}
		sR.insert(r[i]);
	}
	set<ll> sC;
	vector<ll> c(C);
	rep(i, C) {
		cin >> c[i];
		if (sC.count(c[i]) > 0) {
			//多重に入っているのでダメ
			cout << 0 << endl;
			return 0;
		}
		sC.insert(c[i]);
	}

	//全行列の数をソートする
	vector<LLTriple> A;
	rep(i, R) {
		A.push_back(LLTriple(r[i], 1, i, (sC.count(r[i]) > 0 ? 1 : 0)));
	}
	rep(i, C) {
		A.push_back(LLTriple(c[i], 0, i, (sR.count(c[i]) > 0 ? 1 : 0)));
	}
	std::sort(A.begin(), A.end(), [](const LLTriple &a, const LLTriple &b) {
		return a.num < b.num; //降順にするには > とする
	});


	mll result = 1;
	ll usedCount = 0;
	ll rowIndex = 0;
	ll colIndex = 0;
	FACinit();
	set<ll> sFixedNum;

	rep(i, R + C) {
		debug_out();
		debug_out("i:");
		debug_out(i);
		debug_out("num:");
		debug_out(A[i].num);
		debug_out("row?:");
		debug_out(A[i].rowFlag);
		debug_out("fixed?:");
		debug_out(A[i].fixed);

		mll pat = 1;

		//詰めることができる残りセル数
		ll nCell = A[i].rowFlag ? C - colIndex : R - rowIndex;

		//詰めることができる数の個数
		ll nNum = A[i].num - usedCount;

		//位置固定の場合
		bool fix = false;

		if (sFixedNum.count(A[i].num) > 0) { //sFixedNumにすでに入っている場合は固定済み
			//固定済みなのでセル数も詰めることができる数の個数もそのまま
		}
		else if (A[i].fixed) { 
			nCell--;
			nNum--;
			sFixedNum.insert(A[i].num);
			fix = true;
		}
		else {
			//numがどこかに入り、残りのセルを詰める
			pat *= nCell;
			nCell--;
			nNum--;
			fix = true;
		}

		debug_out("nCell:");
		debug_out(nCell);
		debug_out("nNum:");
		debug_out(nNum);

		//詰める場合の数
		pat *= FAC(nNum) / FAC(nNum - nCell);
		result *= pat;

		debug_out("pat:");
		debug_out(pat);
		debug_out("result:");
		debug_out(result);

		//詰めた数のカウント
		usedCount += nCell + (fix ? 1 : 0);

		//行列index進める
		if (A[i].rowFlag) {
			rowIndex++;
		}
		else {
			colIndex++;
		}
	}

	cout << result << endl;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const string KEY = "keyence";

const int N = 1e6 + 5;

const ll MOD = 1e9 + 7;

pair<bool, bool> nums[N];
ll mul[N];

ll solve() {
    ll n, m;
    cin >> n >> m;
    for (int i = 0; i < n; ++i) {
        int d;
        scanf("%d", &d);
        if (nums[d].first) {
            return 0;
        }
        nums[d].first = true;
    }
    for (int i = 0; i < m; ++i) {
        int d;
        scanf("%d", &d);
        if (nums[d].second) {
            return 0;
        }
        nums[d].second = true;
    }

    ll vacant = 0;
    ll hor = 0; // first
    ll ver = 0; // second

    ll res = 1;

    for (ll i = n * m; i >= 1; --i) {
        if (nums[i].first && nums[i].second) {
            vacant += hor + ver;
            ++hor;
            ++ver;
        } else if (nums[i].first) {
            if (ver == 0) {
                return 0;
            }
            vacant += ver - 1;
            ++hor;
            res = (res * ver) % MOD;
        } else if (nums[i].second) {
            if (hor == 0) {
                return 0;
            }
            vacant += hor - 1;
            ++ver;
            res = (res * hor) % MOD;
        } else {
            if (vacant == 0) {
                return 0;
            }
            res = (res * vacant) % MOD;
            --vacant;
        }
    }

    return res;
}

int main() {
#ifdef LOCALHOST
    freopen("input", "r", stdin);
#endif
    cout << solve() << endl;

    return 0;
}

