#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e3 + 5;
const int MOD = 1e9 + 7;

int N, M;
int a[MAXN], b[MAXN];

void load() {
	scanf("%d%d", &N, &M);
	for (int i = 0; i < N; i++)
		scanf("%d", a + i);
	for (int i = 0; i < M; i++)
		scanf("%d", b + i);
}

void move(int *arr, int &ptr, int val) {
	while (ptr && arr[ptr - 1] >= val)
		ptr--;
}

void mult(int &x, int y) {
	x = (long long)x * y % MOD;
}

bool bad(int *arr, int n) {
	for (int i = 1; i < n; i++)
		if (arr[i] == arr[i - 1])
			return true;
	return false;
}

int solve() {
	sort(a, a + N);
	sort(b, b + M);

	if (bad(a, N) || bad(b, M))
		return 0;

	int sol = 1;
	int ptrA = N, ptrB = M;
	for (int i = N * M; i; i--) {
		move(a, ptrA, i);
		move(b, ptrB, i);
		if (a[ptrA] < i || b[ptrB] < i)
			return 0;
		if (a[ptrA] > i && b[ptrB] > i)
			mult(sol, (N - ptrA) * (M - ptrB) - N * M + i);
		else if (a[ptrA] > i)
			mult(sol, N - ptrA);
		else if (b[ptrB] > i)
			mult(sol, M - ptrB);
	}

	return sol;
}

int main() {
	load();
	printf("%d\n", solve());
	return 0;
}

