const lint MOD = 1e9 + 7;
const int MAX_N = 1005;
int N, M, A[MAX_N], B[MAX_N], C[MAX_N*MAX_N], D[MAX_N*MAX_N], E[MAX_N*MAX_N];

int main(){
    ios::sync_with_stdio(false), cin.tie(nullptr);
    cin >> N >> M;
    for(int i=0;i<N;i++) {cin >> A[i]; D[A[i]]++;}
    for(int i=0;i<M;i++) {cin >> B[i]; E[B[i]]++;}

    for(int i=0;i<N;i++) for(int j=0;j<M;j++) C[min(A[i], B[j])]++;

    lint ans = 1;
    for(int i=N*M;0<i;i--){
        if(D[i]>1 || E[i]>1) {cout << 0 << endl; return 0;}
        else if(D[i] && E[i]) C[i]+=C[i+1];
        else if(D[i] || E[i]) {ans = ans * C[i] % MOD; C[i] += C[i+1];}
        else{
            C[i] += C[i+1];
            if(C[i]-N*M+i<=0) {cout << 0 << endl; return 0;}
            ans = ans * (C[i]-N*M+i) % MOD;
        }
    }

    cout << ans << endl;
