#include<bits/stdc++.h>
using namespace std;
const int mod=998244353;
int a[1001*1001],b[1001*1001],inv[1001*1001];
int aa[1001],bb[1001];
int *A=aa,*B=bb,x,y;
int cnt,n,m,ans;
void init(){
	a[0]=b[0]=1;
	a[1]=b[1]=inv[1]=1;
	for(int i=2;i<=1000*1000;i++){
		inv[i]=1ll*(mod-mod/i)*inv[mod%i]%mod;
		a[i]=1ll*a[i-1]*i%mod;
		b[i]=1ll*b[i-1]*inv[i]%mod;
	}
}
int P(int n,int m){
	return 1ll*a[n]%mod*b[n-m]%mod;
}
int main(){
	init();
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++) scanf("%d",&aa[i]);
	for(int i=1;i<=m;i++) scanf("%d",&bb[i]);
	sort(aa+1,aa+n+1);
	sort(bb+1,bb+n+1);
	x=y=ans=1;
	while(x<=n&&y<=m){
		if(A[x]==B[y]){
			ans=1ll*ans*P(A[x]-cnt-1,n+m-x-y)%mod;
			cnt+=n+m-x-y+1;
			x++,y++;
			continue;
		}
		if(A[x]>B[y]) swap(n,m),swap(x,y),swap(A,B);
		ans=1ll*ans*(n-x+1)%mod*P(A[x]-cnt-1,n-x);
		cnt+=(n-x+1);
		x++;
	}
	printf("%d",ans);
