// 方針
// グリッドのN*M個の要素には重複がないので，
// (1) i行目のM個の値のうち，1つはちょうどAiで，他の(M-1)個の値は全てAi未満
// (2) j行目のN個の値のうち，1つはちょうどBjで，他の(N-1)個の値は全てBj未満
// (1)より，(1.1) Aiはすべて異なる。
// また，(1.2) すべての行について，{1~N*M}から{A1~AN}を除いた集合から，重複なくAi未満の要素を(M-1)個ずつ選べなければならない。
// (1.2)の操作を行う際，Aiが小さいほど制約が厳しい。なので，
// (1.3) Aiを昇順に並べたときに，すべてのi:1~Nについて，1以上Ai以下の整数がi*M個以上なければならない。
// すなわち，Ai >= i*M でなければならない。
// 同様に，Bjを昇順に並べたとき， Bj >= j*N でなければならない。
// (3) (i,j)成分g[i][j]は，Ai以下かつBi以下であるから，min(Ai,Bi)以下。
// 同様に，g[i][j]を昇順に並べたときに，g[i][j]がk番目であるとして，全ての(i,j)(k番目)について，1以上g[i][j]以下の整数がk個以上なければならない。
// つまり，g[i][j]のうちk番目のものがk以上でなければならない。

// (1.1) Aiがすべて異なり，Bjがすべて異なり，g[i][j]のうちk番目のもの(g(k)とする)がk以上であれば，条件を満たす数字の書き込み方が存在する?
// 各kに対し，1+g(k)-k 通りの選択肢が考えられるから，制約の強いk=1からk=N*Mまで 1+g(k)-k を掛け合わせれば答え?

// i行目のM個の数のうち，Aiとできるのは，Bj>=Aiなる(i,j)に限られる。
// なので，Aiの小さい方から，BjのうちAi以上のものの個数を数え(ni個とする)，そのいずれかにAiを書き込み(自由度ni)，第i行の残りM-1個のマスには1以上Ai未満の整数を書き込む(M-1<=Ai-1を前提に，自由度Perm(Ai-1,M-1))。
// これをi=1~Nについて繰り返せばよい(?)

const ll MOD = 1'000'000'007;

ll rem(ll x) { x %= MOD; if(x < 0) x += MOD; return x; }
ll madd(ll x, ll y) { return (rem(x) + rem(y)) % MOD; }
ll msub(ll x, ll y) { return madd(x, -y); }
ll mmul(ll x, ll y) { return rem(x) * rem(y) % MOD; }
ll mpow(ll x, ll n) { assert(n >= 0); ll res = 1; while (n > 0) { if (n & 1) res = mmul(res, x); x = mmul(x, x); n >>= 1; } return res; }
ll inv(ll x) { assert(x % MOD != 0); return mmul(x, MOD - 2); }
ll mdiv(ll x, ll y) { return mmul(x, inv(y)); }
void mad(ll &x, const ll y) { x = madd(x, y); }
void msb(ll &x, const ll y) { x = msub(x, y); } void mml(ll &x, const ll y) { x = mmul(x, y); }
void mdv(ll &x, const ll y) { x = mdiv(x, y); }

ll fact(int k) {
	assert(k >= 0);
	ll res = 1;
	rep2(i, 2, k + 1) res = mmul(res, i);
	return res;
}

vl facts(int n) {
	assert(n >= 0);	
	vl res(n + 1); res[0] = 1;
	rep2(k, 1, n + 1) res[k] = mmul(res[k - 1], k);
	return res; // 不要ならvoidとする
}

vl cmbs(int n) {
	assert(n >= 0);
	vl res(n + 1); res[0] = 1;
	rep2(r, 1, n + 1) res[r] = mmul(res[r - 1], mdiv(n + 1 - r, r));
	return res;
}

