#include<bits/stdc++.h>

using namespace std;

#define MAX 1010
const bool debug = 0;

const long long mod = 1000000007;
int N,M,A[MAX],B[MAX];

void compute() {
  long long ans = 1;
  map<int,int> mp_A, mp_B;
  set<int> put_A, put_B;
  for(int i=0;i<N;++i) mp_A[A[i]] = i;
  for(int i=0;i<M;++i) mp_B[B[i]] = i;

  for(int i=N*M;i>=1;--i) {

    bool exist_A = ( mp_A.count(i) != 0 );
    bool exist_B = ( mp_B.count(i) != 0 );

    if( exist_A  && exist_B ) {
      put_A.insert( mp_A[i] );
      put_B.insert( mp_B[i] );

    } else if( exist_A ) {
      ans *= (long long)put_B.size();
      ans %= mod;
      put_A.insert( mp_A[i] );

    } else if( exist_B ) {
      ans *= (long long)put_A.size();
      ans %= mod;
      put_B.insert( mp_B[i] );

    } else {
      long long coef = ( (long long)put_A.size() * (long long)put_B.size() );
      coef %= mod;
      coef -= ( N * M - i );
      if( coef < 0LL ) coef += mod;
      ans *= coef;
      ans %= mod;
    }

  }

  cout << ans << endl;
}

int main() {
  cin >> N >> M;
  for(int i=0;i<N;++i) cin >> A[i];
  for(int i=0;i<M;++i) cin >> B[i];
  compute();
  return 0;
}

