    ib=min(ib,(int)m-1);
    if(a[ia]==i && b[ib]==i){
      v.push_back(i);
      ia++;
      ib++;
    }else if(a[ia]==i){
      v.push_back(i);
      ia++;
    }else if(b[ib]==i){
      v.push_back(i);
      ib++;
    }
  }

