constexpr intmax_t MOD = 1e9+7;

template <class Tp>
Tp gcd(Tp a, Tp b, Tp& x, Tp& y) {
  x = Tp(0);
  y = Tp(1);
  for (Tp u=y, v=x; a;) {
    Tp q = b/a;
    std::swap(x-=q*u, u);
    std::swap(y-=q*v, v);
    std::swap(b-=q*a, a);
  }
  return b;
}

template <class Tp>
Tp modpow(Tp x, int iexp) {
  Tp res = 1;
  for (Tp dbl = x; iexp; iexp >>= 1) {
    if (iexp & 1) res = res * dbl % MOD;
    dbl = dbl * dbl % MOD;
  }
  return res;
}

template <class Tp>
Tp modinv(Tp a) {
  return modpow(a, MOD-2);
}

template <class Tp>
Tp moddiv(Tp a, Tp b) {
  return a * modinv(b) % MOD;
}

