			//同時
			int num = n-ridx +m-cidx -1;
			if(used+num <= a[ridx]){
				ans *= nPr(a[ridx]-used-1, num-1);
				ans %= mod;
				used += num;
				ridx++;
				cidx++;
			}else{
				ans = 0;
				break;
			}
		}else if(cidx==m || (ridx!=n && a[ridx] < b[cidx])){
			//行を取る
			int num = m-cidx;
			if(used+num <= a[ridx]){
				ans *= nPr(a[ridx]-used-1, num-1) *num %mod;
				ans %= mod;
				used += num;
				ridx++;
			}else{
				ans = 0;
				break;
			}
		}else{
			//列を取る
			int num = n-ridx;
			if(used+num <= b[cidx]){
				ans *= nPr(b[cidx]-used-1, num-1) *num %mod;
				ans %= mod;
				used += num;
				cidx++;
			}else{
				ans = 0;
				break;
			}
		}
	}
