const int MOD = 1e9 + 7;
const int N_MAX = 2e5+5;
//mint:mod演算のための型
using mint = Fp<MOD>;
//型変換
#define MINT (mint)

//mod MOD上での階乗
mint fact[N_MAX];
mint finv[N_MAX];
void init(){
  fact[0] = fact[1] = MINT 1;
  for(int i = 2; i < N_MAX; i++){
    fact[i] = fact[i-1] * i;
  }
  finv[N_MAX-1] = MINT 1/fact[N_MAX-1];
  for(int i = N_MAX-1; i>0; --i){
    finv[i-1] = finv[i] * i;
  }
}

//mod MOD上での逆元
inline mint inv(mint n){
  return MINT 1/n;
}

//二項係数の計算(mod MOD上)
inline mint COM(int n, int k){
  if(n<k) return 0;
  if(k<0) return 0;
  return fact[n]*finv[k]*finv[n-k];
}

//順列計算
inline mint PER(int n, int k){
  if(n<k) return 0;
  if(k<0) return 0;
  return fact[n]*finv[n-k];
}

