struct Problem {

	static const ULL M = 1000000007;

	void Solve() {
		UL H, W; cin >> H >> W;
		deque<UL> YM(H), XM(W);
		rep(y, H) cin >> YM[y];
		rep(x, W) cin >> XM[x];
		sort(XM.rbegin(), XM.rend()); XM.push_back(0);
		sort(YM.rbegin(), YM.rend()); YM.push_back(0);
		ULL ans = 1;
		UL emp = 0;
		UL w, h; w = 0; h = 0;
		for (UL i = W * H; i > 0; i--) {
			if (XM.front() == i && YM.front() == i) {
				XM.pop_front(); if (XM.front() == i) { cout << 0 << endl; return; }
				YM.pop_front(); if (YM.front() == i) { cout << 0 << endl; return; }
				emp += (w + h); h++; w++;
			}
			else if (XM.front() == i) {
				XM.pop_front(); if (XM.front() == i) { cout << 0 << endl; return; }
				ans = ans * h % M; if (h == 0) { cout << 0 << endl; return; }
				emp += h; w++; emp--;
			}
			else if (YM.front() == i) {
				YM.pop_front(); if (YM.front() == i) { cout << 0 << endl; return; }
				ans = ans * w % M; if(w == 0) { cout << 0 << endl; return; }
				emp += w; h++; emp--;
			}
			else {
				if(emp == 0) { cout << 0 << endl; return; }
				ans = ans * emp % M;
				emp--;
			}
		}
		cout << ans << endl;
	}

	Problem();
};
