      rest += B[idx_b] - prev - 1;
      ms = N - idx_a - 1;
      if (rest - ms < 0) {
        std::cout << 0 << std::endl;
        return;
      }
      ret *= ms + 1;
      ret %= mod;
      ret *= (fact[rest] * factinv[rest-ms]) % mod;
      ret %= mod;
      rest -= ms;
      prev = B[idx_b];
      idx_b++;
    } else if (idx_b >= M) {
      rest += A[idx_a] - prev - 1;
