            ans %= MOD;
        }else if(av[i] == -1 && bv[i] == -1){
            ans *= max(0LL, avrui[i] * bvrui[i] - c);
            ans %= MOD;
        }
        c++; // C++
    }
    cout << ans % MOD << endl;
}

