#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}



ll solve(int N,int M,vi& a,vi& b) {
    set<int> sa(ALL(a)), sb(ALL(b));
    if (sa.size() < N || sb.size() < M) return 0;


    int Z = N*M;

    vll fact(Z+1);
    fact[0] = fact[1] = 1;
    for(int i=2; i<=Z; ++i) fact[i] = MUL(fact[i-1], i);

    vi visited(Z+1, 0);
    priority_queue<int,vi,greater<int>> pq;

    rep(r,N) rep(c,M) {
        if (a[r] == b[c]) {
            visited[ a[r] ] = 1;
        } else {
            int mn = min(a[r], b[c]);
            pq.push(mn);
        }
    }

    ll ans = 1;
    int cnt = 0;

    int wait = 0;
    for (int n=1; n<=Z; ++n) {
        while (!pq.empty()) {
            if (pq.top() == n) { ++cnt; pq.pop(); }
            else break;
        }

        if (!visited[n]) ++wait;
        if (cnt == 0) continue;


        if (wait < cnt) return 0;



        ll p = 1;
        if (visited[n]) {
            p = MUL(comb(wait,cnt), fact[cnt]);
        } else {
            p = MUL(comb(wait-1,cnt-1), fact[cnt]);
        }

        ans = MUL(ans, p);

        wait -= cnt; cnt = 0;

    }
    if (wait > 0) return 0;

    return ans;
}

