const int MAXN = 1234;
const LL MOD = (LL)1e9 + 7;
int r[MAXN * MAXN], c[MAXN * MAXN];
int mz[MAXN][MAXN];
bool used[MAXN * MAXN];
int cnt[MAXN * MAXN];

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    bool ans = true;
    for (int i = 0; i < N; i++) {
        int tmp;
        scanf("%d", &tmp);
        if (r[tmp]) ans = false;
        r[tmp] = 1;
        for (int j = 0; j < M; j++) mz[i][j] = tmp;
    }
    for (int i = 0; i < M; i++) {
        int tmp;
        scanf("%d", &tmp);
        if (c[tmp])
           ans = false;
        c[tmp] = 1;
        for (int j = 0; j < N; j++) {
            if (mz[j][i] == tmp) used[tmp] = 1;
            mz[j][i] = min(mz[j][i], tmp);
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int cur = mz[i][j];
            cnt[cur]++;
        }
    }
    LL sum = 1, pool = 0;
    for (int i = 1; i <= N * M; i++) {
        //printf("i = %d cnt = %d\n", i, cnt[i]);
        if (!used[i]) {
           if (cnt[i]) sum *= cnt[i];
           else pool++;
           sum %= MOD;
        }
        cnt[i]--;
        if (pool < cnt[i]) ans = false;
        for (int j = 0; j < cnt[i]; j++) {
            sum *= pool;
            pool--;
            sum %= MOD;
        }
    }
    if (!ans) sum = 0;
    printf("%lld\n", sum);
    return 0;
}

