signed main() {
	INIT;

	VAR(int, n, m);
	VEC(int, a, n);
	VEC(int, b, m);

	std::sort(ALL(a)); std::reverse(ALL(a));
	std::sort(ALL(b)); std::reverse(ALL(b));

	const int M = n * m;

	std::vector<PAIR> pos(M + 1, PAIR(-INFINT, -INFINT));

	REP(i, n) {
		if (pos[a[i]].first != -INFINT) {
			OUT(0)BR;
			return 0;
		}
		pos[a[i]].first = i;
	}
	REP(j, m) {
		if (pos[b[j]].second != -INFINT) {
			OUT(0)BR;
			return 0;
		}
		pos[b[j]].second = j;
	}

	if (pos[M].first == -INFINT || pos[M].second == -INFINT) {
		OUT(0)BR;
		return 0;
	}

	int p = 0, q = 0;
	int ans = 1;
	int rest = 0;

	RFOR(i, 1, M) {
		bool P = pos[i].first == p + 1;
		bool Q = pos[i].second == q + 1;

		if(P) {
			++p;
			rest += q + 1;
		}
		if(Q) {
			++q;
			rest += p + 1;
		}
		if (P && Q);
		else if (P) (ans *= q + 1) %= MOD;
		else if (Q) (ans *= p + 1) %= MOD;
		else (ans *= rest) %= MOD;
		--rest;
		if (rest < 0) ans = 0;
	}
	OUT(ans)BR;
	return 0;
}

