	for (int i = 0; i < M - 1; i++) if (B[i + 1] == B[i]) ans = 0;

	Factorial Fac(5000);
	int row = 0, col = 0;
	int cnt = 0, prev = 0;
	while (row < N && col < M) {

		if (A[row] < B[col]) {
			cnt += A[row] - prev - 1;
			prev = A[row];
			ans *= M - col;
			ans *= Fac.Pmod(cnt, M - col - 1);
			cnt -= M - col - 1;
			row++;
		}
		else if (A[row] > B[col]){
			cnt += B[col] - prev - 1;
			prev = B[col];
			ans *= N - row;
			ans *= Fac.Pmod(cnt, N - row - 1);
			cnt -= N - row - 1;
			col++;
		}
		else {
			cnt += A[row] - prev - 1;
			prev = A[row];
			ans *= Fac.Pmod(cnt, N + M - (row + col) - 2);
			cnt -= N + M - (row + col) - 2;
			row++, col++;
		}

	}

