int getPow(int k)
{
  if(k == 1) {
    return 1;  
  }
  if(k <= 0) {
    return 0;
  }
  if(myPow[k] != -1) {
    return myPow[k];
  }
  return myPow[k] = (k * getPow(k-1)) % MOD;
}

