#define rrep(i, n) for (int64_t i = (n)-1; i >= 0; i--)
#define rirep(i, n) for (int64_t i = n; i >= 0; i--)

const int64_t MOD = 1e9 + 7;
int64_t dpow(int64_t x, int64_t y)
{
    if (y == 0) {
        return 1;
    }
    if (y % 2 == 0) {
        return dpow(x * x % MOD, y / 2);
    } else {
        return x * dpow(x, y - 1) % MOD;
    }
}

int64_t inv(int64_t x)
{
    return dpow(x, MOD - 2);
}

int main()
{
    int n, m;
    cin >> n >> m;

    vector<int> a(n), b(m);
    rep(i, n)
    {
        cin >> a[i];
    }
    rep(i, m)
    {
        cin >> b[i];
    }

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    rep(i, n - 1)
    {
        if (a[i] == a[i + 1]) {
            cout << 0 << endl;
            return 0;
        }
    }
    rep(i, m - 1)
    {
        if (b[i] == b[i + 1]) {
            cout << 0 << endl;
            return 0;
        }
    }

    vector<int> c(n + m);
    copy(a.begin(), a.end(), c.begin());
    copy(b.begin(), b.end(), c.begin() + n);
    sort(c.begin(), c.end());
    c.erase(unique(c.begin(), c.end()), c.end());

    vector<bool> isFree(c.size(), true);
    vector<int> ag(n, 0), bg(m, 0);
    rep(i, n) rep(j, m)
    {
        if (a[i] < b[j]) {
            ag[i]++;
        } else if (a[i] > b[j]) {
            bg[j]++;
        } else {
            ag[i]++;
            isFree[lower_bound(c.begin(), c.end(), a[i]) - c.begin()] = false;
        }
    }

    vector<int> cg(c.size(), 0);
    rep(i, n)
    {
        int idx = lower_bound(c.begin(), c.end(), a[i]) - c.begin();
        cg[idx] += ag[i];
    }
    rep(i, m)
    {
        int idx = lower_bound(c.begin(), c.end(), b[i]) - c.begin();
        cg[idx] += bg[i];
    }

    vector<int64_t> fact(n * m + 1);
    irep(i, n * m)
    {
        if (i == 0) {
            fact[i] = 1;
        } else {
            fact[i] = fact[i - 1] * i % MOD;
        }
    }

    int64_t result = 1, used = 0;
    rep(i, c.size())
    {
        int r = c[i] - used;
        if (r < cg[i]) {
            cout << 0 << endl;
            return 0;
        }
        if (isFree[i]) {
            result = result * (fact[r] * inv(fact[r - cg[i]]) % MOD) % MOD;
        } else {
            result = result * (fact[r - 1] * inv(fact[r - 1 - (cg[i] - 1)]) % MOD) % MOD;
        }
        used += cg[i];

        //cout << "i=" << i << "\t" << used << "\t" << result << "\t" << r << "\t" << cg[i] << endl;
    }
    cout << result << endl;

    return 0;
}

