struct BIT{
private:
  ll n;
  vector<ll> bit_array;
public:
  BIT(ll s){
    bit_array.resize(s+1,0);
    n=s;
  }
  void add(ll i,ll x){
    while(i<=n){
      bit_array[i]+=x;
      i+=(i&(-i));
    }
  }
  ll sum(ll i){
    ll s=0;
    while(i>0){
      s+=bit_array[i];
      i-=(i&(-i));
    }
    return s;
  }
};
struct wBIT{
private:
  ll n;
  vector<BIT> bit_array;
public:
  wBIT(ll s,ll t){
    BIT b=BIT(t);
    bit_array.resize(s+1,b);
    n=s;
  }
  void add(ll i,ll j,ll x){
    while(i<=n){
      bit_array[i].add(j,x);
      i+=(i&(-i));
    }
  }
  ll sum(ll i,ll j){
    ll s=0;
    while(i>0){
      s+=bit_array[i].sum(j);
      i-=(i&(-i));
    }
    return s;
  }
};

int main(){
  ll h,w;
  cin>>h>>w;
  ll mod=1;
  for(int i=0;i<9;i++) mod*=10;
  mod+=7;
  ll hmax[1005],wmax[1005];
  vector<ll> vh,vw;
  for(ll i=0;i<1005;i++){
    for(ll j=0;j<1005;j++) used[i][j]=false;
  }
