    cin>>hmax[i];
    vh.push_back(hmax[i]);
  }
  for(ll i=1;i<=w;i++){
    cin>>wmax[i];
    vw.push_back(wmax[i]);
  }
  sort(vh.begin(),vh.end());
  sort(vw.begin(),vw.end());
  ll ans=1;
  wBIT sm=wBIT(h,w);
  for(ll i=1;i<=h;i++){
    for(ll j=1;j<=w;j++) sm.add(i,j,1);
  }
  //cout<<"a"<<endl;
  for(ll i=h*w;i>0;i--){
    ll tat=lower_bound(vh.begin(),vh.end(),i)-vh.begin();
    ll yok=lower_bound(vw.begin(),vw.end(),i)-vw.begin();
    tat++;
    yok++;
    ll pls;
    if(vh[tat-1]==i&&vw[yok-1]==i) pls=1;
    else if(vw[yok-1]==i){
      pls=sm.sum(h,yok)-sm.sum(tat-1,yok)-sm.sum(h,yok-1)+sm.sum(tat-1,yok-1);
    }
    else if(vh[tat-1]==i){
      pls=sm.sum(tat,w)-sm.sum(tat,yok-1)-sm.sum(tat-1,w)+sm.sum(tat-1,yok-1);
    }
    else{
      pls=sm.sum(h,w)-sm.sum(h,yok-1)-sm.sum(tat-1,w)+sm.sum(tat-1,yok-1);
    }
    //cout<<pls<<endl;
    ans*=pls;
    ans%=mod;
    ll x=tat,y=yok;
    sm.add(x,y,-1);
  }
