template <int mod> struct ModInt {
    int val;
    ModInt() : val(0) {}
    ModInt(long long x) : val(x >= 0 ? x % mod : (mod - (-x) % mod) % mod) {}
    ModInt &operator+=(const ModInt &p) {
        if ((val += p.val) >= mod) {
            val -= mod;
        }
        return *this;
    }
    ModInt &operator-=(const ModInt &p) {
        if ((val += mod - p.val) >= mod) {
            val -= mod;
        }
        return *this;
    }
    ModInt &operator*=(const ModInt &p) {
        val = (int)(1LL * val * p.val % mod);
        return *this;
    }
    ModInt &operator/=(const ModInt &p) {
        *this *= p.inverse();
        return *this;
    }
    ModInt operator-() const { return ModInt(-val); }
    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }
    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }
    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }
    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }
    bool operator==(const ModInt &p) const { return val == p.val; }
    bool operator!=(const ModInt &p) const { return val != p.val; }
    ModInt inverse() const {
        int a = val, b = mod, u = 1, v = 0, t;
        while (b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }
    ModInt pow(long long n) const {
        ModInt ret(1), mul(val);
        while (n > 0) {
            if (n & 1)
                ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }
    friend ostream &operator<<(ostream &os, const ModInt &p) { return os << p.val; }
    friend istream &operator>>(istream &is, ModInt &a) {
        long long t;
        is >> t;
        a = ModInt<mod>(t);
        return (is);
    }
    static int get_mod() { return mod; }
};
using modint = ModInt<MOD>;

int main() {
    // cin.tie(0);
    // ios::sync_with_stdio(false);

    int N, M;
    cin >> N >> M;
    vector<int> A(N), B(M);
    REP(i, N) { cin >> A.at(i); }
    REP(i, M) { cin >> B.at(i); }
    sort(ALL(A), greater<int>());
    sort(ALL(B), greater<int>());

    int a_i = 0;
    int b_i = 0;
    modint ans = modint(1);
    for (int x = N * M; x > 0; x--) {
        while (A[a_i] > x) {
            a_i++;
        }
        while (B[b_i] > x) {
            b_i++;
        }
        if (A[a_i] == B[b_i] && A[a_i] == x) {
            if ((a_i + 1 < N && A[a_i + 1] == A[a_i]) || (b_i + 1 < M && B[b_i + 1] == B[b_i])) {
                cout << 0;
                return 0;
            }
        } else if (A[a_i] == x) {
            ans *= modint(b_i);
        } else if (B[b_i] == x) {
            ans *= modint(a_i);
        } else {
            ans *= modint(a_i) * modint(b_i) - (modint(N * M) - modint(x));
        }
    }

    cout << ans;
    return 0;
}

#include<cstdio>

#define ran 1011

struct modular_arithmetic{
	int mod;

	modular_arithmetic(){
		mod = 1000000007;
	}
	//No specific settings.
	int add(int x,int y){return (x+=y)<mod?x:x-mod;}
	int sub(int x,int y){return (x-=y)>=0?x:x+mod;}
	int mul(int x,int y){return (int)((long long int)x*y%mod);}
};
modular_arithmetic ma;

int n, m;
int r_ma[ran], c_ma[ran];
bool r[ran*ran], c[ran*ran];

int main() {
	scanf("%d%d", &n, &m);
	for(int i=1;i<=n;i++) {
		scanf("%d", &r_ma[i]);
		r[r_ma[i]] = true;
	}
	for(int i=1;i<=m;i++) {
		scanf("%d", &c_ma[i]);
		c[c_ma[i]] = true;
	}

	int ans = 1;
	int got_r = 0, got_c = 0;
	for(int i = n*m; i>0 && ans>0; i--) {
		if (r[i] && c[i]) {
			got_r ++; got_c ++;
		} else
		if (r[i]) {
			ans = ma.mul(ans, got_c);
			got_r ++;
		} else
		if (c[i]) {
			ans = ma.mul(ans, got_r);
			got_c ++;
		} else {
			ans = ma.mul(ans, got_r * got_c - (n*m-i));
		}
	}
	printf("%d\n", ans);

	return 0;
}

