const ll mod = 1e9 + 7;
const ll inf = 1e18;
const double PI = acos(-1);

void check(VI& A){
  set<ll> se;
  for(ll a : A) se.insert(a);
  if(se.size()==A.size()){
    return;
  }else{
    p(0);
    exit(0);
  }
}

void zero(){
  p("0");
  exit(0);
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll N, M;
    cin >> N >> M;

    VI A(N+1); // ポイント！
    rep(i, N){
        cin >> A.at(i);
    }
    check(A);
    RSORT(A);

    VI B(M+1); // ポイント！
    rep(i, M){
        cin >> B.at(i);
    }
    check(B);
    RSORT(B);

    debug(A);
    debug(B);

    ll i = 0;//Aで置くとしたらここ
    ll j = 0;//Bで置くとしたらここ
    ll res = 1;
    // 大きい順においていく
    for(ll x=N*M; x>=1; x--){
      ll c; // 係数
      if(A[i]==x && B[j]==x){
        i++;
        j++;
        c = 1;
      }
      else if(A.at(i)==x){
        i++;
        c = j;
      }
      else if(B.at(j)==x){
        j++;
        c = i;
      }
      else{
        c = i*j - (N*M-x);
        if(c<0) zero();
      }
      res *= c;
      res %= mod;
    }
    p(res);

    return 0;
}

