lli ExGCD(lli a, lli b, lli &x, lli &y){
	lli d=a;
	x=1; y=0;
	if(b!=0){ d=ExGCD(b, a%b, y, x); y-=a/b*x; }
	return d;
}
lli fact[300001];
lli inv[300001];
void maketable(){
	fact[0] = 1;
	for(int i=0; i<300000; i++){
		fact[i+1] = fact[i]*(i+1) %mod;
	}
	lli y;
	for(int i=0; i<300000; i++){
		ExGCD(fact[i], mod, inv[i], y);
		while(inv[i]<0) inv[i]+=mod;
	}
}
lli nPr(lli n, lli r){
	return fact[n] *inv[n-r] %mod;
}

int main(){
	maketable();
	int n,m;
	cin >> n >> m;
	vector<int> a(n), b(m);
	for(int i=0; i<n; i++){
		cin >> a[i];
	}
	sort(a.begin(), a.end());
	a.erase(unique(a.begin(), a.end()), a.end());
	for(int i=0; i<m; i++){
		cin >> b[i];
	}
	sort(b.begin(), b.end());
	b.erase(unique(b.begin(), b.end()), b.end());
	if((int)a.size()!=n || (int)b.size()!=m){
		cout << 0 << endl;
		return 0;
	}

	lli ans = 1;
	int ridx=0, cidx=0;
	int used=0;
	while(ridx<n && cidx<m){
		if(ridx!=n && cidx!=m && a[ridx]==b[cidx]){
			//同時
			int num = n-ridx +m-cidx -1;
			if(used+num <= a[ridx]){
				ans *= nPr(a[ridx]-used-1, num-1);
				ans %= mod;
				used += num;
				ridx++;
				cidx++;
			}else{
				ans = 0;
				break;
			}
		}else if(cidx==m || (ridx!=n && a[ridx] < b[cidx])){
			//行を取る
			int num = m-cidx;
			if(used+num <= a[ridx]){
				ans *= nPr(a[ridx]-used-1, num-1) *num %mod;
				ans %= mod;
				used += num;
				ridx++;
			}else{
				ans = 0;
				break;
			}
		}else{
			//列を取る
			int num = n-ridx;
			if(used+num <= b[cidx]){
				ans *= nPr(b[cidx]-used-1, num-1) *num %mod;
				ans %= mod;
				used += num;
				cidx++;
			}else{
				ans = 0;
				break;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

