void solve() {
    ll a_bigger[n], b_bigger[m];
    fill(a_bigger, a_bigger + n, 0);
    fill(b_bigger, b_bigger + m, 0);

    bool used[n * m];
    fill(used, used + n * m, false);
    rep(i, n) rep(j, m) if (a[i] >= b[j]) {
                a_bigger[i]++;
                used[a[i]] = true, used[b[j]] = true;
            }
    rep(i, m) rep(j, n) if (b[i] >= a[j]) b_bigger[i]++;
    ll c_used = 0;
