    ll ans = 1;
    rep(i, n) {
        ans *= a_bigger[i], ans %= mod;
    }
    rep(i, m) {
        ans *= b_bigger[i], ans %= mod;
    }
    repone(i, n * m - c_used) ans *= i, ans %= mod;
    cout << ans << endl;
}

