const int mod = 1e9 + 7;
const int MX = 1100000;
ll inv[MX], f[MX], invf[MX];
void calc(){
	inv[0] = inv[1] = f[0] = f[1] = invf[0] = invf[1] = 1;
	for (int i = 2; i < MX; i++){
		inv[i] = mod - mod / i * inv[mod % i] % mod;
		f[i] = f[i - 1] * i % mod;
		invf[i] = invf[i - 1] * inv[i] % mod;
	}
}
inline ll C(ll n, ll k){
	if(n < k || k < 0) return 0;
	return f[n] * invf[k] % mod * invf[n - k] % mod;
}
int main(){
	calc();
	cin.tie(0); cin.sync_with_stdio(0);
	int n, m; cin >> n >> m;
	vi a(n), b(m);
	rep(i, n) cin >> a[i];
	rep(i, m) cin >> b[i];
	sort(all(a)); sort(all(b));

	ll ans = 1;
	int x = 0, y = 0, use = 0;

	for(int i = n * m; i > 0; i--){
		bool af = binary_search(all(a), i);
		bool bf = binary_search(all(b), i);

		if(!af && !bf){
			ans *= x * y - n * m + i;
		}
		else if(af && bf){
			x++; y++; use++;
		}
		else if(af){
			ans *= y; x++; use++;
		}
		else{
			ans *= x; y++; use++;
		}
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

