    vector<int> row(N * M, -1), col(N * M, -1);
    rep(i, N) row[a[i]] = i;
    rep(j, M) col[b[j]] = j;
    int R = 0, C = 0, k = 0;
    ll ans = 1;
    for (int x = N * M - 1; x >= 0; x--) {
