int idx(const vector<int>& s, int x) {
    auto it = lower_bound(all(s), x);
    if (it == s.end())
        return s.size();
    if (*it != x)
        return s.size();
    return it - s.begin();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    forn(i, n)
        cin >> a[i];
    vector<int> b(m);
    forn(j, m)
        cin >> b[j];
    vector<int> sa = a;
    sort(all(sa));
    vector<int> sb = b;
    sort(all(sb));

    for (int i = 0; i < n - 1; i++)
        if (sa[i] == sa[i + 1]) {
            cout << 0 << endl;
            return 0;
        }

    for (int i = 0; i < m - 1; i++) {
        if (sb[i] == sb[i + 1]) {
            cout << 0 << endl;
            return 0;
        }
    }

    ll places = 0;
    ll ans = 1;

    for (int i = n * m; i >= 1; i--) {
        int ina = idx(sa, i);
        int inb = idx(sb, i);
        int lba = lower_bound(all(sa), i) - sa.begin();
        int lbb = lower_bound(all(sb), i) - sb.begin();

        if (ina != n && inb != m) {
            places += (n - ina - 1) + (m - inb - 1);
        } else if (ina != n) {
            ans = (ans * (m - lbb)) % mod;
            places += m - lbb - 1;
        } else if (inb != m) {
            ans = (ans * (n - lba)) % mod;
            places += n - lba - 1;
        } else {
            ans = (ans * places) % mod;
            --places;
        }
    }

    cout << ans << endl;

    return 0;
}

