		int a; cin >> a; a--;
		H[a]++;
	}
	rep(i, 0, M) {
		int a; cin >> a; a--;
		V[a]++;
	}
	int sh = 0, sv = 0, cross = 0;
	ll res = 1;
	rer(i, N * M, 0) {
		if(H[i] >= 2 || V[i] >= 2) {
			cout << 0 << "\n"; return;
		}
		else if(H[i] && V[i]) {
			sh++;
			sv++;
			cross++;
		}
		else if(H[i]) {
			MUL(res, sv);
			sh++;
			cross++;
		}
		else if(V[i]) {
			MUL(res, sh);
			sv++;
			cross++;
		}
		else {
			MUL(res, max(sh * sv - cross, 0));
			cross++;
		}
	}
	cout << res << "\n";
}

