const long long MOD = 1000000007;

void solve(long long N, long long M, std::vector<long long> A,
           std::vector<long long> B) {
  sort(all(A));
  sort(all(B));

  ll ans = 1;
  for (ll x = N * M; x >= 1; x--) {
    if ((upper_bound(all(A), x) - lower_bound(all(A), x) > 1) ||
        (upper_bound(all(B), x) - lower_bound(all(B), x) > 1)) {
      ans = 0;
      break;
    }

    bool aExists = binary_search(all(A), x);
    bool bExists = binary_search(all(B), x);
    ll num = 1;
    if (aExists && !bExists) {
      num = B.end() - lower_bound(all(B), x);
    } else if (!aExists && bExists) {
      num = A.end() - lower_bound(all(A), x);
    } else if (!aExists && !bExists) {
      num = (B.end() - lower_bound(all(B), x)) *
                (A.end() - lower_bound(all(A), x)) -
            (N * M - x);
    }
    ans *= num;
    ans %= MOD;
  }
  print(ans);
}

