ModInt<> solve() {
  a.erase(unique(a.begin(), a.end()), a.end());
  b.erase(unique(b.begin(), b.end()), b.end());
  if (a.size() != n || b.size() != m) return 0;
  ModInt<> res = 1;
  for (int i = n * m, aid = 0, bid = 0, sum = 0; i >= 1; --i) {
    if (aid < n && bid < m && a[aid] == i && b[bid] == i)
      sum += aid++ + bid++;
    else if (aid < n && a[aid] == i) {
      res *= bid;
      sum += bid - 1;
      ++aid;
    } else if (bid < m && b[bid] == i) {
      res *= aid;
      sum += aid - 1;
      ++bid;
    } else
      res *= sum--;
  }
  return res;
}

