struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 x) : x(x) {
    if (x > P || x < 0) { cerr << "Invalied FiniteField!" << endl; exit(1); }
  }
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

FiniteField Solve() {
  int h, w;
  cin >> h >> w;
  vector<int> rs(h);
  for (int i = 0; i < h; i++) {
    cin >> rs[i];
  }
  vector<int> cs(w);
  for (int i = 0; i < w; i++) {
    cin >> cs[i];
  }

  FiniteField ans = 1;
  for (int x = h * w; x >= 1; x--) {
    int r = -1;
    int c = -1;
    for (int i = 0; i < h; i++) {
      if (rs[i] == x) {
        if (r < 0) r = i;
        else return 0;
      }
    }
    for (int i = 0; i < w; i++) {
      if (cs[i] == x) {
        if (c < 0) c = i;
        else return 0;
      }
    }

    if (r >= 0 && c >= 0) {
      // do nothing
    } else if (r >= 0) {
      ans *= w;
    } else if (c >= 0) {
      ans *= h;
    } else {
      int r_count = 0;
      int c_count = 0;
      for (int i = 0; i < h; i++) {
        if (rs[i] > x) {
          r_count++;
        }
      }
      for (int i = 0; i < w; i++) {
        if (cs[i] > x) {
          c_count++;
        }
      }
      int m = r_count * c_count - (h * w - x);
      if (m <= 0) return 0;
      ans *= m;
    }
  }
  return ans;
}

