void solve(long long N, long long M, vector<long long> A, vector<long long> B){
	sort(A.begin(),A.end());
	sort(B.begin(),B.end());
	bool runnable=true;
	for (int i = 0; i<N-1; i++) {
		if (A[i] == A[i+1]) runnable = false;
	}
	for (int i = 0; i<M-1; i++) {
		if (B[i] == B[i+1]) runnable = false;
	}

	long long res = 1;
	for (int i = N*M; i>0; i--) {
		long long aCount = upper_bound(A.begin(),A.end(),i) - lower_bound(A.begin(),A.end(),i);
		long long bCount = upper_bound(B.begin(),B.end(),i) - lower_bound(B.begin(),B.end(),i);
		if (aCount != 0 && bCount != 0) {
		} else if (aCount != 0) {
			res *= B.end() - upper_bound(B.begin(),B.end(),i);
			res %= 1000000007;
		} else if (bCount != 0) {
			res *= A.end() - upper_bound(A.begin(),A.end(),i);
			res %= 1000000007;
		} else {
			//cout << ( N - (upper_bound(A.begin(),A.end(),i) - A.begin()))*(M - (upper_bound(B.begin(),B.end(),i) - B.begin()))-(N*M-i) << "\n";
			res *= ( N - (upper_bound(A.begin(),A.end(),i) - A.begin()))*(M - (upper_bound(B.begin(),B.end(),i) - B.begin()))-(N*M-i);
			res %= 1000000007;
		}
	}
	if (runnable) {
		cout << res << "\n";
	} else {
		cout << "0\n";
	}
}

