const ll mod = 1000000007LL;

int bf() {
  vector<int> vec(H*W);
  rep(i,H) rep(j,W) vec[i+j*W] = i + j * W + 1;
  sort(ALL(vec));
  int cnt = 0;
  do {
    vector<int> a(H,-1), b(W,-1);
    rep(i,H) {
      rep(j,W) {
	a[i] = max(a[i],vec[i+j*W]);
	b[j] = max(b[j],vec[i+j*W]);
      }
    }
    bool ok = true;
    rep(i,H) if( a[i] != A[i] ) ok = false;
    rep(i,W) if( b[i] != B[i] ) ok = false;
    if( ok ) ++cnt;
  } while( next_permutation(ALL(vec)) );
  return cnt;
}

void compute() {
  ll ans = 1;
  map<int,int> mp_x, mp_y;
  rep(i,H) mp_y[A[i]] = i;
  rep(i,W) mp_x[B[i]] = i;
  set<int> put_x, put_y;
  for(int v=H*W;v>=1;--v) {
    bool exist_x = mp_x.count(v);
    bool exist_y = mp_y.count(v);
    if( exist_x && exist_y ) {
      put_x.insert(mp_x[v]);
      put_y.insert(mp_y[v]);

    } else if( exist_x ) {
      if( put_y.size() == 0 ) {
	puts("0");
	return;
      }
      ( ans *= (ll)put_y.size() ) %= mod;
      put_x.insert(mp_x[v]);

    } else if( exist_y ) {
      if( put_x.size() == 0 ) {
	puts("0");
	return;
      }
      ( ans *= (ll)put_x.size() ) %= mod;
      put_y.insert(mp_y[v]);

    } else {
      ll score = (ll)put_x.size() * (ll)put_y.size();
      score -= ( H * W - v );
      ans = ans * score;
      ans %= mod;
    }
  }
  cout << ans << endl;
  //cout << "ANS : " << bf() << endl;
}

