    fac = new ll[1000000];
    finv = new ll[1000000];
    inv = new ll[1000000];
    fac[0] = 1;
    for(int i=1;i<1000000;i++){
      fac[i] = i*fac[i-1];
      fac[i] %= MOD;
    }
    inv[1] = 1;
    for(int i=2;i<1000000;i++){
      inv[i] = MOD-inv[MOD%i]*(MOD/i)%MOD;
    }
    finv[0] = 1;
    for(int i=1;i<1000000;i++){
      finv[i] = inv[i]*finv[i-1];
      finv[i] %= MOD;
    }
  }
  ll calc(ll n,ll k){
    ll c = fac[n];
    c *= finv[k];c %= MOD;
    c *= finv[n-k];c %= MOD;
    return c;
  }
};

ll gcd(ll x,ll y){
  if(x%y == 0) return y;
  else return gcd(y,x%y);
}
int main(){
  ll n,m;
  cin >> n >> m;
  ll a[n],b[m];
  bool able = true;
  for(int i=0;i<n;i++){
    cin >> a[i];
    if(a[i] < 1 || n*m < a[i]) able = false;
  }
  for(int i=0;i<m;i++){
    cin >> b[i];
    if(b[i] < 1 || n*m < b[i]) able = false;
  }
  sort(a,a+n);
  sort(b,b+n);
  for(int i=1;i<n;i++){
    if(a[i] == a[i-1]) able = false;
  }
  for(int i=1;i<m;i++){
    if(b[i] == b[i-1]) able = false;
  }
  ll ans = 1;
  if(!able){
    cout << 0 << endl;
    return 0;
  }

  ll x,y;
  for(ll v=n*m;v>=1;v--){
    auto itrx = lower_bound(a,a+n,v);
    auto itry = lower_bound(b,b+m,v);
    x = itrx - a;
    y = itry - b;
    if(x == n || y == m){
      ans = 0;
      continue;
    }
    if(*itrx == v && *itry == v) continue;
    if(*itrx == v){
      ans *= m-y;
      ans %= MOD;
      continue;
    }
    if(*itry == v){
      ans *= n-x;
      ans %= MOD;
      continue;
    }
    ll mul;
    mul = (m-y)*(n-x)-(n*m-v);
    mul %= MOD;
    ans *= mul;
    ans %= MOD;
  }
  cout << ans << endl;
  return 0;
}

