#include <bits/stdc++.h>
using namespace std;

class Solution {
  vector<bool> freeRow, freeCol;
  int freeRowNum, freeColNum;
  int n, m;
  struct Place {
    int num;
    int id;
    Place(int num, int id) : num(num), id(id) {}
    bool operator<(Place oth) const {
      return num < oth.num;
    }
  };
  vector<Place> row, col;
  const long long MOD = 1e9 + 7;
public:
  void run(istream &in, ostream &out) {
    in >> n >> m;
    freeRow.assign(n, false);
    freeRowNum = n;
    freeCol.assign(m, false);
    freeColNum = m;
    for (int i = 0; i < n; ++i) {
      int a; in >> a;
      row.emplace_back(a, i);
    }
    for (int i = 0; i < m; ++i) {
      int a; in >> a;
      col.emplace_back(a, i);
    }
    sort(row.begin(), row.end());
    sort(col.begin(), col.end());
    auto rowFront = [&](int a) -> bool {
      return row.size() and row.back().num == a;
    };
    auto colFront = [&](int a) -> bool {
      return col.size() and col.back().num == a;
    };
    long long ans = 1;
    for (int i = n * m; i >= 1; --i) {
      if (rowFront(i) and colFront(i)) {
        ans *= 1;
        freeRow[row.back().id] = true;
        --freeRowNum;
        row.pop_back();

        freeCol[col.back().id] = true;
        --freeColNum;
        col.pop_back();
      }
      else if (rowFront(i)) {
        ans = ans * (m - freeColNum) % MOD;
        freeRow[row.back().id] = true;
        --freeRowNum;
        row.pop_back();
      }
      else if (colFront(i)) {
        ans = ans * (n - freeRowNum) % MOD;
        freeCol[col.back().id] = true;
        --freeColNum;
        col.pop_back();
      }
      else {
        ans = ans * ((m - freeColNum) * (n - freeRowNum) - n * m + i)% MOD;
      }
    }
    out << ans << '\n';;
  }
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  Solution().run(cin, cout);
  return 0;
}

