  ll n, m;
  cin >> n >> m;
  vll as(n), bs(m);
  rep(i, n) cin >> as[i];
  rep(i, m) cin >> bs[i];
  sort(as.begin(), as.end());
  sort(bs.begin(), bs.end());
  ll siz = 0, presiz = 0;
  ll cand = 0;
  bool ok = as.back() == n * m && bs.back() == n * m;
  rep(i, n - 1) ok &= as[i] < as[i + 1];
  rep(i, m - 1) ok &= bs[i] < bs[i + 1];
  if(!ok){
    puts("0");
    return 0;
  }
  mint ans(1);
  rrepLRE(i, m * n, 1) {
    ll y = Lower_bound(as, i);
    ll x = Lower_bound(bs, i);
    presiz = siz;
    siz = (n - y) * (m - x);
    cand += siz - presiz;
    ll mulv;
    if (as[y] == i && bs[x] != i)
      mulv = m - x;
    else if (as[y] != i && bs[x] == i)
      mulv = n - y;
    else if (as[y] == i && bs[x] == i)
      mulv = 1;
    else
      mulv = cand;
    ans *= mulv;
    cand--;
  }

  cout << ans.x << endl;

  return 0;
}

