// 二項係数ライブラリ
template <class T>
struct Combination {
    vector<T> fact_, inv_, finv_;
    constexpr Combination() {}
    constexpr Combination(int n) noexcept : fact_(n, 1), inv_(n, 1), finv_(n, 1) {
        init(n + 1);
    }
    constexpr void init(int n) noexcept {
        fact_.assign(n, 1), inv_.assign(n, 1), finv_.assign(n, 1);
        int MOD = fact_[0].get_mod();
        for(int i = 2; i < n; i++) {
            fact_[i] = fact_[i - 1] * i;
            inv_[i] = -inv_[MOD % i] * (MOD / i);
            finv_[i] = finv_[i - 1] * inv_[i];
        }
    }
    constexpr T nPr(int n, int k) const noexcept {
        if(n < k || n < 0 || k < 0)
            return 0;
        return fact_[n] * finv_[n - k];
    }
    constexpr T nCr(int n, int k) const noexcept {
        if(n < k || n < 0 || k < 0)
            return 0;
        return fact_[n] * finv_[k] * finv_[n - k];
    }
    constexpr T nHr(int n, int k) const noexcept {
        if(n < k || n < 0 || k < 0)
            return 0;
        return nCr(n + k - 1, k);
    }
    constexpr T fact(int n) const noexcept {
        if(n < 0)
            return 0;
        return fact_[n]; //n!
    }
    constexpr T inv(int n) const noexcept {
        if(n < 0)
            return 0;
        return inv_[n]; //1/n
    }
    constexpr T finv(int n) const noexcept {
        if(n < 0)
            return 0;
        return finv_[n]; //1/n!
    }
};

void solve() {
    ll n, m;
    cin >> n >> m;
    vec<ll> a(n), b(m);
    REP(i, n) { cin >> a[i]; }
    REP(i, m) { cin >> b[i]; }
    sort(all(a));
    sort(all(b));

    REP(i, n - 1) {
        if(a[i] == a[i + 1]) {
            cout << 0 << en;
            return;
        }
    }
    REP(i, m - 1) {
        if(b[i] == b[i + 1]) {
            cout << 0 << en;
            return;
        }
    }

    if(a[n - 1] != b[m - 1] or a[n - 1] != n * m) {
        cout << 0 << en;
        return;
    }

    Combination<mint> com(n * m);

    mint ans = 1;
    ll used = 0;
    vec<bool> flag(m, false);

    int i = 0, j = 0;
    while(used < n * m) {
        if(a[i] < b[j]) {
            ans *= com.nPr(a[i] - used - 1, m - j - 1) * (m - j);
            i++;
            used += m - j;
        } else if(a[i] == b[j]) {
            ans *= com.nPr(a[i] - used - 1, m - j - 1);
            flag[j] = true;
            i++;
            used += m - j;
        } else {
            if(flag[j])
                ans *= com.nPr(b[j] - used, n - i);
            else
                ans *= com.nPr(b[j] - used - 1, n - i - 1) * (n - i);
            j++;
            used += n - i;
        }
    }
    cout << ans << en;
}

