    map<int, bool> mp_A, mp_B;
    bool is_ok = true;
    ll A, B;
    for (int i = 0; i < N; i++) {
        cin >> A;
        if (mp_A[A]) is_ok = false;
        mp_A[A] = true;
        A_count[A] = 1;
    }
    for (int i = 0; i < M; i++) {
        cin >> B;
        if (mp_B[B]) is_ok = false;
        mp_B[B] = true;
        B_count[B] = 1;
    }
    if (!is_ok) {
        cout << 0 << endl;
        return 0;
    }
    for (ll i = N * M; i > 1; i--) {
        A_count[i - 1] += A_count[i];
        B_count[i - 1] += B_count[i];
    }
    ll ans = 1;
    for (ll now_num = N * M; now_num >= 1; now_num--) {
        if (mp_A[now_num] && mp_B[now_num]) continue;
        else if (mp_A[now_num]) ans = (ans * B_count[now_num]) % MOD;
        else if (mp_B[now_num]) ans = (ans * A_count[now_num]) % MOD;
        else ans = (ans * (((A_count[now_num] * B_count[now_num]) % MOD - (N * M - now_num) + MOD) % MOD)) % MOD;
    }
    cout << ans << endl;
    return 0;
}

