    auto u = upper_bound(xs.begin(), xs.end(), value);
    return u - l;
}

ll count_same_or_larger(const ll value, const vector<ll> &xs) {
    auto l = lower_bound(xs.begin(), xs.end(), value);
    return xs.end() - l;
}

