const int MOD=1e9+7;
std::vector<int> a,b;
int N,M;

int loboa(int n){
  int l=0,r=N;
  while(r-l>1){
    int m=(l+r)/2;
    if(a[m]>=n)l=m;
    else r=m;
  }
  return l;
}
int lobob(int n){
  int l=0,r=M;
  while(r-l>1){
    int m=(l+r)/2;
    if(b[m]>=n)l=m;
    else r=m;
  }
  return l;
}

signed main() {
  cin>>N>>M;
  std::vector<int> a(N),b(M);
  for(int i=0;i<N;i++)cin>>a[i];
  for(int i=0;i<M;i++)cin>>b[i];
  sort(a.rbegin(),a.rend());
  sort(b.rbegin(),b.rend());
  for(int i=1;i<N;i++)if(a[i]==a[i-1]){cout<<-1<<endl;return 0;}
  for(int i=1;i<M;i++)if(b[i]==b[i-1]){cout<<-1<<endl;return 0;}
  int ans=1;
  for(int i=N*M;i>0;i--){
    int A=loboa(i);
    int B=lobob(i);
    if(a[A]<i||b[B]<i){cout<<-1<<endl;return 0;}
    if(a[A]==i&&b[B]==i)continue;
    if(a[A]==i)ans*=B+1;
    if(b[B]==i)ans*=A+1;
    if(a[A]!=i&&b[B]!=i){
      if((A+1)*(B+1)-N*M+i>0)ans*=(A+1)*(B+1)-N*M+i;
      else {cout<<-1<<endl;return 0;}
    }
    ans%=MOD;
  }
  cout<<ans<<endl;
}

