    cin >> n >> m;
    map<int, int> ma;
    bool check = false;
    for (int i = 0; i < n; i++)
    {
        ll temp;
        cin >> temp;
        a.push_back(temp);
        ma[temp]++;
        if (ma[temp] > 1)
            check = true;
    }
    map<int, int> mb;
    for (int i = 0; i < m; i++)
    {
        ll temp;
        cin >> temp;
        b.push_back(temp);
        mb[temp]++;
        if (mb[temp] > 1)
            check = true;
    }
    if (check)
        return cout << 0 << "\n", 0;
    sort(ALL(a), greater<ll>());
    sort(ALL(b), greater<ll>());
    ll ans = 1;
    ll x = 0;
    ll y = 0; //ぴったりの数を探しているところ
    //else埋められるのはxyの前の数まで
    //i==a[x]||i==b[y]を満たすときは初めて入るため必ずその行or列は空
