int main(){
    int N,M;
    cin >> N >> M;
    vector<int> A(N);
    vector<int> B(N);
    for(int i=0; i<N; i++){
        cin >> A[i];
    }
    for(int i=0; i<N; i++){
        cin >> B[i];
    }

    long long ans =1;
    vector<long long> candidate(N*M,0);
    vector<int> decide(N*M,0);
    vector<int> Aed(N*M,0);
    vector<int> Bed(N*M,0);
    for(int i=0; i<N; i++){
        int a=A[i]-1;
        if(Aed[a]==1)ans=0;
        else Aed[a]++;
        for(int j=0; j<M; j++){
            int b=B[j]-1;
            if(Bed[b]>i)ans=0;
            else Bed[b]++;
            if(a<b){
                candidate[a]++;
            }else if(a>b){
                candidate[b]++;
            }else{
                decide[a]=1;
                candidate[a]++;
            }
        }
    }
    long long tmp=0;
    for(int i=N*M-1; i>=0; --i){
        if (candidate[i]==0){
            candidate[i]=tmp;
        }else{
            tmp+=candidate[i];
        }
        if(decide[i]==1){
            candidate[i]=1;
        }
        tmp--;
    }
    long long MOD=1000000007;
    for(int i=0; i<N*M; i++){
        ans*=max((long long)0,candidate[i]);
        ans%=MOD;
    }

    //vec_cout(candidate);
    //cout << endl;
