  cin.tie(0);
  ll N, M; cin >> N >> M;
  vector<ll> A(N), B(M);
  rep(i, N) cin >> A[i];
  rep(i, M) cin >> B[i];
  sort(A.begin(), A.end());
  sort(B.begin(),B.end());
  ll ans = 1;
  for(ll k = N * M; k > 0 ; k--) {
     if(binary_search(A.begin(), A.end(), k)) {
        if(binary_search(B.begin(), B.end(), k)) {
           continue;
        } else {
            ans *= (A.end() - lower_bound(A.begin(), A.end(), k));
            ans %= mod;
        }
     }
     else if(binary_search(B.begin(), B.end(), k)) {
         ans *= (B.end() - lower_bound(B.begin(), B.end(), k));
         ans %= mod;
     }
     else {
         ll C = (A.end() - lower_bound(A.begin(), A.end(), k)) * (B.end() - lower_bound(B.begin(), B.end(), k)) - (N * M - k);
         ans *= (C > 0 ? C : 0);
         ans %= mod;
     }
  }
  cout << ans << endl;
  return 0;
}

