ll f(){
    int n = N * M, po = 0;
    int r = 0, c = 0, rem = 0;
    ll cnt = 1;

    while(n > 0){
        if(po < v.size() && fst(v[po]) == n){
            int x1, y1;
            std::tie(x1, y1) = v[po];

            if(po + 1 < v.size() && fst(v[po+1]) == n){
                if(snd(v[po+1]) == y1){
                    return 0;
                }

                po += 2;
                rem += r + c;
                r += 1;
                c += 1;
            }else{
                if(y1 == 1){
                    if(c == 0){
                        return 0;
                    }

                    cnt = cnt * c % MOD;
                    r += 1;
                    rem += c - 1;
                }else{
                    if(r == 0){
                        return 0;
                    }

                    cnt = cnt * r % MOD;
                    c += 1;
                    rem += r - 1;
                }

                po += 1;
            }
        }else{
            if(rem == 0){
                return 0;
            }

            cnt = cnt * rem % MOD;
            rem -= 1;
        }

        n -= 1;
    }

    if(r < N || c < M || rem > 0){
        return 0;
    }

    return cnt;
}

