    MINUS(AtoInd); MINUS(BtoInd);
    REP(i, N) {
        // 同じ値が 2 回以上出てくるなら 0
        if(AtoInd[A[i]] != -1) { return 0; }
        AtoInd[A[i]] = i;
        AB_sort.push_back(make_tuple(A[i], i, 0));
    }
    REP(i, M) {
        if(BtoInd[B[i]] != -1) { return 0; }
        BtoInd[B[i]] = i;
        AB_sort.push_back(make_tuple(B[i], i, 1));
    }
    SORT(AB_sort);

    // grid の作成
    grid.assign(N, vector<ll>(M, -1));
    for(auto& ab : AB_sort) {
        ll val = get<0>(ab);
        ll ind = get<1>(ab);
        ll type = get<2>(ab);

        if(type == 0) {
            REP(j, M) {
                if(grid[ind][j] == -1) { grid[ind][j] = val; }
            }
        }
        else {
            REP(i, N) {
                if(grid[i][ind] == -1) { grid[i][ind] = val; }
            }
        }
    }

    // cnt の作成
    cnt.assign(N * M + 1, 0);
    REP(i, N) { REP(j, M) { cnt[grid[i][j]]++; } }

    // cnt を元にパターン数を求める
    ll ret = 1;
    ll used = 0;    // 使用済みの数字の数
    for(ll i = 1; i <= N * M; ++i) {
        if(cnt[i] == 0) { continue; }
        ll avail = i - used;
        if(cnt[i] > avail) { return 0; }
        // 最大値の分の 1 つは必ず選択しなければならない
        if(AtoInd[i] != -1 && BtoInd[i] != -1) {
            // かつ最大値の位置が確定しているなら、それ以外のもののパターンを加える
            ret *= noc.Permutation(avail - 1, cnt[i] - 1);
            ret %= MOD;
        }
        else {
            // 最大値もある程度動いていいなら、動く
            ret *= cnt[i];
            ret %= MOD;
            ret *= noc.Permutation(avail - 1, cnt[i] - 1);
            ret %= MOD;
        }
        used += cnt[i];
    }

    return ret;
}

