const int MOD = 1e9 + 7;

void add(int& x, int y) {
    ((x += y) >= MOD) && (x -= MOD);
}

int mul(int x, int y) {
    return x * 1ll * y % MOD;
}

const int MAXN = 1e3 + 10;

int n, m;
vi a;
vi b;

bool read() {
    if (!(cin >> n >> m)) {
        return 0;
    }
    a.resize(n);
    forn(i, n) {
        cin >> a[i];
        --a[i];
    }
    b.resize(m);
    forn(i, m) {
        cin >> b[i];
        --b[i];
    }
    return 1;
}

int pos_a[MAXN * MAXN];
int pos_b[MAXN * MAXN];

int solve() {
    memset (pos_a, -1, sizeof pos_a);
    memset (pos_b, -1, sizeof pos_b);

    forn(i, n) {
        pos_a[a[i]] = i;
    }
    forn(i, m) {
        pos_b[b[i]] = i;
    }

    int ans = 1;
    int cnt_a = 0;
    int cnt_b = 0;
    int crosses = 0;
    ford(v, n * m) {
        int pa = pos_a[v];
        int pb = pos_b[v];
        if (pa != -1 && pb == -1) {
            ans = mul(ans, cnt_b);
            crosses += cnt_b - 1;
        } else if (pa == -1 && pb != -1) {
            ans = mul(ans, cnt_a);
            crosses += cnt_a - 1;
        } else if (pa != -1 && pb != -1) {
            crosses += cnt_a;
            crosses += cnt_b;
        } else {
            ans = mul(ans, crosses);
            --crosses;
        }
        if (crosses < 0) {
            return 0;
        }
        cnt_a += pa != -1;
        cnt_b += pb != -1;
    }

    return ans;
}

