  if (num == -1) return 1;
  if (must_col[num] != -1 && must_row[num] != -1) {
    return rec(num - 1) % MOD;
  }
  ll ret = 1;
  if (must_col[num] == -1) ret *= N - POSL(A, num); // ret %= MOD;
  if (must_row[num] == -1) ret *= M - POSL(B, num); // ret %= MOD;
  return ret * rec(num - 1) % MOD;
}

