// テーブルを作る前処理
void init() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for (int i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % MOD;
		inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
		finv[i] = finv[i - 1] * inv[i] % MOD;
	}
}

LL nPr(LL n, LL r) {
	if (n < r) {
		return 0LL;
	}
	return (fac[n] *finv[n-r]) % MOD;
}

int main(){
	init();
