			if (ab[i][j] == ab[i][j + 1]) {
				printf("0\n");
				return 0;
			}
		}
	}
	vector<PII> vpii;
	REP(i, 2)REP(j, nm[i])vpii.PB(MP(ab[i][j], i));
	LL done = 0;
	SORT(vpii);
	vpii.PB(MP(-1, -1));
	vpii.insert(vpii.begin(), MP(-1, -1));
	LL ret = 1;
	REP(i, vpii.size() - 2) {
		auto x = vpii[i+1];
		if (vpii[i + 2].first == x.first) {
			ret = (ret*nPr(x.first - done - 1, nm[1-x.second] - 1)) % MOD;
		}
		else if (vpii[i].first == x.first) {
			ret = (ret*nPr(x.first - done, nm[1 - x.second])) % MOD;
		}
		else {
			ret = (((ret * nm[1 - x.second]) % MOD) * nPr(x.first - 1 - done, nm[1 - x.second] - 1))%MOD;
		}
		done += nm[1 - x.second];
		nm[x.second]--;
		if (nm[x.second] == 0)break;
	}
	cout << ret << endl;
	return 0;
}

