void solve() {
	int N, M; cin >> N >> M;
	vector<int> A(N); for (auto& a : A) cin >> a;
	vector<int> B(M); for (auto& a : B) cin >> a;
	sort(ALL(A));
	sort(ALL(B));
	if (A.back() != N * M or B.back() != N * M) {
		cout << 0 << endl;
		return;
	}

	vector<bool> memo(N * M + 1);
	set<int> Aset;
	for (auto& a : A) {
		if (Aset.count(a) == 1) {
			cout << 0 << endl;
			return;
		}
		Aset.insert(a);
	}
	set<int> Bset;
	for (auto& b : B) {
		if (Bset.count(b) == 1) {
			cout << 0 << endl;
			return;
		}
		Bset.insert(b);
	}

	for (auto& b : B) {
		if (Aset.count(b) == 1) {
			memo[b] = true;
		}
	}

	vector<int> cnt(N * M + 1);
	REP(i, memo.size()) if (memo[i]) cnt[i] = 1;

	RFOR(i, 1, cnt.size()) cnt[i - 1] += cnt[i];

	mint res = 1;

	RFOR(i, 1, cnt.size()){
		auto Aindex = lower_bound(ALL(A), i) - A.begin();
		auto Bindex = lower_bound(ALL(B), i) - B.begin();
		if (A[Aindex] == i and B[Bindex] == i) {
			res *= 1;
		}
		else if (A[Aindex] == i) {
			res *= (B.size() - Bindex);
		}
		else if (B[Bindex] == i) {
			res *= (A.size() - Aindex);
		}
		else {
			res *= (A.size() - Aindex) * (B.size() - Bindex) - (cnt.size() - i - 1);
		}
	}
	cout << res << endl;
}

