      ans *= (long long)col_index + 1LL;
      ans = mod(ans);
    }else if(b[col_index]==i){
      ans *= (long long)row_index + 1LL;
      ans = mod(ans);
    }else{
      if((1+row_index)*(1+col_index)-(n*m-i)<=0){
        ans = 0;
        break;
      }
      ans *= (1LL+(long long)row_index)*(1LL+(long long)col_index)-((long long)n*(long long)m-(long long)i);
      ans = mod(ans);
    }
  }

  cout<<ans<<endl;

  return 0;
}

