int ser(vel &v, int tan) {
	int si = v.size() - 1;
	if (tan == v[si]) {
		return si;
	}
	int lo = 0;
	int up = si;
	while (up - lo > 1) {
		int mi = (lo + up) / 2;
		if (v[mi] >= tan) {
			lo = mi;
		}
		else {
			up = mi;
		}
	}
	return lo;
}
int rui(int a, int n, int p) {
	if (n == 0) {
		return 1;
	}
	int x = rui(a, n / 2, p);
	x *= x;
	x = x % p;
	int bi = 1;
	if (n % 2 == 1) {
		bi = a % p;
	}
	x *= bi;
	return x % p;
}
int com(int n, int r, vel &kai, vel &inv,int p) {
	int q = n - r;
	if (n < 0 or p < 0 or q < 0) {
		return 0;
	}
	int ans = kai[n] * inv[r];
	ans = ans % p;
	ans *= inv[q];
	return ans % p;
}
