const ll MOD = 1e9+7;

/*
 BIT 1-index
 add : x に valを加算
 sum : [1,x] の総和を出力
 */
struct BIT {
    ll N;
    vector<ll> bit;
    BIT(ll N):N(N) {
        /* BITは[1..N]で扱う */
        bit.resize(N + 1, 0);
    }

    void add(int x, ll val){
        while (x <= N) {
            bit[x] += val;
            x += x & -x;
        }
    }

    ll sum(int x){
        ll ret = 0;
        if(x == 0) return ret;
        while (x) {
            ret += bit[x];
            x &= (x - 1);
        }
        return (ret);
    }
    // [l,r]
    ll sum(int l,int r){
        return sum(r) - sum(l-1);
    }
};

template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<ll> A(N),B(M);
    vector<ll> cntA(N*M+1),cntB(N*M+1);
    for(auto& in:A){ cin >> in; cntA[in]++;}
    for(auto& in:B){ cin >> in; cntB[in]++;}

    BIT bitA(N*M),bitB(N*M);
    for(int i = 1; i <= N*M;i++){
        if(cntA[i] >= 2 || cntB[i] >= 2) return 0;
        bitA.add(i,cntA[i]);
        bitB.add(i,cntB[i]);
    }

    res = 1;
    for(int x = N*M; x >= 1;x--){
        if(cntA[x] >= 2 || cntB[x] >= 2) res = 0;

        ll L = 1,R = 1;
        if(cntA[x] == 0) L = bitA.sum(x,N*M);
        if(cntB[x] == 0) R = bitB.sum(x,N*M);

        if(cntA[x] == 0 && cntB[x] == 0) (res *= L*R-(N*M-x))%=MOD;
        else (res *= L*R)%=MOD;
    }
    return res;
}
