	int ans = 1;
	for (int i = 0; i < n + m and ans!=0; i++) {
		int num = c[i];
		int nea = ser(a, num);
		int neb = ser(b, num);
		if (nea - ola <= 1 and neb - olb <= 1) {
			if (nea == ola) {
				if (neb != olb) {
					ans *= nea+1;
					ans *= com((nea + 1)*(neb + 1)-n*m+ olc - 2, olc-num - 1, kai, inv,pr);
					ans = ans % pr;
				}
			}
