int main()
{
  scanf( "%lld%lld", &N, &M );
  rep( i, N )
    scanf( "%lld", A+i );
  rep( i, M )
    scanf( "%lld", B+i );

  std::sort( A, A+N );
  std::sort( B, B+M );

  rep( i, N )
    printf( "%lld ", A[i] );
  puts("");
  rep( i, M )
    printf( "%lld ", B[i] );
  puts("");

  ll prod = 1;

  for( ll i = N*M; i > 0; --i )
  {
    ll p = std::lower_bound( A, A+N, i )-A;
    ll q = std::lower_bound( B, B+M, i )-B;

    if( A[p] == i && B[q] == i )
    {
      if( (p+1 < N && A[p+1] == A[p]) || (q+1 < M && B[q+1] == B[q]) )
        prod = 0;
    }
    else if( A[p] == i )
      prod = (prod*(M-q)) % mod;
    else if( B[q] == i )
      prod = (prod*(N-p)) % mod;
    else
      prod = (prod*((N-p)*(M-q)-(N*M-i))) % mod;
  }

  printf( "%lld\n", prod );

