int fpow(int a, int p) {
	if (!p) return 1;
	int tmp = fpow(a, p >> 1);
	tmp = mul(tmp, tmp);
	if (p & 1) tmp = mul(tmp, a);
	return tmp;
}
int inv(int a) {
	return fpow(a, mod - 2);
}
int C(int n, int k) {
	if (n < k || k < 0) return 0;
	return mul(fac[n], mul(ifac[k], ifac[n - k]));
}
struct Max {
	int maxValue, id;
	bool isRow;
	Max(int maxValue = -1, int id = -1, bool isRow = -1): maxValue(maxValue), id(id), isRow(isRow) {};
	bool operator<(const Max &rhs) const {
		if (maxValue == rhs.maxValue) {
			return isRow < rhs.isRow;
		}
		return maxValue < rhs.maxValue;
	}
} maxVal[N];
int n, m, a[N], b[N];
bool covered[N][N];
int usedNumbers = 0;
signed main() {
	#ifdef BLU
	in("blu.inp");
