ll fa(ll x) {
    if(x==0) return 1;
    if(mfa[x]!=-1) return mfa[x];
    return mfa[x]=x*fa(x-1)%MOD;
}

ll rfa(ll x) {
    if(x==0) return 1;
    if(mrfa[x]!=-1) return mrfa[x];
    rfa(x-1);
    return mrfa[x]=mPow(fa(x), MOD-2)%MOD;
}

ll C(ll n, ll k) {
    if(n<k) return 0;
    return fa(n)*rfa(k)%MOD*rfa(n-k)%MOD;
}

