        inv[i] = (i == 1) ? 1 : (mod - (mod / i) * inv[mod % i] % mod);
    }

    fact[0] = 1;
    fact_inv[0] = 1;

    for(int i = 1; i < n * m + 1; ++i) {
        fact[i] = fact[i - 1] * i % mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }

    auto comb = [&](int n, int k) {
        if (n < k) {
            return i64(0);
        }

        return fact[n] * fact_inv[n - k] % mod * fact_inv[k] % mod;
    };

    int s = 0;

    for (int i = 1; i <= n * m; i++) {
        if (cnt1[i] == 0 && cnt2[i] == 0) {
            continue;
        }

        if (cnt2[i] > 1) {
            ans = 0;
            break;
        } else if (cnt2[i] == 1) {
            ans = ans * fact[cnt1[i]] % mod * comb(i - 1 - s, cnt1[i]) % mod;
        } else {
            ans = ans * fact[cnt1[i]] % mod * comb(i - 1 - s, cnt1[i] - 1) % mod;
        }

        s += cnt1[i] + cnt2[i];
    }

    out(ans);
}

