ll factorial[1001*1001];

ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

ll np(ll a, ll b){
	ll res = factorial[a] * modinv(factorial[a-b], mod);
	res %= mod;
	return res;
}

