void solve(){
  ini(N , M);
  vi a(N) , b(M); in(a , b);

  auto f = [&](vi v) -> int{
    map<int,int> m;
    each(x , v) m[x]++;
    each(x , m){
      if(x.second != 1) return false;
    }
    return true;
  };
  if( !f(a) || !f(b) ) die(0);
  modint ans = 1;
  int ua = 0 , ub = 0 , cnt = 0;
  for(int i = N * M ; i > 0 ; i--){
    int fa = (find(all(a) , i) != a.end());
    int fb = (find(all(b) , i) != b.end());
    if(fa && fb){
      cnt += ua + ub;
      ua++;
      ub++;
    }
    else if(fa){
      if(ub == 0) die(0);
      ans *= ub;
      ua++;
      cnt += ub - 1;
    }
    else if(fb){
      if(ua == 0) die(0);
      ans *= ua;
      ub++;
      cnt += ua - 1;
    }
    else{
      if(cnt == 0) die(0);
      ans *= cnt;
      cnt--;
    }

    trc(i , ua , ub , cnt , ans);
  }

  out(ans);


}

