const long long MOD = 1000000007;



void solve(long long N, long long M, vector<long long> A, vector<long long> B){
    sort(A.begin(),A.end());
    sort(B.begin(),B.end());

    for(size_t i = 0; i < A.size(); i++)
    {
        cerr<<A[i]<<" ";
    }
    cerr<<endl;
    for(size_t i = 0; i < B.size(); i++)
    {
        cerr<<B[i]<<" ";
    }
    cerr<<endl;

    long long iA=N-1,iB=M-1;
    long long ans=1;
    for(long long i=N*M;i>0&&ans>0;i--){
        bool a=(iA>=0&&A[iA]==i),b=(iB>=0&&B[iB]==i);
        if(a&&b){
            iA--;iB--;
        }else if(a){
            iA--;
            ans=ans*(M-iB-1)%MOD;
        }else if(b){
            iB--;
            ans=ans*(N-iA-1)%MOD;
        }else{
            long long tmp=(N-iA-1)*(M-iB-1)-(N*M-i);
            if(tmp<=0){
                ans=0;
            }
            ans=ans*(tmp)%MOD;
        }
    }
    cout<<ans<<endl;
}

