typedef long long ll;

const int MOD = 1e9 + 7;

ll solve(const vector<ll>& A, const vector<ll>& B) {
  int N = A.size();
  int M = B.size();

  REP(i, N - 1) if(A[i + 1] == A[i]) return 0;
  REP(i, M - 1) if(B[i + 1] == B[i]) return 0;

  ll ret = 1;
  for(int i = N * M; i > 0; --i) {
    auto itrA = lower_bound(ALL(A), i);
    auto itrB = lower_bound(ALL(B), i);
    if((*itrA == i) && (*itrB == i)) {
      continue;
    }else if(*itrA == i) {
      ret = ret * (B.end() - itrB) % MOD;
    }else if(*itrB == i) {
      ret = ret * (A.end() - itrA) % MOD;
    }else{
      ll tmp = (A.end() - itrA) * (B.end() - itrB) - (N * M - i);
      if(tmp <= 0) return 0;
      ret = ret * tmp % MOD;
    }
  }
  return ret;
}

