LL powmod(LL x, LL y){
	LL a = 1;
	while(y){
		if(y & 1){ a = a * x % MOD; }
		x = x * x % MOD;
		y >>= 1;
	}
	return a;
}

const int LIM = 1000010;
LL fact[LIM];
LL ifact[LIM];

LL perm(int n, int k){
	if(n < 0 || k < 0 || n < k){ return 0; }
	return fact[n] * ifact[n - k] % MOD;
}

LL solve(){
	const int INF = 1010101010;

	int n, m;
	cin >> n >> m;
	vector<int> as(n + 1, INF), bs(m + 1, INF);
	for(int i = 0; i < n; ++i){ cin >> as[i]; }
	for(int i = 0; i < m; ++i){ cin >> bs[i]; }
	sort(ALL(as));
	sort(ALL(bs));

	for(int i = 1; i < n; ++i){
		if(as[i - 1] == as[i]){ return 0; }
	}
	for(int i = 1; i < m; ++i){
		if(bs[i - 1] == bs[i]){ return 0; }
	}

	int i = 0, j = 0;
	int rems[] = {m, n};
	LL ans = 1;
	int det = 0;
	while(i < n || j < m){
		if(as[i] < bs[j]){
			int v = as[i];
			int k = 0;
			LL t = perm(v - det, rems[k]) - perm(v - det - 1, rems[k]);
			ans = ans * t % MOD;
			det += rems[k];
			--rems[!k];
			++i;
		}
		else if(as[i] > bs[j]){
			int v = bs[j];
			int k = 1;
			LL t = perm(v - det, rems[k]) - perm(v - det - 1, rems[k]);
			ans = ans * t % MOD;
			det += rems[k];
			--rems[!k];
			++j;
		}
		else{
			int v = as[i];
			LL t = perm(v - det - 1, rems[0] + rems[1] - 2);
			ans = ans * t % MOD;
			det += rems[0] + rems[1] - 1;
			--rems[0];
			--rems[1];
			++i;
			++j;
		}
	}

	ans = (ans % MOD + MOD) % MOD;
	return ans;
}

