    for (ll k = m * n + 1; --k;) {

        while (u >= 0) {
            if (a[u] < k) break;
            u--;
        }
        while (v >= 0) {
            if (b[v] < k) break;
            v--;
        }
        u++; v++;

        if (a[u] < k || b[v] < k) {
            cout << 0 << endl;
            return 0;
        }
        ll pr = 0;
        if (a[u] == k && b[v] == k) {
            // cerr << "pattern 0, ";
            pr = 1;
        } else if (a[u] == k) {
            // cerr << "pattern 1, ";
            pr = (n - u) % p;
        } else if (b[v] == k) {
            // cerr << "pattern 2, ";
            pr = (m - v) % p;
        } else {
            // cerr << "pattern 3, ";
            pr = 1ll * ((n - u) % p * (m - v) % p + p - (m * n - k) % p) % p;
        }
        // cerr << "[" << k << "]: ";
        // cerr << "(" << u << ", " << v << ") ";
        // cerr << pr << " toori (total " << ans << "toori)" << endl;
        ans *= pr;
        ans %= p;
    }

    cout << ans << endl;

}

