ll perm(ll n,ll k){
  ll result=1LL;
  for(ll i=0LL;i<k;i++){
    result*=n-i;
    result%=MOD;
  }
  return result;
}

ll solve(){
  sort(a+1,a+N+1);
  sort(b+1,b+M+1);
  if(a[N]!=N*M || b[M]!=N*M) return 0;
  for(int n=2;n<=N;n++) if(a[n-1]==a[n]) return 0;
  for(int m=2;m<=M;m++) if(b[m-1]==b[m]) return 0;

  ll result=1;
  {
    int n=1,m=1;
    ll k,used=0;
    while(n<N||m<M){
      if(a[n]==b[m]){
