	//result*=1;
	//result%=MOD;
	used++;
	k--;
	if(a[n]-used<k)return 0;
	result*=perm(a[n]-used,k);
	result%=MOD;
	used+=k;
	n++;m++;
      }else if(a[n]<b[m]){
	k=M-m+1;
	//cout<<a[n]<<" "<<b[m]<<" "<<used<<" "<<k<<endl;
	result*=k;
	result%=MOD;
	used++;
	k--;
	if(a[n]-used<k)return 0;
	result*=perm(a[n]-used,k);
