	result*=k;
	result%=MOD;
	used++;
	k--;
	if(b[m]-used<k)return 0;
	result*=perm(b[m]-used,k);
	result%=MOD;
	used+=k;
	m++;
      }
      //cout<<result<<endl;
    }
  }

  return result;
}

