const int MOD = 1e+9 + 7;


int main()
{
    int N, M;
    cin >> N >> M;
    vector<int> A(N), B(M);
    for( int i = 0; i < N; ++i ) cin >> A[i];
    for( int i = 0; i < M; ++i ) cin >> B[i];

    vector<bool> in_A(N*M+1, false), in_B(N*M+1, false);
    REP(i, N) in_A[A[i]] = true;
    REP(i, M) in_B[B[i]] = true;

    // 大きいものから順に決めていく
    long long ans = 1;
    int rc = 0, rr = 0; // row, col でそれぞれ今まで現れた値の数
    for(int i = N*M; i > 0; --i){
        if(in_A[i] and in_B[i]) ++rc, ++rr;
