            ans *= rr % MOD;
            ++rc;
        }else if(in_B[i]){
            ans *= rc % MOD;
            ++rr;
        }else{
            // A にも B にも現れないとき、i より大きい場所でまだ空いているに場所にのみ置ける
            // -> i より大きい場所: rc*rr, まだ空いているに場所: - (N*M-i)
            ans *= (rc * rr - (N*M-i)) % MOD;
        }
        ans %= MOD;
    }
    cout << ans << endl; 

    return 0;
}

