const string KEY = "keyence";

const int N = 1e6 + 5;

const ll MOD = 1e9 + 7;

pair<bool, bool> nums[N];
ll mul[N];

ll solve() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; ++i) {
        int d;
        scanf("%d", &d);
        nums[d].first = true;
    }
    for (int i = 0; i < n; ++i) {
        int d;
        scanf("%d", &d);
        nums[d].second = true;
    }

    ll vacant = 0;
    ll hor = 0; // first
    ll ver = 0; // second

    for (int i = n * m; i >= 1; --i) {
        if (nums[i].first && nums[i].second) {
            vacant += hor + ver;
            ++hor;
            ++ver;
            mul[i] = 1;
        } else if (nums[i].first) {
            if (ver == 0) {
                return 0;
            }
            vacant += ver - 1;
            ++hor;
            mul[i] = ver;
        } else if (nums[i].second) {
            if (hor == 0) {
                return 0;
            }
            vacant += hor - 1;
            ++ver;
            mul[i] = hor;
        } else {
            if (vacant == 0) {
                return 0;
            }
            mul[i] = vacant;
            --vacant;
        }
    }
    return accumulate(mul + 1, mul + n * m + 1, 1ll,
                      [](ll a, ll b) { return (a * b) % MOD; });

    return 0;
}

