                    cout << 0 << endl;
        return 0;
        }
    }
    while(1){
        //cerr << x << " " << y << " " << ans << endl;
        if(x==n&&y==m)break;
        if(x==n){
            int p = b[y];
            ll tmp = com(p-c-1,n-x-1)*(ll)(n-x)%mod;
            ans *= tmp;
            ans %= mod;

            c += n-x;
            y++;
        }else if(y==m){
            int p = a[x];
                ll tmp = com(p-c-1,m-y-1)*(ll)(m-y)%mod;
                ans *= tmp;
                ans %= mod;
                x++;
                c += m-y;
        }else{
            if(a[x]==b[y]){
                int p = a[x];
                ll tmp = com(p-c-1,m-1-y+n-1-x);
                ans *= tmp;
                ans %= mod;
                c += m-1-y+n-1-x +1;
                x++;
                y++;
            }else if(a[x]>b[y]){
                int p = b[y];
                ll tmp = com(p-c-1,n-x-1)*(ll)(n-x)%mod;
                ans *= tmp;
