	}
	for (auto& v : col)
	{
		std::cin >> v;
		cole.emplace(v);
	}
	boost::sort(row);
	boost::sort(col);
	boost::range::set_union(rowe, cole, std::inserter(unie, std::end(unie)));
	if (rowe.size() != N || cole.size() != M)
	{
		out::write_line(0);
		return;
	}
	mod_t ret = 1;
	for (int i : boost::irange(1, N*M + 1) | adaptor::reversed)
	{
		int rindex = boost::range::lower_bound(row, i) - row.begin();
		int cindex = boost::range::lower_bound(col, i) - col.begin();
		if (cole.count(i))
		{
			if (rindex == N)
			{
				ret = 0;
				break;
			}
			if (row[rindex] != i)
			{
				ret *= N - rindex;
			}
			unie.erase(i);
		}
		else if (rowe.count(i))
		{
			if (cindex == M)
			{
				ret = 0;
				break;
			}
			ret *= M - cindex;
			unie.erase(i);
		}
		else
		{
			int free = (N - rindex)*(M - cindex) - (N*M - i);
			if (free <= 0)
			{
				ret = 0;
				break;
			}
			ret *= free;
		}
	}
	out::write_line(ret);
