            fact = new ll[N + 1];
            fact[0] = 1;
            for(ll i = 1; i <= N; i++){
                fact[i] = fact[i - 1] * i % MOD;
            }
        }

        ll f(ll N){ return fact[N]; }

        ll pow(ll a, ll b){
            return b ? (b & 1 ? a : 1) * pow(a * a % MOD, b / 2) % MOD : 1;
        }

        ll perm(ll n, ll k){
            return fact[n] * pow(fact[n - k], MOD - 2) % MOD;
        }

        ll comb(ll n, ll k){
            return fact[n] * pow(fact[n - k] * fact[k] % MOD, MOD - 2) % MOD;
        }
};

int main(){
    Combination C(1000 * 1000 + 10, MOD);
    ll N, M;
    cin >> N >> M;
    vector<ll> A(N), B(M);
    for(ll &e : A){
        cin >> e;
    }
    for(ll &e : B){
        cin >> e;
    }
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());
    for(ll i = 0; i < N - 1; i++){
        if(A[i] == A[i + 1]){
