        }
    }
    for(ll i = 0; i < M - 1; i++){
        if(B[i] == B[i + 1]){
            cout << 0 << endl;
            return 0;
        }
    }
    A.push_back(INF);
    B.push_back(INF);
    ll r = 0, c = 0;
    ll cnt = 0;
    ll ans = 1;
    while(r < N || c < M){
        if(A[r] < B[c]){
            ll select = M - c - 1;
            if(select > A[r] - cnt - 1){
                cout << 0 << endl;
                return 0;
            }
            ans *= C.perm(A[r] - cnt - 1, select);
            ans %= MOD;
            ans *= (M - c);
            ans %= MOD;
            cnt += select + 1;
            r++;
        }else if(A[r] > B[c]){
            ll select = N - r - 1;
            if(select > B[c] - cnt - 1){
                cout << 0 << endl;
                return 0;
            }
            ans *= C.perm(B[c] - cnt - 1, select);
            ans %= MOD;
            ans *= (N - r);
            ans %= MOD;
            cnt += select + 1;
            c++;
        }else if(A[r] == B[c]){
            ll select = M + N - r - c - 2;
            if(select > A[r] - cnt - 1){
