int R[1003], C[1003];
int n, m;

LL solve() {
	LL way = 1;
	const LL MOD = 1000000007;
	int x = -1, y = -1;
	for (int t = n * m; t >= 1; t--) {
		if (t == n * m) {
			if (R[0] != t || C[0] != t) 
				return 0;
			x = y = 0;
			continue;
		}
		if (x + 1 < n && t < R[x + 1]) 
			return 0;
		if (y + 1 < m && t < C[y + 1]) 
			return 0;
		if (x + 1 < n && t == R[x + 1] && y + 1 < m && t == C[y + 1]) {
			x++, y++;
		}
		else if (x + 1 < n && t == R[x + 1]) {
			way = (way * (y + 1)) % MOD;
			x++;
		}
		else if (y + 1 < m && t == C[y + 1]) {
			way = (way * (x + 1)) % MOD;
			y++;
		}
		else {
			int frees = (x + 1) * (y + 1) - (n * m - t);
			if (free <= 0) return 0;
			way = (way * frees) % MOD;
		}
	}
	return way;
}

void solve(int ks) {
	scanf("%d %d", &n, &m);
	for (int i = 0; i < n; i++) scanf("%d", &R[i]);
	for (int i = 0; i < m; i++) scanf("%d", &C[i]);
	sort(R, R + n);
	sort(C, C + m);
	reverse(R, R + n);
	reverse(C, C + m);
	LL ans = solve();
	printf("%lld\n", ans);
}

