    vector<ll> A(N + 1, 0), B(M + 1, 0);
    rep(i, N) cin >> A[i];
    rep(i, M) cin >> B[i];

    sort(all(A));
    reverse(all(A));
    sort(all(B));
    reverse(all(B));

    ll ans = 1;
    ll a = 0, b = 0;

    for (ll num = N * M; num > 0; num--) {
        ll cal;
        if ((A[a] > num) || (B[b] > num)) {
            ans = 0;
            break;
        }
        if (A[a] == num && B[b] == num) {
            cal = 1;
            a++;
            b++;
        }
        else if (A[a] == num) {
            cal = b;
            a++;
        }
        else if (B[b] == num) {
            cal = a;
            b++;
        }
        else {
            cal = a * b - (N * M - num);
            if (cal <= 0) {
                ans = 0;
                break;
            }
        }
        ans *= cal;
        ans %= MOD;
        // cout << num << " " << ans << endl;
    }

    cout << ans << endl;
    return 0;
}

#include <iostream>
