	for (int n = H * W; n > 0; n--) {
		ll tmp = 1;
		if (n == A[Apos] && n == B[Bpos]) {
			Apos++, Bpos++;
		}
		else if (n == A[Apos]) {
			tmp *= Bpos;
			Apos++;
		}
		else if (n == B[Bpos]) {
			tmp *= Apos;
			Bpos++;
		}
		else {
			tmp *= (Apos * Bpos - (H * W - n));
		}
		ans *= tmp;
		ans %= MOD;
	}
	cout << ans << endl;
	return 0;
}

