bool judge(const vector<int> &target)
{
  for(auto e : target)
  {
    if(e > 1)
    {
      return false;
    }
  }
  return true;
}

int main()
{
  int n, m;
  ll mod = 1000000007;
  cin >> n >> m;
  vector<int> a(n * m + 1, 0);
  vector<int> b(n * m + 1, 0);
  for(int i = 0; i < n; i++)
  {
    int temp;
    cin >> temp;
    a[temp]++;
  }
  for(int j = 0; j < m; j++)
  {
    int temp;
    cin >> temp;
    b[temp]++;
  }

  //不可能性の判定
  bool cana = judge(a);
  bool canb = judge(b);
  if(!cana && !canb)
  {
    cout << 0 << endl;
    return 0;
  }

  //累積和を計算
  vector<int> asum = a;
  vector<int> bsum = b;
  for(int i = 1; i <= n * m; i++)
  {
    asum[i] += asum[i - 1];
    bsum[i] += bsum[i - 1];
  }

  /*
   * 大きい方から埋めていくことを考える
   * もし埋めたい数字xがAとBの条件に現れているなら置く場所は一意に決まる(重複なく置くからそこに置かないと置く場所がない)
   * xがAにのみ現れる場合
   * このときxを置くことができるのはx < Biとなっている列に置くことができる
   * xがBにのみ現れる場合も同様でx < Aiとなっている行に置くことができる
   * xがAにもBにも現れない場合
   * xを置くことができるのはx < Aiとなっている行の数*x < Biとなっている列の数
   * このときすでにN * M - x個が置かれているのでそれを引く
   */
  ll result = 1;
  for(ll i = n * m; i > 0; i--)
  {
    if(a[i] == 1 && b[i] == 1)
    {
      result = result;
    }else if(a[i] == 1){
      result = (result * (bsum[n * m] - bsum[i])) % mod;
    }else if(b[i] == 1){
      result = (result * (asum[n * m] - asum[i])) % mod;
    }else{
      ll temp = (asum[n * m] - asum[i]) * (bsum[n * m] - bsum[i]);
      temp -= n * m - i;
      result = (result * temp) % mod;
    }
  }
  cout << result << endl;
  return 0;
}

