            }

            res *= modDiv(kai[a[i] - num], kai[(a[i] - num) - (m - dj)]);
            res %= MOD;
            num += m - dj;
            di++;

            i++;
            j++;
        }
        else if (a[i] < b[j])
        {
            if (a[i] - 1 - num < 0)
            {
                cout << 0 << endl;
                return 0;
            }

            res *= m - dj;
            res %= MOD;
            res *= modDiv(kai[a[i] - 1 - num], kai[(a[i] - 1 - num) - (m - dj - 1)]);
            res %= MOD;

            num += m - dj;
