bool used[1005][1005];
struct BIT{
private:
  ll n;
  vector<ll> bit_array;
public:
  BIT(ll s){
    bit_array.resize(s+1,0);
    n=s;
  }
  void add(ll i,ll x){
    while(i<=n){
      bit_array[i]+=x;
      i+=(i&(-i));
    }
  }
  ll sum(ll i){
    ll s=0;
    while(i>0){
      s+=bit_array[i];
      i-=(i&(-i));
    }
    return s;
  }
};
struct wBIT{
private:
  ll n;
  vector<BIT> bit_array;
public:
  wBIT(ll s,ll t){
    BIT b=BIT(t);
    bit_array.resize(s+1,b);
    n=s;
  }
  void add(ll i,ll j,ll x){
    while(i<=n){
      bit_array[i].add(j,x);
      i+=(i&(-i));
    }
  }
  ll sum(ll i,ll j){
    ll s=0;
    while(i>0){
      s+=bit_array[i].sum(j);
      i-=(i&(-i));
    }
    return s;
  }
};

