		if(binary_search(A, A + N, i) && binary_search(B, B + M, i)) cnt = 1;	// B + Nになってました
		else if(binary_search(A, A + N, i)) cnt = M + (B - lower_bound(B, B + M, i));	//M - ()だったのをM + ()にしました
		else if(binary_search(B, B + M, i)) cnt = N + (A - lower_bound(A, A + N, i));	//N - ()だったのをN + ()にしました
		else{
			cnt = (M + (B - lower_bound(B, B + M, i))) * (N + (A - lower_bound(A, A + N, i)));//↑と同じ
			flag = false;
		}
		if(!flag && cnt < (M * N - i)){
			printf("0\n");
			return 0;
		}
		if(flag) res *= (ll)cnt;
		else res *= (ll)(cnt - (M * N - i));
		res %= MOD;
	}
	printf("%lld\n", res);
	return 0;
}

