int main(){
  ll n,m;
  cin >> n >> m;
  vector<ll> a,b;
  ll temp;
  bool able = true;
  for(int i=0;i<n;i++){
    cin >> temp;
    a.push_back(temp);
    if(a[i] < 1 || n*m < a[i]) able = false;
  }
  for(int i=0;i<m;i++){
    cin >> temp;
    b.push_back(temp);
    if(b[i] < 1 || n*m < b[i]) able = false;
  }
  sort(a.begin(),a.end());
  sort(b.begin(),b.end());
  for(int i=1;i<n;i++){
    if(a[i] == a[i-1]) able = false;
  }
  for(int i=1;i<m;i++){
    if(b[i] == b[i-1]) able = false;
  }
  ll ans = 1;
  if(!able) ans = 0;
  ll x,y;
  for(ll v=n*m;v>=1;v--){
    auto itrx = lower_bound(a.begin(),a.end(),v);
    auto itry = lower_bound(b.begin(),b.end(),v);
    x = itrx - a.begin();
    y = itry - b.begin();
    if(x == n || y == m){
      ans = 0;
      continue;
    }
    if(*itrx == v && *itry == v) continue;
    if(*itrx == v){
      ans *= m-y;
      ans %= MOD;
      continue;
    }
    if(*itry == v){
      ans *= n-x;
      ans %= MOD;
      continue;
    }
    ll mul;
    mul = (m-y)*(n-x)-(n*m-v);
    mul %= MOD;
    ans *= mul;
    ans %= MOD;
  }
  cout << ans << endl;
  return 0;
}

