    }
    pos[b[i]][1] = i;
  }

  ll ok = 0, fillA = 0, fillB = 0;
  ll ans = 1;

  for(int i=n*m-1;i>=0;i--) {
    if(pos[i][0] != -1 && pos[i][1] != -1) {
      ok += fillA + fillB;
      fillA++; fillB++;
    } else if (pos[i][0] != -1) {
      ans = (ans * fillB) % mod;
      ok += fillB - 1;
      fillA++;
    } else if (pos[i][1] != -1){
      ans = (ans * fillA) % mod;
      ok += fillA - 1;
      fillB++;
    } else {
      ans = (ans * ok) % mod;
      ok--;
    }
  }

  cout << ans << endl;

  return 0;
}

