[[noreturn]] void impossible() {
    PRINTLN(0);
    exit(0);
}

void solve() {
    i64 H = RD();
    i64 W = RD();

    vector<i64> row_cum(H*W+1, 0);
    REP(_, H) {
        i64 a = RD();
        if(row_cum[a] > 0) impossible();
        ++row_cum[a];
    }
    vector<i64> col_cum(H*W+1, 0);
    REP(_, W) {
        i64 b = RD();
        if(col_cum[b] > 0) impossible();
        ++col_cum[b];
    }
    ALL(partial_sum, row_cum, begin(row_cum));
    ALL(partial_sum, col_cum, begin(col_cum));
    DBG(row_cum);
    DBG(col_cum);

    ModInt ans = 1;
    for(i64 v = H*W; v >= 1; --v) {
        bool row_exist = row_cum[v] > row_cum[v-1];
        bool col_exist = col_cum[v] > col_cum[v-1];

        i64 cur;
        if(row_exist && col_exist) {
            cur = 1;
        }
        else if(row_exist) {
            cur = col_cum[H*W] - col_cum[v];
        }
        else if(col_exist) {
            cur = row_cum[H*W] - row_cum[v];
        }
        else {
            cur = (row_cum[H*W]-row_cum[v]) * (col_cum[H*W]-col_cum[v]) - (H*W-v);
        }
        if(cur <= 0) impossible();

        ans *= cur;
    }

    PRINTLN(ans);
}

