  BIT(ll s){
    bit_array.resize(s+1,0);
    n=s;
  }
  void add(ll i,ll x){
    while(i<=n){
      bit_array[i]+=x;
      i+=(i&(-i));
    }
  }
  ll sum(ll i){
    ll s=0;
    while(i>0){
      s+=bit_array[i];
      i-=(i&(-i));
    }
    return s;
  }
};
struct wBIT{
private:
  ll n;
