// 剰余を考慮した整数のクラス
template <uint_fast64_t Mod> class Mint {
    using u64 = uint64_t;
    public:
    u64 a;
    constexpr Mint(const u64 x = 0) noexcept : a(x % Mod){}
    constexpr void set(const u64 x = 0) noexcept { a = x % Mod; }
    constexpr u64 &value() noexcept { return a; }
    constexpr const u64 &value() const noexcept { return a; }
    constexpr Mint operator+(const Mint rhs) const noexcept {
        return Mint(*this) += rhs;
    }
    constexpr Mint operator-(const Mint rhs) const noexcept {
        return Mint(*this) -= rhs;
    }
    constexpr Mint operator*(const Mint rhs) const noexcept {
        return Mint(*this) *= rhs;
    }
    constexpr Mint operator/(const Mint rhs) const noexcept {
        return Mint(*this) /= rhs;
    }
    constexpr Mint &operator+=(const Mint rhs) noexcept {
        a += rhs.a;
        if (a >= Mod) a -= Mod;
        return *this;
    }
    constexpr Mint &operator++() noexcept {
        a += 1;
        if (a >= Mod) a -= Mod;
        return *this;
    }
    constexpr Mint operator++(int) noexcept {
        Mint m = *this;
        a += 1;
        if (a >= Mod) a -= Mod;
        return m;
    }
    constexpr Mint &operator-=(const Mint rhs) noexcept {
        if (a < rhs.a) a += Mod;
        a -= rhs.a;
        return *this;
    }
    constexpr Mint &operator--() noexcept {
        if (a < 0) a += Mod;
        a -= 1;
        return *this;
    }
    constexpr Mint operator--(int) noexcept {
        Mint m = *this;
        if (a < 0) a += Mod;
        a -= 1;
        return m;
    }
    constexpr Mint &operator*=(const Mint rhs) noexcept {
        a = a * rhs.a % Mod;
        return *this;
    }
    constexpr Mint &operator/=(const Mint rhs) noexcept {
        u64 exp = Mod - 2;
        while(exp) {
            if(exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }
    constexpr operator long long() const {return a;}
    friend ostream& operator<< (ostream& os, const Mint<Mod> &m) {
        os << m.a;
        return os;
    };
    friend istream& operator>> (istream& is, Mint<Mod> &m) {
        long long l;
        is >> l;
        m.set(l);
        return is;
    };
};
typedef Mint<MOD> mint;
typedef vector<Mint<MOD>> vmint;

void solve() {
    ll N, M;
    cin >> N >> M;
    vll A(N), B(M);
    for(auto &a:A) cin >>a;
    for(auto &a:B) cin >>a;
    vll C = A;
    UNIQ(C);
    if(A.size() != C.size()) {
        out(0);
        return;
    }
    C = B;
    UNIQ(C);
    if(B.size() != C.size()) {
        out(0);
        return;
    }
    map<ll, ll> mpa;
    map<ll, ll> mpb;
    vll va(N*M+1), vaa(N*M+1);
    vll vb(N*M+1), vbb(N*M+1);
    REP(i, N) mpa[A[i]]++;
    REP(i, M) mpb[B[i]]++;
    C = A;
    DESC(C);
    REP(i, N) {
        va[C[i]] += 1;
    }
    C = B;
    DESC(C);
    REP(i, M) {
        vb[C[i]] += 1;
    }
    CUMSUMR(va, vaa);
    CUMSUMR(vb, vbb);
    mint ans = 1;
    for(ll i = N*M; i >= 1; i--) {
        if(mpa[i] == 1 && mpb[i] == 1) {
            ans *= 1;
        }else if(mpa[i] == 1 && mpb[i] == 0) {
            ans *= vbb[i];
        }else if(mpa[i] == 0 && mpb[i] == 1) {
            ans *= vaa[i];
        }else if(mpa[i] == 0 && mpb[i] == 0) {
            ans = ans * (mint(vaa[i]) * mint(vbb[i]) - mint(N*M-i));
        }else{
            debug("Failed");
            out(0);
            return;
        }
        //debug(ans);
    }
    out(ans);
}

int main() {
    fast_io;
    solve();
    return 0;
}

