const ll LLINF = (1LL<<60);
const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_NM 1000100

class NumberOfCase {
    public:
        // 初期化 O(n log m) m は素数
        // n : 求めたい組み合わせの最大値, m : 剰余(素数)
        NumberOfCase(ll n, ll m) : m_Size(n), m_Mod(m) {
            m_Fact = new ll[m_Size + 1];
            m_FInv = new ll[m_Size + 1];
            m_Inv = new ll[m_Size + 1];
            // 0! ～ m_Size! までの階乗を保管する配列の作成 (mod m_Mod をとってある)
            m_Fact[0] = 1;
            for(int i = 1; i <= m_Size; ++i) { m_Fact[i] = (m_Fact[i-1] * i) % m_Mod; }
            // m_Size! の逆元 1/m_Size! を二分累乗法で求める
            // フェルマーの小定理より a^-1 = a^(p-2) mod p -> (m_Size!)^-1 = (m_Size!)^(p-2) mod p
            m_FInv[m_Size] = ModPow(m_Fact[m_Size], m_Mod-2, m_Mod);
            // 以下 1 / (N-1)! = N / N! であることを利用
            for(int i = m_Size - 1; i >= 0; --i) { m_FInv[i] = (m_FInv[i + 1] * (i + 1)) % m_Mod; }
            // 逆元の作成（割り算のとき利用）
            m_Inv[1] = 1;
            for(int i = 2; i <= m_Size; ++i) { m_Inv[i] = m_Inv[m_Mod % i] * (m_Mod - m_Mod / i) % m_Mod; }
        }
        ~NumberOfCase() {
            delete[] m_Fact;
            delete[] m_FInv;
            delete[] m_Inv;
        }
        // 階乗 n! の取得 O(1)
        ll Factorial(ll n) { return m_Fact[n]; }
        // n! の逆元の取得 O(1)
        ll FInverse(ll n) { return m_FInv[n]; }
        // 逆元の取得 O(1)
        ll Inverse(ll n) { return m_Inv[n]; }
        // 剰余を考慮した割り算 n / m の結果を返す
        ll Div(ll n, ll m) { return (n * m_Inv[m]) % m_Mod; }
        // 順列 nPr の取得 O(1)
        ll Permutation(ll n, ll r) { return (m_Fact[n] * m_FInv[n - r]) % m_Mod; }
        // 組み合わせ nCr の取得 O(1)
        ll Combination(ll n, ll r) {
            ll ret = (m_Fact[n] * m_FInv[n - r]) % m_Mod;
            ret = (ret * m_FInv[r]) % m_Mod;
            return ret;
        }
        // 重複組み合わせ nHr の取得 O(1)
        ll Homogen(ll n, ll r) { return Combination(r+n-1, r); }
    private:
        // x の n 乗 を m で余りをとったもの O(log n)
        ll ModPow(ll x, ll n, ll mod) {
            ll res = 1;
            while ( n > 0) {
                if (n & 1) { res = res * x % mod; } // 最下位ビットが立っているときに x^(2^i) を掛ける
                x = x * x % mod;                    // x を順次 2 乗していく
                n >>= 1;
            }
            return res;
        }
    private:
        const ll    m_Size;     // 導出する範囲 (10^5 くらいまでにして欲しい)
        const ll    m_Mod;      // 剰余
        ll*         m_Fact;     // 階乗
        ll*         m_FInv;     // 階乗の逆元
        ll*         m_Inv;      // 逆元
};

ll N, M;
vector<ll> A, B;

vector< vector<ll> > grid;

ll AtoInd[MAX_NM]; // Ai から i を求める
ll BtoInd[MAX_NM];

vector< tuple<ll, ll, ll> > AB_sort;  // <0>: A[i]かB[i]  <1>: i  <2>:0 なら A, 1 なら B

vector<ll> cnt;     // grid 上の各数字が書かれたマスの数

ll solve() {
    NumberOfCase noc(N * M + 1, MOD);

    // AtoInd/BtoInd の作成
    // A_sort/B_sort の作成
    MINUS(AtoInd); MINUS(BtoInd);
    REP(i, N) {
        // 同じ値が 2 回以上出てくるなら 0
        if(AtoInd[A[i]] != -1) { return 0; }
        AtoInd[A[i]] = i;
        AB_sort.push_back(make_tuple(A[i], i, 0));
    }
    REP(i, M) {
        if(BtoInd[B[i]] != -1) { return 0; }
        BtoInd[B[i]] = i;
        AB_sort.push_back(make_tuple(B[i], i, 1));
    }
    SORT(AB_sort);

    // grid の作成
    grid.assign(N, vector<ll>(M, -1));
    for(auto& ab : AB_sort) {
        ll val = get<0>(ab);
        ll ind = get<1>(ab);
        ll type = get<2>(ab);

        //if(AtoInd[val] != -1 && BtoInd[val] != -1) {
        //    // 位置が確定できる値なら、確定し grid のほかの部分は val - 1 にする
        //    grid[AtoInd[val]][BtoInd[val]] = val;
        //    val--;
        //}
        if(type == 0) {
            REP(j, M) {
                if(grid[ind][j] == -1) { grid[ind][j] = val; }
            }
        }
        else {
            REP(i, N) {
                if(grid[i][ind] == -1) { grid[i][ind] = val; }
            }
        }
    }

    // DEBUG
    //REP(i, N) {
    //    REP(j, M) {
    //        DBG("%lld ", grid[i][j]);
    //    }
    //    DBG("\n");
    //}

    // cnt の作成
    cnt.assign(N * M + 1, 0);
    REP(i, N) {
        REP(j, M) {
            cnt[grid[i][j]]++;
        }
    }

    // cnt を元にパターン数を求める
    ll ret = 1;
    ll used = 0;    // 使用済みの数字の数
    for(ll i = 1; i <= N * M; ++i) {
        //DBG("i: %lld used: %lld\n", i, used);
        if(cnt[i] == 0) { continue; }
        // 確定しているものを選ぶパターンは 1 つだけ
        //if(i] != -1 && BtoInd[i] != -1) {
        //    used++;
        //}
        ll avail = i - used;
        if(cnt[i] > avail) { return 0; }
        //DBG("  avail: %lld %lldP%lld: %lld ret: %lld\n",
        //        avail, avail, noc.Permutation(avail, cnt[i]), cnt[i], ret);
        // 最大値の分の 1 つは必ず選択しなければならない
        if(AtoInd[i] != -1 && BtoInd[i] != -1) {
            // かつ最大値の位置が確定しているなら、それ以外のもののパターンを加える
            ret *= noc.Permutation(avail - 1, cnt[i] - 1);
            ret %= MOD;
        }
        else {
            // 最大値もある程度動いていいなら、動く
            ret *= cnt[i];
            ret %= MOD;
            ret *= noc.Permutation(avail - 1, cnt[i] - 1);
            ret %= MOD;
        }
        //DBG("  -> %lld\n", ret);
        used += cnt[i];
    }

    return ret;
}

signed main()
{
    cin >> N >> M;
    A.resize(N);
    B.resize(M);
    REP(i, N) { cin >> A[i]; }
    REP(i, M) { cin >> B[i]; }
    ll ans = solve();
    printf("%lld\n", ans);
    return 0;
}

