ll N, M;
vector<ll> A;
vector<ll> B;

void solve() {
	scanf("%lld%lld", &N, &M);
	A.assign(N, 0);
	rep(i, N) { scanf("%lld", &A[i]); }
	B.assign(M, 0);
	rep(i, M) { scanf("%lld", &B[i]); }


	map<ll,ll> am,bm;
	rep(i,N)am[A[i]]++;
	rep(i,M)bm[B[i]]++;
	for(pair<ll,ll> t:am){
		if(t.second>1){
			p(0);return;
		}
	}
	for(pair<ll,ll> t:bm){
		if(t.second>1){
			p(0);return;
		}
	}

	Modint ans=1;
	ll tatecount=0,yokocount=0;
	ll count=0;
	rrepeq(i,N*M){
		bool isa=am[i]==1;
		bool isb=bm[i]==1;
		if(isa && isb){
			//かける場所は1通り
			tatecount++;
			yokocount++;
			if(tatecount>N || yokocount>M){
				p(0);return;
			}
		}else if(isa && !isb){
			//かける場所はM方向に自由度がある
			ll t=yokocount;
			ans*=t;
			tatecount++;
		}else if(!isa && isb){
			//かける場所はN方向に自由度がある
			ll t=tatecount;
			ans*=t;
			yokocount++;
		}else{
			ll t=tatecount*yokocount-count;
			if(t<=0){
				p(0);return;
			}
			ans*=t;

		}
		count++;
	}

	printf("%lld\n", ans);

