    {
        if (a[ai] > i || b[bi] > i)
        {
            ans = 0;
            break;
        }
        else if (a[ai] == i && b[bi] == i)
        {
            updateAns(1);
            ai++;
            bi++;
        }
        else if (a[ai] == i)
        {
            updateAns(bi);
            ai++;
        }
        else if (b[bi] == i)
        {
            updateAns(ai);
            bi++;
        }
        else
        {
            updateAns(ai * bi - (n * m - i));
        }
    }

