{
	memset(px,-1,sizeof(px));
	memset(py,-1,sizeof(py));
	n=read(),m=read();
	for(int i=1;i<=n;i++)cx[a[i]=read()]++,px[a[i]]=i;
	for(int i=1;i<=m;i++)cy[b[i]=read()]++,py[b[i]]=i;
