constexpr intmax_t MOD = 1e9+7;

template <class Tp>
Tp gcd(Tp a, Tp b, Tp& x, Tp& y) {
  x = Tp(0);
  y = Tp(1);
  for (Tp u=y, v=x; a;) {
    Tp q = b/a;
    std::swap(x-=q*u, u);
    std::swap(y-=q*v, v);
    std::swap(b-=q*a, a);
  }
  return b;
}

template <class Tp>
Tp modinv(Tp a) {
  Tp x, y;
  gcd(a, MOD, x, y);
  x %= MOD;
  if (x < 0) x += MOD;
  return x;
}

template <class Tp>
Tp moddiv(Tp a, Tp b) {
  return a * modinv(b) % MOD;
}

int main() {
  size_t N, M;
  scanf("%zu %zu", &N, &M);

  std::vector<intmax_t> A(N), B(M);
  for (auto& a_i: A) scanf("%jd", &a_i);
  for (auto& b_i: B) scanf("%jd", &b_i);

  std::sort(A.begin(), A.end());
  std::sort(B.begin(), B.end());

  if (A.back() != N*M || B.back() != N*M)
    return puts("0"), 0;

  for (size_t i = 1; i < N; ++i)
    if (A[i] == A[i-1]) return puts("0"), 0;
  for (size_t j = 1; j < N; ++j)
    if (B[j] == B[j-1]) return puts("0"), 0;

  std::set<intmax_t> aa, bb;
  for (auto a_i: A) aa.insert(a_i);
  for (auto b_i: B) bb.insert(b_i);

  std::vector<intmax_t> G(N*M);
  auto encode = [=](size_t h, size_t w)->size_t {
    return h*M + w;
  };

  for (size_t i = 0; i < N; ++i)
    for (size_t j = 0; j < M; ++j)
      G[encode(i, j)] = std::min(A[i], B[j]);

  std::sort(G.begin(), G.end());
  std::vector<intmax_t> I(N*M);
  std::iota(I.begin(), I.end(), 1);
  for (size_t i = 0; i < N*M; ++i)
    if (G[i] < I[i])
      return puts("0"), 0;

  std::vector<intmax_t> fact(N*M+1);
  fact[0] = 1;
  for (size_t i = 1; i <= N*M; ++i)
    fact[i] = fact[i-1] * i % MOD;

  std::map<intmax_t, intmax_t> mp;
  for (auto g_i: G) ++mp[g_i];

  auto npr = [&](intmax_t n, intmax_t r)->intmax_t {
    return moddiv(fact[n], fact[n-r]);
  };

  intmax_t res = 1;
  intmax_t sub = 0;
  for (auto p: mp) {
    fprintf(stderr, "%jd: %jd\n", p.first, p.second);
    intmax_t fst = p.first;
    intmax_t snd = p.second;
    if (aa.count(fst) && bb.count(fst)) {
    } else {
      fprintf(stderr, "* %jd\n", snd);
      (res *= snd) %= MOD;
    }
    fprintf(stderr, "P(%jd, %jd)\n", fst-(sub+1), snd-1);
    (res *= npr(fst-(sub+1), snd-1)) %= MOD;
    sub += snd;
  }

  printf("%jd\n", res);
}

