long long solve()
{
	int n, m;
	scanf("%d%d", &n, &m);
	std::vector<int> a(n), b(m);
	for (auto& e: a)
		scanf("%d", &e);
	for (auto& e: b)
		scanf("%d", &e);
	std::sort(a.rbegin(), a.rend());
	std::sort(b.rbegin(), b.rend());
	for (int i{1}; i < n; i++)
		if (a[i] == a[i - 1])
			return 0;
	for (int i{1}; i < m; i++)
		if (b[i] == b[i - 1])
			return 0;
	a.push_back(-1);
	b.push_back(-1);

	long long count{1};
	int a_i{}, b_i{};
	for (int i{n * m}; i > 0; i--)
	{
		if (i == a[a_i] && i == b[b_i])
		{
			a_i++;
			b_i++;
		}
		else if (i == a[a_i])
		{
			count *= b_i;
			count %= mod;
			a_i++;
		}
		else if (i == b[b_i])
		{
			count *= a_i;
			count %= mod;
			b_i++;
		}
		else
		{
			count *= a_i * b_i + i - n * m;
			count %= mod;
		}
	}
	return count;
}

