int main() {
    scanf("%d%d", &n, &m);
    bool flag = true;
    for (int i = 1; i <= n; ++i) {
        scanf("%d", a + i);
        if (x[a[i]]) flag = false;
        x[a[i]] = i;
    }
    for (int i = 1; i <= m; ++i) {
        scanf("%d", b + i);
        if (y[b[i]]) flag = false;
        y[b[i]] = i;
    }
    int ans = 1;
    int prex = 0, prey = 0;
    int cntx = 0, cnty = 0;
    for (int i = n * m; i; --i) {
        if (x[i] && y[i]) {
            mat[x[i]][y[i]] = i;
            ++cntx;
            ++cnty;
            prex = x[i];
            prey = y[i];
        } else if (x[i]) {
            if (!cnty) flag = false;
            mat[x[i]][prey] = i;
            ++cntx;
            prex = x[i];
            ans = 1ll * ans * cnty % mod;
        } else if (y[i]) {
            if (!cntx) flag = false;
            mat[prex][y[i]] = i;
            ++cnty;
            prey = y[i];
            ans = 1ll * ans * cntx % mod;
        }
    }

    if (!flag) {
        puts("0");
        return 0;
    }

    for (int i = 1; i <= n; ++i) {
