class DDoubleLandscape {
public:
	void solve(std::istream& in, std::ostream& out) {
        int n, m;
        in >> n >> m;
        vector<int> a(n), b(m);
        vector<int> exist_a(n*m+1, 0);
        rep(i, n){
            in >> a[i];
            if(exist_a[a[i]]){
                out << 0 << endl;
                return;
            }
            exist_a[a[i]] = 1;
        }

        vector<int> exist_b(n*m+1, 0);
        rep(i, m){
            in >> b[i];
            if(exist_b[b[i]]){
                out << 0 << endl;
                return;
            }
            exist_b[b[i]] = 1;
        }

        ll res = 1;
        rep(i, n){
            int cnt = 0;
            bool multi = false;
            rep(j, m){
                if(a[i] == b[j]) multi = true;
                if(a[i] < b[j]) cnt++;
            }
            if(multi) continue;
            res *= cnt;
            res %= mod;
        }

        rep(j, m){
            int cnt = 0;
            bool multi = false;
            rep(i, n){
                if(a[i] == b[j]) multi = true;
                if(b[j] < a[i]) cnt++;
            }
            if(multi) continue;
            res *= cnt;
            res %= mod;
        }

        vector<int> sum(n*m+1, 0);
        rep(i, n){
            rep(j, m){
                sum[min(a[i], b[j])-1]++;
            }
        }
        repr(i, n*m-1, 0){
            sum[i] += sum[i+1];
        }

        repr(i, n*m, 1){
            if(exist_a[i] || exist_b[i]) continue;
            res *= (sum[i] - (n*m-i));
            res %= mod;
        }

        out << res << endl;
	}
};


