int main() {
  int n, m;
  cin >> n >> m;
  int a[n], b[m];
  int find[n * m + 1][2];
  REP1(i, n * m) REP(j, 2) find[i][j] = 0;
  REP(i, n) {
    cin >> a[i];
    find[a[i]][0]++;
  }
  REP(i, m) {
    cin >> b[i];
    find[b[i]][1]++;
  }
  REP1(i, n * m) REP(j, 2) {
    if (1 < find[i][j]) {
      cout << 0 << endl;
      return 0;
    }
  }
  int sum[n * m + 1][2];
  for (int i = 0; i <= n * m; ++i) REP(j, 2) sum[i][j] = 0;
  REP(i, n) sum[a[i]][0]--;
  REP(i, m) sum[b[i]][1]--;
  sum[0][0] = n, sum[0][1] = m;
  REP(i, n * m) REP(j, 2) sum[i + 1][j] += sum[i][j];
  ll ans = 1;
  for (int x = n * m; x >= 1; --x) {
    if (find[x][0] && find[x][1]) {
      ans *= 1;
    } else if (find[x][0]) {
      ans *= sum[x][1];
    } else if (find[x][1]) {
      ans *= sum[x][0];
    } else {
      ans *= (sum[x][1] * sum[x][0] % MOD - (n * m % MOD - x));
    }
    ans %= MOD;
  }
