            cout << 0 << endl;
            return 0;
        }
    }

    ll ans = 1;
    for (int i = N * M; i >= 1; i--)
    {
        int ba = belongs_a(i);
        int bb = belongs_b(i);
        if (ba >= 0 && bb >= 0)
        {
            continue;
        }
        else if (ba >= 0)
        {
            ans *= greater_num_b(i);
            ans %= MOD;
        }
        else if (bb >= 0)
        {
            ans *= greater_num_a(i);
            ans %= MOD;
        }
        else
        {
            ll p = greater_num_a(i) * greater_num_b(i) % MOD;
            p = (p - (M * N - i) + MOD) % MOD;
            ans *= p;
            ans %= MOD;
        }
    }
    cout << ans << endl;
}

