const int N = 1005;
const int md = (int)1e9 + 7;
int n, m;
int a[N], b[N];
int mp[N][N], leftpoint = 1;
int used[N][N];
pair<int, int> point[N * N];
int choose, fix;
struct node
{
	int x, y;
	bool operator <(const node &rhs)const
	{
		return min(a[x], b[y]) > min(a[rhs.x], b[rhs.y]);
	}
	int val()
	{
		return min(a[x], b[y]);
	}
	int check()
	{
		return (used[x][y] == 0);
	}
} expand[N * N];
int mark[N * N];
long long ans = 1;
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0), cout.tie(0);
	cin >> n >> m;
	for (int i = 1; i <= n; ++i)
	{
		cin >> a[i];
		if (mark[a[i]])
			return cout << 0, 0; 
		 point[a[i]].first = i;
		mark[a[i]] = 1;
	} 
	memset(mark, 0, sizeof(mark));
	for (int i = 1; i <= m; ++i)
	{
		cin >> b[i], point[b[i]].second = i;
		if (mark[b[i]])
			return cout << 0, 0;
		mark[b[i]] = 1;
	}
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
			expand[(i - 1) * m + j] = (node){i, j};
	sort(expand + 1, expand + n * m + 1);
	for (int i = n * m; i > 0; --i)
	{
//		cout << ans << endl;
		if (point[i].first > 0 && point[i].second > 0)
		{
			used[point[i].first][point[i].second] = 1;
//			++fix;
			--choose;
			continue;
		}
		if (point[i].first > 0)
		{
//			++fix;
			int tot = 0;
			int x = point[i].first;
			for (int j = 1; j <= m; ++j)
			if (used[x][j] == 0 && i <= b[j])
				++tot;
			ans = ans * tot % md;
			--choose;
			continue;
		}
		if (point[i].second > 0)
		{
//			++fix;
			int tot = 0;
			int y = point[i].second;
			for (int j = 1; j <= n; ++j)
			if (used[j][y] == 0 && i <= a[j])
				++tot;
			ans = ans * tot % md;
			--choose;
			continue;
		}
		while (leftpoint <= n * m && i <= expand[leftpoint].val())
		{
			leftpoint++;
//			--choose;
			choose++;
		}
		ans = ans * (choose - fix) % md;
//		cout << choose<< endl;
		--choose;
	}
//	cout << leftpoint << endl;
	cout << ans;
	return 0;
}

