    vector<bool> t(n * m + 1, false), u(n * m + 1, false);
    rep(i, n){
        rep(j, m){
            int x = min(a[i], b[j]);
            s[x]++;
            u[x] = true;
            if(a[i] == b[j]){
                t[x] = true;
            }
        }
    }

    if(s[n*m] == 0){
        cout << 0 << endl;
        return 0;
    }

    sort(ALL(a), greater<int>());
    sort(ALL(b), greater<int>());
    int tar = n * m;
    rep(i, n){
        rep(j, m){
            if(a[i] == b[j]){
                tar = min(tar, a[i] - 1);
                while(tar > 1 && u[tar]){
                    tar--;
                }
                s[tar] += s[a[i]] - 1;
                s[a[i]] = 1;
            }
        }
    }

    int sum = 0;
    int ans = 1;
    for(int i = 1; i <= n * m; i++){
        if(sum + s[i] > i){
            cout << 0 << endl;
