            int tmp = 1;
            int x = i - sum;
            rep(j, s[i]){
                tmp *= x;
                tmp %= MOD;
                x--;
            }
            if(u[i]){
                int x = i - sum - 1;
                int tmp2 = 1;
                rep(j, s[i]){
                    tmp2 *= x;
                    tmp2 %= MOD;
                    x--;
                }
                tmp = (tmp + MOD - tmp2) % MOD;
            }
            ans *= tmp;
            ans %= MOD;
        }
        sum += s[i];
    }

    cout << ans << endl;

    return 0;
}

