    scanf("%d", &x);
    if (col[x] || set.count(x)) {
      return puts("0"), 0;
    }
    col[x] = i;
    set.emplace(x);
  }
  int r = 0, c = 0;
  int result = 1;
  for (int v = n * m; v >= 1; -- v) {
    if (row[v] && col[v]) {
      ++ r, ++ c;
    } else if (row[v]) {
      result = result * 1LL * c % MOD;
      ++ r;
    } else if (col[v]) {
      result = result * 1LL * r % MOD;
      ++ c;
    } else {
      int w = std::max(r * c - (n * m - v), 0);
      result = result * 1LL * w % MOD;
    }
    // printf("v = %d, result = %d, r = %d, c = %d\n", v, result, r, c);
  }
  printf("%d\n", result);
}

#include <algorithm>
