#define M 1000000007
using namespace std;

int modinv(int a, int m) {
    int x = m, y = a, p = 1, q = 0, r = 0, s = 1;
    while (y != 0) {
        int u = x / y;
        int x0 = y; y = x - y * u; x = x0;
        int r0 = p - r * u, s0 = q - s * u;
        p = r; r = r0; q = s; s = s0;
    }
    return q < 0 ? q + m : q;
}
// modular factorial----------------
long long fact[1001001], facti[1001001];

// initialization
void init_fact() {
    fact[0] = 1; facti[0] = 1;
    for (int i = 1; i <= 1001000; i++) {
        fact[i] = (fact[i-1] * i) % M;
        facti[i] = modinv(fact[i], M);
    }
}

long long perm(int n, int k) {
    if (n < 0 || k < 0 || k > n) return 0;
    return fact[n] * facti[n-k] % M;
}

int main() {
    int n, m; cin >> n >> m;
    int A[n], B[m];
    for (int i = 0; i < n; i++) cin >> A[i];
    for (int i = 0; i < m; i++) cin >> B[i];
    sort(A, A + n); sort(B, B + m);
    for (int i = 1; i < n; i++) if (A[i-1] == A[i]) { cout << 0 << endl; return 0; }
    for (int i = 1; i < m; i++) if (B[i-1] == B[i]) { cout << 0 << endl; return 0; }
    int i = 0, j = 0;
    long long ans = 1;
    init_fact();
    while (i < n && j < m) {
        // cout << i << ' ' << j << ' ' << lb << ' ' << res << ' ' << ans << endl;
        int res = min(A[i], B[j]) - i * m - j * n + i * j;
        if (A[i] < B[j]) {
            int cnt =  m - j;
            ans = ans * (perm(res, cnt) - perm(res-1, cnt)) % M;
            i++;
        } else if (A[i] > B[j]) {
            int cnt = n - i;
            ans = ans * (perm(res, cnt) - perm(res-1, cnt)) % M;
            j++;
        } else {
            int cnt = n - i + m - j - 2;
            ans = ans * perm(res-1, cnt) % M;
            i++; j++;
        }
    }
    cout << (ans % M + M) % M << endl;
}

