ll solve() {
    sort(a, a+n);
    sort(b, b+m);

    int t = n * m;
    int i = n-1, j = m-1;
    if (!(a[i] == t && b[j] == t)) return 0;

    ll res = 1;
    while (i >= 0 || j >= 0) {
        //cerr << a[i] << " " << b[j] << " " << t << endl;
        if ((i > 0 && a[i] == a[i-1]) || (j > 0 && b[j] == b[j-1])) {
            return 0;
        }

        if (i >= 0 && a[i] == t && j >= 0 && b[j] == t) {
            i--;
            j--;
        } else if (i >= 0 && a[i] == t) {
            res *= (m - j - 1);
            res %= mod;
            i--;
        } else if (j >= 0 && b[j] == t) {
            res *= (n - i - 1);
            res %= mod;
            j--;
        } else {
            int sz = (m-j-1) * (n-i-1);
            int f = n * m - t;
            if (f >= sz) return 0;
            res *= (sz - f);
            res %= mod;
        }

        t--;
    }

    for (int i = 1; i <= t; i++) {
        res *= i;
        res %= mod;
    }
    return res;
}

