typedef long long ll;

const int mod = 1000000007;
const int Maxn = 1005;

int n, m;
int R[Maxn], C[Maxn];
int res = 1;

bool Less(const int &a, const int &b)
{
    return a > b;
}

int main()
{
    scanf("%d %d", &n, &m);
    for (int i = 0; i < n; i++)
        scanf("%d", &R[i]);
    for (int j = 0; j < m; j++)
        scanf("%d", &C[j]);
    sort(R, R + n, Less);
    sort(C, C + m, Less);
    int a = 0, b = 0;
    for (int i = 0; i + 1 < n; i++)
        if (R[i] == R[i + 1]) { printf("0\n"); return 0; }
    for (int i = 0; i + 1 < m; i++)
        if (C[i] == C[i + 1]) { printf("0\n"); return 0; }
    for (int i = n * m; i > 0; i--) {
        int was = n * m - i;
        bool myrow = a < n && R[a] == i;
        bool mycol = b < m && C[b] == i;
        if (myrow && mycol) { a++; b++; }
        else if (myrow) { res = ll(res) * b % mod; a++; }
        else if (mycol) { res = ll(res) * a % mod; b++; }
        else res = ll(res) * (a * b - was) % mod;
    }
    printf("%d\n", res);
    return 0;
}

