			++q;
			rest += p + 1;
		}
		if (P && Q);
		else if (P) (ans *= q + 1) %= MOD;
		else if (Q) (ans *= p + 1) %= MOD;
		else (ans *= rest) %= MOD;
		--rest;
		if (rest < 0) ans = 0;
        std::err < rest <<std::endl;
	}
	OUT(ans)BR;
	return 0;
}

