    cins(A, A + N);
    sort(A, A + N);
    cins(B, B + M);
    sort(B, B + M);
    if(A[N - 1] < N * M || B[M - 1] < N * M){
        cout << 0 << endl;
        return 0;
    }
    long maximum[N][M];
    for(int i = 0; i < N; i++){
        for(int j = 0; j < M; j++){
            maximum[i][j] = min(A[i], B[j]);
        }
    }
    long ans = 1;
    vector<bool> is_in_remaining(N * M, true);
    for(int i = 0; i < N; i++){
        long count = 0;
        is_in_remaining[A[i] - 1] = false;
        for(int j = 0; j < M; j++){
            if(A[i] == B[j]){
                maximum[i][j] = -1;
                goto next;
            }
            count += (A[i] < B[j]);
        }
        maximum[i][M - 1] = -1;
        ans = (ans * count) % mod;
    next:;
    }
    for(int i = 0; i < M; i++){
        long count = 0;
        is_in_remaining[B[i] - 1] = false;
        for(int j = 0; j < N; j++){
            if(B[i] == A[j]){
                goto next2;
            }
            count += (B[i] < A[j]);
        }
        maximum[N - 1][i] = -1;
        ans = (ans * count) % mod;
    next2:;
    }
    vector<long> out_edge;
    for(int i = 0; i < N; i++){
        for(int j = 0; j < M; j++){
            if(maximum[i][j] != -1){
                out_edge.push_back(maximum[i][j] - 1);
            }
        }
    }
    sort(all(out_edge));
    vector<long> lower;
    for(int i = 0; i < N * M; i++){
        if(is_in_remaining[i]){
            lower.push_back(i);
        }
    }
    for(int i = 0; i < lower.size(); i++){
        long times = (upper_bound(all(lower), out_edge[i]) - lower.begin() - i);
        if(times <= 0){
            cout << 0 << endl;
            return 0;
        }
        ans = ans * times % mod;
    }
    cout << ans % mod << endl;
}

