const static ll MOD = 1000000007;

ll solve(const vector<int>& A, const vector<int>& B){
  int N = A.size();
  int M = B.size();
  vector<int> cnt(N*M+10, 0);
  vector<int> sum(N*M+10, 0);
  vector<int> sum2(N*M+10, 0);
  vector<int> kakutei(N*M+10, 0);

  set<int> sA, sB;
  rep(i,N){
    sA.insert(A[i]);
  }
  rep(i,M){
    sB.insert(B[i]);
  }
  if(sA.size() != N || sB.size() != M) return 0;

  rep(i,N){
    rep(j,M){
      if(A[i] == B[j]){
        kakutei[A[i]] = 1;
      }else{
        int mn = min(A[i], B[j]);
        cnt[1]++;
        cnt[mn+1]--;
      }
    }
  }

  int base = 0;
  rep(i,cnt.size()){
    base += cnt[i];
    sum[i] = base;
  }

  rep(i,N){
    if(kakutei[A[i]] == 1) continue;
    int num = 0;
    rep(j,M){
      if(A[i] < B[j]) num++;
    }
    sum2[A[i]] = num;
  }
  rep(j,M){
    if(kakutei[B[j]] == 1) continue;
    int num = 0;
    rep(i,N){
      if(B[j] < A[i]) num++;
    }
    sum2[B[j]] = num;
  }

  ll ret = 1;
  base = 0;
  int already = 0;
  for(int i=N*M; i>0; i--){
    if(kakutei[i] == 0){
      if(sum[i] < base) return 0;
      if(already > sum[i]) return 0;
      //cout << i << "\t" << already << "\t" << sum[i] << "\t" << sum2[i] << endl;

      if(sum2[i] != 0){
        ret *= min(sum[i]-already, sum2[i]);
        ret %= MOD;
      }else{
        ret *= (sum[i] - already);
        ret %= MOD;
      }

      already++;
    }
    base = sum[i];
  }

  return ret;
}

int main(){
  int N, M;
  cin >> N >> M;
  vector<int> A, B;
  rep(i,N){
    int a;
    cin >> a;
    A.push_back(a);
  }
  rep(i,M){
    int b;
    cin >> b;
    B.push_back(b);
  }

  cout << solve(A, B) << endl;

  return 0;
}

