struct UF {
	int n;
	vi d;
	UF() {}
	UF(int n) :n(n), d(n, -1) {}
	int root(int v) {
		if (d[v] < 0) return v;
		return d[v] = root(d[v]);
	}
	bool same(int a, int b) {
		return root(a) == root(b);
	}
	bool unite(int x, int y) {
		x = root(x); y = root(y);
		if (x == y) return false;
		if (size(x) < size(y)) swap(x, y);
		d[x] += d[y];
		d[y] = x;
		return true;
	}
	int size(int v) { return -d[root(v)]; }
};

struct Fibonacci {

	vvll fib;
	Fibonacci() {
		fib.resize(2, vll(2));
		fib[0][0] = 1; fib[0][1] = 1;
		fib[1][0] = 1; fib[1][1] = 0;
	}

	vvll mul(vvll &A, vvll &B) {
		vvll C(2, vll(2));
		rep(i, 2) {
			rep(k, 2) {
				rep(j, 2) {
					C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
				}
			}
		}
		return C;
	}

	ll pow(ll n) {
		vvll A = fib;
		vvll B(2, vll(2));
		rep(i, 2) {
			B[i][i] = 1;
		}
		while (n > 0) {
			if (n & 1)B = mul(B, A);
			A = mul(A, A);
			n >>= 1;
		}
