    sort(s2 , s2 + n, cmp);
    int l1 = 0, l2 = 0;
    ll sum = 1;
    for (int i = n * m; i >= 1; i--) {
        if (l1 == n && l2 == m) {
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);continue;
        }
        if (l1 == n && l2 != m) {
            if (s2[l2] > i) return 0;
            if (s2[l2] == i) {
                ll t = l1;
                l2++;
                if (t == 0) return 0;
                sum = mod(sum * 1ll * t);
                continue;
            }
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);continue;
        }

        if (l1 != n && l2 == m) {
            if (s1[l1] > i) return 0;
            if (s1[l1] == i) {
                ll t = l2;
                l1++;
                if (t == 0) return 0;
                sum = mod(sum * 1ll * t);
                continue;
            }
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);continue;
        }

        if (s1[l1] > i || s2[l2] > i) return 0;

        if (s1[l1] == i && s2[l2] == i) {
            l1++,l2++;continue;
        }
        if (s1[l1] == i && s2[l2] != i) {
            ll t = l2;
            l1++;
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);
            continue;
        }
        if (s1[l1] != i && s2[l2] == i) {
            ll t = l1;
            l2++;
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);
            continue;
        }
        if (s1[l1] != i && s2[l2] != i) {
            ll t = l1 * 1ll * l2 - (n * m - i);
            if (t == 0) return 0;
            sum = mod(sum * 1ll * t);
        }
    }
    return sum;
}





