int c[1024000];

void solve(ll N, ll M, vector<ll> A, vector<ll> B) {
  memset(r, -1, sizeof(r));
  memset(c, -1, sizeof(c));
  REP(i,N) r[A[i] - 1] = i;
  REP(i,M) c[B[i] - 1] = i;
  int rc = 0, cc = 0;
  int cnt = 0;
  Mod res = 1;
  for (int i = N * M - 1; i >= 0; --i) {
    if (r[i] == -1 && c[i] == -1) {
      res *= (rc * cc - cnt);
      ++cnt;
    }
    else if (r[i] == -1) {
      res *= cc;
      ++rc;
      ++cnt;
    }
    else if (c[i] == -1) {
      res *= rc;
      ++cc;
      ++cnt;
    }
    else {
      ++rc;
      ++cc;
      ++cnt;
    }
    // cout << rc << " " << cc << endl;
  }
  cout << int(res) << endl;
}

