		if (b[j] == b[j + 1]) {
			cout << 0;
			return 0;
		}
	cerr << "Test" << endl;

	if (a[n - 1] != n * m || b[m - 1] != n * m) {
		cout << 0;
		return 0;
	}
	cerr << "Test" << endl;

	for (ll x = 1, i = 0, j = 0; x <= n * m; ++x) {
		while (a[i] < x)
			++i;
		while (b[j] < x)
			++j;
		assert(i < n && j < m);
		if (x != a[i] && x != b[j])
			cnts[i][j]++;
	}


	ll i = n - 1, j = m - 1;
	ll placed = 0;
	ll ans = 1;
	while (i >= 0 && j >= 0) {
		placed++;
