			ans *= (m - j);
		if (a[i] > b[j])
			ans *= (n - i);
		ans %= mod;
		for (ll &cnt = cnts[i][j]; cnt > 0; --cnt) {
			ans *= (n - i) * (m - j) % mod - placed;
			ans %= mod;
			placed++;
		}

		if (i && j && a[i - 1] == b[j - 1])
			--i, --j;
		else if (!j || (i && a[i - 1] > b[j - 1]))
			--i;
		else
			--j;
	}
	cout << (ans % mod + mod) % mod << endl;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j)
			assert(!cnts[i][j]);
	return 0;
}

