const int INF = 0x3f3f3f3f;
const long long LINF = 0x3f3f3f3f3f3f3f3fLL;
/*----------------------------------------*/
const int MOD = 1000000007;

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n, m; cin >> n >> m;
  int nm = n * m, small = INF;
  vector<int> a(n), b(m), check_a(n), check_b(m);
  REP(i, n) {
    cin >> a[i];
    small = min(small, a[i]);
    check_a[i] = a[i];
  }
  sort(ALL(check_a));
  check_a.erase(unique(ALL(check_a)), check_a.end());
  if (check_a.size() != n) {
    cout << 0 << '\n';
    return 0;
  }
  REP(i, m) {
    cin >> b[i];
    small = min(small, b[i]);
    check_b[i] = b[i];
  }
  sort(ALL(check_b));
  check_b.erase(unique(ALL(check_b)), check_b.end());
  if (check_b.size() != m) {
    cout << 0 << '\n';
    return 0;
  }
  vector<bool> used(nm+1, false);
  map<int, int> nn, mm;
  long long ans = 1;
  REP(i, n) {
    REP(j, m) {
      if (a[i] == b[j]) {
        used[a[i]] = true;
        ++nn[a[i]];
      } else if (a[i] < b[j]) ++nn[a[i]];
    }
    if (nn[a[i]] == 0) {
      cout << 0 << '\n';
      return 0;
    } else if (!used[a[i]]) {
      ans *= nn[a[i]];
      ans %= MOD;
    }
    --nn[a[i]];
    if (nn[a[i]] == 0) nn[a[i]] = INF;
  }
  REP(i, m) {
    REP(j, n) if (b[i] <= a[j]) ++mm[b[i]];
    if (used[b[i]]) continue;
    if (mm[b[i]] == 0) {
      cout << 0 << '\n';
      return 0;
    } else {
      ans *= mm[b[i]];
      ans %= MOD;
      --mm[b[i]];
      if (mm[b[i]] == 0) mm[b[i]] = INF;
    }
  }
  int haireru = 0;
  for (int now = nm; now >= small; --now) {
    if (used[now]) {
      if (nn[now] == INF) {
        if (mm[now] != INF) haireru += mm[now];
      } else if (mm[now] == INF) haireru += nn[now];
      else haireru += nn[now] + mm[now];
    } else if (nn[now]) {
      if (nn[now] != INF) haireru += nn[now];
    } else if (mm[now]) {
      if (mm[now] != INF) haireru += mm[now];
    } else if (haireru <= 0) {
      cout << 0 << '\n';
      return 0;
    } else {
      ans *= haireru;
      // cout << haireru << " " << ans << '\n';
      ans %= MOD;
      --haireru;
    }
  }
  for (int now = small-1; now >= 1; --now) {
    ans *= now;
    ans %= MOD;
  }
  cout << ans << '\n';
  return 0;
}

