        koho = 1;
        j++;
      }
      else koho = j;
      i++;
    }
    else{
      if(B[j] == t){
        koho = i;
        j++;
      }
      else koho = i * j - (nxm - t);
    }
    //cout << "x " << koho << "\n";
    res = (res * koho) % MOD;
  }
  return (int)res;
}

