// seiyaku[i][1] : 値iは列seiyaku[i][0]で最大値でないといけない
int seiyaku[1000001][2] = {};

int main()
{
	int n, m;
	cin >> n >> m;
	long long int ans = 1;
	for(int i = 1; i <= n; i++){
		int a;
		cin >> a;
		if(seiyaku[a][0] > 0) ans = 0;
		else seiyaku[a][0] = i;
	}
	for(int i = 1; i <= m; i++){
		int b;
		cin >> b;
		if(seiyaku[b][1] > 0) ans = 0;
		else seiyaku[b][1] = i;
	}
	set<int> alreadymax_r,alreadymax_g;

	for(int i = n * m; i>= 1; i--){
		int g = seiyaku[i][0];
		int r = seiyaku[i][1];
		if(g > 0 && r > 0){
			// 行と列どちらにも制約がある(最大値となる)場合
			// g行目r列目にiを埋めないといけない
			if(alreadymax_g.find(g) != alreadymax_g.end() || alreadymax_r.find(r) != alreadymax_r.end()){
				ans = 0;
			} else {
				alreadymax_g.insert(g);
				alreadymax_r.insert(r);
			}
		} else if(g > 0 && r == 0){
			// 行にのみ制約がある場合
			// g行目に埋めることは確定しているが、列は確定していない
			if(alreadymax_g.find(g) != alreadymax_g.end()){
				// g行目にすでに最大値が埋まっていたらアウト
				ans = 0;
			} else {
				alreadymax_g.insert(g);
				// g行目で制約を気にせず入れられるマスの数はalreadymax_r.size()
				ans = (ans * alreadymax_r.size()) % mod;
			}
		} else if(g == 0 && r > 0){
			// 列のみに制約がある場合
			// 上と同様
			if(alreadymax_r.find(r) != alreadymax_r.end()){
				ans = 0;
			} else {
				alreadymax_r.insert(r);
				ans = (ans * alreadymax_g.size()) % mod;
			}
		} else {
			// 行にも列にも制約がない場合
			ans = (ans * (alreadymax_g.size() * alreadymax_r.size() - (n * m - i))) % mod;
		}
	}
	cout << ans << endl;
}

