			mint p=fe.comb(b[y]-d-1,w-y+h-x-2);
			//cout<<ans<<endl;
			ans*=p;
			d+=w-y+h-x-1;
			x++; y++;
		}
	}
	cout<<ans<<endl;
	return 0;
}

