using bint = boost::multiprecision::cpp_int;

bint permutation(int n, int r)
{
    bint result = 1;
    for (int i = 0; i < r; i++) {
        result *= (n - i);
    }
    return result;
}

int main()
{
    int N, M;
    std::cin >> N >> M;
    std::vector<int> as(N);
    std::vector<int> bs(M);
    for (int i = 0; i < N; i++) {
        std::cin >> as.at(i);
    }
    for (int i = 0; i < M; i++) {
        std::cin >> bs.at(i);
    }
    std::sort(as.begin(), as.end());
    std::sort(bs.begin(), bs.end());
    int a_idx = 0;
    int b_idx = 0;
    int num_decided = 0;
    bint result = 1;
    while (a_idx != N - 1 or b_idx != M - 1) {
        if (a_idx > N - 1) {
            a_idx = N - 1;
        }
        if (b_idx > M - 1) {
            b_idx = M - 1;
        }
        if (a_idx == N - 1 and b_idx == M - 1) {
            break;
        }
        if (as.at(a_idx) < bs.at(b_idx)) {
            // 選択肢は1~A_{a_idx} - 1個あって，そのうちnum_decided個はすでに選ばれている
            // その中からM - 1 - b_idx個を選ぶ組み合わせ(Permutation)
            if (as.at(a_idx) - 1 - num_decided < M - 1 - b_idx) {
                std::cout << 0 << std::endl;
                return 0;
            }
            result *= permutation(as.at(a_idx) - 1 - num_decided, M - 1 - b_idx);
            num_decided += M - 1 - b_idx;
            a_idx++;
        } else if (as.at(a_idx) > bs.at(b_idx)) {
            if (bs.at(b_idx) - 1 - num_decided < N - 1 - a_idx) {
                std::cout << 0 << std::endl;
                return 0;
            }
            result *= permutation(bs.at(b_idx) - 1 - num_decided, N - 1 - a_idx);
            num_decided += N - 1 - a_idx;
            b_idx++;
        } else { // equal
            if (as.at(a_idx) - 1 - num_decided < (M - 1 - b_idx) + (N - 1 - a_idx)) { // as.at(a_idx) == bs.at(b_idx)
                std::cout << 0 << std::endl;
                return 0;
            }
            result *= permutation(as.at(a_idx) - 1 - num_decided, (M - 1 - b_idx) + (N - 1 - a_idx));
            a_idx++;
            b_idx++;
        }
    }
    std::cout << result << std::endl;
    return 0;
}

