	for (int i = n * m; i > 0; i--) {
		while (l > 0 && a[l - 1] >= i)l--;
		while (r > 0 && b[r - 1] >= i)r--;
		if (a[l] == i && b[r] == i) {
			aa[l]++;
			bb[r]++;
			if ((n - l)*(m - r) <= (n*m - i))ans = 0;
		}
		else {
			if (a[l] == i) {
				aa[l]++;
				if (n*m - i <= (n - l - 1)*(m - r)) {
					ans *= m - r;
					ans %= p;
				}
				else ans = 0;
			}
			if (b[r] == i) {
				bb[r]++;
				if (n*m - i <= (n - l)*(m - r - 1)) {
					ans *= n - l;
					ans %= p;
				}
