const ll mod = 1e9+7;

ll f_[1000100];
ll f(ll n) {
	if(n == 0)
		return 1;
	if(f_[n])
		return f_[n];
	return n * f(n-1) % mod;
}

ll ivf_[1000100];
ll ivf(ll n) {
	if(ivf_[n])
		return ivf_[n];
	ll x = f(n);
	ll p = mod -2;
	ll res = 1;
	while(p) {
		if(p & 1)
			res = (res * x) % mod;
		x = (x * x) % mod;
		p /= 2;
	}
	return res;
}

ll choose(ll n, ll r) {
	return (f(n) * ivf(n-r)) % mod;
}

int main() {
	int N, M;
	cin >> N >> M;
	vector<pii> A(N), B(M);
	rep(i, N) {
		int a; cin >> a;
		A[i] = pii(a,i);
	}
	rep(i, M) {
		int a; cin >> a;
		B[i] = pii(a,i);
	}
	A.push_back(pii(1000100, -1));
	B.push_back(pii(1000100, -1));
	sort(rall(A));
	sort(rall(B));

	int x = 0;
	ll res = 1;

	unordered_map<ll,int> mp;
	rep(i,N) {
		mp[A[i+1].fi]++;
		if(mp[A[i+1].fi] >= 2)
			res = 0;
	}
	mp.clear();
	rep(i,M) {
		mp[B[i+1].fi]++;
		if(mp[B[i+1].fi] >= 2)
			res = 0;
	}
	while(res && A.size()+B.size() > 2) {
		bool a, b;
		a = b = false;
		if(A.back().fi == B.back().fi)
			a = b = true;
		else if(A.back().fi < B.back().fi)
			a = true;
		else
			b = true;

		int c = 0;
		int n = 0;
		if(a) {
			c += B.size()-1;
			n = A.back().fi;
			A.pop_back();
		}
		if(b) {
			c += A.size()-1;
			n = B.back().fi;
			B.pop_back();
		}
		if(n < x+c) {
			res = 0;
		}
		else {
			res = res * choose((n-1)-x, c-1) % mod;
			if(a && !b)
				res = res * (B.size()-1) % mod;
			else if(!a && b)
				res = res * (A.size()-1) % mod;
			x += c;
		}
	}
	cout << res << endl;
	return 0;
}

