const int MO=1e9+7;
int N,M,NN,MM,n,m,a[1111111],b[1111111],ts,tmp[1111111];
LL f[1111111],fac[1111111],inv[1111111];
LL pw(LL x,LL y){
	LL t=1;
	for (;y;y>>=1){
		if (y&1) t=t*x%MO;
		x=x*x%MO;
	}
	return t;
}
LL C(int x,int y){
	if (x<y) return 0;
	return fac[x]*inv[y]%MO*inv[x-y]%MO;
}
int main(){
	fac[0]=1;
	FOR(i,1,1000000) fac[i]=fac[i-1]*i%MO;
	inv[1000000]=pw(fac[1000000],MO-2);
	FORD(i,999999,0) inv[i]=inv[i+1]*(i+1)%MO;
	cin>>n>>m;
	FOR(i,1,n) getint(a[i]),tmp[++ts]=a[i];
	FOR(i,1,m) getint(b[i]),tmp[++ts]=b[i];
	sort(a+1,a+n+1);
	FOR(i,1,n) if (a[i]==a[i-1]) return puts("0"),0;
	sort(b+1,b+m+1);
	FOR(i,1,m) if (b[i]==b[i-1]) return puts("0"),0;
	sort(tmp+1,tmp+ts+1);
	ts=unique(tmp+1,tmp+ts+1)-tmp-1;
	f[ts]=1;
	N=n,M=m;
	FORD(rp,ts,1){ //f[rp]->f[rp-1]
		NN=N;
		MM=M;
		while (a[NN]>tmp[rp-1]) --NN;
		while (b[MM]>tmp[rp-1]) --MM;
		int r=tmp[rp]-tmp[rp-1];
	//	原来填了>tmp[rp] n*m-tmp[rp]
	//	原来有格子(n-N)*(m-M)
	//	现在有格子(n-NN)*(m-MM)
		if (NN==N){
			(f[rp-1]+=f[rp]*(n-N)%MO*C((n-NN)*(m-MM)-(n*m-tmp[rp])-1,r-1)%MO*fac[r-1])%=MO;
		}
		else if (MM==M){
			(f[rp-1]+=f[rp]*(m-M)%MO*C((n-NN)*(m-MM)-(n*m-tmp[rp])-1,r-1)%MO*fac[r-1])%=MO;
		}
		else{
			(f[rp-1]+=f[rp]*C((n-NN)*(m-MM)-(n*m-tmp[rp])-1,r-1)%MO*fac[r-1])%=MO;
		}
		N=NN;
		M=MM;
	}
	cout<<(f[0]%MO+MO)%MO<<endl;
	return 0;
}

