        int a;
        cin >> a;
        a--;
        if (r[a] == -1) {
            r[a] = i;
        } else {
            flag = false;
            break;
        }
    }

    for (int i = 0; i < m; i++) {
        int b;
        cin >> b;
        b--;
        if (c[b] == -1) {
            c[b] = i;
        } else {
            flag = false;
            break;
        }
    }

    int ans = 1;
    int cr = 0, cc = 0;
    for (int i = n * m - 1; i >= 0; i--) {
        if (r[i] == -1 && c[i] == -1) {
            ans = 1ll * ans * (cr * cc - (n * m - 1 - i)) % z;
        } else if (r[i] == -1) {
            ans = 1ll * ans * cr % z;
            cc++;
        } else if (c[i] == -1) {
            ans = 1ll * ans * cc % z;
            cr++;
        } else {
            cr++;
            cc++;
        }

        if (cr > n || cc > m) {
            flag = false;
        }
    }

    cout << (flag ? ans : 0) << endl;

    return 0;
