using namespace std;


long long modinv(long long a) {
	long long b = 1000000007, u = 1, v = 0;
	while (b) {
		long long t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= 1000000007;
	if (u < 0) { 
		u += 1000000007; 
	}
	return u;
}

long long fact(int n) {
	if (n <= 0) {
		return 0;
	}
	long long answer = 1;
	for (int i = 2; i <= n; i++) {
		answer *= i;
		answer %= 1000000007;
	}
	return answer;
}

long long comb(int n, int m) {
	long long answer;

	if (n < m || n < 0 || m < 0) {
		return 0;
	}
	if (n == m) {
		return 1;
	}
	answer = fact(n) * (modinv((fact(n - m) * fact(m)) % 1000000007) % 1000000007);
	answer = answer % 1000000007;
	return answer;
}

int main() {
	int n, m;
	int a[1000], b[1000];
	long long count = 1;

	cin >> n >> m;

	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	for (int i = 0; i < m; i++) {
		cin >> b[i];
	}

	sort(a, a + n);
	sort(b, b + m);

	for (int i = 0; i < n - 1; i++) {
		if (a[i] == a[i + 1]) {
			count = 0;
		}
	}
	for (int j = 0; j < m - 1; j++) {
		if (b[j] == b[j + 1]) {
			count = 0;
		}
	}

	int i = 0, j = 0;
	while(1) {
		if (count == 0) { break; }
		if (i == n - 1 && j == m - 1) { break; }
		if (a[i] == b[j]) {
			count *= ((comb(b[j] - 1 - (i*m + j*n - i*j), n + m - (2 + i + j))) * fact(n + m - (2 + i + j))) % 1000000007;
			count %= 1000000007;
			i++;
			j++;
		}
		else if (a[i] > b[j] && j < m - 1) {
			count *= (comb(b[j] - (i*m + j*n - i*j) - 1, n - i - 1) * fact(n - i)) % 1000000007;
			count %= 1000000007;
			j++;
		}
		else if(a[i] < b[j] && i < n - 1){
			count *= (comb(a[i] - (i*m + j*n - i*j) - 1, m - j - 1) * fact(m - j)) % 1000000007;
			count %= 1000000007;
			i++;
		}
	}

	cout << count % 1000000007 << endl;
}

