  scanf("%d ", &A[i]);
  REP(i, M)
  scanf("%d ", &B[i]);
  sort(A, A + N);
  sort(B, B + M);
  long long int mod = 1000000007;

  // check whether duplicate number exists.
  bool flag = false;
  REP(i, N - 1) {
