#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

const ll MOD = 1000000007;
ll N, M, A[1000], B[1000];
bool row[1000001], col[1000001];

ll solve() {
  REP(i, 0, N) {
    if (row[A[i]]) return 0;
    row[A[i]] = true;
  }
  REP(i, 0, M) {
    if (col[B[i]]) return 0;
    col[B[i]] = true;
  }

  ll ans = 1, cr = 0, cc = 0;
  for (ll k = N * M; k >= 1; k--) {
    ll r = row[k], c = col[k];
    if (row[k] && col[k]) {
      cr++;
      cc++;
    } else if (row[k] && !col[k]) {
      (ans *= cc) %= MOD;
      cr++;
    } else if (!row[k] && col[k]) {
      (ans *= cr) %= MOD;
      cc++;
    } else {
      ll t = N * M - k, x = (cr * cc) - t;
      (ans *= x) %= MOD;
    }
  }
  return ans;
}

int main(void) {
  cin >> N >> M;
  REP(i, 0, N) cin >> A[i];
  REP(i, 0, M) cin >> B[i];

  cout << solve() << endl;
}

