  }
  for (int i = 0; i < M-1; i++) {
    if (B[i] == B[i+1]) {
      std::cout << 0 << std::endl;
      return;
    }
  }
  int idx_a = 0;
  int idx_b = 0;
  long long prev = 0;
  long long rest = 0;
  long long ret = 1;
  long long ms = 0;
  for (int i = 0; i < N+M; i++) {
    if (A[idx_a] == B[idx_b]) {
      rest += A[idx_a] - prev - 1;
      ms = (N - idx_a) + (M - idx_b) - 2;
      ret *= fact[rest] * factinv[rest-ms] % mod;
      ret %= mod;
      i++;
      rest -= ms;
      prev = A[idx_a];
      idx_a++;
      idx_b++;
    } else {
      if (A[idx_a] < B[idx_b]) {
        rest += A[idx_a] - prev - 1;
        ms = M - idx_b - 1;
        ret *= ms + 1;
        ret %= mod;
        ret *= fact[rest] * factinv[rest-ms] % mod;
        ret %= mod;
        rest -= ms;
        prev = A[idx_a];
        idx_a++;
      } else {
        rest += B[idx_b] - prev - 1;
        ms = N - idx_a - 1;
        ret *= ms + 1;
        ret %= mod;
        ret *= fact[rest] * factinv[rest-ms] % mod;
        ret %= mod;
        rest -= ms;
        prev = B[idx_b];
        idx_b++;
      }
    }
  }
  std::cout << ret << std::endl;
}

