int _main()
{
    ll n; llin(n);
    ll m; llin(m);
    V<ll> alist; llina(alist, n);
    V<ll> blist; llina(blist, m);

    static ll val_raw[1000003];
    make_map(val_raw, alist, n);

    static ll val_column[1000003];
    make_map(val_column, blist, m);

    ll ans = 1LL;
    ll cross = 0LL;
    ll raw_cnt = 0LL;
    ll column_cnt = 0LL;

    rrep (val, n * m + 1LL) {
        if (val == 0LL) break;

        ll raw = val_raw[val];
        ll column = val_column[val];
        ll ptn = 1LL;

        if (raw >= 0LL && column >= 0LL) {
            cross += (raw_cnt + column_cnt);
            raw_cnt++;
            column_cnt++;
            ptn = 1LL;
        }

        if (raw >= 0LL && column < 0LL) {
            cross += (column_cnt - 1LL);
            raw_cnt++;
            ptn = column_cnt;
        }

        if (raw < 0LL && column >= 0LL) {
            cross += (raw_cnt - 1LL);
            column_cnt++;
            ptn = raw_cnt;
        }

        if (raw < 0LL && column < 0LL) {
            if (cross <= 0LL) {
                cout << 0 << endl;
                return 0;
            }
            ptn = cross--;
        }

        ans *= ptn;
        ans %= MOD;
    }

