#include <bits/stdc++.h>
using namespace std;
const int MAX = 1010000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long int fact(long long int n){
	long long int f=1;
	for(int i=1;i<=n;i++) f=(f*i)%MOD;
	return f;
}

int main (void){
	COMinit();
	long long int n,m,a[1010],b[1010],i,j,ans=1,def=0;
	cin >> n >> m;
	for(i=0;i<n;i++) cin >> a[i];
	for(i=0;i<m;i++) cin >> b[i];
	sort(a,a+n);
	sort(b,b+m);
	a[n]=2000; b[m]=2000;
	int flag=0;
	for(i=0;i<n;i++){
		if(a[i]<m*(i+1)) flag=1;
	}
	for(i=0;i<m;i++){
		if(b[i]<n*(i+1)) flag=1;
	}
	if(flag==1){
		cout << "0" << endl;
		return 0;
	}
	for(i=0;i<n-1;i++){
		if(a[i]==a[i+1]) flag=1;
	}
	for(i=0;i<m-1;i++){
		if(b[i]==b[i+1]) flag=1;
	}
	if(flag==1){
		cout << "0" << endl;
		return 0;
	}
	i=0; j=0;
	while(i!=n||j!=m){
		def++;
		if(a[i]<b[j]){
			if(a[i]-def<m-j-1){
				cout << "0" << endl;
				return 0;
			}
			ans=(ans*((fact(m-j)*COM(a[i]-def,m-j-1))%MOD))%MOD;
			def+=(m-j-1);
			i++;
		} else if(a[i]>b[j]){
			if(b[j]-def<n-i-1){
				cout << "0" << endl;
				return 0;
			}
			ans=(ans*((fact(n-i)*COM(b[j]-def,n-i-1))%MOD))%MOD;
			def+=(n-i-1);
			j++;
		} else {
			if(a[i]-def<m+n-i-j-2){
				cout << "0" << endl;
				return 0;
			}
			ans=(ans*((fact(m+n-i-j-2)*COM(a[i]-def,m+n-i-j-2))%MOD))%MOD;
			def+=(m+n-i-j-2);
			i++;
			j++;
		}
	}
	cout << ans << endl;
	return 0;
}

