int Appear(int a) {
	if (P[a] == -1 && Q[a] == -1) return 0;
	if (P[a] != -1 && Q[a] != -1) return 1;
	if (P[a] != -1) {
		int cnt = 0;
		REP(i, 0, W) {
			cnt += B[i] >= a;
		}
		return cnt;
	}
	if (Q[a] != -1) {
		int cnt = 0;
		REP(i, 0, H) {
			cnt += A[i] >= a;
		}
		return cnt;
	}
}

