void _main()
{
    ll n; llin(n);
    ll m; llin(m);
    S V<ll> alist; llina(alist, n);
    S V<ll> blist; llina(blist, m);

    S bool exists_a[1005] = {};
    for (auto a : alist) {
        if (exists_a[a]) {
            cout << 0 << endl;
            return;
        }
        exists_a[a] = true;
    }

    S bool exists_b[1005] = {};
    for (auto b : blist) {
        if (exists_b[b]) {
            cout << 0 << endl;
            return;
        }
        exists_b[b] = true;
    }

    ll ans = 1LL;
    ll not_found = 0;
    ll line_n = 0;
    ll line_m = 0;

    rrep (val, n * m + 1) {
        if (!val) break;

        if (exists_a[val] && exists_b[val]) {
            not_found += line_n;
            not_found += line_m;
            line_n++;
            line_m++;
            continue;
        }

        if (exists_a[val]) {
            ans *= line_m;
            ans %= MOD;
            not_found += line_m - 1LL;
            line_n++;
            continue;
        }

        if (exists_b[val]) {
            ans *= line_n;
            ans %= MOD;
            not_found += line_n - 1LL;
            line_m++;
            continue;
        }

        ans *= not_found;
        ans %= MOD;
        not_found--;
    }

    cout << ans << endl;
}

