			else{
				if(row[i]){
					long long mul = sumc[i+1];
					ans = ans*mul%mod;
				}
				else if(col[i]){
					long long mul = sumr[i+1];
					ans = ans*mul%mod;
				}
				else{
					long long used = n*m-i;
					long long have = sumr[i+1]*sumc[i+1]-used;
					if(have<=0){
						ans = 0;
						break;
					}
					else ans = ans*have%mod;
				}
			}
		}
		printf("%lld\n",ans);
	}
	return 0;
}

