    }
  }
  for (int j = 1; j < M; j++) {
    if (bs[j] == bs[j - 1]) {
      printf("0\n");
      return 0;
    }
  }

  // fill from the larger numbers
  long ans = 1;
  for (long num = N * M; num > 0; num--) {
    const long num_placed = N * M - num,
               i_min = lower_bound(as, as + N, num) - as,
               j_min = lower_bound(bs, bs + M, num) - bs,
               a = as[i_min], b = bs[j_min];
    if (num == a && num == b) {
      ans *= 1;
    } else if (num == a) {
      ans = ans * (M - j_min) % NUM_MOD;
    } else if (num == b) {
      ans = ans * (N - i_min) % NUM_MOD;
    } else {
      if ((N - i_min) * (M - j_min) <= num_placed) {
        printf("0\n");
        return 0;
      }
      ans = ans * ((N - i_min) * (M - j_min) - num_placed) % NUM_MOD;
    }
