	for (size_t i = 0; i < n; i++)
		cin >> a[i];
	for (size_t i = 0; i < m; i++)
		cin >> b[i];
	sort(a, a + n);
	sort(b, b + m);
	int ai = 0;
	int bi = 0;
	ll mv = 0;
	ll cnt = 0;
	ll res = 1;
	while (ai < n || bi < m)
	{
		ll rl = n - ai; // 残り行数
		ll rc = m - bi; // 残り列数
		if (ai >= n || (a[ai] > b[bi])) {
			// bが小さい時
			// b[bi]も含めて残りの好きなところに配置出来る
			ll cn = b[bi] - mv;
			if (cn == 0) {
				cout << 0 << endl;
				return;
			}
			if (cnt + cn < rl) {
				cout << 0 << endl;
				return;
			}
			res *= (rl * upr(cnt + cn - 1, rl - 1)) % INF;
			cnt = (cnt + cn - rl);
			mv = b[bi];
			bi++;
		}
		else if(bi >= m || (a[ai] < b[bi])){
			// aが小さい時
			ll cn = a[ai] - mv;
			if (cn == 0) {
				cout << 0 << endl;
				return;
			}
			if (cnt + cn < rc) {
				cout << 0 << endl;
				return;
			}
			res *= (rc* upr(cnt + cn - 1, rc - 1)) % INF;
			cnt = (cnt + cn - rc);
			mv = a[ai];
			ai++;
		}
		else if (a[ai] == b[bi]) {

			ll cn = a[ai] - mv;
			if (cn == 0) {
				cout << 0 << endl;
				return;
			}

			if ((cnt + cn - 1) < (rc + rl - 2)) {
				cout << 0 << endl;
				return;
			}
			res *= upr(cnt + cn - 1, rc + rl - 2);
			cnt = cnt + cn - 1 - (rc + rl - 2);
			mv = a[ai];
			ai++;
			bi++;
		}
		res %= INF;
	}
	cout << res << endl;
}

