const int maxn = 1002;
const int mo = 1e9 + 7;

int n, m;
long long sum_a[maxn*maxn], sum_b[maxn*maxn];
int a[maxn], b[maxn];

int main() {

	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cin >> n >> m;

	int tmp;
	for (int i = 0; i < n; ++i)
	{
		cin >> tmp;
		if (a[tmp]) {
			cout << 0 << endl;
			return 0;
		}
		a[tmp] = 1;
	}

	for (int i = 0; i < m; ++i)
	{
		cin >> tmp;
