    for (int t = w * h; t >= 1; t--) {
        if (contain(horizontal, t) && contain(vertical, t)) {
            dp.push_back(1);
            d_w++;
            d_h++;
        } else if (contain(horizontal, t)) {
            dp.push_back(d_h);
            d_w++;
        } else if (contain(vertical, t)) {
            dp.push_back(d_w);
            d_h++;
        } else {
            int f = w * h - t;
            int area = d_w * d_h;
            int ok = max(area - f, 0);
            dp.push_back(ok);
        }
    }
    mint ans = 1;
    for (int p : dp) ans *= p;
    cout << ans << endl;

}

