        cin >> B[i];
    }

    //! A/Bに同じ数字が書かれている場合には0を出力
    bool same = false;
    REP(i, N)
    {
        FOR(j, N, i + 1)
        {
            if (A[i] == A[j])
                same = true;
        }
    }
    REP(i, M)
    {
        FOR(j, M, i + 1)
        {
            if (B[i] == B[j])
                same = true;
        }
    }
    if (same)
    {
        cout << 0 << endl;
        return 0;
    }

    REP(h, N)
    {
        REP(w, M)
        {
            int t = std::min(A[h], B[w]);
            T[t++;
            if (A[h] == B[w])
                S[t] = true;
        }
    }

    ll ans = 1;
    ll next = 0;
    for (int i = N * M; i > 0; --i)
    {
        if (T[i] == 0)
        {
            T[i] += next;
            next = 0;
        }
        if (!S[i])
            ans = (ans * T[i]) % MOD;
        next += T[i] - 1;
    }
    cout << ans << endl;
    return 0;
}

