	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N, M;
	cin >>N>>M;
	vector<int> A(N), B(M);
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 0; i < M; i++) cin >> B[i];
	sort(A.begin(), A.end());
	sort(B.begin(), B.end());

	mint ans = 1;
	for (int i = 0; i < N - 1; i++) if (A[i + 1] == A[i]) ans = 0;
	for (int i = 0; i < M - 1; i++) if (B[i + 1] == B[i]) ans = 0;

	Factorial Fac(1000000);
	int row = 0, col = 0;
	int cnt = 0, prev = 0;
	while (row < N && col < M) {

		if (A[row] < B[col]) {
			cnt += A[row] - prev - 1;
			prev = A[row];
			ans *= M - col;
			ans *= Fac.Pmod(cnt, M - col - 1);
			cnt -= M - col - 1;
			row++;
		}
		else if (A[row] > B[col]){
			cnt += B[col] - prev - 1;
			prev = B[col];
			ans *= N - row;
			ans *= Fac.Pmod(cnt, N - row - 1);
			cnt -= N - row - 1;
			col++;
		}
		else {
			cnt += A[row] - prev - 1;
			prev = A[row];
			ans *= Fac.Pmod(cnt, N + M - (row + col) - 2);
			cnt -= N + M - (row + col) - 2;
			row++, col++;
		}

	}

	cout << ans << "\n";

	return 0;
}

