constexpr int DEBUG = 0;

constexpr int64 P = 1000000007;

struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 x) : x(x) {
    if (x > P || x < 0) { cerr << "Invalied FiniteField!" << endl; exit(1); }
  }
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

FiniteField Solve() {
  int h, w;
  cin >> h >> w;
  vector<int> v_to_r(h * w + 1, -1);
  vector<int> v_to_c(h * w + 1, -1);
  vector<int> rs(h);
  vector<int> cs(w);
  for (int i = 0; i < h; i++) {
    cin >> rs[i];
    if (v_to_r[rs[i]] >= 0) return 0;
    v_to_r[rs[i]] = i;
  }
  for (int i = 0; i < w; i++) {
    cin >> cs[i];
    if (v_to_c[cs[i]] >= 0) return 0;
    v_to_c[cs[i]] = i;
  }

  FiniteField ans = 1;
  int r_count = 0;
  int c_count = 0;
  for (int x = h * w; x >= 1; x--) {
    int r = v_to_r[x];
    int c = v_to_c[x];

    if (r >= 0 && c >= 0) {
      r_count++;
      c_count++;
    } else if (r >= 0) {
      ans *= c_count;
      r_count++;
    } else if (c >= 0) {
      ans *= r_count;
      c_count++;
    } else {
      int m = r_count * c_count - (h * w - x);
      if (m <= 0) return 0;
      ans *= m;
    }
  }
  return ans;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve().Value() << endl;
}

