    ll squared_norm() const {return x * x + y * y;}
    tuple<ll, ll> get_value(){return make_tuple(x, y);}

    ll which_quadrant() const{
        if (x == 0 && y == 0) return 0;
        if (x >= 0 && y >= 0) return 1;
        else if (x <= 0 && y >= 0) return 2;
        else if (x <= 0 && y <= 0) return 3;
