const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;
const bool multiple_queries = false;

void solve(){
    /*
    *** 注意 ***
    ・マイナスの整数の除算が0 (マイナスのときはCeil関数になる)になって，マイナスの判定ができていない．
    ・MODの逆元を取るときは素数か否かに注意．
    ・Queue, stack, deque等で必ず`empty`なら飛ばすようにする．
    ・set, multisetで`RE`を起こすときは初期段階で解法に影響が出ないようなダミーをsetに入れておくとエラーを回避できる．
    ・掛け算のOverflow注意．(x * y > 10^18　-> x > 10^18 / y) のような形で判定するとよい．
    ・総和を取る公式 (1+2+...+n = n * (n + 1) / 2)の計算時等で最終的には10^18に収まる場合は`/2`の順序を早める．
    ・Bit演算をするときに`a ^ b != c`のような式は代入演算子になったりするので注意． (ABC150F)
    ・aborted (core dumped) のエラーが出ているときは変数の二重宣言やベクトルの区間外参照を確認．
    -> 特にこのRunning ErrorではVectorのShapeが合っているか確認．
    ・`tuple`のコンパイルエラーは`make_tuple(a, b, c, ...)`で回避．
    ・グラフの最短経路と木の最短経路は同じDFSでも更新方法に注意. (ABC148E)
    ・Running Errorの１つとして，関数の返り値のタイプが定義されているのに何も返していないことが考えられる．
    ・Running Errorとしてベクトルサイズが0であるにもかかわらずsortをしている場合がある．
    ・境界条件は必ず試す．
    ・multiset.lower_bound(val) (O(logN)) != lower_bound(all(multiset), val) (<- O(N)) ABC134E
    ・Overflow不等式: (前提条件：a, b, c > 0)
        1. a * b <= c -> a <= c / b
        2. a * b <  c -> a <= c / b && (c % b || a != c / b)
        3. c <= a * b -> (c + b - 1) / b <= a
        4. c <  a * b -> (c + b - 1) / b <= a && (c % b || a != c / b)
    */
    // generate_array(size, min, max);
    ll n, m; in2(n, m);
    vl as, bs, cs(n * m, 0);
    read_vector(n, as, -1);
    read_vector(m, bs, -1);
    sort(all(as));
    sort(all(bs));

    mint ans = 1; bool ok = true;
    rep(i, n - 1) For(j, i + 1, n)
        if (as[i] == as[j]) ok = false;
    rep(i, m - 1) For(j, i + 1, m)
        if (bs[i] == bs[j]) ok = false;
    rep(i, n) rep(j, m)
        if (as[i] == bs[j]) cs[as[i]] = 1;
    rep(i, n){
        if (cs[as[i]]) continue;
        cs[as[i]] = m - (lower_bound(all(bs), as[i]) - bs.begin());
    }
    rep(i, m){
        if (cs[bs[i]]) continue;
        cs[bs[i]] = n - (lower_bound(all(as), bs[i]) - as.begin());
    }

    revrep(i, n * m){
        if (cs[i]) {ans *= cs[i]; continue;}
        cs[i] = n - (lower_bound(all(as), i) - as.begin());
        cs[i] *= m - (lower_bound(all(bs), i) - bs.begin());
        ans *= (cs[i] - n * m + i + 1);
    }
    prl(ok ? ans : 0);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
