            cout << 0 << endl;
            return 0;
        }
    }

    if(A[0] == B[0] && A[0] == N*M){
        ans = 1;
        ll op = N*M-1;
        ll tate = 1, yoko = 1;
        ll kouten = 1, put_kouten = 1;
        while(idx_A < N || idx_B < M){
            if(idx_A == N){
                if(op > B[idx_B]){
                    ans = (ans * (kouten-put_kouten)) % mod;
                    put_kouten++;
                }
                else{
                    kouten += yoko; tate++;
                    ans = (ans * yoko) % mod;
                    put_kouten++;
                    idx_B++;
                }
            }
            else if(idx_B == M){
                if(op > A[idx_A]){
                    ans = (ans * (kouten-put_kouten)) % mod;
                    put_kouten++;
                }
                else{
                    kouten += tate; yoko++;
                    ans = (ans * tate) % mod;
                    put_kouten++;
                    idx_A++;
                }
            }
            else{
                if(op > A[idx_A] && op > B[idx_B]){
                    ans = (ans * (kouten-put_kouten)) % mod;
                    put_kouten++;
                }
                else if(op == A[idx_A] && op == B[idx_B]){
                    //一意に決まる
                    kouten += tate; yoko++;
                    kouten += yoko; tate++;
                    put_kouten++;
                    idx_A++; idx_B++;
                }
                else if(op == A[idx_A]){
                    kouten += tate; yoko++;
                    ans = (ans * tate) % mod;
                    put_kouten++;
                    idx_A++;
                }
                else{
                    kouten += yoko; tate++;
                    ans = (ans * yoko) % mod;
                    put_kouten++;
                    idx_B++;
                }
            }
            op--;
        }
        //1以上op以下の数は好きなとこにおける -> ans *= fac[op];
        ll fac[op+1]; fac[0] = 1;
        rep(i, op){
            fac[i+1] = (fac[i]*(i+1)) % mod;
        }
        ans = (ans * fac[op]) % mod;
    }
    else{
        ans = 0;
    }
    cout << ans << endl;
    return 0;
}

