const LL MOD = 1000000007;

LL solve(LL n, LL m, vector<pair<LL,LL>>& rest){
    LL row_r = n;
    LL col_r = m;
    LL ans = 1;
    LL cur = 0;
    for(pair<LL,LL> p: rest){
        LL v = p.first;
        LL type = p.second;
        if(type == 1){ // row
            LL w = v - cur;
            //cerr << "type1 " << w << endl;
            if(w < col_r) return 0;
            ans = ans * col_r % MOD;
            for(LL j = 0; j < col_r-1; ++j){
                ans = ans * (w-1-j) % MOD;
            }
            cur += col_r;
            row_r -= 1;
        }else if(type == 2){ // col
            LL w = v - cur;
            //cerr << "type2 " << w << endl;
            if(w < row_r) return 0;
            ans = ans * row_r % MOD;
            for(LL j = 0; j < row_r-1; ++j){
                ans = ans * (w-1-j) % MOD;
            }
            cur += row_r;
            col_r -= 1;
        }else{ // row + col
            assert(type == 3);
            LL w = v - cur;
            //cerr << "type3 " << w << endl;
            if(w < col_r + row_r - 1) return 0;
            for(LL j = 0; j < col_r+row_r-1-1; ++j){
                ans = ans * (w-1-j) % MOD;
            }
            cur += col_r+row_r-1;
            row_r -= 1;
            col_r -= 1;
        }
    }
    return ans;
}

