    vi cols(N*M+1, -1);

    for (int i=0;i<N;i++) {
        rows[A[i]] = i;
    }
    for (int j=0;j<M;j++) {
        cols[B[j]] = j;
    }

    vb usedrows(N, false);
    vb usedcols(M, false);

    int hnum = 0;
    int hrows = 0;
    int hcols = 0;

    mi ans = 1;

    for (int x=N*M; x>0; x--) {
        // cout << x << endl;
        if (rows[x] == -1 && cols[x] == -1) {
            // cout << "case 1 " << endl;
            int hiding = hrows*hcols - hnum;
            ans *= hiding;
            hnum++;
        } else if (rows[x] == -1) {
            // cout << "case 2 " << endl;
            if (usedcols[cols[x]]) {
                cout << 0 << endl;
                return 0;
            }
            ans *= hrows;

            usedcols[cols[x]] = true;
            hcols++;
            hnum++;
        } else if (cols[x] == -1) {
            // cout << "case 3 " << endl;
            if (usedrows[rows[x]]) {
                cout << 0 << endl;
                return 0;
            }
            ans *= hcols;

            usedrows[rows[x]] = true;
            hrows++;
            hnum++;
        } else {
            // cout << "case 4 " << endl;
            if (usedrows[rows[x]] || usedcols[cols[x]]) {
                cout << 0 << endl;
                return 0;
            }

            usedrows[rows[x]] = true;
            usedcols[cols[x]] = true;

            hrows++;
            hcols++;
            hnum++;
        }
    }

    cout << ans << endl;
}

