    scanf( "%lld", A+i );
  rep( i, M )
    scanf( "%lld", B+i );

  std::sort( A, A+N );
  std::sort( B, B+M );

  ll prod = 1;

  for( ll i = N*M; i > 0; --i )
  {
    ll p = std::lower_bound( A, A+N, i )-A;
    ll q = std::lower_bound( B, B+M, i )-B;

    if( A[p] == i && B[q] == i )
    {
      if( (p+1 < N && A[p+1] == A[p]) || (q+1 < M && B[q+1] == B[q]) )
