    }
    else if( A[p] == i )
      prod = (prod*(M-q)) % mod;
    else if( B[q] == i )
      prod = (prod*(N-p)) % mod;
    else
      prod = (prod*((N-p)*(M-q)-(N*M-i))) % mod;
  }

  printf( "%lld\n", prod%mod );

  return 0;
}

