			if (gc[i].empty()) {
				ans = (ans * cr) % MOD;
				--cr;
			}
			else {
				ans = (ans * r) % MOD;
				cr += r - 1;
				++c;
			}
		}
		else {
			if (gc[i].empty()) {
				ans = (ans * c) % MOD;
				cr += c - 1;
				++r;
			}
			else {
				cr += r + c;
				++r, ++c;
			}
		}
	}
	cout << ans << "\n";
	return 0;
}

