void solve() {
  int n, m;
  cin >> n >> m;
  vi32 a(n), b(m);
  cin >> a >> b;
  sort(all(a));
  sort(all(b));
  int now = n * m;
  int ap = n, bp = m;
  mint ans = 1;
  while (now) {
    if (ap > 0 && a[ap - 1] == now) {
      if (bp > 0 && b[bp - 1] == now) {
        ap--;
        bp--;
      } else {
        ap--;
        ans *= (m - bp);
      }
    } else {
      if (bp > 0 && b[bp - 1] == now) {
        bp--;
        ans *= (n - ap);
      } else {
        ans *= (n - ap) * (m - bp) - (n * m - now);
      }
    }
    now--;
  }
  cout << ans << endl;
}

