			ll W = A.end() - lower_bound(A.begin(), A.end(), i);
			pos = H * W - ((ll)N * M - i);
			pos = (pos % mod + mod) % mod;
			res = (res * pos) % mod;
		}
		else if (appered_A[i] && !appered_B[i]) {
			ll H = B.end() - lower_bound(B.begin(), B.end(), i);
			pos = H;
			res = (res * H) % mod;
		}
		else if (!appered_A[i]) { // appered_B[i]
			ll W = A.end() - lower_bound(A.begin(), A.end(), i);
			pos = W;
			res = (res * W) % mod;
		}
#ifdef PRINT
		cout << "Number " << i << " : " << pos << endl;
#endif
	}
	cout << res << endl;
	return 0;
