#include <bits/stdc++.h>
using i64 = long long;

template <class T = long long int>
class Bit {
    private:
    T len;
    T *arr;

    public:
    Bit(T l, T initialValue = 0) : len(l) {
        arr = new T[l+1];
        for (T i = 0; i < l + 1; i++) {
            arr[i] = initialValue;
        }
    }
    ~Bit() {
        delete[] arr;
    }
    void update(T a, T newval) {
        for (T x = a; x <= len; x += x & -x) arr[x] += newval;
    }
    T query(T a) const {
        T ret = 0;
        for (T x = a; x > 0; x -= x & -x) ret += arr[x];
        return ret;
    }
};

int main() {
    int n, m;
    const i64 mod = 1000000007;
    std::cin >> n >> m;
    std::vector<int> a(n), b(m);
    Bit<> ba(n * m), bb(n * m);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
        ba.update(a[i], 1);
    }
    for (int j = 0; j < m; j++) {
        std::cin >> b[j];
        bb.update(b[j], 1);
    }

    std::set<int> sa, sb;
    for (auto x : a) sa.insert(x);
    for (auto y : b) sb.insert(y);
    if (sa.size() != n || sb.size() != m) {
        std::cout << 0 << std::endl;
        return 0;
    }

    i64 ret = 1;
    for (int k = n * m; k > 0; k--) {
        auto ait = sa.find(k), bit = sb.find(k);
        if (ait != sa.end() && bit != sb.end()) continue;
        if (ait != sa.end()) {
            auto nb = bb.query(k - 1);
            ret = ret * (m - nb) % mod;
        } else if (bit != sb.end()) {
            auto na = ba.query(k - 1);
            ret = ret * (n - na) % mod;
        } else {
            auto na = n - ba.query(k), nb = m - bb.query(k);
            auto mm = n * m - k;
            ret = ret * (na * nb - mm) % mod;
        }
    }

    std::cout << ret << std::endl;

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int mod=998244353;
int a[1001],b[1001],inv[1001];
int aa[1001],bb[1001];
int *A=aa,*B=bb,x,y;
int cnt,n,m,ans;
void init(){
	a[0]=b[0]=1;
	a[1]=b[1]=inv[1]=1;
	for(int i=2;i<=1000;i++){
		inv[i]=1ll*(mod-mod/i)*inv[mod%i]%mod;
		a[i]=1ll*a[i-1]*i%mod;
		b[i]=1ll*b[i-1]*inv[i]%mod;
	}
}
int P(int n,int m){
	return 1ll*a[n]%mod*b[n-m]%mod;
}
int main(){
	init();
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++) scanf("%d",&aa[i]);
	for(int i=1;i<=m;i++) scanf("%d",&bb[i]);
	sort(aa+1,aa+n+1);
	sort(bb+1,bb+n+1);
	x=y=ans=1;
	while(x<=n&&y<=m){
		if(A[x]==B[y]){
			ans=1ll*ans*P(A[x]-cnt-1,n+m-x-y)%mod;
			cnt+=n+m-x-y+1;
			x++,y++;
			continue;
		}
		if(A[x]>B[y]) swap(n,m),swap(x,y),swap(A,B);
		ans=1ll*ans*(n-x+1)%mod*P(A[x]-cnt-1,n-x);
		cnt+=(n-x+1);
		x++;
	}
	printf("%d",ans);
}

