		cin >> a[i];
	}
	for (int i = 0; i < m; i++) {
		cin >> b[i];
	}
	sort(a, a + n);
	sort(b, b + m);
	long long ans = 1;
	int as = n - 1;
	int bs = m - 1;
	int ketteigyou = 0;
	int ketteiretu = 0;
	int ketteizumi = 0;
	for (int now = n*m; now >= 1; now--) {
		long long tmp = 1;
		int judge1, judge2;
		if (as < 0|| now != a[as])judge1 = 0;
		else judge1 = 1;
		if (bs < 0|| now != b[bs])judge2 = 0;
		else judge2 = 1;
		if ((!judge1) && (!judge2)) {
			tmp = ketteigyou*ketteiretu - (n*m - now);
		}
		if (judge1&&judge2) {
			tmp = 1;
			as -= 1;
			bs -= 1;
			ketteigyou += 1;
			ketteiretu += 1;
		}
		if (judge1&&(!judge2)) {
			tmp =ketteiretu;
			as -= 1;
			ketteigyou += 1;
		}
		if ((!judge1)&&judge2) {
			tmp = ketteigyou;
			bs -= 1;
			ketteiretu += 1;
		}
		if (tmp <= 0) { ans = 0; break; }
		else {
			tmp %= mod;
			ans *= tmp;
			ans %= mod;
		}
	}
