const int nmax = 1e9 + 7;
const long long INF = 1e18;
const double PI = 2 * asin(1);
typedef long long ll;

int main(){
  ll N, M; cin >> N >> M;

  vector <ll> A(N), B(M);
  for (int i = 0; i < N; i++) cin >> A[i];
  for (int i = 0; i < M; i++) cin >> B[i];
  sort(A.begin(), A.end(), greater<ll>());
  sort(B.begin(), B.end(), greater<ll>());

  ll ans = 1;
  for (int i = 0; i < N - 1; i++){
    if (A[i] == A[i + 1]) ans = 0;
  }
  for (int i = 0; i < M - 1; i++){
    if (B[i] == B[i + 1]) ans = 0;
  }

  ll I = 0, J = 0;
  for (ll now = N * M; now >= 1; now--){
    bool flagi = false, flagj = false;

    for (int i = I; i < N; i++){
      if(A[i] > now){
        I++;
      }else if (A[i] == now){
        I++; flagi = true;
      }else{
        break;
      }
    }

    for (int j = J; j < M; j++){
      if (B[j] > now){
        J++;
      }else if(B[j] == now){
        J++; flagj = true;
      }else break;
    }

    if (flagi == true && flagj == true){
      ans *= 1;
    }else if(flagi == true){
      ans *= J;
    }else if(flagj == true){
      ans *= I;
    }else{
      ans *= I * J - ((N * M) - now);
    }
    ans %= nmax;
  }

  cout << ans << endl;
  return 0;
}

