int n, m;
vector<int> a, b;
map<int, int> row, column;
vector<int> accRow, accColumn;
map<int, int> both;
vector<int> accBoth;

int main() {
	std::ios::sync_with_stdio(false);

	in(n, m);
	inr(a, n);
	inr(b, m);

	bool fail = false;
	for (int y = 0; y < n; ++y) {
		if (row[a[y]] > 0) {
			fail = true;
		}
		row[a[y]]++;
	}
	for (int x = 0; x < m; ++x) {
		if (column[b[x]] > 0) {
			fail = true;
		}
		column[b[x]]++;
	}
	if (fail) {
		out(0);
		getchar();
		return 0;
	}

	for (int y = 0; y < n; ++y) {
		for (int x = 0; x < m; ++x) {
			both[min(a[y], b[x])]++;
		}
	}

	accRow.resize(n * m + 1);
	accColumn.resize(n * m + 1);
	accBoth.resize(n * m + 1);

	accRow[n * m] = row[n * m];
	accColumn[n * m] = column[n * m];
	accBoth[n * m] = both[n * m];
	for (int i = 1; i < n * m; ++i) {
		int v = n * m - i;
		accRow[v] = accRow[v + 1] + row[v];
		accColumn[v] = accColumn[v + 1] + column[v];
		accBoth[v] = accBoth[v + 1] + both[v];
	}

	ll ans = 1;
	for (int v = 1; v <= n * m; ++v) {
		ll value = 0;
		if (row[v] > 0 && column[v] > 0) {
			value = 1;
		} else if (row[v] > 0) {
			value = accColumn[v];
		} else if (column[v] > 0) {
			value = accRow[v];
		} else {
			value = accBoth[v];
			value -= n * m - v;
		}
		ans = mod_mul(ans, value, V_MOD);
	}

	out(ans);

	getchar();
}

