int mod=1000000007;
int mod_adjust(int a){
    if(a > mod){
        a %= mod;
        return a;
    }
    if(a < 0){
        a *= -1;
        a %= mod;
        a = mod - a;
    }
    return a;
}
int mod_add(int a,int b){
    a = mod_adjust(a);
    b = mod_adjust(b);
    long long k = a%mod; k += b%mod; k %= mod;
    return (int)k;
}
int mod_sub(int a,int b){
    int k = mod_adjust(a); k += mod_adjust(b); k %= mod;
    return k;
}
int mod_multi(int a,int b){
    long long k = (long long)mod_adjust(a); k *= (long long)mod_adjust(b); k %= mod;
    return (int)k;
}
int mod_div(int a,int b){
    a = mod_adjust(a);
    b = mod_adjust(b);

    int X=mod,Y=b,X1=1,X2=0,Y1=0,Y2=1;
    while(1){
        int q=X/Y;
        int r=X-Y*q;
        X1=mod_sub(X1,mod_multi(q,Y1));
        X2=mod_sub(X2,mod_multi(q,Y2));

        if(a%r==0){
            int k=a/r;
            return mod_multi(X2,k);
        }

        int z;
        z=X1;X1=Y1;Y1=z;
        z=X2;X2=Y2;Y2=z;
        X=Y;Y=r;
    }
}
int mod_pow(int x,int n){
    if(n<0){
        return mod_pow(mod_div(1,x),-n);
    }
    if(n==0){
        return 1;
    }
    if(n==1){
        return x;
    }
    if(n%2==0){
        int k = mod_pow(x,n/2);
        return mod_multi(k,k);
    }
    else{
        int k = mod_pow(x,n/2);
        return mod_multi(mod_multi(k,k),x);
    }
}
int mod_combination(int n,int r){
    int a=1, b=1;
    FOR(i,r){
        a=mod_multi(a,n-i);
        b=mod_multi(b,i+1);
    }
    return mod_div(a,b);
}

