template <typename D, typename T = i64>
class SegTree {
public:
    i64 n;
    vector<T> t;

private:
    void build(const i64* a, int v, int tl, int tr) {
        if (tl == tr)
            t[v] = a[tl];
        else {
            int tm = (tl + tr) / 2;
            build(a, v * 2, tl, tm);
            build(a, v * 2 + 1, tm + 1, tr);
            t[v] = D().op(t[v * 2], t[v * 2 + 1]);
        }
    }

    i64 get(int v, int tl, int tr, int l, int r) {
        if (l > r) {
            return D().def();
        }
        if (l == tl && r == tr) {
            return t[v];
        }
        int tm = (tl + tr) / 2;
        return D().op(get(v * 2, tl, tm, l, min(r, tm)),
            get(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r));
    }

    void update(int v, int tl, int tr, int pos, int new_val) {
        if (tl == tr) {
            t[v] = new_val;
        }
        else {
            int tm = (tl + tr) / 2;
            if (pos <= tm) {
                update(v * 2, tl, tm, pos, new_val);
            }
            else {
                update(v * 2 + 1, tm + 1, tr, pos, new_val);
            }
            t[v] = D().op(t[v * 2] + t[v * 2 + 1]);
        }
    }

public:
    void build(const vector<i64 >& a) {
        n = a.size();
        t.resize(n * 4);
        build(a.data(), 1, 0, n - 1);
    }

    void build(i64* a, i64 n) {
        this->n = n;
        t.resize(n * 4);
        build(a, 1, 0, n - 1);
    }

    i64 get(i64 l, i64 r) {
        return get(1, 0, n - 1, l, r);
    }

    void update(i64 pos, i64 new_val) {
        update(1, 0, n - 1, pos, new_val);
    }
};


