namespace solution {

    const int N = 1e6 + 100;
    ll fact[N];
    ll inv[N];
    const ll M = 1e9 + 7;

    inline ll pw(ll a, ll p) {
        ll ret = 1;
        while (p) {
            if (p & 1) ret = (ret * a) % M;
            a = (a * a) % M;
            p >>= 1;
        }
        return ret;
    }

    inline ll nCr(int n, int k) {
        if (n < k) return 0;
        return fact[n] * inv[k] % M * inv[n - k] % M;
    }

    void init() {

        fact[0] = inv[0] = 1;
        for (int i = 1; i < N; ++i) {
            fact[i] = fact[i - 1] * i % M;
            inv[i] = pw(fact[i], M - 2);
        }


    }


    ll solve(vl a, vl b) {
        int n = a.size(), m = b.size();
        sort(ALL(a)), sort(ALL(b));
        a.resize(unique(ALL(a)) - a.begin());
        b.resize(unique(ALL(b)) - b.begin());
        if (a.size() != n || b.size() != m) return 0;
        vector<char> useda(n, 0), usedb(m, 0);
        vector<triple(int)> sorted;

        vector<vector<char>> noneed(n, vector<char> (m, 0));
        fori (i, n) {
            fori (j, m) {
                if (a[i] == b[j]) {
                    useda[i] = 1;
                    usedb[j] = 1;
                    noneed[i][j] = 1;
                }
                sorted.push_back(make_tuple(min(a[i], b[j]),  i, j));
            }
        }

        vector<vector<int>> calc(n, vector<int> (m , 0));

        sort(ALL(sorted));
        fori (i, sorted.size()) {
            int ii, jj, val;
            tie(val, ii, jj) = sorted[i];
            calc[ii][jj] = val - i;
        }

//        watch(calc);

        ll ans = 1;
        for (int i = 0; i < n; ++i) if (!useda[i]) {
                ll f = 1, s = 1;
                for (int j = 0; j < m; ++j) if (b[j] >= a[i]) {
                        ll nn = calc[i][j];
                        f = f * nn % M;
                        s = s * (nn - 1) % M;
                        noneed[i][j] = 1;
                    }
                ans = ans * (f - s + M) % M;
            }
        for (int j = 0; j < m; ++j) if (!usedb[j]){
                ll f = 1, s = 1;
                for (int i = 0; i < n; ++i) if (a[i] > b[j]) {
                        ll nn = calc[i][j];
                        f = f * nn % M;
                        s = s * (nn - 1) % M;
                        noneed[i][j] = 1;
                    }
                ans = ans * (f - s + M) % M;
            }
//        fori (i, n) {
//            fori (j, m) cout << bool(noneed[i][j]) << " ";
//            cout << endl;
//        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) if (!noneed[i][j]) {
                    ll mn = min(a[i], b[j]);
                    ll cur;
                    if (mn == a[i] && useda[i] || mn == b[i] && usedb[i]) {
                        cur = calc[i][j];
                    } else {
                        cur = calc[i][j];
                    }
                    ans = ans * cur % M;
                }
        }
        return ans;
    }


    void presolve() {
        int n, m;
        cin >> n >> m;
        vl a(n), b(m);
        fori (i, n) cin >> a[i];
        fori (i, m) cin >> b[i];
        cout << solve(a, b);
    }
}

