int main() {
	int n = ri(), m = ri();
	vi a(n); FOR(i,n) a[i] = ri(); sort(all(a));
	vi b(m); FOR(i,m) b[i] = ri(); sort(all(b));
	FOR(i,n-1) if (a[i] == a[i+1]) { cout << 0 << endl; return 0; }
	FOR(i,m-1) if (b[i] == b[i+1]) { cout << 0 << endl; return 0; }
	if (a[n-1] != n*m || b[m-1] != n*m) { cout << 0 << endl; return 0; }
	MComb com(n*m+1);
	set<int> al;
	FOR(i,n) al.insert(a[i]);
	FOR(i,m) al.insert(b[i]);
	vector<pair<int,int> > ranges;
	int last = 0;
	for (auto i : al) {
		if (i && last+1 <= i-1) {
			ranges.push_back({last+1, i-1});
		}
		ranges.push_back({i,i});
		last = i;
	}
	int used = 0;
	mint res = 1;
	DOWN(j,ranges.size()) {
		auto i = ranges[j];
		if (i.fi != i.se || !al.count(i.fi)) { // interval
			// i.se+1以上
			auto x = lower_bound(all(a),i.se+1);
			auto y = lower_bound(all(b),i.se+1);
			if (x == a.end() || y == b.end()) {
				cout << 0 << endl;
				return 0;
			}
			int xx = a.end()-x;
			int yy = b.end()-y;
			int num = i.se-i.fi+1;
			if (xx*yy < num+used) {
				cout << 0 << endl;
				return 0;
			}
			res *= com.npr(xx*yy-used, num);
			used += num;
			////////////////////////////////
		} else {
			auto x = lower_bound(all(a),i.fi);
			auto y = lower_bound(all(b),i.fi);
			if (x == a.end() || y == b.end()) {
				cout << 0 << endl;
				return 0;
			}
			int xx = a.end()-x;
			int yy = b.end()-y;
			if (*x == i.fi && *y == i.se) {
				if (xx*yy <= used) {
					cout << 0 << endl;
					return 0;
				}
				used++;
			} else {
				if (*x == i.fi) {
					res *= yy;
				} else res *= xx;
				used++;
			}
		}
	}
	cout << res << endl;
    return 0;
}

