int n, m, ans = 1, ar[2][N], mark[N * N];

int32_t main() {
	cin >> n >> m;
	for (int j = 0; j < n; j++) {
			cin >> ar[0][j];
			if (ar[0][j] > n * m || mark[ar[0][j]])
				return cout << 0, 0;
			mark[ar[0][j]] = 1;
	}

	memset(mark, 0, sizeof mark);
	for (int i = 0; i < m; i++) {
		cin >> ar[1][i];
		if (ar[1][i] > n * m || mark[ar[1][i]])
			return cout << 0, 0;
		mark[ar[1][i]] = 1;
	}

	sort(ar[0], ar[0] + n, [&] (int a, int b) { return a > b; });
	sort(ar[1], ar[1] + m, [&] (int a, int b) { return a > b; });

	int l = 0, r = 0;
	for (int i = m * n; i; i--) {
		while (l < n && ar[0][l] >= i)
			l++;
		while (r < m && ar[1][r] >= i)
			r++;
		if (!l || !r)
			return cout << 0, 0;
