		if (ar[0][l - 1] == i && ar[1][r - 1] == i);
		else if (ar[0][l - 1] == i)
			ans = (ans * r) % mod;
		else if (ar[1][r - 1] == i)
			ans = (ans * l) % mod;
		else
			ans = (ans * (l * r - (m * n - i))) % mod;
	}
	cout << ans;
}

