#include <stdio.h>
#include <stdlib.h>

long long permutation(int n, int k)
{
    long long result;

    result = 1;
    if (n < k) {printf("Error: perm (%d, %d)\n", n, k);exit(1);}
    while(k > 0) {
        result *= n;
        n--; k--;
        result %= 1000000007;
    }
    return result;
}

int qsort_int(const void *a, const void *b)
{
    return *(int *)a - *(int *)b;
}

int solve(int n, int m, int a[], int b[])
{
    int i;
    int row, col; //残りの行数，列数
    int count;
    int inc;
    int a_ptr, b_ptr;
    long long ans;

    // 重複チェック
    for (i = 1; i < n; i++) {
        if (a[i - 1] == a[i]) {return 0;}
    }
    for (i = 1; i < m; i++) {
        if (b[i - 1] == b[i]) {return 0;}
    }

    a_ptr = 0; b_ptr = 0;
    row = n; col = m;
    ans = 1;
    count = 0;

    while(1) {
        if (a_ptr >= n || b_ptr >= m) {break;}

        if (a[a_ptr] == b[b_ptr]) {
            inc = row + col - 1;
            if (a[a_ptr] < count + inc) {return 0;}
            ans *= permutation(a[a_ptr] - count - 1, inc - 1);
            count += inc;
            row--; col--;
            a_ptr++; b_ptr++;
        } else if (a[a_ptr] < b[b_ptr]) {
            inc = col;
            if (a[a_ptr] < count + inc) {return 0;}
            ans *= permutation(a[a_ptr] - count - 1, inc - 1);
            ans %= 1000000007;
            ans *= inc;
            count += inc;
            row--;
            a_ptr++;
        } else { //b[b_ptr] < a[a_ptr]
            inc = row;
            if (b[b_ptr] < count + inc) {return 0;}
            ans *= permutation(b[b_ptr] - count - 1, inc - 1);
            ans %= 1000000007;
            ans *= inc;
            count += inc;
            col--;
            b_ptr++;
        }

        ans %= 1000000007;
    }

    return (int) ans;
}

