char checkBoard(int n,int m,long a[],long b[],long board[])
{
	int i,j;
	char res;

	for (i=0;i<n;i++) {
		res = 0;
		for (j=0;j<m;j++) {
			if (board[i+n*j] == a[i]) {
				res = 1;
				break;
			}

		}
		if (res == 0) return 0;
	}

	for (j=0;j<m;j++) {
		res = 0;
		for (i=0;i<n;i++) {
			if (board[i+n*j] == b[j]) {
				res = 1;
				break;
			}

		}
		if (res == 0) return 0;
	}
	return 1;
}

long long landing(int n,int m,long a[],long b[],long board[],long now,long long res)
{
	int i,j;
	now++;
	if (now > n*m) {
		if (checkBoard(n,m,a,b,board)==0) return 0;
		return 1;
	}

	for (i=0;i<n;i++) {
		if (now > a[i]) continue;

		for (j=0;j<m;j++) {
			if (board[i+n*j] == -1) {

				if (now > b[j]) {
					continue;
				}

				board[i+n*j] = now;
				res += landing(n,m,a,b,board,now,0);
				board[i+n*j] = -1;
			}
		}
	}
	return res;
}

