	qsort(pipArray, piACnt, sizeof(int), fSortFncId);

	// 重複カット
	int liACnt = piACnt;
	fCutDpl(pipArray, &liACnt);
	if (liACnt != piACnt) {
		return -1;
	}

	// 番兵
	pipArray[piACnt] = 0;

	return 0;
}

// 実行メイン
int
fMain(
)
{
	int i, liRet;
	char lc1Buf[1024];

	// 行数・列数 - 取得
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
	sscanf(lc1Buf, "%d%d", &siRCnt, &siCCnt);
	int liMCnt = siRCnt * siCCnt;

	// 行内最大値 - 取得
	liRet = fGetData(si1RMax, siRCnt);
	if (liRet != 0) {
		return 0;
	}

	// 列内最大値 - 取得
	liRet = fGetData(si1CMax, siCCnt);
	if (liRet != 0) {
		return 0;
	}

	// パターン数 - 取得
	int liPCnt = 1;
	int liRNo = 0;
	int liCNo = 0;
	for (i = liMCnt; i >= 1; i--) {
		if (si1RMax[liRNo] == i) {
			liRNo++;

			// マス確定
			if (si1CMax[liCNo] == i) {
				liCNo++;
			}

			// 新行内
			else {
				liPCnt = fGetModMulti(liPCnt, liCNo);
			}
		}
		else {

			// 新列内
			if (si1CMax[liCNo] == i) {
				liCNo++;
				liPCnt = fGetModMulti(liPCnt, liRNo);
			}

			// 既存行列内
			else {
				int liVal = liCNo * liRNo - liMCnt + i;
				liPCnt = fGetModMulti(liPCnt, liVal);
			}
		}
	}

	return liPCnt;
}

