typedef int32_t i32;
typedef int64_t i64;

int cmp (const void *a, const void *b) {
  i32 d = *(i32 *)a - *(i32 *)b;
  return d == 0 ? 0 : d < 0 ? 1 : -1;
}

int cond (i32 *a, i32 n) {
  qsort (a, n, sizeof (i32), cmp);
  for (i32 i = 0; i < n - 1; ++i) {
    if (a[i] == a[i + 1]) {
      return 0;
    }
  }
  return 1;
}

void run (void) {
  i32 n, m;
  scanf ("%" SCNi32 "%" SCNi32, &n, &m);
  i32 *a = (i32 *) calloc (n + 1, sizeof (i32));
  i32 *b = (i32 *) calloc (m + 1, sizeof (i32));
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, a + i);
  }
  a[n] = 0;
  for (i32 i = 0; i < m; ++i){
    scanf ("%" SCNi32, b + i);
  }
  b[m] = 0;
  if (!(cond (a, n) && cond (b, m))) {
    puts("0");
    return;
  }
  const i32 mod = 1000000007;
  i32 ans = 1;
  for (i32 i = n * m, x = 0, y = 0; i >= 1; --i) {
    if (a[x] == i && b[y] == i) {
      x++;
      y++;
    } else if (a[x] == i) {
      ans = (i64) ans * y % mod;
      x++;
    } else if (b[y] == i) {
      ans = (i64) ans * x % mod;
      y++;
    } else {
      ans = (i64) ans * (x * y - (n * m - i)) % mod;
    }
  }
  printf ("%" PRIi32 "\n", ans);
}

int main (void) {
  run();
  return 0;
}

