	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt(), m = in.nextInt();
			int[] a = in.nextIntArray(n);
			int[] b = in.nextIntArray(m);
			long[] ax = new long[m * n + 1];
			long[] bx = new long[m * n + 1];
			for (int i : a) ax[i]++;
			for (int i : b) bx[i]++;
			if (ng(ax) || ng(bx)) {
				out.println(0);
				return;
			}

			long[] asum = ax.clone();
			long[] bsum = bx.clone();
			Arrays.parallelPrefix(asum, Math::addExact);
			Arrays.parallelPrefix(bsum, Math::addExact);

			long ans = 1;
			for (int i = n * m, cnt = 0; i >= 1; i--, cnt++) {
				if (ax[i] == 1 && bx[i] == 1) {
					ans *= 1;
				} else if (ax[i] == 1 && bx[i] == 0) {
					ans *= bsum[n * m] - bsum[i - 1];
					ans %= MOD;
				} else if (ax[i] == 0 && bx[i] == 1) {
					ans *= asum[n * m] - asum[i - 1];
					ans %= MOD;
				} else if (ax[i] == 0 && bx[i] == 0) {
					ans *= (asum[n * m] - asum[i - 1]) * (bsum[n * m] - bsum[i - 1]) - cnt;
					ans %= MOD;
				}
 			}

			out.println(ans);
		}

		boolean ng(long[] a) {
			for (long l : a) {
				if (l > 1) return true;
			}
			return false;
		}
	}

	public static int lowerBound(int[] a, int obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (obj <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public char nextChar() {
			while (true) {
				final int c = read();
				if (!isSpace[c]) {
					return (char) c;
				}
			}
		}

		public String nextString() {
			return new String(nextChars());
		}

		public char[] nextChars() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			return Arrays.copyOf(str, len);
		}

		int reads(int len, boolean[] accept) {
			try {
				while (true) {
					final int c = read();
					if (accept[c]) {
						break;
					}
					if (str.length == len) {
						char[] rep = new char[str.length * 3 / 2];
						System.arraycopy(str, 0, rep, 0, str.length);
						str = rep;
					}
					str[len++] = (char) c;
				}
			} catch (MyInput.EndOfFileRuntimeException e) {
			}
			return len;
		}

