public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    void solve(){
        int n = ni();
        int m = ni();
        int[] a = new int[n];
        int[] b = new int[m];
        int[] a2 = new int[n];
        int[] b2 = new int[m];
        for(int i = 0; i < n; i++){
            a[i] = ni();
            a2[i] = a[i];
        }
        for(int i = 0; i < m; i++){
            b[i] = ni();
            b2[i] = b[i];
        }
        Arrays.sort(a2);
        Arrays.sort(b2);
        int[][] res = new int[n+m][2];
        for(int i = 0; i < n; i++){
            res[i][0] = a[i];
            res[i][1] = 0;
        }
        for(int i = 0; i < m; i++){
            res[i+n][0] = b[i];
            res[i+n][1] = 1;
        }
        Arrays.sort(res, (c,d) -> d[0]-c[0]);
        long ans = 1;
        int[][] board = new int[n][m];
        for(int i = n*m; i >= 1; i--){
            long tmp = 0;
            boolean f = false;
            int l = -1;
            int r = -1;
            for(int j = 0; j < n; j++){
                if(a[j]==i){
                    l = j;
                    break;
                }
            }
            for(int j = 0; j < m; j++){
                if(b[j]==i){
                    r = j;
                    break;
                }
            }
            if(l!=-1&&r!=-1){
                if(board[l][r]!=0){
                    out.println(0);
                    return;
                }
                board[l][r] = i;
                tmp++;
            }
            else if(l!=-1){
                for(int j = 0; j < m; j++){
                    if(b[j]>=i&&board[l][j]==0){
                        if(!f){
                            board[l][j] = i;
                            f = true;
                        }
                        tmp++;
                    }
                }
            }
            else if(r!=-1){
                for(int j = 0; j < n; j++){
                    if(a[j]>=i&&board[j][r]==0){
                        if(!f){
                            board[j][r] = i;
                            f = true;
                        }
                        tmp++;
                    }
                }
            }
            else{
                long ll = n - lowerBound(a2, i);
                long rr = m - lowerBound(b2, i);
                // out.println(ll+" "+rr);
                // out.println(i+" "+a[lowerBound(a,i)]);
                tmp = ll*rr-(n*m-i);
            }
            ans *= tmp;
            ans %= mod;
        }

        for(int i = 0; i < n; i++){
            long m1 = 0;
            for(int j = 0; j < m; j++){
                m1 = Math.max(m1, board[i][j]);
            }
            if(m1!=a[i]){
                out.println(0);
                return;
            }
        }
        for(int j = 0; j < m; j++){
            long m1 = 0;
            for(int i = 0; i < n; i++){
                m1 = Math.max(m1, board[i][j]);
            }
            if(m1!=b[j]){
                out.println(0);
                return;
            }
        }
        out.println(ans);
    }

    public static int lowerBound(int[] a, int v){ return lowerBound(a, 0, a.length, v); }
    public static int lowerBound(int[] a, int l, int r, int v)
    {
        if(l > r || l < 0 || r > a.length)throw new IllegalArgumentException();
        int low = l-1, high = r;
        while(high-low > 1){
            int h = high+low>>>1;
            if(a[h] < v){
                low = h;
            }else{
                high = h;
            }
        }
        return high;
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

