            a[i] = sc.nextInt();
            if(a[i] < min) min = a[i];
            if(c[a[i]-1][0] != -1){
                valid = false;
                break;
            }else c[a[i]-1][0] = i;
        }
        for(int i = 0; i < M; i++) {
            b[i] = sc.nextInt();
