            maxr[ri[n * m]] = n * m;
            maxc[ci[n * m]] = n * m;


            long[] b = new long[n * m + 2];
            b[n * m] = 1;

            int rr = 1;
            int cr = 1;

            for (int i = n * m - 1; i > 0; i--) {
                if (ri[i] == -1 && ci[i] == -1) {

                } else if (ri[i] != -1 && ci[i] != -1) {
                    b[i] = 1;
                    if (maxr[ri[i]] > i || maxc[ci[i]] > i) {
                        out.println(0);
