    public void solve() {
        int N = in.nextInt();
        int M = in.nextInt();
        int[] A = in.nextIntArray(N);
        int[] B = in.nextIntArray(M);
        HashSet<Integer> aHash = new HashSet<>();
        HashSet<Integer> bHash = new HashSet<>();
        for (int i = 0; i < N; i++) {
            if (aHash.contains(A[i])) {
                System.out.println("0");
                return;
            }
            aHash.add(A[i]);
        }
        for (int j = 0; j < M; j++) {
            if (bHash.contains(B[j])) {
                System.out.println("0");
                return;
            }
            bHash.add(B[j]);
        }
        if (N == 1 && M == 1) {
            System.out.println("1");
            return;
        }

        Pair[] ps = new Pair[N+M];
        for (int i = 0; i < N; i++) {
            ps[i] = new Pair(A[i], 0);
        }
        for (int i = 0; i < M; i++) {
            ps[i+N] = new Pair(B[i], 1);
        }
        Arrays.sort(ps, (p1, p2) -> Integer.compare(p2.v, p1.v));

        if (ps[0].v != ps[1].v) {
            System.out.println("0");
            return;
        }
        long res = 1;
        long rCnt = 1, cCnt = 1;
        int cellCnt = 1;
        for (int i = 2; i < N + M; i++, cellCnt++) {
            if (ps[i-1].v != ps[i].v + 1) {
                for (int j = ps[i - 1].v - 1; j > ps[i].v; j--) {
                    if (rCnt * cCnt == cellCnt) {
                        System.out.println("0");
                        return;
                    }
                    res = MULT(res, rCnt * cCnt - cellCnt);
                    cellCnt++;
                }
            }

            if (i < N + M - 1 && ps[i].v == ps[i+1].v) {
                if (ps[i].t == ps[i+1].t) {
                    throw new RuntimeException();
                }
                rCnt++;
                cCnt++;
                i++;
            } else {
                if (ps[i].t == 0) {
                    res = MULT(res, rCnt);
                    cCnt++;
                } else {
                    res = MULT(res, cCnt);
                    rCnt++;
                }
            }
        }
        long fact = 1;
        for (int i = 2; i <= ps[ps.length-1].v - 1; i++) {
            fact = MULT(fact, i);
        }
        res = MULT(res, fact);
        System.out.println(res);
    }

    long MULT(long a, long b) {
        long res = ((a % MOD) * (b % MOD)) % MOD;
        return res;
    }
