		for (int i = 0; i < a.length; i++) {
			long th = 0;
			if (na[a[i]] == 2) {
				continue;
			}
			for (int j = 0; j < b.length; j++) {
				if (b[j] > a[i]) {
					th++;
				}
			}
			ans *= th;
			ans %= mod;
