		for (int i = 0; i < b.length; i++) {
			long th = 0;
			if (na[b[i]] == 2) {
				continue;
			}
			for (int j = 0; j < a.length; j++) {
				if (b[i] < a[j]) {
					th++;
				}
			}
			ans *= th;
			ans %= mod;
		}
		int c = 0;
		int d = 0;
		for (int i = n * m; i > 0; i--) {
			if (na[i] > 0) {
				c++;
			}
			if (nb[i] > 0) {
				d++;
			}
			if (na[i] == 0 && nb[i] == 0) {
				int mult = c * d - n * m + i;
				if (mult <= 0) {
					out.println(0);
					return;
				}
				ans *= mult;
				ans %= mod;
			}
		}
		out.println(ans);
	}

