    int m = ni();

    int[] a = na(n);
    int[] b = na(m);

    Arrays.sort(a);
    Arrays.sort(b);

    for (int i = 1; i < n; i ++) {
      if (a[i] == a[i - 1]) {
        System.out.println(0);
        return;
      }
    }
    for (int i = 1; i < m; i ++) {
      if (b[i] == b[i - 1]) {
        System.out.println(0);
        return;
      }
    }

    int mod = 1000000000 + 7;
    int cnt = 0;
    long ret = 1;
   for (int i = n * m; i >= 1; i--) {
      int ai = lowerBound(a, i);
      int bi = lowerBound(b, i);

      int x = n - ai;
      int y = m - bi;
      long last = (long)x * y;

      if (ai == n || bi == m || last < cnt) {
        System.out.println(0);
        return;
      }

      if (a[ai] == i && b[bi] == i) {
      } else if (a[ai] == i) {
        ret *= y;
      } else if (b[bi] == i) {
        ret *= x;
      } else {
        ret *= last - cnt;
      }
      ret %= mod;
      cnt ++;
    }
    System.out.println(ret);
  }

  public static int lowerBound(int[] a, int v) {
    int low = -1, high = a.length;
    while (high - low > 1) {
      int h = high + low >>> 1;
      if (a[h] >= v) {
        high = h;
      } else {
        low = h;
      }
    }
    return high;
  }

