					if((m-1-q) * (n-1-p) >= (n*m-i+1)){
						ans = ans * ((m-1-q) * (n-1-p) - (n*m-i+1) + 1) % mod;
					}else{
						out.println(0);
						return;
					}
				}
			}
		}
		out.println(ans);
	}

