import java.util.function.LongUnaryOperator;

class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] row = new int[n * m];
        int[] col = new int[n * m];
        Arrays.fill(row, -1);
        Arrays.fill(col, -1);
        for (int i = 0; i < n; i++) {
            int a = in.nextInt() - 1;
            if (row[a] != -1) {
                out.println(0);
                return;
            }
            row[a] = i;
        }
        for (int i = 0; i < m; i++) {
            int b = in.nextInt() - 1;
            if (col[b] != -1) {
                out.println(0);
                return;
            }
            col[b] = i;
        }
        int cr = 0, cc = 0, cu = 0;
        long ans = 1;
        for (int i = n * m - 1; i >= 0; i--) {
            if (row[i] != -1 && col[i] != -1) {
                cr++;
                cc++;
            } else if (row[i] != -1) {
                cr++;
                ans = ans * cc % mod;
            } else if (col[i] != -1) {
                cc++;
                ans = ans * cr % mod;
            } else {
                ans = ans * (cr * cc % mod + mod - cu) % mod;
            }
            cu++;
        }
        out.println(ans);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

