import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int N, M;
    static int[] A;
    static int[] B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        A = sc.nextIntArray(N);
        B = sc.nextIntArray(M);

        System.out.println(solve());
    }

    static int MOD = 1_000_000_007;

    static long solve() {
        int[] C = new int[N*M+1]; // 番兵+1
        boolean[] fix = new boolean[N*M+1];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int a = A[i];
                int b = B[j];
                int idx = i * M + j;
                C[idx] = Math.min(a, b);

                if( a == b ) {
                    if( fix[a] ) {
                        // debug("fix dupe");
                        return 0;

                    } else {
                        fix[a] = true;
                    }
                }
            }
        }
        C[N*M] = Integer.MAX_VALUE; // 番兵
        Arrays.sort(C);

        // debug(C);

        FermatCombination fc = new FermatCombination(N*M+10, MOD);

        int ans = 1;
        int cur = C[0];
        int num = 1;
        for (int i = 1; i <= N*M; i++) {
            if( C[i] == cur ) {
                num++;

            } else {
                // 2 2 4 4 4 のようなケース
                if( cur < i ) {
                    // debug("out of idx", cur, i);
                    return 0;
                }

                int used = i - num;
                int available = cur - used;

                // 一つ数値固定するので1ずつ減らす
                int c = fc.comb(available-1, num-1);
                int fa = fc.factorial[num-1];

                // fixの場合は1固定
                int fi = fix[cur] ? 1 : num;

                ans = fc.mul(fc.mul(fc.mul(c, fa), fi), ans);

                // debug(cur, num, available, c, fi, fix[cur], fc.mul(fc.mul(c, fa), fi));

                cur = C[i];
                num = 1;
            }
        }

        return ans;
    }

    static class FermatCombination {

        private final int size;
        private final int mod;
        private final int[] factorial; // n -> factorial(n)
        private final int[] inverse;   // n -> inverse(factorial(n))

        FermatCombination(int size, int mod) {
            this.mod = mod;
            this.size = size;
            factorial = new int[size + 1];
            inverse = new int[size + 1];

            init();
        }

        private void init() {
            factorial[0] = 1;
            factorial[1] = 1;
            inverse[0] = 1;
            inverse[1] = 1;
            for (int i = 2; i <= size; i++) {
                factorial[i] = mul(factorial[i-1], i);
                inverse[i] = pow(factorial[i], mod - 2);
            }
        }

        private int pow(int base, int exp) {
            if( exp == 0 ) return 1;

            int ans = 1;
            base %= mod;
            while( exp > 0 ) {
                if( (exp & 1) == 1 ) {
                    ans = mul(ans, base);
                }

                base = mul(base, base);
                exp = exp >> 1;
            }
            return ans;
        }

        private int mul(int a, int b) {
            return (int)((long)a * b % mod);
        }

        int comb(int n, int k) {
            if( n > size ) throw new RuntimeException("wtf : size=" + size + " n=" + n);
            return mul(mul(factorial[n], inverse[k]), inverse[n - k]);
        }

        // 重複組み合わせ
        // k種類からn個選ぶ場合の数
        int hcomb(int k, int n) {
            return comb(k+n-1, n);
        }

        int group(int n, int g, int k) {
            // C(n, g) * C(n-g, g)... / k!
            // n! / (n-gk)! / g! ^ k / k!
            int ret = factorial[n];             // n!
            ret = mul(ret, inverse[n - g*k]);   // 1 / (n-gk)!
            ret = mul(ret, pow(inverse[g], k)); // 1 / (g! ^ k)
            ret = mul(ret, inverse[k]);         // 1 / k!
            return ret;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
