public class Main {

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt(), m = in.nextInt();
			int[] a = in.nextIntArray(n);
			int[] b = in.nextIntArray(m);
			long[] ax = new long[m * n + 1];
			long[] bx = new long[m * n + 1];
			for (int i : a) ax[i]++;
			for (int i : b) bx[i]++;
			if (ng(ax) || ng(bx)) {
				out.println(0);
				return;
			}

			long[] asum = ax.clone();
			long[] bsum = bx.clone();
			Arrays.parallelPrefix(asum, Math::addExact);
			Arrays.parallelPrefix(bsum, Math::addExact);

			long ans = 1;
			for (int i = n * m, cnt = 0; i >= 1; i--, cnt++) {
				if (ax[i] == 1 && bx[i] == 1) {
					ans *= 1;
				} else if (ax[i] == 1 && bx[i] == 0) {
					ans *= bsum[n * m] - bsum[i - 1];
					ans %= MOD;
				} else if (ax[i] == 0 && bx[i] == 1) {
					ans *= asum[n * m] - asum[i - 1];
					ans %= MOD;
				} else if (ax[i] == 0 && bx[i] == 0) {
					ans *= (asum[n * m] - asum[i - 1]) * (bsum[n * m] - bsum[i - 1]) - cnt;
					ans %= MOD;
				}
 			}

			out.println(ans);
		}

		boolean ng(long[] a) {
			for (long l : a) {
				if (l > 1) return false;
			}
			return true;
		}
	}

	public static int lowerBound(int[] a, int obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (obj <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public char nextChar() {
			while (true) {
				final int c = read();
				if (!isSpace[c]) {
					return (char) c;
				}
			}
		}

		public String nextString() {
			return new String(nextChars());
		}

		public char[] nextChars() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			return Arrays.copyOf(str, len);
		}

		int reads(int len, boolean[] accept) {
			try {
				while (true) {
					final int c = read();
					if (accept[c]) {
						break;
					}
					if (str.length == len) {
						char[] rep = new char[str.length * 3 / 2];
						System.arraycopy(str, 0, rep, 0, str.length);
						str = rep;
					}
					str[len++] = (char) c;
				}
			} catch (MyInput.EndOfFileRuntimeException e) {
			}
			return len;
		}

		public int[] nextIntArray(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArray1Index(final int n) {
			final int[] res = new int[n + 1];
			for (int i = 1; i < n + 1; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArrayDec(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt() - 1;
			}
			return res;
		}

		public long[] nextLongArray(final int n) {
			final long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public long[] nextLongArray1Index(final int n) {
			final long[] res = new long[n + 1];
			for (int i = 1; i < n + 1; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public long[] nextLongArrayDec(final int n) {
			final long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong() - 1;
			}
			return res;
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public double[] nextDoubleArray(int n) {
			double[] res = new double[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextDouble();
			}
			return res;
		}

		static class EndOfFileRuntimeException extends RuntimeException {
		}

	}

}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		int[] array = new int[n*m+1];
		boolean[] fixed = new boolean[n*m+1];
		int[] a = new int[n];
		for(int i=0;i<n;i++) a[i] = in.nextInt();
		int[] b = new int[m];
		for(int j=0;j<m;j++) b[j] = in.nextInt();

		for(int i=0;i<n;i++) {
			for(int j=0;j<m;j++) {
				if(a[i]==b[j]) fixed[a[i]] = true;
				else {
					array[Math.min(a[i], b[j])]++;
				}
			}
		}

		int mod = 1000000007;
		long ans = 1L;
		array[n*m] = fixed[n*m]?1:0;
		for(int i=n*m-1;i>=1;i--) {
			if(fixed[i]) {
				array[i] += array[i+1];
				continue;
			}else if(array[i]>0) {
				ans = (ans * array[i]) % mod;
				array[i] += array[i+1];
				array[i]--;
			}else {
				array[i] += array[i+1];
				array[i]--;
				ans = (ans * array[i]) % mod;
			}
		}

		System.out.println(ans);
		in.close();
	}

}

import java.util.*;

public class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int mod = (int)1e9+7;

        int n = Integer.parseInt(sc.next());
        int m = Integer.parseInt(sc.next());
        int[] a = new int[n+1];
        int[] b = new int[m+1];

        long ans = 1;
        Map<Integer,Integer> map = new HashMap<>();
        for(int i=0; i<n; i++){
            a[i] = Integer.parseInt(sc.next());
            map.merge(a[i], 1, Integer::sum);
            if(map.get(a[i])>=2) ans = 0;
        }
        map.clear();
        for(int i=0; i<m; i++){
            b[i] = Integer.parseInt(sc.next());
            map.merge(b[i], 1, Integer::sum);
            if(map.get(b[i])>=2) ans = 0;
        }

        Arrays.sort(a);
        Arrays.sort(b);

        int aidx = 0;
        int bidx = 0;

        for(int i=n*m; i>=1; i--){
            int at = a[n-aidx];
            int bt = b[m-bidx];

            long tmp = 1;

            if(at==i && bt==i){
                //tmp = 1;
                aidx++;
                bidx++;
            }else if(at==i){
                tmp = bidx;
                aidx++;
            }else if(bt==i){
                tmp = aidx;
                bidx++;
            }else{
                tmp = aidx*bidx - (n*m-i);
                if(tmp<0) tmp = 0;
            }

            ans = ans*tmp%mod;
        }

        System.out.println(ans);

    }

}

