            if(i>=0&&j>=0) continue;
            if(i>=0&&j<0){
                j = -(j+1);
                ans = ans*(m-j)%mod;
            }else if(i<0&&j>=0){
                i = -(i+1);
                ans = ans*(n-i)%mod;
            }else{
                j = -(j+1);
                i = -(i+1);
                ans = ans*((n-i)*(m-j)-(n*m-k))%mod;
            }
        }
        return ans;
    }
