import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final int m;
  final int[] as;
  final int[] bs;
  final ModCalculator mc;

  Solver(int n, int m, int[] as, int[] bs) {
    this.n = n;
    this.m = m;
    this.as = as;
    this.bs = bs;
    this.mc = new ModCalculator(1_000_000_007L);
  }

  public long solve() {
    Map<Integer, Integer> vToI = new HashMap<>();
    for (int i = 0; i < n; i++) {
      if (vToI.get(as[i]) != null) {
        return 0;
      }
      vToI.put(as[i], i);
    }
    TreeMap<Integer, Integer> vToCountI = new TreeMap<>();
    Arrays.sort(as);
    vToCountI.put(Integer.MAX_VALUE, 0);
    for (int i = n-1; i >= 0; i--) {
      vToCountI.put(as[i], n - i);
    }

    Map<Integer, Integer> vToJ = new HashMap<>();
    for (int j = 0; j < m; j++) {
      if (vToJ.get(bs[j]) != null) {
        return 0;
      }
      vToJ.put(bs[j], j);
    }
    TreeMap<Integer, Integer> vToCountJ = new TreeMap<>();
    Arrays.sort(bs);
    vToCountJ.put(Integer.MAX_VALUE, 0);
    for (int j = m-1; j >= 0; j--) {
      vToCountJ.put(bs[j], m - j);
    }

    long answer = 1;
    for (int k = n * m; k >= 1; k--) {
      Integer i = vToI.get(k);
      Integer j = vToJ.get(k);
      if (i != null && j != null) {
        // Do nothing.
      } else if (i != null) {

        int countLargerB = vToCountJ.higherEntry(k).getValue();
        answer = mc.mul(answer, countLargerB);

      } else if (j != null) {

        int countLargerA = vToCountI.higherEntry(k).getValue();
        answer = mc.mul(answer, countLargerA);

      } else {

        int countLargerA = vToCountI.higherEntry(k).getValue();
        int countLargerB = vToCountJ.higherEntry(k).getValue();
        if (countLargerA == 0 || countLargerB == 0) {
          return 0;
        }
        answer = mc.mul(answer, countLargerA * countLargerB - n * m + k);
      }

      if (answer == 0) {
        return 0;
      }
    }
    return answer;
  }
}

