class Solver {
  final int n;
  final int m;
  final int[] as;
  final int[] bs;
  final ModCalculator mc;

  Solver(int n, int m, int[] as, int[] bs) {
    this.n = n;
    this.m = m;
    this.as = as;
    this.bs = bs;
    this.mc = new ModCalculator(1_000_000_007L);
  }

  public long solve() {
    Map<Integer, Integer> vToI = new HashMap<>();
    for (int i = 0; i < n; i++) {
      if (vToI.get(as[i]) != null) {
        return 0;
      }
      vToI.put(as[i], i);
    }

    Map<Integer, Integer> vToJ = new HashMap<>();
    for (int j = 0; j < m; j++) {
      if (vToJ.get(bs[j]) != null) {
        return 0;
      }
      vToJ.put(bs[j], j);
    }

    long answer = 1;
    for (int k = n * m; k >= 1; k--) {
      Integer i = vToI.get(k);
      Integer j = vToJ.get(k);
      if (i != null && j != null) {
        // Do nothing.
      } else if (i != null) {

        int countLargerB = 0;
        for (int b : bs) {
          if (b > k) {
            countLargerB++;
          }
        }
        answer = mc.mul(answer, countLargerB);

      } else if (j != null) {

        int countLargerA = 0;
        for (int a : as) {
          if (a > k) {
            countLargerA++;
          }
        }
        answer = mc.mul(answer, countLargerA);

      } else {

        int countLargerA = 0;
        for (int a : as) {
          if (a > k) {
            countLargerA++;
          }
        }
        int countLargerB = 0;
        for (int b : bs) {
          if (b > k) {
            countLargerB++;
          }
        }
        if (countLargerA == 0 || countLargerB == 0) {
          return 0;
        }
        answer = mc.mul(answer, countLargerA * countLargerB - n * m + k);
      }

      if (answer == 0) {
        return 0;
      }
    }
    return answer;
  }
}

