		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt(), m = in.nextInt();
			int[] a = in.nextIntArray(n);
			int[] b = in.nextIntArray(m);
			long[] ax = new long[m*n+1];
			long[] bx = new long[m*n+1];
			Arrays.sort(a);
			Arrays.sort(b);
			for (int i : a) ax[i]++;
			for (int i : b) bx[i]++;
			for (int i = 0; i < n; i++) {
				if (ax[i] > 1) {
					out.println(-1);
