				}
			}

			for (int i = 0; i < m; i++) {
				if (bx[i] > 1) {
					out.println(-1);
					return;
				}
			}

			long[] asum = ax.clone();
			long[] bsum = bx.clone();
			Arrays.parallelPrefix(asum, Math::addExact);
			Arrays.parallelPrefix(bsum, Math::addExact);

			long ans = 1;
			for (int i = n * m, cnt = 0; i >= 1; i--, cnt++) {
				if (ax[i] == 1 && bx[i] == 1) {
					ans *= 1;
				} else if (ax[i] == 1 && bx[i] == 0) {
					ans *= max(bsum[n*m] - bsum[i-1], 1);
					ans %= MOD;
				} else if (ax[i] == 0 && bx[i] == 1) {
					ans *= max(asum[n*m] - asum[i-1], 1);
					ans %= MOD;
				} else if (ax[i] == 0 && bx[i] == 0) {
					ans *= max((asum[n*m] - asum[i-1]) * (bsum[n*m] - bsum[i-1]) - cnt, 1);
					ans %= MOD;
				}
 			}

			out.println(ans);
		}
	}

	public static int lowerBound(int[] a, int obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (obj <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}

	static class MyInput {
		private final BufferedReader in;
