      int p = lowerBound(a, i);
      int q = lowerBound(b, i);

      if (n == p || m == q) {
        System.out.println(0);
        return;
      }
      if (a[p] == i && b[q] == i) {
      } else if (a[p] == i) {
        ret *= m - q;
      } else if (b[q] == i) {
        ret *= n - p;
      } else {
        ret *= Math.max(0, (n - p) * (m - q) - cnt);
      }
      cnt++;
      ret %= mod;
    }

    System.out.println(ret);
  }

  public static int lowerBound(int[] a, int v) {
    int low = -1, high = a.length;
    while (high - low > 1) {
      int h = high + low >>> 1;
      if (a[h] >= v) {
        high = h;
      } else {
        low = h;
      }
    }
    return high;
  }

