    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.*;

public class Main {
    public static final int MOD = 1_000_000_007;

    /**
     * @param args
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();
        int[] A = new int[N];
        int[] B = new int[M];
        for (int i=0; i<N; i++) {
            A[i] = sc.nextInt();
        }
        for (int i=0; i<M; i++) {
            B[i] = sc.nextInt();
        }

        long ans = solve(N, M, A, B);
        // long ans = solve_reverse(N, M, A, B);
        // long ans = solve4004049(N, M, A, B);

        System.out.println(ans);
    }

    /**
     *
     */
    private static long solve(int N, int M, int[] A, int[] B) {
        Arrays.sort(A);
        Arrays.sort(B);
        System.err.println("A = " + Arrays.toString(A));
        System.err.println("B = " + Arrays.toString(B));

        int p = N-1;
        int q = M-1;
        long ans = 1;
        int rest = 0;

        if (A[N-1] != N*M || B[M-1] != N*M) return 0;

        for (int i=N*M-1; i>=1; i--) {
            boolean P = p-1 >= 0 && A[p-1] == i;
            boolean Q = q-1 >= 0 && B[q-1] == i;
            // System.err.println("A[p] = A[" + p + "] = " + A[p]);
            // System.err.println("B[q] = B[" + q + "] = " + B[q]);
            // System.err.println("P: " + P + ", Q: " + Q);

            if (P) {
                p--;
                rest += M-q;
            }
            if (Q) {
                q--;
                rest += N-p;
            }

            if (P && Q) {
                // nothing
            } else if (P) {
                ans = ans * (M-q) % MOD;
            } else if (Q) {
                ans = ans * (N-p) % MOD;
            } else {
                ans = ans * rest % MOD;
            }

            rest--;
            if (rest < 0) {
                System.err.println("rest = " + rest);
                return 0;
            }

            // System.err.println("ans=" + ans + ", rest=" + rest + ", p=" + p + ", q=" + q);
        }

        return ans;
    }

    /**
     * posなしreverseあり版
     */
    private static long solve_reverse(int N, int M, int[] A, int[] B) {
        Arrays.sort(A);
        A = reverse(A);
        Arrays.sort(B);
        B = reverse(B);
        System.err.println("A = " + Arrays.toString(A));
        System.err.println("B = " + Arrays.toString(B));

        // p, qは配置候補の領域(0<=p<N, 0<=q<M)
        int p = 0;
        int q = 0;
        long ans = 1;
        int rest = 0;

        // AまたはBに最大値(N*M)が含まれていない場合は、条件を満たすことはできない
        if (A[0] != N*M || B[0] != N*M) return 0;

        // i=N*M のときは位置が一意に決定して空きスペースも0なのでスキップ
        for (int i=N*M-1; i>=1; i--) {
            // 行(P)または列(Q)を拡張可能か
            boolean P = p+1 < N && A[p+1] == i;
            boolean Q = q+1 < M && B[q+1] == i;
            System.err.println("A[p] = A[" + p + "] = " + A[p]);
            System.err.println("B[q] = B[" + q + "] = " + B[q]);
            System.err.println("P: " + P + ", Q: " + Q);

            if (P) {
                p++;
                rest += q+1;
            }
            if (Q) {
                q++;
                rest += p+1;
            }

            if (P && Q) {
                // 行・列両方の配置領域を拡張する場合は、iの配置場所は一意に決定する
                // このとき候補数ansは変化しない
            } else if (P) {
                // 拡張した idx: qの列のいずれか(q+1通り)に配置する
                ans = ans * (q+1) % MOD;
            } else if (Q) {
                // 拡張した idx: pの列のいずれか(p+1通り)に配置する
                ans = ans * (p+1) % MOD;
            } else {
                // 既存の候補領域のいずれか(rest通り)に配置する
                ans = ans * rest % MOD;
            }
            // 1つ配置したので候補数は1つ減る
            rest--;
            //
            if (rest < 0) {
                System.err.println("rest = " + rest);
                return 0;
            }

            System.err.println("ans=" + ans + ", rest=" + rest + ", p=" + p + ", q=" + q);
        }

        return ans;
    }

