public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * キーエンス プログラミング コンテスト 2019 D問題
		 * 考察メモ
		 * まず、大きい方から順番に決め打つことを考える
		 * そうすると、値の見つかった個数で次のように分類できる
		 * ・値が同じ側で2ヶ所以上に出現した
		 * →絶対におかしいので0通り
		 * ・値が2ヶ所で見つかった
		 * →自明に定まる、1通り
		 * ・値が1ヶ所で見つかった
		 * →その入れられる行/列のうち、自分より大きい数字が書いてある候補から一つどれでも選んでおｋ
		 * そしてその候補数を1減らすようにしておく
		 * ・値が0ヶ所で見つかった
		 * これも同様、入れられる行/列のうち、自分より大きい数字が書いてある候補から一つどれでも選んでおｋ
		 * そして候補数を1減らす
		 *
		 */
		int N = io.nextInt(), M = io.nextInt();
		int[] A = new int[N + 1];
		for (int i : IntRange.open(N)) A[i] = io.nextInt();
		Arrays.sort(A);
		ArrayUtility.reverse(A);
		int[] B = new int[M + 1];
		for (int i : IntRange.open(M)) B[i] = io.nextInt();
		Arrays.sort(B);
		ArrayUtility.reverse(B);
		int a = 0, b = 0;
		ModInteger ans = new ModInteger(1000000007, 1);
		for (int i = N * M;i >= 1;-- i) {
			if (A[a] == i) {
				if (A[++a] == i) ans.multiplyEqual(0); // 同じ数字は2個無いです
				if (B[b] == i) {
					if (B[++b] == i) ans.multiplyEqual(0); // 同じ数字は2個無いです
				} else {
					ans.multiplyEqual(b);
				}
			} else if (B[b] == i) {
				if (B[++b] == i) ans.multiplyEqual(0); // 同じ数字は2個無いです
				ans.multiplyEqual(a);
			} else {
				ans.multiplyEqual(a * b - (N * M - i)); // NM-iは今までおいた個数、つまりa*bから引いたのは空きマス
			}
		}
		io.println(ans);
	}

