    static class DDoubleLandscape {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            int[] a = in.readIntArray(n);
            int[] b = in.readIntArray(m);
            MiscUtils.decreaseByOne(a, b);

            boolean[] aa = new boolean[n * m];
            boolean[] bb = new boolean[n * m];
            for (int i = 0; i < n; i++) aa[a[i]] = true;
            for (int i = 0; i < m; i++) bb[b[i]] = true;

            int aCnt = 0;
            int bCnt = 0;
            Modulo.mod = MiscUtils.MOD7;
            Modulo ans = new Modulo(1);
            for (int i = n * m - 1; i >= 0; i--) {
                if (aa[i] && bb[i]) {
                    if (aCnt == n || bCnt == m) {
                        out.printLine(0);
                        return;
                    }
                    aCnt++;
                    bCnt++;
                } else if (aa[i]) {
                    if (aCnt == n || bCnt == 0) {
                        out.printLine(0);
                        return;
                    }
                    ans.mlt(bCnt);
                    aCnt++;
                } else if (bb[i]) {
                    if (bCnt == m || aCnt == 0) {
                        out.printLine(0);
                        return;
                    }
                    ans.mlt(aCnt);
                    bCnt++;
                } else {
                    if (aCnt == 0 || bCnt == 0) {
                        out.printLine(0);
                        return;
                    }
                    ans.mlt(aCnt * bCnt - (m * n - 1 - i));
                }
            }

            out.printLine(ans);
        }

    }

