            int r = A.Length - 1;
            if (n <= A[l]) { return A.Length; }
            if (n > A[r]) { return 0; }
            while (r - l >= 2)
            {
                int m = (l + r) / 2;
                if (n <= A[m]) { r = m; } else { l = m; }
            }
            return A.Length - l - 1;
        }

        static long Solve(int N, int M, int[] A, int[] B)
        {
            const int MOD = 1000000007;
            Array.Sort(A);
            Array.Sort(B);
            var rows = new HashSet<int>();
            var cols = new HashSet<int>();
            foreach (int a in A)
            {
                if (rows.Contains(a)) { return 0; }
                rows.Add(a);
            }
            foreach (int b in B)
            {
                if (cols.Contains(b)) { return 0; }
                cols.Add(b);
            }
            long ans = 1;
            for (int i = N * M; i > 0; --i)
            {
                bool x = rows.Contains(i);
                bool y = cols.Contains(i);
                int h = Search(i, A);
                int w = Search(i, B);
                if (!x && !y)
                {
                    ans *= h * w - (N * M - i);
                    ans %= MOD;
                }
                else if (x && y)
                {
                    // do nothing
                }
                else if (x)
                {
                    ans *= w;
                    ans %= MOD;
                }
                else if (y)
                {
                    ans *= h;
                    ans %= MOD;
                }
            }
            return ans;
        }

        static void Main(string[] args)
        {
            int[] V = ReadInts();
            int N = V[0], M = V[1];
            int[] A = ReadInts();
            int[] B = ReadInts();
            Console.WriteLine(Solve(N, M, A, B));
        }
    }
}

