            string[] dataCol = Console.ReadLine().Split(' ');

            dataRow = dataRow.OrderByDescending(x => x).ToArray();
            dataCol = dataCol.OrderByDescending(x => x).ToArray();

            int minData = 0;
            if (int.Parse(dataRow[sizeRow - 1]) < int.Parse(dataCol[sizeCol - 1]))
            {
                minData = int.Parse(dataRow[sizeRow - 1]);
            }
            else
            {
                minData = int.Parse(dataCol[sizeCol - 1]);            
            }

            bool wDataFlg = false;

            for (int i = 0; i < bigSize - 1; i++)
            {
                if (i < sizeRow - 1)
                {
                    if (dataRow[i] == dataRow[i + 1])
                    {
                        wDataFlg = true;
                        break;
                    }
                }

                if (i < sizeCol - 1)
                {
                    if (dataCol[i] == dataCol[i + 1])
                    {
                        wDataFlg = true;
                        break;
                    }
                }

            }

            long retData = 0;

            if (!wDataFlg)
            {
                retData = 1;
                for (int i = dataCnt; minData <= i; i--)
                {
                    bool rowEqExistsFlg = false;
                    bool colEqExistsFlg = false;

                    int rowCnt = 0;
                    int colCnt = 0;

                    bool endRowFlg = false;
                    bool endColFlg = false;

                    for (int j = 0; j < bigSize; j++)
                    {
                        if (j < sizeRow)
                        {

                            if (!rowEqExistsFlg)
                            {
                                if (i == int.Parse(dataRow[j]))
                                {
                                    rowEqExistsFlg = true;
                                    rowCnt = 1;
                                }
                                else if (i < int.Parse(dataRow[j]))
                                {
                                    rowCnt++;
                                }
                                else if (int.Parse(dataRow[j]) < i)
                                {
                                    endRowFlg = true;
                                }
                            }
                        }

                        if (j < sizeCol)
                        {

                            if (!colEqExistsFlg)
                            {
                                if (i == int.Parse(dataCol[j]))
                                {
                                    colEqExistsFlg = true;
                                    colCnt = 1;
                                }
                                else if (i < int.Parse(dataCol[j]))
                                {
                                    colCnt++;
                                }
                                else if (int.Parse(dataCol[j]) < i)
                                {
                                    endColFlg = true;
                                }
                            }
                        }

                        if (endRowFlg && endColFlg)
                        {
                            break;
                        }

                        if (rowEqExistsFlg && colEqExistsFlg)
                        {
                            break;
                        }
                    }

                    int optData = 0;
                    if (!rowEqExistsFlg && !colEqExistsFlg)
                    {
                        optData = sizeRow * sizeCol - i;
                    }

                    if (rowCnt * colCnt - optData <= 0)
                    {
                        retData = 0;
                        break;
                    }
                    else
                    {
                        retData = (retData * (rowCnt * colCnt - optData)) % MOD;
                    }
                }

                for (int i = minData - 1; 1 <= i; i--)
                {
                    retData = (retData * (sizeRow * sizeCol - (sizeRow * sizeCol - i))) % MOD;
                }
            }

            Console.WriteLine(retData);
        }
