class c
{
    static void Main()
    {
        var nm = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        var a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        var b = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        long rest = 0;
        long ans = 1;
        var check = new long[nm[0] * nm[1] + 1];
        var dbl = new long[nm[0] * nm[1] + 1];
        var map = new long[nm[0]][];
        for (int i = 0; i < nm[0]; i++)
        {
            map[i] = new long[nm[1]];
        }
        for (int i = 0; i < nm[0]; i++)
        {
            for (int j = 0; j < nm[1]; j++)
            {
                map[i][j] = a[i];
            }
        }
        for (int i = 0; i < nm[0]; i++)
        {
            for (int j = 0; j < nm[1]; j++)
            {
                if (map[i][j] == b[j]) map[i][j] *= -1;
                else map[i][j] = Math.Min(map[i][j], b[j]);
            }
        }
        for (int i = 0; i < nm[0]; i++)
        {
            for (int j = 0; j < nm[1]; j++)
            {
                if (map[i][j] < 0)
                {
                    dbl[-map[i][j]]++;
                }
                else check[map[i][j]]++;
            }
        }
        for (int i = 1; i <= nm[0] * nm[1]; i++)
        {
            if (dbl[i] > 0)
            {
                rest += dbl[i];
            }
            if (check[i] > 0)
            {
                if (rest + check[i] > i) ans = 0;
                ans *= nPr(i - rest, check[i]);
                ans %= 1000000007;
                rest += check[i];
            }
        }
        if (dbl.Max() > 1) { Console.WriteLine(0); }
        else Console.WriteLine(ans);
    }
    static long nPr(long n, long r)
    {
        long ans = 1;
        for (long i = 1; i <= r; i++)
        {
            ans *= n - i + 1;
            ans %= 1000000007;
        }
        return ans;
    }
}

