                    ans = ans * coef % MOD;
                }
                else
                {
                    long coefA = listA.Count - LowerBound(listA, num);
                    long coefB = listB.Count - LowerBound(listB, num);
                    long coef = coefA * coefB - (n * m - num);
                    ans = ans * coef % MOD;
                }
            }
