using System;
using System.Linq;

static class D
{
    private const long M = 1000000007;

    static long Solve(int[] a, int[] b)
    {
        int n = a.Length;
        int m = b.Length;

        if (a.Distinct().Count() != n) return 0;
        if (b.Distinct().Count() != m) return 0;

        long ans = 1;
        int k = n * m;
        for (; k >= 1; k--) {
            int r = 0, c = 0;

            for (int i = 0; i < n; i++) {
                if (a[i] == k) { r = -1; break; }
                if (a[i] >  k) { r++; }
            }
            for (int i = 0; i < m; i++) {
                if (b[i] == k) { c = -1; break; }
                if (b[i] >  k) { c++; }
            }
            if (r == n && c == m)
                break;

            int rc = Math.Abs(r) * Math.Abs(c);
            if (r > 0 && c > 0) {
                rc -= n * m - k;
            }
            if (rc == 0) return 0;
            ans = (ans * rc) % M;
        }
        for (; k >= 1; k--) {
            ans = (ans * k) % M;
        }

        return ans;
    }

    static void Main()
    {
        Console.ReadLine();
        int[] a = Console.ReadLine().Split().Select(Int32.Parse).ToArray();
        int[] b = Console.ReadLine().Split().Select(Int32.Parse).ToArray();
        Console.WriteLine(Solve(a, b));
    }
}

