class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int m = int.Parse(input[1]);
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long[] numsb = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long answer = 1;
		long answerMemo = 0;
		long mod = 1000000007;
    int checkedA = n-2;
    int checkedB = m-2;

    Array.Sort(nums);
    Array.Sort(numsb);

		for(int i = n-1; i >= 0; i--)
		{
			for(int j = m-1; j >= 0; j--)
			{
        int num = i*m+j+1;
        //Console.WriteLine(answer);

        if(checkedA != -1)
        {
          if(nums[checkedA] == num) checkedA--;
        }
        if(checkedB != -1)
        {
          if(numsb[checkedB] == num) checkedB--;
        }

        if(checkedA != -1)
        {
          if(nums[checkedA] >= num)
          {
            answer = 0;
          }
        }
        if(checkedB != -1)
        {
          if(numsb[checkedB] >= num)
          {
            answer = 0;
          }
        }

        if(nums[checkedA+1] == num && numsb[checkedB+1] == num)
        {
          answer *= 1;
        }else if(nums[checkedA+1] != num && numsb[checkedB+1] != num)
        {
          answerMemo = (n-checkedA-1) * (m-checkedB-1) - (n*m-num);
          answer *= answerMemo;
          answer %= mod;
          if(answerMemo < 0) answer = 0;
        }else if(nums[checkedA+1] == num)
        {
          answerMemo = m-checkedB-1;
          answer *= answerMemo;
          answer %= mod;
          if(answerMemo < 0) answer = 0;
        }else
        {
          answerMemo = n-checkedA-1;
          answer *= answerMemo;
          answer %= mod;
          if(answerMemo < 0) answer = 0;
        }

			}
		}

		Console.WriteLine(answer);
	}
}

