class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int m = int.Parse(input[1]);
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long[] numsb = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long answer = 1;
		long answerMemo = 0;
		long mod = 1000000007;
		bool[] checkedNums = new bool[n*m];//記入済みの数

		for(int i = 0; i < n; i++)
		{
			answerMemo = 0;
			for(int j = 0; j < m; j++)
			{
				checkedNums[nums[i]-1] = true; 

				if(numsb[j] > nums[i]) answerMemo++;
				else if(numsb[j] == nums[i])
				{
					answerMemo = 1;
					break;
				}
			}
			answer *= answerMemo;
			answer %= mod;
		}

		for(int i = 0; i < m; i++)//列も同様
		{
			answerMemo = 0;
			for(int j = 0; j < n; j++)
			{
				if(checkedNums[numsb[i]-1])//行と同じ数はパス
				{
					answerMemo = 1;
					break;
				}
				checkedNums[numsb[i]-1] = true; 

				if(nums[j] > numsb[i]) answerMemo++;
				else if(nums[j] == numsb[i])
				{
					answerMemo = 1;
					break;
				}
			}
			answer *= answerMemo;
			answer %= mod;
		}

		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{
				if(!checkedNums[i*m+j])
				{
					answer *= i*m+j+1;
					answer %= mod;
				}
			}
		}

		Console.WriteLine(answer);
	}
}

