			return;
		}

		for(int i = 0; i < N * M; i++)
		{
			csumA[i + 1] = csumA[i] + cntA[i + 1];
			csumB[i + 1] = csumB[i] + cntB[i + 1];
		}

		var ans = new ModInt(1);
		for(int x = N * M; x > 0; x--)
		{
			bool inA = (cntA[x] == 1);
			bool inB = (cntB[x] == 1);
			if(inA && (!inB))
			{
				var numB = new ModInt(csumB[N * M] - csumB[x - 1]);
				ans *= numB;
			}
			else if((!inA) && inB)
			{
				var numA = new ModInt(csumA[N * M] - csumA[x - 1]);
				ans *= numA;
			}
			else if((!inA) && (!inB))
			{
				var numA = new ModInt(csumA[N * M] - csumA[x - 1]);
				var numB = new ModInt(csumB[N * M] - csumB[x - 1]);
				var numFixed = new ModInt((long)(N * M - x));
				ans *= numA * numB - numFixed;
			}
		}

		Console.WriteLine(ans.Val);
	}
}


public struct ModInt
{
	public long Mod { get; private set; }
	public long Val { get; private set; }

	public ModInt(long v)
	{
		Mod = 1000000007;
		Val = v;
	}

	public static ModInt operator+(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long tmp = x.Val + y.Val;
		if(tmp >= mod)
			tmp -= mod;
		return new ModInt(tmp);
	}

	public static ModInt operator-(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long tmp = x.Val;
		if(tmp < y.Val)
			tmp += mod;
		tmp -= y.Val;
		return new ModInt(tmp);
	}

	public static ModInt operator*(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		return new ModInt((x.Val * y.Val) % mod);
	}

	public static ModInt operator/(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long pow = mod - 2;
		long yy = y.Val;
		long inv = 1;
		while(pow > 0)
		{
			if((pow & 1) == 1)
				inv = (inv * yy) % mod;
			yy = (yy * yy) % mod;
			pow >>= 1;
		}
		return new ModInt((x.Val * inv) % mod);
	}
}


