            setb.Add(b[i]);
        if (seta.Count != nm[0] || setb.Count != nm[1])
            return 0;
        Array.Sort(a);
        Array.Sort(b);
        var res = 1L;
        for(var i = nm[0] * nm[1]; i >= 1; i--)
