            var ctb = nm[1]-Search.UpperBound(b, i);
            if (isa && isb) continue;
            else if (isb)
                res = res * cta % Input.MOD;
            else if (isa)
                res = res * ctb % Input.MOD;
            else res = (res * ((long)cta * ctb - nm[0] * nm[1] + i)) % Input.MOD;
        }
        return res;
    }
