		Array.Sort(B,(x,y)=>y-x);
		int C = N*M;
		int a1 = 0;
		int a2 = 0;
		long ans = 1;
		long mod = 1000000007;
		while(C>0){
			int f1 = 0;
			if(a1<N && A[a1]==C){
				f1 = 1;
				a1++;
			}
