        }

        public long Min(params long[] a)
        {
            var min = a[0];
            for (int i = 1; i < a.Length; i++)
            {
                if (min > a[i]) min = a[i];
            }
            return min;
        }

        public long Max(params long[] a)
        {
            var max = a[0];
            for (int i = 1; i < a.Length; i++)
            {
                if (max < a[i]) max = a[i];
            }
            return max;
        }

        public void Solve(ConsoleInput input)
        {
            var n = input.ReadInt;
            var m = input.ReadInt;
            var a = input.ReadLongArray(n);
            var b = input.ReadLongArray(m);

            long c = 0;
            if (a.Distinct().Count() == n && b.Distinct().Count() == m)
            {
                c = 1;
                for (var x = n * m; x >= 1; x--)
                {
                    var ina = a.Any(i => i == x);
                    var inb = b.Any(i => i == x);
                    var ca = a.Where(e => e >= x).Count();
                    var cb = b.Where(e => e >= x).Count();
                    if (ina && inb) c *= 1;
                    else if (ina && !inb) c *= cb;
                    else if (!ina && inb) c *= ca;
                    else c *= (ca * cb) - (n * m - x);
                    c %= 1000000007;
                }
            }
            WriteLine($"{c}");

            //Solve(input);
        }

        private int Max(params int[] array)
        {
            int max = array[0];
            foreach (var a in array)
            {
                if (max < a) max = a;
            }
            return max;
        }
