                            if (i == int.Parse(dataRow[j]))
                            {
                                rowEqExistsFlg = true;
                                rowCnt = 1;
                            }
                            else if (i <= int.Parse(dataRow[j]))
                            {
                                rowCnt++;
                            }
                        }
                    }

                    if (j < sizeCol)
                    {
                        if (wCntFlgCol[int.Parse(dataCol[j])])
                        {
                            wCntExistsFlgCol = true;
                            break;
                        }
                        else
                        {
                            wCntFlgCol[int.Parse(dataCol[j])] = true;
                        }

                        if (!colEqExistsFlg)
                        {
                            if (i == int.Parse(dataCol[j]))
                            {
                                colEqExistsFlg = true;
                                colCnt = 1;
                            }
                            else if (i <= int.Parse(dataCol[j]))
                            {
                                colCnt++;
                            }
                        }
                    }

                    if (wCntExistsFlgRow || wCntExistsFlgCol)
                    {
                        break;
                    }

                    if (rowEqExistsFlg && colEqExistsFlg)
                    {
                        break;
                    }
                }

                if (wCntExistsFlgRow || wCntExistsFlgCol)
                {
                    retData = 0;
                    break;
                }

                int optData = 0;
                if (!rowEqExistsFlg && !colEqExistsFlg)
                {
                    optData = sizeRow * sizeCol - i;
                }

                if (rowCnt * colCnt - optData <= 0)
                {
                    retData = 0;
                    break;
                }
                else
                {
                    retData = (retData * (rowCnt * colCnt - optData)) % MOD;
                }
            }

            Console.WriteLine(retData);
        }
    }
