                                    rowCnt = 1;
                                }
                                else if (i < dataRow[j])
                                {
                                    rowCnt++;
                                }
                                else if (dataRow[j] < i)
                                {
                                    endRowFlg = true;
                                }
                            }
                        }

                        if (j < sizeCol)
                        {

                            if (!colEqExistsFlg)
                            {
                                if (i == dataCol[j])
