using System;
using System.Linq;

public class Solution
{
    /// <summary>
    /// 2分探索で値vの位置を得る．vが無いときは，vを超える最小の値の位置を得る
    /// </summary>
    /// <typeparam name="T"></typeparam>
    /// <param name="v">探す値</param>
    /// <param name="list">対象リスト</param>
    /// <returns>vの位置</returns>
    static int BinSearchIndex(int v, int[] list)
    {
        int minRange = 0;
        int maxRange = list.Count();
        while (minRange != maxRange)
        {
            var center = (minRange + maxRange) / 2;
            if (list[center] < v)
            {
                minRange = center + 1;
            }
            else
            {
                maxRange = center;
            }
        }

        return minRange;
    }

    static bool IsIncludeSame(int[] list)
    {
        return list.Zip(list.Skip(1), (a, b) => a - b).Any(v => v == 0);
    }

    public static void Main()
    {
        const int mod = (int)1e9 + 7;
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var n = vals[0];
        var m = vals[1];
        var nm = n * m;
        var a = Console.ReadLine().Split(' ').Select(int.Parse).OrderBy(v => v).ToArray();
        var b = Console.ReadLine().Split(' ').Select(int.Parse).OrderBy(v => v).ToArray();

        if (IsIncludeSame(a) || IsIncludeSame(b))
        {
            Console.WriteLine(0);
            return;
        }

        long pattern = 1;
        for (int i = 1; i <= nm; i++)
        {
            var aIndex = BinSearchIndex(i, a);
            var bIndex = BinSearchIndex(i, b);
            var foundA = aIndex < n && a[aIndex] == i;
            var foundB = bIndex < m && b[bIndex] == i;
            if (foundA && foundB)
            {
                continue;
            }

            int p;
            if (foundA)
            {
                p = m - bIndex;
            }
            else if (foundB)
            {
                p = n - aIndex;
            }
            else
            {
                p = (n - aIndex) * (m - bIndex) - (nm - i);
            }

            pattern *= p;
            pattern %= mod;
        }

        Console.WriteLine(pattern);
    }
}

