            var b = ReadAndParseLongArr();
            var listA = new List<long>(a);
            var listB = new List<long>(b);
            listA.Sort();
            listA.Reverse();
            listB.Sort();
            listB.Reverse();
            if(!IsValid(listA) || !IsValid(listB))
            {
                Console.WriteLine(0);
                return;
