            long ans = 1;
            for(int num = n * m; num >= 1; --num)
            {
                bool hasA = listA.Contains(num);
                bool hasB = listB.Contains(num);
                if( hasA && hasB)
                {
                    ans *= 1;
                }else if( hasA && !hasB)
                {
                    long coef = 0;
                    foreach(var val in listB)
                    {
                        if( val >= num) { coef++; }
                    }
                    ans = ans * coef % MOD;
                }else if( !hasA && hasB)
                {
                    long coef = 0;
                    foreach(var val in listA)
                    {
                        if( val >= num) { coef++; }
                    }
                    ans = ans * coef % MOD;
                }
                else
                {
                    long coefA = 0;
                    foreach (var val in listA)
                    {
                        if (val >= num) { coefA++; }
                    }
                    long coefB = 0;
                    foreach (var val in listB)
                    {
                        if (val >= num) { coefB++; }
                    }
                    long coef = coefA * coefB - (n * m - num);
                    ans = ans * coef % MOD;
                }
            }
            Console.WriteLine(ans);
        }
        private static bool IsValid(List<long> list)
        {
            for(int i=1;i<list.Count;++i)
            {
                if(list[i] == list[i - 1]) { return false; }
            }
            return true;
        }
        #region よく使う便利関数
        private static bool isPrime(long x)
        {
            if (x == 2) { return true; }
            if (x < 2 || x % 2 == 0) { return false; }
            long i = 3;
            while (i * i <= x)
            {
                if (x % i == 0) { return false; }
                i = i + 2;
            }
            return true;
        }
        private static long lcm(long x, long y)
        {
            return x / gcd(x, y) * y;
        }
        private static long gcd(long x, long y)
        {
            return y > 0 ? gcd(y, x % y) : x;
        }
        private static long pow(long x, long n)
        {
            if (n == 0) { return 1; }
            long res = pow(x * x % MOD, n / 2);
            if (n % 2 == 1)
            {
                res = res * x % MOD;
            }
            return res;
        }
