                return;
            }

            Mlong ans = 1;
            for (int i = 1; i <= N * M; i++)
            {
                int ai = LowerBound(A, i);
                int bi = LowerBound(B, i);

                if (ai == N || bi == M)
                {
                    ans = 0;
                    break;
                }

                if (A[ai] == i && B[bi] == i)
                {

                }
                else if (A[ai] == i)
                {
                    ans *= M - bi;
                }
                else if (B[bi] == i)
                {
                    ans *= N - ai;
                }
                else
                {
                    ans *= (N - ai) * (M - bi) - (N * M - i);
                }
            }
            Console.WriteLine(ans);
        }

        public static int LowerBound<T>(T[] a, T v)
        {
            return LowerBound(a, v, Comparer<T>.Default);
        }
        public static int LowerBound<T>(T[] a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Length - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var res = cmp.Compare(a[mid], v);
                if (res == -1) l = mid + 1;
                else r = mid - 1;
            }
            return l;
        }
    }
