class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int m = int.Parse(input[1]);
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long[] numsb = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
		long answer = 1;
		long answerMemo = 0;
		long mod = 1000000007;
    int checkedA = n-1;
    int checkedB = m-1;

    Array.Sort(nums);
    Array.Sort(numsb);

		for(int i = n-1; i >= 0; i--)
		{
			for(int j = m-1; j >= 0; j--)
			{
        int num = i*m+j+1;
        //Console.WriteLine(answer);



        if(checkedA != -1)
        {
          if(nums[checkedA] >= num)
          {
            answer = 0;
          }
        }
        if(checkedB != -1)
        {
          if(numsb[checkedB] >= num)
          {
            answer = 0;
          }
        }

        if(nums[checkedA+1] == num && numsb[checkedB+1] == num)
        {
          answer *= 1;
        }else if(nums[checkedA+1] != num && numsb[checkedB+1] != num)
        {
          answerMemo = (n-checkedA-1) * (m-checkedB-1) - (n*m-num);
          answer *= answerMemo;
          answer %= mod;
          if(answerMemo < 0) answer = 0;
        }else if(nums[checkedA+1] == num)
        {
          answerMemo = m-checkedB-1;
          answer *= answerMemo;
          answer %= mod;
          if(answerMemo < 0) answer = 0;
        }else
        {
          answerMemo = n-checkedA-1;
          answer *= answerMemo;
          answer %= mod;
          if(answerMemo < 0) answer = 0;
        }

			}
		}

		Console.WriteLine(answer);
	}
}

using System;
using System.Linq;

public class Solution
{
    /// <summary>
    /// 2分探索で値vの位置を得る．vが無いときは，vを超える最小の値の位置を得る
    /// </summary>
    /// <typeparam name="T"></typeparam>
    /// <param name="v">探す値</param>
    /// <param name="list">対象リスト</param>
    /// <returns>vの位置</returns>
    static int BinSearchIndex(int v, int[] list)
    {
        int minRange = 0;
        int maxRange = list.Count();
        while (minRange != maxRange)
        {
            var center = (minRange + maxRange) / 2;
            if (list[center] < v)
            {
                minRange = center + 1;
            }
            else
            {
                maxRange = center;
            }
        }

        return minRange;
    }

    static bool IsIncludeSame(int[] list)
    {
        return list.Zip(list.Skip(1), (a, b) => a - b).Any(v => v == 0);
    }

    public static void Main()
    {
        const int mod = (int)1e9 + 7;
        var vals = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var n = vals[0];
        var m = vals[1];
        var nm = n * m;
        var a = Console.ReadLine().Split(' ').Select(int.Parse).OrderBy(v => v).ToArray();
        var b = Console.ReadLine().Split(' ').Select(int.Parse).OrderBy(v => v).ToArray();

        if (IsIncludeSame(a) || IsIncludeSame(b))
        {
            Console.WriteLine(0);
            return;
        }

        long pattern = 1;
        for (int i = 1; i <= nm; i++)
        {
            var aIndex = BinSearchIndex(i, a);
            var bIndex = BinSearchIndex(i, b);
            var foundA = a[aIndex] == i;
            var foundB = b[bIndex] == i;
            if (foundA && foundB)
            {
                continue;
            }

            int p;
            if (foundA)
            {
                p = m - bIndex;
            }
            else if (foundB)
            {
                p = n - aIndex;
            }
            else
            {
                p = (n - aIndex) * (m - bIndex) - (nm - i);
            }

            pattern *= p;
            pattern %= mod;
        }

        Console.WriteLine(pattern);
    }
}

