        M = sc.NextInt();
        A = sc.IntArray();
        B = sc.IntArray();

        ModInt ans = 1;

        var tmpHs = new HashSet<int>();

        for (int i = 0; i < N; i++)
        {
            if (!tmpHs.Add(A[i]))
            {
                Console.WriteLine(0);
                return;
            }
        }

