        for (int i = 0; i < M; i++)
        {
            if (!tmpHs.Add(B[i]))
            {
                Console.WriteLine(0);
                return;
            }
        }

        Array.Sort(A);
        Array.Sort(B);

        for (int i = N * M; i >= 1; i--)
        {
            int y = Algorithm.LowerBound(A, i);
            int x = Algorithm.LowerBound(B, i);

           // Console.WriteLine($"{i} {x} {y}");

            int p;
            int yy;

            bool f = false;
            if (y < N && A[y] == i)
