		Out.Flush();
	}
	void Solve() => WriteLine(Calc(G, G, G));
	long Calc(List<int> I, List<int> A, List<int> B)
	{
		int N = I[0], M = I[1];
		A.Sort(); B.Sort();
		for (var i = 1; i < N; i++) if (A[i] == A[i - 1]) return 0;
		for (var j = 1; j < M; j++) if (B[j] == B[j - 1]) return 0;
		A.Add(N * M + 1);
		B.Add(N * M + 1);
		int p = N, q = M;
		var ans = 1L;
		for (var i = N * M; i >= 1; i--)
		{
			if (p > 0 && A[p - 1] == i) p--;
			if (q > 0 && B[q - 1] == i) q--;
			if (A[p] == i && B[q] == i) continue;
			if (A[p] == i) ans = ans * (M - q) % MOD;
			else if (B[q] == i) ans = ans * (N - p) % MOD;
			else ans = ans * ((N - p) * (M - q) - (N * M - i)) % MOD;
			if (ans == 0) return 0;
		}
		return ans;
	}
}

