func main() {
	f := func() (a int) {
		fmt.Scan(&a)
		return
	}
	p:= 1000000000 + 7
	N := f()
	M := f()
	A := scanIntSlice(N)
	B := scanIntSlice(M)
	sort.Sort(sort.Reverse(sort.IntSlice(A)))
	sort.Sort(sort.Reverse(sort.IntSlice(B)))

	var aIndex, bIndex int
	tmpval := N * M
	ans := 1
	for tmpval>0{
		//fmt.Println(aIndex,bIndex,tmpval,ans)
		if aIndex<N && bIndex< M && A[aIndex] == tmpval && B[bIndex] == tmpval {
			aIndex++
			bIndex++
		} else if aIndex<N && A[aIndex] == tmpval {
			ans *= bIndex
			aIndex++
		} else if bIndex < M && B[bIndex] == tmpval {
			ans *= aIndex
			bIndex++
		} else {
			free := aIndex*bIndex - (N*M - tmpval)
			//fmt.Println("---",(N-aIndex)*(M-bIndex) , (N*M - tmpval))
			//fmt.Println("===",N,M,aIndex,bIndex,tmpval,free)
			if free == 0 {
