func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	aa := make([]int, n)
	bb := make([]int, m)
	for i := 0; i < n; i++ {
		aa[i] = -getNextInt(scanner)
	}
	for i := 0; i < m; i++ {
		bb[i] = -getNextInt(scanner)
	}

	sort.Ints(aa)
	sort.Ints(bb)
	for i := 1; i < n; i++ {
		if aa[i] == aa[i-1] {
			fmt.Fprintln(writer, 0)
			return
		}
	}
	for i := 1; i < m; i++ {
		if bb[i] == bb[i-1] {
			fmt.Fprintln(writer, 0)
			return
		}
	}
	mod := int64(1e9 + 7)
	ai := 0
	bi := 0
	var ans int64
	ans = 1
	for i := n*m - 1; i >= 0; i-- {
		for ai < n && -aa[ai] > i+1 {
			ai++
		}
		for bi < m && -bb[bi] > i+1 {
			bi++
		}
		p := ai*bi - (n*m - 1 - i)
		if ai < n && -aa[ai] == i+1 {
			if bi < m && -bb[bi] == i+1 {
				continue
			}
			p = bi
		} else if bi < m && -bb[bi] == i+1 {
			p = ai
		}
		if p <= 0 {
			fmt.Fprintln(writer, 0)
			return
		}
		ans *= int64(p)
		ans %= mod
	}

	fmt.Fprintln(writer, ans)
}

