const mod = 1e9 + 7

func intsHaveDuplicateElm(a []int) bool {
	m := make(map[int]bool, len(a))
	for _, aa := range a {
		if _, exists := m[aa]; exists {
			return true
		} else {
			m[aa] = true
		}
	}
	return false
}

func main() {
	var n, m int
	fmt.Scan(&n, &m)
	as := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&as[i])
	}
	bs := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Scan(&bs[i])
	}

	if intsHaveDuplicateElm(as) || intsHaveDuplicateElm(bs) {
		fmt.Println(0)
		return
	}

	sort.Sort(sort.Reverse(sort.IntSlice(as)))
	sort.Sort(sort.Reverse(sort.IntSlice(bs)))

	aExists := make([]bool, n*m+1)
	for _, aa := range as {
		aExists[aa] = true
	}
	aGreater := make([]int, n*m+1)
	for _, aa := range as {
		aGreater[1]++
		aGreater[aa]--
	}
	for i := 2; i < len(aGreater); i++ {
		aGreater[i] += aGreater[i-1]
	}

	bExists := make([]bool, n*m+1)
	for _, bb := range bs {
		bExists[bb] = true
	}
	bGreater := make([]int, n*m+1)
	for _, bb := range bs {
		bGreater[1]++
		bGreater[bb]--
	}
	for i := 2; i < len(bGreater); i++ {
		bGreater[i] += bGreater[i-1]
	}

	calc := func(x int) int {
		if aExists[x] && bExists[x] {
			return 1
		} else if aExists[x] {
			return bGreater[x]
		} else if bExists[x] {
			return aGreater[x]
		} else {
			return aGreater[x]*bGreater[x] - (n*m - x)
		}
	}

	ans := 1
	for i := n * m; i >= 1; i-- {
		ans = ans * calc(i) % mod
	}
	fmt.Println(ans)
}

function exec(N, M, A, B) {
  const a_max = Math.max.apply(null, A);
  const b_max = Math.max.apply(null, B);
  const max = Math.max(a_max, b_max);

  const A_Set = new Set(A);
  const B_Set = new Set(B);

  const mod = 10 ** 9 + 7;

  const already_A = [];
  const already_B = [];

  let ans = 1;

  for (let i = max; i > 0; i--) {
    const a_exists = A_Set.has(i);
    const b_exists = B_Set.has(i);
    if (a_exists && b_exists) {
      already_A.push(i);
      already_B.push(i);
    } else if (a_exists) {
      already_A.push(i);
      ans = ans * already_B.length;
      ans = ans % mod;
    } else if (b_exists) {
      already_B.push(i);
      ans = ans * already_A.length;
      ans = ans % mod;
    } else {
      let tmp = ((already_A.length * already_B.length) % mod) - (N * M - i);
      if (tmp < 0) {
        tmp += mod;
      }
      ans = (ans * tmp) % mod;
    }
  }

  return ans % mod;
}

