    xs[A[x]] = x;
  }
  foreach (y; 0 .. N) {
    if (ys[B[y]] != -1) {
      return 0;
    }
    ys[B[y]] = y;
  }

  long ans = 1;
  int cx, cy;
  foreach_reverse (i; 0 .. M * N) {
    for (; cx < M && i <= A[cx]; ++cx) {}
    for (; cy < N && i <= B[cy]; ++cy) {}
    long here;
    if (xs[i] != -1) {
      if (ys[i] != -1) {
        here = 1;
