            j_l.append(i)
    if len(j_l)==0:
        return 0

    tmp=0
    for i in i_l:
        for j in j_l:
            array_c = copy.deepcopy(array)
            array_c[i, j] = num
            if max_row[i]<num:
                max_row[i] = num
            if max_col[i]<num:
                max_col[i] = num
            tmp += count(array_c, num-1, max_col, max_row)
            tmp = tmp//mod
    return tmp
