def bisearch(lower, upper, x, C):
  if x <= C[upper]:
    return upper
  if upper - lower == 1:
    return lower
  mid = (upper + lower) // 2
  if C[mid] < x:
    return bisearch(lower, mid, x, C)
  else:
    return bisearch(mid, upper, x, C)
