        while i < N-1:
            if A[i+1] >= x:
                i += 1
            else:
                break

        while j < M-1:
            if B[j+1] >= x:
                j += 1
            else:
                break

        marked_row = False
        marked_col = False

        count_row = A[0:i+1].count(x)
        if count_row > 1:
            return(0)
        if count_row == 1:
            usable_row = 1
            marked_row = True
        else:
            usable_row = i+1

        count_col = B[0:j+1].count(x)
        if count_col > 1:
            return(0)
        if count_col == 1:
            usable_col = 1
            marked_col = True
        else:
            usable_col = j+1

        if marked_row or marked_col:
            usable_area = usable_row * usable_col
        else:
            usable_area = usable_row * usable_col - used_area

        if usable_area <= 0:
            return(0)

        result = result * usable_area % mod
        used_area += 1

    return(result)


