def slv(N, M, A, B):

    mod = 10**9 + 7

    if len(A) != len(set(A)):
        return 0
    if len(B) != len(set(B)):
        return 0

    A.sort()
    B.sort()
    As = set(A)
    Bs = set(B)

    ans = 1
    NM = N*M
    for i in range(N*M, 0, -1):
        if i in As and i in Bs:
            pass
        elif i in As:
            j = M - bisect.bisect_right(B, i)
            ans = (ans * j) % mod
        elif i in Bs:
            j = N - bisect.bisect_right(A, i)
            ans = (ans * j) % mod
        else:
            j = N - bisect.bisect_right(A, i)
            k = M - bisect.bisect_right(B, i)
            ans = (ans * (j*k-(NM-i))) % mod


    return ans


