macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, m: usize, mut a: [usize; n], mut b: [usize; m]);
    let mut memo = vec![0; n * m];
    let mut dup = vec![false; n * m];
    a.sort();
    b.sort();
    a.dedup();
    b.dedup();
    if a.len() != n || b.len() != m {
        println!("{}", 0);
        return;
    }
    for &ai in a.iter() {
        let mut count = 0;
        for &bi in b.iter() {
            if bi > ai {
                count += 1;
            } else if ai == bi {
                dup[ai - 1] = true;
            }
        }
        memo[ai - 1] = count;
    }
    for &ai in b.iter() {
        let mut count = 0;
        for &bi in a.iter() {
            if bi >= ai {
                count += 1;
            }
        }
        memo[ai - 1] += count;
    }
    let mut stock = 0;
    for i in (0..(n * m)).rev() {
        if memo[i] != 0 {
            stock += memo[i] - 1;
        } else {
            memo[i] = stock;
            if stock == 0 {
                println!("{}", 0);
                return;
            }
            stock -= 1;
        }
    }
    let mut ret = Mint(1);
    for i in 0..(n * m) {
        if !dup[i] {
            ret *= memo[i];
        }
    }
    println!("{}", ret); // DEBUG
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

