fn main() {
    input!{
        n: usize,
        m: usize,
        a: [usize; n],
        b: [usize; m]
    }
    let d = 1000000007;
    let mut sa = a;
    sa.sort_by(|x, y| y.cmp(&x));
    let mut sb = b;
    sb.sort_by(|x, y| y.cmp(&x));
    if sa[0] != n * m || sb[0] != n * m {
        println!("0");
        return;
    }
    for i in 0..n - 1 {
        if sa[i] == sa[i + 1] {
            println!("0");
            return;
        }
    }
    for i in 0..m - 1 {
        if sb[i] == sb[i + 1] {
            println!("0");
            return;
        }
    }
    let mut ans: usize = 1;
    let mut ida = 0;
    let mut idb = 0;
    for i in (1..n * m).rev() {
        let mut tr = ida + 1;
        let mut tc = idb + 1;
        if (ida < n - 1 && i == sa[ida + 1]) || (idb < m - 1 && i == sb[idb + 1]) {
            if ida < n - 1 && i == sa[ida + 1] {
                tr = 1;
                ida += 1;
            }
            if idb < m - 1 && i == sb[idb + 1] {
                tc = 1;
                idb += 1;
            }
            ans = ans * (tr * tc) % d;
        } else {
            ans = ans * (tr * tc - (n * m - i)) % d;
        }
    }
    println!("{}", ans);
}

