#[derive(Clone, Debug)]
pub struct MemorizedFactorial {
    n: usize,
    fact: Vec<Modi64>,
    inv_fact: Vec<Modi64>,
}
impl MemorizedFactorial {
    pub fn new(max_n: usize) -> MemorizedFactorial {
        let mut fact = vec![1.into(); max_n + 1];
        let mut inv_fact = vec![1.into(); max_n + 1];
        for i in 1..(max_n + 1) {
            fact[i] = fact[i - 1] * (i as i64).into();
            inv_fact[i] = inv_fact[i - 1] / (i as i64).into();
        }
        MemorizedFactorial {
            n: max_n + 1,
            fact: fact,
            inv_fact: inv_fact,
        }
    }
    pub fn combination(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[r] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    pub fn permutation(&self, n: usize, r: usize) -> Modi64 {
        if r <= n {
            self.fact[n] * self.inv_fact[n - r]
        } else {
            0.into()
        }
    }
    pub fn homogeneous_product(&self, n: usize, r: usize) -> Modi64 {
        if n != 0 && r != 0 {
            self.combination(n + r - 1, r)
        } else {
            1.into()
        }
    }
}
use std::collections::HashSet;
fn main() {
    input! { n, m, mut a: [usize; n], mut b: [usize; m] };
    if a.iter().collect::<HashSet<_>>().len() != n
        || b.iter().collect::<HashSet<_>>().len() != m
        || a.iter().max().unwrap() != b.iter().max().unwrap()
    {
        println!("{}", 0);
        return;
    }
    a.sort();
    b.sort();
    let fact = MemorizedFactorial::new(n * m);
    let mut ans = Modi64(1);
    let (mut i, mut j) = (0, 0);
    while i < n && j < m {
        let defined = i * m + j * n - i * j;
        if a[i] < b[j] {
            if a[i] < defined + m - j {
                ans = 0.into();
                break;
            }
            ans *= fact.permutation(a[i] - defined - 1, m - j - 1) * Modi64((m - j) as i64);
            i += 1;
        } else if a[i] > b[j] {
            if b[j] < defined + n - i {
                ans = 0.into();
                break;
            }
            ans *= fact.permutation(b[j] - defined - 1, n - i - 1) * Modi64((n - i) as i64);
            j += 1;
        } else {
            let r = n + m - i - j - 1;
            if a[i] < defined + r {
                ans = 0.into();
                break;
            }
            ans *= fact.permutation(a[i] - defined - 1, r - 1);
            i += 1;
            j += 1;
        }
    }
    println!("{}", ans.0);
}

