    let mut sc = Scanner::new();
    let n: usize = sc.next();
    let m: usize = sc.next();

    let a: Vec<usize> = sc.next_vec();
    let b: Vec<usize> = sc.next_vec();

    println!("{}", func(&a, &b, n, m));
}

