const P: i64 = 1_000_000_007;

fn main() {
    let (N, M) = read!(usize, usize);
    let A = read![[usize]];
    let B = read![[usize]];

    let mut X = vec![0; N * M + 1];
    let mut Y = vec![0; N * M + 1];

    for a in A {
        X[a] = 1;
    }
    for b in B {
        Y[b] = 1;
    }

    let mut SX = vec![0; N * M + 2];
    let mut SY = vec![0; N * M + 2];
    for i in (1..N * M + 1).rev() {
        SX[i - 1] += SX[i] + X[i];
        SY[i - 1] += SY[i] + Y[i];
    }

    debug!(X, Y, SX, SY);

    let mut s = 1_i64;
    for x in (1..N * M + 1).rev() {
        if X[x] >= 2 || Y[x] >= 2 {
            s = 0;
            break;
        }

        if X[x] + Y[x] == 2 {
            continue;
        }

        if X[x] == 1 {
            s *= SY[x];
            s %= P;
            continue;
        }

        if Y[x] == 1 {
            s *= SX[x];
            s %= P;
            continue;
        }

        let mut t = SX[x] * SY[x];
        t = t - min(t, (N * M - x) as i64);

        s *= t;
        s %= P;
    }

    println!("{}", s)
}

