use std::cmp::Ordering;

/// Equivalent to std::lowerbound and std::upperbound in c++
pub trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }

    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

fn main() {
    input! {
        n: usize,
        m: usize,
        xs: [i64; n],
        ys: [i64; m],
    };

    let mut xs_sorted = xs;
    xs_sorted.sort();
    xs_sorted.dedup();
    let mut ys_sorted = ys;
    ys_sorted.sort();
    ys_sorted.dedup();

    let ans = if xs_sorted.len() == n && ys_sorted.len() == m {
        let mut ans = 1;

        for i in 1..((n * m) as i64 + 1) {
            let in_xs = {
                let j = xs_sorted.lower_bound(&i);
                j < n && xs_sorted[j] == i
            };
            let in_ys = {
                let j = ys_sorted.lower_bound(&i);
                j < m && ys_sorted[j] == i
            };

            let x_cands = if in_xs {
                1
            } else {
                n - xs_sorted.upper_bound(&i)
            } as i64;
            let y_cands = if in_ys {
                1
            } else {
                m - ys_sorted.upper_bound(&i)
            } as i64;

            if in_xs || in_ys {
                ans *= x_cands * y_cands;
            } else {
                ans *= x_cands * y_cands - ((n * m) as i64 - i);
            }

            ans %= 1_000_000_007;
        }

        ans
    } else {
        0
    };

    println!("{}", ans);
}

