fn solve() {
    let (n,m) = get!(usize, usize);
    let a = get!([usize]);
    let b = get!([usize]);

    let mut map = BTreeMap::new();
    for e in a {
        let entry = map.entry(e).or_insert(0);
        if *entry == 1 {
            println!("0");
            return;
        }
        *entry |= 1;
    }
    for e in b {
        let entry = map.entry(e).or_insert(0);
        if *entry&2 == 2 {
            println!("0");
            return;
        }
        *entry |= 2;
    }

    let mut ranges = vec![vec![n*m+2; m]; n];
    let mut vec = vec![0; n*m+1];
    let mut x = 0;
    let mut y = 0;
    let mut set = BTreeSet::new();
    let mut nece = BTreeSet::new();
    for (k,v) in map {
        nece.insert(k);
        if v & 1 > 0 {
            for i in 0..m {
                if k+1<ranges[x][i] {
                    vec[k] += 1;
                }
                ranges[x][i] = min!(ranges[x][i], k+1);
            }
            x += 1;
        }
        if v & 2 > 0 {
            for i in 0..n {
                if k+1<ranges[i][y] {
                    vec[k] += 1;
                }
                ranges[i][y] = min!(ranges[i][y], k+1);
            }
            y += 1;
        }
        if v == 3 {
            if vec[k] < 1 {
                println!("0");
                return;
            }
            set.insert(k);
        }
    }

    let mut sums = vec![0; n*m+1];
    sums[n*m] = vec[n*m];
    for i in (1..n*m+1).rev() {
        sums[i-1] = sums[i]+vec[i-1];
    }
    let mut minus = 0;
    let mut res = ModInt::new(1);
    for i in (1..n*m+1).rev() {
        if sums[i] <= minus {
            println!("0");
            return;
        }
        if nece.contains(&i) {
            if !set.contains(&i) {
                res *= vec[i];
            }
            minus += 1;
            continue;
        }
        res *= sums[i]-minus;
        minus += 1;
    }
    println!("{}", res);
}

use std::io::BufRead;
use std::str::FromStr;
use std::fmt;
use std::str;
use std::collections::HashMap;

struct InputScanner<R: BufRead> {
    reader: R,
    buf: Vec<u8>, // Should never be empty
    pos: usize,   // Should never be out of bounds as long as the input ends with '\n'
}

impl<R: BufRead> InputScanner<R> {
    fn new(reader: R, capacity: usize) -> Self {
        InputScanner {
            reader: reader,
            buf: Vec::with_capacity(capacity),
            pos: 0,
        }
    }

    #[inline]
    fn next<T: FromStr>(&mut self) -> T
    where
        T::Err: fmt::Debug,
    {
        if self.buf.is_empty() {
            self._read_next_line();
        }
        let mut start = None;
        loop {
            match (self.buf[self.pos], start.is_some()) {
                (b' ', true) | (b'\n', true) => break,
                (_, true) | (b' ', false) => self.pos += 1,
                (b'\n', false) => self._read_next_line(),
                (_, false) => start = Some(self.pos),
            }
        }
        let target = &self.buf[start.unwrap()..self.pos];
        unsafe { str::from_utf8_unchecked(target) }.parse().unwrap()
    }

    #[inline]
    fn _read_next_line(&mut self) {
        self.pos = 0;
        self.buf.clear();
        if self.reader.read_until(b'\n', &mut self.buf).unwrap() == 0 {
            panic!("Reached EOF");
        }
    }
}

fn main() {
    let stdin = std::io::stdin();
    let mut scanner = InputScanner::new(stdin.lock(), 10000);
    let n: i32 = scanner.next();
    let m: i32 = scanner.next();
    let a: Vec<i32> = (0..n).map(|_| scanner.next()).collect();
    let b: Vec<i32> = (0..m).map(|_| scanner.next()).collect();

    let row_map: HashMap<i32, i32> = a.iter().enumerate().map(|(i, &x)| (x, i as i32)).collect();
    let col_map: HashMap<i32, i32> = b.iter().enumerate().map(|(i, &x)| (x, i as i32)).collect();

    let md = 1000000007;
    let res = if row_map.len() < a.len() || col_map.len() < b.len() {
        0
    } else {
        let mut covered_rows = 0;
        let mut covered_cols = 0;
        let mut res: i64 = 1;
        let mut cross = 0;
        for x in (1..(n*m+1)).rev() {
            let r = row_map.get(&x);
            let c = col_map.get(&x);
            match (r, c) {
                (Some(_), Some(_)) => {
                    covered_rows += 1;
                    covered_cols += 1;
                    cross += 1;
                },
                (Some(_), None) => {
                    res = (res * covered_cols) % md;
                    cross += 1;
                    covered_rows += 1;
                },
                (None, Some(_)) => {
                    res = (res * covered_rows) % md;
                    cross += 1;
                    covered_cols += 1;
                },
                (None, None) => {
                    let v = covered_cols * covered_rows - cross;
                    if v <= 0 {
                        res = 0;
                        break;
                    }
                    res = (res * v) % md;
                    cross += 1;
                }
            }
        };
        res
    };
    println!("{}", res)
}

use std::cmp;
