pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m) = i.read2::<usize, usize>();
    let a = i.read_vec::<usize>(n);
    let b = i.read_vec::<usize>(m);

    writeln!(o, "{}", solve(a, b)).unwrap();
}
fn solve(mut a: Vec<usize>, mut b: Vec<usize>) -> usize {
    let mut used = 0;
    a.sort();
    a.reverse();

    b.sort();
    b.reverse();
    for i in 1..a.len() {
        if a[i - 1] == a[i] {
            return 0;
        }
    }
    for i in 1..b.len() {
        if b[i - 1] == b[i] {
            return 0;
        }
    }

    let mut r = Mod::new(1);
    while !a.is_empty() || !b.is_empty() {
        if let (Some(a0), Some(b0)) = (a.pop(), b.pop()) {
            let (n, c) = if a0 == b0 {
                (a0, a.len() + b.len())
            } else if a0 < b0 {
                b.push(b0);
                r *= b.len();
                (a0, b.len() - 1)
            } else {
                a.push(a0);
                r *= a.len();
                (b0, a.len() - 1)
            };
            used += 1;
            if used + c > n {
                return 0;
            }
            for _ in 0..c {
                r *= n - used;
                used += 1;
            }
        } else {
            return 0;
        }
    }
    r.0
}

