const P: i64 = 1_000_000_007;

fn main() {
    let (N, M) = read!(usize, usize);
    let A = read![[usize]];
    let B = read![[usize]];

    let mut X = vec![0; N * M + 1];
    let mut Y = vec![0; N * M + 1];

    for a in A {
        X[a] += 1;
    }
    for b in B {
        Y[b] += 1;
    }

    let mut ax = 0;
    let mut bx = 0;

    let mut s = 1_i64;
    for x in (1..N * M + 1).rev() {
        if X[x] >= 2 || Y[x] >= 2 {
            s = 0;
            break;
        }

        if X[x] + Y[x] == 2 {
            ax += 1;
            bx += 1;
            continue;
        }

        if X[x] == 1 {
            s *= bx;
            s %= P;
            ax += 1;
            continue;
        }

        if Y[x] == 1 {
            s *= ax;
            s %= P;
            bx += 1;
            continue;
        }

        s *= ax * bx - (N * M - x) as i64;
        s %= P;
    }

    println!("{}", s)
}

