pub trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

fn main() {
    let v = read_vec::<usize>();
    let (n, m) = (v[0], v[1]);
    let mut a = read_vec::<u64>();
    let mut b = read_vec::<u64>();
    a.sort();
    b.sort();
    let big_int = 1000_000_000 + 7;

    for i in 1..n {
        if a[i] == a[i - 1] {
            println!("0");
            return;
        }
    }

    for i in 1..m {
        if b[i] == b[i - 1] {
            println!("0");
            return;
        }
    }
    let dict_a = a.iter().cloned().collect::<HashSet<_>>();
    let dict_b = b.iter().cloned().collect::<HashSet<_>>();

    let mut ans = 1u64;
    for i in (1..n * m + 1).rev() {
        let i = i as u64;
        if dict_a.contains(&i) && dict_b.contains(&i) {
            continue;
        }
        if dict_a.contains(&i) {
            ans *= (m - b.lower_bound(&i)) as u64;
        } else if dict_b.contains(&i) {
            ans *= (n - a.lower_bound(&i)) as u64;
        } else {
            ans *= ((m - b.lower_bound(&i)) * (n - a.lower_bound(&i)) - (n * m - i as usize)) as u64;
        }
        // println!("{:?}", ans);
        ans %= big_int;
        if ans <= 0 {
            break;
        }
    }
    println!("{:?}", ans);
}

