fn main() {
    input! {
        n: usize,
        m: usize,
        a: [usize; n],
        b: [usize; m],
    }

    let mut sa = BTreeMap::new();
    let mut sb = BTreeMap::new();

    for &r in a.iter() {
        *sa.entry(r).or_insert(0) += 1;
    }
    for &r in b.iter() {
        *sb.entry(r).or_insert(0) += 1;
    }

    for (_, v) in sa.iter() {
        if *v >= 2 {
            println!("0");
            return;
        }
    }

    for (_, v) in sb.iter() {
        if *v >= 2 {
            println!("0");
            return;
        }
    }

    let mut use_n = 0;
    let mut use_m = 0;
    let mut placed = 0;
    let mut ans = Mod::new(1);

    for i in (1..n * m + 1).rev() {
        let fa = sa.contains_key(&i);
        let fb = sb.contains_key(&i);

        if fa && fb {
            use_n += 1;
            use_m += 1;
        } else if fa {
            use_n += 1;
            ans *= Mod::new(use_m);
        } else if fb {
            use_m += 1;
            ans *= Mod::new(use_n);
        } else {
            if use_m * use_n > placed {
                ans *= Mod::new(use_m * use_n - placed);
            } else {
                ans = Mod::new(0);
            }
        }

        // println!("{:?}", ans);

        placed += 1;
    }

    println!("{}", ans);
