    let mut res = Mint::new(1);
    let mut a = 0;
    let mut b = 0;
    let mut c = 0;
    for i in (0..h * w).rev() {
        let (sa, sb) = (sa.contains(&i), sb.contains(&i));
        if sa && sb {
        } else if !sa && !sb {
            res *= Mint::from(std::cmp::max(a * b - c, 0));
        } else if sa {
            res *= Mint::from(b);
        } else if sb {
            res *= Mint::from(a);
        }
        if sa {
